package com.anvil;

import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;

/**
 * Characters this RuneLite install has been told are not the signed-in Anvil user's.
 *
 * <p>The Account Token names whoever set this RuneLite up, not whoever is playing. Siblings share a
 * PC; friends log in at each other's. So the plugin links every character it plays by default — the
 * one-click path — and the side panel's "Not my account" puts the logged-in character here. While a
 * character in this set is logged in, the plugin sends Anvil nothing at all
 * ({@link BingoApiClient#setAccountPaused}).
 *
 * <p>Stored as digests, never raw: the account hash is a credential the site treats as proof of
 * control, and the name is somebody else's. Both are kept so the launcher's pre-login name hint can
 * be withheld too. RuneLite-free and immutable so it is unit-testable; the plugin persists
 * {@link #serialize()} in its own config.
 */
final class AccountOptOut {
	static final AccountOptOut EMPTY = new AccountOptOut(Collections.emptySet());

	final Set<String> digests;

	AccountOptOut(Set<String> digests) {
		this.digests = Collections.unmodifiableSet(digests);
	}

	static AccountOptOut parse(String raw) {
		Set<String> out = new LinkedHashSet<>();
		if (raw != null) {
			for (String part : raw.split(",")) {
				var p = part.trim();
				if (!p.isEmpty()) out.add(p);
			}
		}
		return new AccountOptOut(out);
	}

	String serialize() {
		return String.join(",", digests);
	}

	/** Is this character opted out? Either key matches: the hash is rename-proof, the name works pre-login. */
	boolean contains(long accountHash, String rsn) {
		var h = hashKey(accountHash);
		var n = nameKey(rsn);
		return (h != null && digests.contains(h)) || (n != null && digests.contains(n));
	}

	/** The launcher's pre-login name: withhold the hint for a character that's opted out. */
	boolean containsName(String rsn) {
		var n = nameKey(rsn);
		return n != null && digests.contains(n);
	}

	AccountOptOut with(long accountHash, String rsn) {
		Set<String> next = new LinkedHashSet<>(digests);
		var h = hashKey(accountHash);
		var n = nameKey(rsn);
		if (h != null) next.add(h);
		if (n != null) next.add(n);
		return new AccountOptOut(next);
	}

	AccountOptOut without(long accountHash, String rsn) {
		Set<String> next = new LinkedHashSet<>(digests);
		next.remove(hashKey(accountHash));
		next.remove(nameKey(rsn));
		return new AccountOptOut(next);
	}

	boolean isEmpty() {
		return digests.isEmpty();
	}

	static String hashKey(long accountHash) {
		return accountHash == -1L ? null : "h" + digest("hash:" + accountHash);
	}

	static String nameKey(String rsn) {
		var norm = Rsn.normalize(rsn);
		return norm.isEmpty() ? null : "n" + digest("rsn:" + norm);
	}

	/** First 16 hex chars of SHA-256 — plenty to tell a handful of local characters apart. */
	static String digest(String s) {
		try {
			var d = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
			var sb = new StringBuilder(16);
			for (int i = 0; i < 8; i++) sb.append(String.format("%02x", d[i]));
			return sb.toString();
		} catch (NoSuchAlgorithmException e) {
			throw new IllegalStateException("SHA-256 is always available", e);
		}
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;

/**
 * Quest points, combat-achievement points and tier, and achievement diaries — the account progress
 * the hiscores never publish (site: lib/memberProgress).
 *
 * <p>The plugin already SEES all of it: it parses every quest, diary and combat-task completion line
 * to credit tiles and post to Discord. It just spent each one and forgot it, so the site could never
 * answer "how many quest points does this member have" — a thing the game knows exactly.
 *
 * <p>Reads varbits, so it must run on the client thread. What it produces is a small map of key →
 * value; the caller diffs it against what it last sent and pushes only the difference, which is
 * usually nothing.
 */
final class AccountProgress {
	/**
	 * Diary completion varbits, region by region, in tier order: easy, medium, hard, elite.
	 *
	 * <p>Karamja (last) is the odd one: its easy, medium and hard tiers predate the other diaries and
	 * are flagged under their old names (ATJUN_*_DONE), apart from their reward-claimed flags
	 * (ATJUN_*_REWARD) — the same shape as every other region's *_COMPLETE. Only elite uses the newer
	 * name. They were once believed to have no completion flag at all, which left three of Karamja's
	 * four tiers reading as unknown.
	 */
	static final int[][] DIARY_VARBITS = {
		{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
		{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE},
	};

	static final String[] DIARY_KEYS = {"diaryEasy", "diaryMedium", "diaryHard", "diaryElite"};

	/**
	 * The key each region's tier mask is stored under, in the same order as {@link #DIARY_VARBITS}.
	 * Matches DIARY_REGIONS on the site.
	 */
	static final String[] DIARY_REGION_KEYS = {
		"diaryArdougne", "diaryDesert", "diaryFalador", "diaryFremennik", "diaryKandarin",
		"diaryKourend", "diaryLumbridge", "diaryMorytania", "diaryVarrock", "diaryWestern",
		"diaryWilderness", "diaryKaramja",
	};

	AccountProgress() {
	}

	/**
	 * Sample everything, right now. Client thread only.
	 *
	 * <p>Returns an empty map when the varbits read as an empty account — a few ticks after login the
	 * client has the values zeroed, and sending that would be a push claiming somebody lost their
	 * quest cape. The server max-merges as a second line of defence, but not sending nonsense is the
	 * first one.
	 */
	static Map<String, Integer> sample(Client client) {
		Map<String, Integer> out = new LinkedHashMap<>();
		if (client == null) return out;

		int questPoints = client.getVarpValue(VarPlayerID.QP);
		int caPoints = client.getVarbitValue(VarbitID.CA_POINTS);

		// Everything zero is what an unpopulated client looks like, not what an account looks like:
		// even a fresh account has quest points from the tutorial's first quest soon enough, and a
		// real one never has all of these at zero at once.
		// Regions complete at each tier (easy, medium, hard, elite), counted off each region's mask.
		int[] masks = new int[DIARY_VARBITS.length];
		int[] diaries = new int[DIARY_KEYS.length];
		int diaryTotal = 0;
		for (int region = 0; region < masks.length; region++) {
			masks[region] = regionMask(client, DIARY_VARBITS[region]);
			for (int tier = 0; tier < diaries.length; tier++) {
				if ((masks[region] & 1 << tier) != 0) {
					diaries[tier]++;
					diaryTotal++;
				}
			}
		}
		if (questPoints <= 0 && caPoints <= 0 && diaryTotal <= 0) return out;

		out.put("questPoints", questPoints);
		out.put("questsCompleted", countQuests(client));
		out.put("caPoints", caPoints);
		// Every tier cleared rather than only the highest, so a profile can light them cumulatively.
		// The highest is 0 (none) through 6 (Grandmaster): the top bit's position.
		int caTiers = tierMask(client, caPoints);
		out.put("caTier", 32 - Integer.numberOfLeadingZeros(caTiers));
		out.put("caTiers", caTiers);
		for (int tier = 0; tier < DIARY_KEYS.length; tier++) out.put(DIARY_KEYS[tier], diaries[tier]);
		// Per region as well as per tier: the counts say how many, these say which.
		for (int region = 0; region < masks.length; region++) out.put(DIARY_REGION_KEYS[region], masks[region]);
		// Says the mask above includes the lower three tiers. Its own key: an older site drops it and
		// keeps treating them as unknown, a current one trusts them (site memberProgress).
		out.put("diaryKaramjaFull", 1);
		// Game mode, raw (0 regular, 1 ironman, 2 ultimate, 3 hardcore, 4 group, 5 hardcore group,
		// 6 unranked group). Read here, past the all-zero guard above, so a login's unpopulated
		// client can't report an ironman as regular. The site maps it and keeps the latest value —
		// unlike the rest of this map it can go down (de-ironing, a hardcore death). Sent top-level,
		// not as a progress row: see BingoApiClient.submitProgress.
		out.put(ACCOUNT_TYPE_KEY, client.getVarbitValue(VarbitID.IRONMAN));
		return out;
	}

	/** The map key the game mode rides under; pulled out into its own field when pushed. */
	static final String ACCOUNT_TYPE_KEY = "accountType";

	/** One region's four tiers, as a mask: easy 1, medium 2, hard 4, elite 8 — the site's numbering. */
	static int regionMask(Client client, int[] region) {
		int mask = 0;
		for (int tier = 0; tier < region.length; tier++) {
			if (client.getVarbitValue(region[tier]) > 0) mask |= 1 << tier;
		}
		return mask;
	}

	/**
	 * Quests finished, out of everything this client build knows about.
	 *
	 * <p>An enum walk of ~200 quests, each a varp read — cheap enough for the half-minute tick that
	 * calls it, and the only way to the number: the game keeps no "quests completed" counter, only
	 * quest points, and those weight quests differently.
	 */
	static int countQuests(Client client) {
		int done = 0;
		for (Quest quest : Quest.values()) {
			if (quest.getState(client) == QuestState.FINISHED) done++;
		}
		return done;
	}

	/**
	 * The raw combat-achievement varps, exactly as the game holds them.
	 *
	 * <p>Completion is bit-packed across these: task `i` is bit `i % 32` of the `i / 32`-th varp in
	 * the order the site sent. Which bit is which task is the site's business — it has the task
	 * catalogue — so this reads integers and understands none of them, and a game update that adds a
	 * varp costs a data change there rather than a release here.
	 *
	 * <p>Client thread.
	 */
	static Map<Integer, Integer> combatVarps(Client client, List<Integer> varps) {
		Map<Integer, Integer> out = new LinkedHashMap<>();
		if (client == null || varps == null) return out;
		for (Integer varpId : varps) {
			if (varpId == null || varpId <= 0) continue;
			out.put(varpId, client.getVarpValue(varpId));
		}
		return out;
	}

	/** One quest, as the site lists it: the game's own id and name, and which of the three states. */
	@RequiredArgsConstructor
	static final class Item {
		final int id;
		final String name;
		final int state;

	}

	/**
	 * EVERY quest with its state, not just the finished ones.
	 *
	 * <p>"Which of these haven't I done" is the question a quest list gets opened for, and a list of
	 * completions can't answer it. Names travel with the ids so the site never needs a quest dataset
	 * of its own — one released next month lists itself.
	 *
	 * <p>Client thread, like everything else here.
	 */
	static List<Item> quests(Client client) {
		List<Item> out = new ArrayList<>();
		if (client == null) return out;
		for (Quest quest : Quest.values()) {
			var state = quest.getState(client);
			int code = state == QuestState.FINISHED ? 2 : state == QuestState.IN_PROGRESS ? 1 : 0;
			out.add(new Item(quest.getId(), quest.getName(), code));
		}
		return out;
	}

	/**
	 * Bit per combat-achievement tier cleared: bit 0 Easy … bit 5 Grandmaster.
	 *
	 * <p>Read from POINTS against each tier's threshold varbit rather than from the tier-status
	 * varbits: the thresholds are what the game itself compares, they're the same numbers the
	 * completion post already uses, and a tier the player cleared but never claimed the reward for
	 * still counts as cleared.
	 */
	static int tierMask(Client client, int caPoints) {
		int mask = 0;
		int index = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values()) {
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && caPoints >= threshold) mask |= 1 << index;
			index++;
		}
		return mask;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.*;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.*;

/**
 * The hiscores counters that are neither a boss nor a skill — clue completions per tier, Colosseum
 * glory, collection-log slots — read from the client instead of waited for.
 *
 * <p>The site can score a tile on any of these, but its only source was the 15-minute hiscores
 * sweep, so "20 elite clues" sat still while every other tile on the board moved within seconds of
 * the kill. The game already knows these numbers; this is just reporting them.
 *
 * <p><b>Only counters the client can actually read are here.</b> The site also offers LMS, PvP
 * Arena and Bounty Hunter — those are hiscores RANKS with no in-game equivalent — and GOTR, which
 * has per-game varbits but no absolute rifts-closed total. Soul Wars is left out for a subtler
 * reason: the varp is a spendable zeal BALANCE while the hiscores counter is zeal EARNED, and a
 * balance is not a smaller-but-honest version of a total, it's a different number. All of those
 * keep their sweep-only behaviour, which is what they had before this existed.
 *
 * <p>Values are absolute and the server keeps {@code max(hiscores, pushed)}, so a counter the
 * client hasn't populated yet (an unsynced collection log reads 0) can never walk a tile backwards.
 * Zero and negative reads are dropped here anyway rather than sent as a no-op request.
 *
 * <p>RuneLite-free apart from the id constants, so the mapping is unit-testable without a client.
 */
final class ActivityStats {
	/** Where a counter lives — the two id spaces are separate, so the kind picks the reader. */
	enum Kind {
		VARBIT,
		VARP
	}

	@RequiredArgsConstructor
	static final class Source {
		final Kind kind;
		final int id;

	}

	/** Site tracked-stat key -> where to read it. Keys mirror lib/hiscoresActivities.ts exactly. */
	static final Map<String, Source> SOURCES;

	/** The site's key for the summed clue total, which has no single counter of its own. */
	static final String CLUES_ALL = "cluesAll";

	static {
		Map<String, Source> m = new LinkedHashMap<>();
		m.put("cluesBeginner", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED));
		m.put("cluesEasy", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_EASY_COMPLETED));
		m.put("cluesMedium", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED));
		m.put("cluesHard", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_HARD_COMPLETED));
		m.put("cluesElite", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_ELITE_COMPLETED));
		m.put("cluesMaster", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_MASTER_COMPLETED));
		m.put("colosseumGlory", new Source(Kind.VARP, VarPlayerID.COLOSSEUM_GLORY));
		m.put("collectionsLogged", new Source(Kind.VARP, VarPlayerID.COLLECTION_COUNT));
		SOURCES = Collections.unmodifiableMap(m);
	}

	/** Every key this can report, for callers that want to filter the site's list down to the real ones. */
	static Set<String> readableKeys() {
		Set<String> keys = new HashSet<>(SOURCES.keySet());
		keys.add(CLUES_ALL);
		return keys;
	}

	static boolean isReadable(String key) {
		return key != null && (SOURCES.containsKey(key) || CLUES_ALL.equals(key));
	}

	/**
	 * True when a varbit/varp change could have moved one of these counters, so the caller can
	 * re-read on the event rather than polling every tick.
	 *
	 * <p>Only the varbit ids are matched, not the varps that back them — a caller that misses an
	 * edge here loses nothing but latency, because the periodic re-read is the actual guarantee.
	 * Passing -1 (RuneLite's "not a varbit"/"not a varp") never matches.
	 */
	static boolean isTrigger(int varbitId, int varpId) {
		for (Source s : SOURCES.values()) {
			if (s.kind == Kind.VARBIT ? s.id == varbitId : s.id == varpId) return true;
		}
		return false;
	}

	/**
	 * Read every wanted key the client can answer for. Unknown or unreadable keys are skipped, as
	 * are non-positive values — a counter reading 0 is almost always one the client hasn't synced
	 * (an unopened collection log), and pushing it would be a request that changes nothing.
	 *
	 * @param wanted the site's tracked activity keys; null/empty reads nothing
	 * @param varbit reads a varbit by id (normally {@code client::getVarbitValue})
	 * @param varp   reads a varplayer by id (normally {@code client::getVarpValue})
	 */
	static Map<String, Integer> read(Collection<String> wanted, IntUnaryOperator varbit, IntUnaryOperator varp) {
		Map<String, Integer> out = new LinkedHashMap<>();
		if (wanted == null || wanted.isEmpty()) return out;
		for (String key : wanted) {
			if (key == null) continue;
			var k = key.trim();
			int value;
			if (CLUES_ALL.equals(k)) {
				// The clue tiers (the "clues…" sources, in hiscores order) summed.
				value = 0;
				for (Map.Entry<String, Source> e : SOURCES.entrySet()) {
					if (e.getKey().startsWith("clues")) value += Math.max(0, varbit.applyAsInt(e.getValue().id));
				}
			} else {
				var s = SOURCES.get(k);
				if (s == null) {
					continue; // a rank-based or unreadable key — the hiscores sweep still covers it
				}
				value = s.kind == Kind.VARBIT ? varbit.applyAsInt(s.id) : varp.applyAsInt(s.id);
			}
			if (value > 0) out.put(k, value);
		}
		return out;
	}

	/**
	 * Unique collection-log slots obtained, or 0 when the client can't answer (the log hasn't synced
	 * this session, or the count exceeds its own maximum and is therefore not what we think it is).
	 * 0 when the log is unread or the count exceeds its own maximum.
	 */
	static int clogSlots(IntUnaryOperator varp) {
		int obtained = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT);
		int total = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT_MAX);
		return obtained > 0 && total > 0 && obtained <= total ? obtained : 0;
	}

	/**
	 * Total collection-log slots in the game, or 0 when unreadable. Needed to place the Gilded rank,
	 * which is a proportion of the total rather than a fixed number (see {@link ClogRank}).
	 */
	static int clogSlotsMax(IntUnaryOperator varp) {
		int total = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT_MAX);
		return Math.max(0, total);
	}

	ActivityStats() {
	}
}

package com.anvil;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup("osrsbingo")
public interface AnvilConfig extends Config {
	// ---- Sections (collapsible groups, top to bottom) ----
	// Split by purpose: Setup + Bingo are event-participation; the "Notifications:" sections are
	// clan-wide Discord posts that fire with or without an active bingo.

	@ConfigSection(
		name = "Bingo",
		description = "In-event behaviour — only matters while you're in a bingo.",
		position = 2
	)
	String bingoSection = "bingoSection";

	@ConfigSection(
		name = "Notifications",
		description = "What you post to your clan's Discord (drops, pets, deaths, levels, achievements) and which chat is hidden in your screenshots are set on the Anvil website: Settings > Announcements (a link is in the Anvil panel's settings tab).",
		position = 3
	)
	String deathsSection = "deathsSection";

	@ConfigSection(
		name = "Player lookup",
		description = "The \"Anvil\" option on player names, and where it appears.",
		position = 1
	)
	String lookupSection = "lookupSection";

	@ConfigSection(
		name = "Profile sync",
		description = "Send your collection log and best times to your Anvil profile.",
		position = 7,
		closedByDefault = true
	)
	String profileSection = "profileSection";

	@ConfigSection(
		name = "Chat messages",
		description = "How Anvil's own lines look in your chatbox.",
		position = 6,
		closedByDefault = true
	)
	String chatSection = "chatSection";

	@ConfigItem(
		keyName = "chatPrefixColor",
		name = "[Anvil] tag colour",
		description = "Colour of the [Anvil] tag at the start of each line. Until you pick one, it turns dark gold on an opaque chatbox.",
		position = 1,
		section = "chatSection"
	)
	default Color chatPrefixColor() {
		return new Color(0xFFD700);
	}

	@ConfigItem(
		keyName = "chatTextColor",
		name = "Message colour",
		description = "Colour of the message after the tag. Until you pick one, it turns black on an opaque chatbox.",
		position = 2,
		section = "chatSection"
	)
	default Color chatTextColor() {
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "chatFeed",
		name = "Show feed in game chat",
		description = "Also print the feed in your game chatbox as it happens: big drops, pets and achievements from boards whose host turned it on and clans you guest in, your teammates' tile progress, and other teams' finished tiles. The side panel's Feed tab works either way. Pick what shows on your Anvil profile.",
		position = 3,
		section = "chatSection"
	)
	default boolean chatFeed() {
		return true;
	}

	@ConfigItem(
		keyName = "supporterChatFlair",
		name = "Supporter names in chat",
		description = "Show Anvil Supporters' name colours (and a Patron's star) in public, clan, friends and private chat, and on your friends list and channel member lists while they are online. The list of names is downloaded from Anvil; nothing about who you see is sent.",
		position = 4,
		section = "chatSection"
	)
	default boolean supporterChatFlair() {
		return true;
	}

	@ConfigItem(
		keyName = "animatedNames",
		name = "Animated names",
		description = "Let Patron and boosted-clan gradients slide, and animated panel banners play. Off resets names and uses still images.",
		position = 5,
		section = "chatSection"
	)
	default boolean animatedNames() {
		return true;
	}

