	/**
	 * POST /api/plugin/clog — collection-log pages the player has actually opened.
	 *
	 * <p>Sends ONLY obtained items, and only pages whose contents changed since the last successful
	 * push ({@link ClogSync} owns that decision). The site already ships the full item catalogue, so
	 * the missing half is derivable — transmitting it would double every payload to say "still
	 * nothing here".
	 *
	 * <p>Idempotent: the server keys on (member, page) and replaces, so a retry or a client restart
	 * mid-sync costs nothing. Profile data only — never scoring.
	 */
	public void submitClogPages(List<ClogPage> pages, int syncedPages) throws IOException {
		if (pages == null || pages.isEmpty()) return;
		var out = new JsonArray();
		for (ClogPage page : pages) {
			if (page == null || page.name == null || page.name.isEmpty()) continue;
			var items = new JsonArray();
			for (int i = 0; i < page.itemIds.length; i++) {
				var item = new JsonObject();
				item.addProperty("id", page.itemIds[i]);
				item.addProperty("q", page.quantities[i]);
				items.add(item);
			}
			var p = new JsonObject();
			p.addProperty("name", page.name);
			p.addProperty("obtained", page.obtained);
			p.addProperty("total", page.total);
			p.add("items", items);
			if (!page.counts.isEmpty()) p.add("counts", gson.toJsonTree(page.counts));
			out.add(p);
		}
		if (out.size() == 0) return;

		var payload = new JsonObject();
		payload.add("pages", out);
		// How much of the log this account has opened at all — drives the site's "68% synced" note.
		payload.addProperty("syncedPages", syncedPages);
		postJson("/api/plugin/clog", payload, "Collection log push failed", true);
	}

	/**
	 * POST /api/plugin/pb — the account's best times, in centiseconds.
	 *
	 * <p>Centiseconds because the game separates runs by hundredths; whole seconds would tie times
	 * the game itself doesn't. The server keeps the FASTEST of stored and pushed, so a retry, a
	 * stale client or an out-of-order request can never raise somebody's record.
	 */
	public void submitPersonalBests(Map<String, Integer> bests) throws IOException {
		if (bests == null || bests.isEmpty()) return;
		Map<String, Integer> valid = new LinkedHashMap<>();
		bests.forEach((k, v) -> {
			if (k != null && !k.isEmpty() && v != null && v > 0) valid.put(k, v);
		});
		if (valid.isEmpty()) return;
		var payload = new JsonObject();
		payload.add("bests", pairs(valid, "activity", "centis"));
		postJson("/api/plugin/pb", payload, "Personal best push failed", true);
	}

	/**
	 * POST /api/plugin/moments — the clan's highlight feed: pets, uniques, big hauls and deaths.
	 *
	 * <p>Reports what the client SAW; the site decides what it meant. It knows which competition
	 * week or board is running, what counts as a unique, and which pets belong to which skill — so
	 * most of what goes up here is discarded there, on purpose, and a clan changing its mind about
	 * any of it costs no plugin release.
	 *
	 * <p>Idempotent: every entry carries a key derived from what happened, so the two loot events
	 * and three chat lines one occurrence fires — and a retry after a timeout — collapse into one
	 * row. A failure therefore just retries with the queue intact.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitMoments(List<AnvilMoments.Moment> batch) throws IOException {
		if (batch == null || batch.isEmpty()) return;
		var out = new JsonArray();
		for (AnvilMoments.Moment m : batch) {
			if (m == null || m.kind == null || m.key == null) continue;
			var o = new JsonObject();
			o.addProperty("kind", m.kind);
			o.addProperty("key", m.key);
			o.addProperty("at", java.time.Instant.ofEpochMilli(m.at).toString());
			o.addProperty("quantity", Math.max(1, m.quantity));
			// Everything below is best-effort — a skilling pet has no source, no KC and no price, and
			// inventing any of them would be worse than a shorter line on the feed.
			if (m.itemId != null) o.addProperty("itemId", m.itemId);
			if (m.valueGp != null && m.valueGp > 0) o.addProperty("valueGp", m.valueGp);
			if (m.kc != null && m.kc > 0) o.addProperty("kc", m.kc);
			addText(o, "itemName", m.itemName);
			addText(o, "source", m.source);
			addText(o, "taskName", m.taskName);
			addText(o, "tier", m.tier);
			addText(o, "sourceKind", m.sourceKind);
			out.add(o);
		}
		if (out.size() == 0) return;
		var payload = new JsonObject();
		payload.add("moments", out);
		postJson("/api/plugin/moments", payload, "Moment push failed", true);
	}

	/** Adds {@code value} when it is non-blank. */
	static void addText(JsonObject o, String key, String value) {
		if (value != null && !value.isEmpty()) o.addProperty(key, value);
	}
}

package com.anvil;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Collection-log "unlock" banner. 178x100 base panel (source PNG is 3x), three centred lines at
 * text-tops y=10/40/64, all 16px with a 1px black shadow and no font smoothing. Open animation:
 * a 1px line draws out horizontally, the background unsquishes to full height, holds, then reverses.
 */
public class BingoClogBannerOverlay extends Overlay {
	// Design space (matches Skeldoor's .collection-log-panel). 1.0 = original asset size.
	static final int BASE_W = 178;
	static final int BASE_H = 100;

	// Text tops (design px) + size. Tuned for even vertical rhythm on the small panel: the header sits
	// just under the top of the frame (11), the "Tile complete!/Progress:" line clears the divider (36),
	// and the label sits close under it (52) so the middle→label gap matches the ~15px gap between the
	// two wrapped label lines — otherwise the body reads as two disconnected zones.
	static final int TOP_Y = 11;
	static final int MID_Y = 36;
	static final int BOTTOM_Y = 52;
	static final float FONT_PX = 16f;
	// The bottom label wraps onto a second line at full size when it's too wide — the RS font is a
	// bitmap face that pixelates when scaled, so we never shrink glyphs. WRAP_LINE_H is the vertical
	// advance (design px) between the two lines, kept tight so both clear the 100px panel.
	static final int WRAP_LINE_H = 15;
	static final int BOTTOM_MAX_LINES = 2;

	// Horizontal padding (design px) kept clear inside the panel; text wider than the inner width wraps
	// onto up to BOTTOM_MAX_LINES lines (bottom label) and is ellipsised only if it overflows the last.
	static final int TEXT_MARGIN_X = 12;

	// Animation (matches the reference gif): a thin line grows to full WIDTH, then the whole
	// background unsquishes to full HEIGHT; close reverses it. Linear motion, no fade.
	static final long H_EXPAND_MS = 800;    // line grows to full width
	static final long V_EXPAND_MS = 800;    // unsquish to full height
	static final long HOLD_MS = 2500;
	static final long V_COLLAPSE_MS = 650;  // squish back down to the line
	static final long H_COLLAPSE_MS = 650;  // line shrinks to nothing
	static final int LINE_H = 1;            // design-px height of the thin opening line

	static final Color ORANGE = new Color(255, 152, 31);
	static final Color WHITE = new Color(255, 255, 255);
	static final Color SHADOW = new Color(0, 0, 0, 255);
	static final Color LINE_COLOR = Color.BLACK; // the thin opening/closing line

	final ConcurrentLinkedQueue<String[]> queue = new ConcurrentLinkedQueue<>();
	final BufferedImage background;
	final Font headerFont;
	final Font bodyFont;
	String[] active; // {top, middle, bottom}
	/** {@link #active} wrapped to the panel, once per banner rather than every frame; null until first drawn. */
	List<List<String>> wrapped;
	long startedAt, lastFrame;
	float ox, oy;

	@Inject
	Client client;

	@Inject
	public BingoClogBannerOverlay(AnvilPlugin plugin) {
		super(plugin);
		setPosition(OverlayPosition.TOP_CENTER);
		setPriority(OverlayPriority.HIGHEST);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		background = loadBackground();
		headerFont = FontManager.getRunescapeBoldFont().deriveFont(FONT_PX);
		// Detail lines use the natively-smaller RS bitmap (the XP-counter/minimap face) at its own
		// crisp size — the standard chat font read too large on the small panel. No deriveFont: scaling
		// a bitmap font off its native grid pixelates (see the wrap-not-shrink note above).
		bodyFont = FontManager.getRunescapeSmallFont();
	}

	static BufferedImage loadBackground() {
		try (InputStream in = BingoClogBannerOverlay.class.getResourceAsStream("/com/anvil/clog_banner.png")) {
			return in == null ? null : ImageIO.read(in);
		} catch (IOException e) {
			return null;
		}
	}

	/** Backwards-compatible entry point used by the existing drop call site. */
	public boolean show(String label, int current, int required) {
		var complete = current >= required;
		var middle = complete ? "Tile complete!" : "Progress:";
		var bottom = required > 1 ? label + " (" + current + "/" + required + ")" : label;
		return show("Anvil Bingo", middle, bottom);
	}

	/** Full three-line control. False when it folded into the "+N more" banner (play no sound). */
	public boolean show(String top, String middle, String bottom) {
		if (queue.size() >= 3) {
			folded.incrementAndGet();
			return false;
		}
		queue.add(new String[]{top, middle, bottom});
		return true;
	}

	/** Banners past the three waiting: one "+N more" closes the run, the rest is in chat and the panel. */
	final AtomicInteger folded = new AtomicInteger();

	@Override
	public Dimension render(Graphics2D g) {
		if (background == null || AnvilPlugin.capturing) return null;

		var now = System.currentTimeMillis();
		var hEnd = H_EXPAND_MS;
		var vEnd = hEnd + V_EXPAND_MS;
		var holdEnd = vEnd + HOLD_MS;
		long vCollapseEnd = holdEnd + V_COLLAPSE_MS;
		var total = vCollapseEnd + H_COLLAPSE_MS;

		if (active == null || now - startedAt >= total) {
			active = queue.poll();
			int n = active == null ? folded.getAndSet(0) : 0;
			if (n > 0) active = new String[]{"Anvil Bingo", "+" + n + " more", "See chat and the panel"};
			if (active == null) return null;
			startedAt = now;
			wrapped = null;
			now = System.currentTimeMillis();
		}

		long e = now - startedAt;

		// w/h = current panel size; line = just the thin opening/closing line (no bg/text yet).
		var line = e < hEnd || e >= vCollapseEnd;
		float w = BASE_W;
		float h = line ? LINE_H : BASE_H;
		if (e < hEnd) {
			// P1: thin line grows to full width.
			w = BASE_W * (e / (float) H_EXPAND_MS);
		} else if (e < vEnd) {
			// P2: whole background unsquishes from the line up to full height.
			h = LINE_H + (BASE_H - LINE_H) * ((e - hEnd) / (float) V_EXPAND_MS);
		} else if (e >= holdEnd && e < vCollapseEnd) {
			// P4: squish back down to the line.
			h = BASE_H - (BASE_H - LINE_H) * ((e - holdEnd) / (float) V_COLLAPSE_MS);
		} else if (line) {
			// P5: line shrinks horizontally to nothing.
			w = BASE_W * (1f - (e - vCollapseEnd) / (float) H_COLLAPSE_MS);
		}

		int iw = Math.max(1, Math.round(w));
		int ih = Math.max(1, Math.round(h));
		int x = (BASE_W - iw) / 2; // centre the (partly-open) panel within the reserved area
		int y = (BASE_H - ih) / 2;

		var g2 = (Graphics2D) g.create();
		// Glide to the dodge spot (and back) instead of jumping when the popup comes or goes; a banner
		// that starts with the popup already up starts there.
		var off = dodge();
		float tx = off == null ? 0 : off.x, ty = off == null ? 0 : off.y;
		if (e < 50 || lastFrame == 0) { ox = tx; oy = ty; }
		else {
			float k = 1f - (float) Math.exp(-(now - lastFrame) / 70.0);
			ox += (tx - ox) * k;
			oy += (ty - oy) * k;
		}
		lastFrame = now;
		g2.translate(Math.round(ox), Math.round(oy));
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

		if (line) {
			// Opening/closing line: a plain strip in the banner's interior tone (not the bg, no text).
			g2.setColor(LINE_COLOR);
			g2.fillRect(x, y, iw, ih);
		} else {
			// Squish the WHOLE background into the current height (full width); it unsquishes to full.
			g2.drawImage(background, x, y, iw, ih, null);

			// Text only while opening/holding (e < holdEnd). On close it's dropped immediately so the
			// panel collapses cleanly instead of a centre sliver of text lingering. Full-size, fixed
			// in place, clipped to the opened region so it's revealed centre-out as the bg unsquishes.
			if (e < holdEnd) {
				g2.clipRect(x, y, iw, ih);
				if (wrapped == null) {
					int maxTextW = BASE_W - 2 * TEXT_MARGIN_X;
					wrapped = Arrays.asList(
						wrap(active[0], g2.getFontMetrics(headerFont), maxTextW, 1),
						wrap(active[1], g2.getFontMetrics(bodyFont), maxTextW, 1),
						wrap(active[2], g2.getFontMetrics(bodyFont), maxTextW, BOTTOM_MAX_LINES));
				}
				drawLines(g2, wrapped.get(0), headerFont, ORANGE, TOP_Y);
				drawLines(g2, wrapped.get(1), bodyFont, ORANGE, MID_Y);
				drawLines(g2, wrapped.get(2), bodyFont, WHITE, BOTTOM_Y);
			}
		}

		g2.dispose();

		return new Dimension(BASE_W, BASE_H);
	}

	/** The game's collection log popup (restyled or not) sits top centre too: when it would cover the
	 *  banner, the banner goes left of it (the right is minimap and orbs), else right, else under it. */
	Point dodge() {
		var w = client.getWidget(InterfaceID.NotificationDisplay.CONTENT);
		var me = getBounds();
		if (w == null || w.isHidden() || me == null) return null;
		var b = w.getBounds();
		// Restyle plugins draw it about twice the widget's size around the same centre: keep clear of that.
		var p = new Rectangle(b.x - b.width / 2, b.y, b.width * 2, b.height * 2);
		if (!p.intersects(me.x, me.y, BASE_W, BASE_H)) return null;
		int gap = 12, vx = client.getViewportXOffset(), right = p.x + p.width + gap;
		if (p.x - gap - vx >= BASE_W) return new Point(p.x - gap - BASE_W - me.x, p.y - me.y);
		if (vx + client.getViewportWidth() - right >= BASE_W) return new Point(right - me.x, p.y - me.y);
		return new Point(0, p.y + p.height + gap - me.y);
	}

	/** Draws {@link #wrap wrapped} lines centred horizontally, {@code topY} being the CSS-style top of the
	 *  first (line-height 1); extra lines advance downward by {@link #WRAP_LINE_H}. */
	static void drawLines(Graphics2D g, List<String> lines, Font font, Color color, int topY) {
		g.setFont(font);
		var fm = g.getFontMetrics();
		for (int i = 0; i < lines.size(); i++) {
			var shown = lines.get(i);
			int x = (BASE_W - fm.stringWidth(shown)) / 2;
			int baseline = topY + i * WRAP_LINE_H + fm.getAscent();
			g.setColor(SHADOW);
			g.drawString(shown, x + 1, baseline + 1);
			g.setColor(color);
			g.drawString(shown, x, baseline);
		}
	}

	/** Greedy word-wrap into at most {@code maxLines} lines that each fit {@code maxWidth}, at the full font
	 *  size (the RS bitmap font pixelates when scaled, so we wrap rather than shrink); any overflow past
	 *  the last line is folded into it, and every kept line is ellipsised if it still overflows (covers a
	 *  lone over-long word too). No text, no lines. */
	static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines) {
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty()) return lines;
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth) {
			lines.add(text);
			return lines;
		}
		var line = new StringBuilder();
		for (String word : text.split("\\s+")) {
			var trial = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(trial) <= maxWidth) {
				line.setLength(0);
				line.append(trial);
				continue;
			}
			if (line.length() > 0) {
				lines.add(line.toString());
				line.setLength(0);
			}
			line.append(word);
		}
		if (line.length() > 0) lines.add(line.toString());
		if (lines.size() > maxLines) {
			// Fold every line past the cap into the last kept line (it gets ellipsised below).
			var tail = new StringBuilder(lines.get(maxLines - 1));
			for (int i = maxLines; i < lines.size(); i++) tail.append(' ').append(lines.get(i));
			lines = new ArrayList<>(lines.subList(0, maxLines - 1));
			lines.add(tail.toString());
		}
		for (int i = 0; i < lines.size(); i++) {
			if (fm.stringWidth(lines.get(i)) > maxWidth) lines.set(i, truncate(lines.get(i), fm, maxWidth));
		}
		return lines;
	}

	/** Trims {@code text} with a trailing ellipsis so it fits within {@code maxWidth} px. */
	static String truncate(String text, FontMetrics fm, int maxWidth) {
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth) return text;
		var ellipsis = "...";
		int ellipsisW = fm.stringWidth(ellipsis);
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end)) + ellipsisW > maxWidth) end--;
		return end <= 0 ? ellipsis : text.substring(0, end).trim() + ellipsis;
	}
}

package com.anvil;

/**
 * Opens a URL in the member's system browser.
 *
 * An interface rather than a direct {@link net.runelite.client.util.LinkBrowser} call so the
 * sign-in flow can be unit-tested without launching anything: production binds
 * {@code LinkBrowser::browse}, tests bind a recorder that just remembers the URL it was handed.
 *
 * <p>Lived inside the federation data source until federation was removed. It is hoisted rather
 * than deleted with it because opening a browser is what DEVICE SIGN-IN does, and that is the
 * plugin's live login path — the one thing in that file that was never about federation at all.</p>
 */
@FunctionalInterface
public interface BrowserOpener {
	/** @return true when a browser was actually opened. */
	boolean open(String url);
}

package com.anvil;

import java.util.*;
import net.runelite.client.game.ItemStack;

/**
 * Items a chat line already credited, held until the loot event for the same acquisition turns up.
 *
 * <p>A raid announces its unique the moment the raid ends ("You received a drop: Dexterous prayer
 * scroll (Chambers of Xeric)") and the drop path credits it then; the chest's loot event only fires
 * when the player opens it, minutes later — far outside the 3s per-tile window — and used to credit
 * the same item a second time. Each chat credit now cancels exactly one later loot copy of the item.
 */
final class ChatCredits {
	/** Long enough to sit in the raid lobby before opening the chest. */
	static final long WINDOW_MS = 30 * 60_000;

	/** itemId → {quantity still owed, when it was credited}. */
	final Map<Integer, long[]> owed = new HashMap<>();

	/** Lines naming the same item this close together (drop line + clog line) are one acquisition. */
	static final long SAME_DROP_MS = 10_000;

	synchronized void note(Collection<ItemStack> credited, long now) {
		for (ItemStack s : credited) {
			var o = owed.get(s.getId());
			var qty = o == null || now - o[1] > WINDOW_MS ? s.getQuantity()
				: now - o[1] <= SAME_DROP_MS ? Math.max(o[0], s.getQuantity())
				: o[0] + s.getQuantity();
			owed.put(s.getId(), new long[]{qty, now});
		}
	}

	/** {@code items} less whatever a chat line already credited; consumes those claims. */
	synchronized List<ItemStack> unclaimed(Collection<ItemStack> items, long now) {
		owed.values().removeIf(o -> now - o[1] > WINDOW_MS);
		List<ItemStack> out = new ArrayList<>(items.size());
		for (ItemStack s : items) {
			var o = owed.get(s.getId());
			int left = s.getQuantity();
			if (o != null) {
				int take = (int) Math.min(o[0], left);
				left -= take;
				o[0] -= take;
				if (o[0] <= 0) owed.remove(s.getId());
			}
			if (left > 0) out.add(left == s.getQuantity() ? s : new ItemStack(s.getId(), left));
		}
		return out;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.function.IntUnaryOperator;

/**
 * Anvil Supporters' colours on their names in normal game chat. The
 * site hands the whole list over and names are matched here, locally: the plugin never tells the site
 * whose messages it saw. The list is versioned: socket deltas (ChatFlairSync) move it one version at a
 * time, and a whole download is only for a version it can't reach that way.
 *
 * <p>Held compact for a list of hundreds of thousands: sorted names, each with a char index into a
 * small palette of looks, looked up by binary search. Replaced whole on every change (copy-on-write),
 * so readers on any thread see one consistent list.
 */

final class ChatFlair {
	/** A look: solid colour, optional gradient stops, Patron star. */
	/** A per-surface look the owner picked themselves: a colour, plus gradient stops when 2+. */
	static final class Surface {
		String c;
		List<String> g;

		@Override
		public String toString() {
			return c + "/" + g;
		}
	}

	static final class Entry {
		String c;
		List<String> g;
		Boolean s;
		/** Tenure chat shape, 1-6 (Apprentice … Legend, tenure.png); drawn instead of {@code s}, any tier. */
		Integer t;
		/** The owner's own look for dark surfaces / light (parchment) ones: drawn as-is, never adapted. */
		Surface d;
		Surface l;
		// Derived once per wire style. Entries are immutable after adoption and shared by every name
		// wearing the same look; transient keeps these client-only caches off Gson's wire format.
		transient String darkColor;
		transient String opaqueColor;
		transient List<String> darkGradient;
		transient List<String> opaqueGradient;
	}

	/**
	 * GET chat-flair/v/&lt;v&gt; ({v, styles, names, ix}), and a push delta ({t:"flair", v, from, styles,
	 * names, ix, del} — or full:true, "fetch it").
	 */
	static final class Wire {
		int v;
		Integer from;
		Boolean full;
		List<Entry> styles;
		String[] names;
		int[] ix;
		String[] del;
	}

	/** GET chat-flair/v?since=: the current version, and the deltas to it when few. */
	static final class Since {
		int v;
		Integer n;
		List<Wire> deltas;
	}

	/** One version of the list. */
	@RequiredArgsConstructor
	static final class Held {
		final int v;
		final String[] names;
		final char[] ix;
		final Entry[] styles;
	}

	/** A sender as the game writes it: rank/account-type icons, then the plain name. */
	static final Pattern SENDER = Pattern.compile("^((?:<img=\\d+>)*)([^<>]+)$");

	volatile Held held = new Held(0, new String[0], new char[0], new Entry[0]);

	int version() {
		return held.v;
	}

	/** Take a whole list. False when it is unusable (then nothing changes). */
	boolean adopt(Wire w) {
		if (w == null || w.v <= 0 || w.names == null || w.ix == null || w.styles == null || w.ix.length != w.names.length) return false;
		TreeMap<String, Entry> all = new TreeMap<>();
		put(all, w);
		held = build(w.v, all);
		return true;
	}

	/** Apply a delta onto the version it was made from. False when it doesn't fit (fetch instead). */
	boolean apply(Wire d) {
		var h = held;
		if (d == null || d.from == null || d.from != h.v || h.v <= 0 || Boolean.TRUE.equals(d.full)) return false;
		TreeMap<String, Entry> set = new TreeMap<>();
		put(set, d);
		Map<String, Boolean> gone = new HashMap<>();
		for (String n : d.del == null ? new String[0] : d.del) gone.put(normalize(n), true);
		// Merge the sorted held names with the sorted changes: one pass, no map of everything.
		held = merge(d.v, h, set, gone);
		return true;
	}

	static void put(Map<String, Entry> into, Wire w) {
		if (w.names == null || w.ix == null || w.styles == null) return;
		for (int n = 0; n < w.names.length && n < w.ix.length; n++) {
			int i = w.ix[n];
			var e = i >= 0 && i < w.styles.size() ? w.styles.get(i) : null;
			if (w.names[n] != null && e != null && ChatPalette.nameColor(e.c) != null) into.put(normalize(w.names[n]), e);
		}
	}

	static Held build(int v, TreeMap<String, Entry> all) {
		Map<String, Integer> palette = new HashMap<>();
		List<Entry> styles = new ArrayList<>();
		var names = new String[all.size()];
		char[] ix = new char[all.size()];
		int n = 0;
		for (Map.Entry<String, Entry> kv : all.entrySet()) {
			names[n] = kv.getKey();
			ix[n++] = (char) intern(palette, styles, kv.getValue());
		}
		return new Held(v, names, ix, styles.toArray(new Entry[0]));
	}

	static Held merge(int v, Held h, TreeMap<String, Entry> set, Map<String, Boolean> gone) {
		Map<String, Integer> palette = new HashMap<>();
		List<Entry> styles = new ArrayList<>();
		for (Entry e : h.styles) intern(palette, styles, e);
		var names = new String[h.names.length + set.size()];
		char[] ix = new char[names.length];
		int n = 0;
		int i = 0;
		java.util.Iterator<Map.Entry<String, Entry>> it = set.entrySet().iterator();
		var next = it.hasNext() ? it.next() : null;
		while (i < h.names.length || next != null) {
			int cmp = next == null ? -1 : i >= h.names.length ? 1 : h.names[i].compareTo(next.getKey());
			if (cmp < 0) {
				if (!gone.containsKey(h.names[i])) {
					names[n] = h.names[i];
					ix[n++] = h.ix[i];
				}
				i++;
				continue;
			}
			if (cmp == 0) {
				i++; // replaced by the delta's look
			}
			if (!gone.containsKey(next.getKey())) {
				names[n] = next.getKey();
				ix[n++] = (char) intern(palette, styles, next.getValue());
			}
			next = it.hasNext() ? it.next() : null;
		}
		return new Held(v, Arrays.copyOf(names, n), Arrays.copyOf(ix, n), styles.toArray(new Entry[0]));
	}

	static int intern(Map<String, Integer> palette, List<Entry> styles, Entry e) {
		var key = e.c + "|" + e.g + "|" + Boolean.TRUE.equals(e.s) + "|" + e.d + "|" + e.l + "|" + e.t;
		var i = palette.get(key);
		if (i == null) {
			palette.put(key, i = styles.size());
			styles.add(e);
		}
		return i;
	}

	/** The look a (normalized) name wears, or null. */
	Entry entry(String name) {
		if (name == null) return null;
		var h = held;
		int at = Arrays.binarySearch(h.names, normalize(name));
		return at >= 0 ? h.styles[h.ix[at]] : null;
	}

	/** The list as a whole download (for the disk copy). */
	Wire toWire() {
		var h = held;
		var w = new Wire();
		w.v = h.v;
		w.names = h.names;
		w.ix = new int[h.ix.length];
		for (int n = 0; n < h.ix.length; n++) w.ix[n] = h.ix[n];
		w.styles = Arrays.asList(h.styles);
		return w;
	}

	boolean isEmpty() {
		return held.names.length == 0;
	}

	int size() {
		return held.names.length;
	}

	/** The site's normalizeRsn: lower case, any run of spaces / underscores (and the game's nbsp) as one space. */
	static String normalize(String name) {
		return SPACES.matcher(name.replace(' ', ' ').trim().toLowerCase(Locale.ROOT)).replaceAll(" ");
	}

	// Compiled once: normalize runs for every chat sender and every friends / channel list row.
	static final Pattern SPACES = Pattern.compile("[\\s_]+");
	static final Pattern TAGS = Pattern.compile("<[^>]*>");
	static final int MAX_NAME_LENGTH = 24;

	/** A sender column's text ("[02:25] <img=1>Name:" with any colouring): the name inside, or null. */
	static final Pattern SENDER_COLUMN = Pattern.compile("^(?:\\[[^\\]]*\\]\\s*)*(?:(?:From|To)\\s+)?(.+?):$");

	/**
	 * What to say on hover over a chat line's SENDER: "Anvil Patron" / "Anvil Champion" / "Anvil
	 * Supporter", or null (not a sender column, or no flair). The star means Patron, a gradient
	 * Champion, a solid colour Supporter.
	 */
	String tierOfSender(String widgetText) {
		if (widgetText == null || isEmpty()) return null;
		var m = SENDER_COLUMN.matcher(TAGS.matcher(widgetText).replaceAll("").trim());
		if (!m.matches()) return null;
		var e = entry(m.group(1));
		return e == null ? null : tierLabel(e);
	}

	static String tierLabel(Entry e) {
		return Boolean.TRUE.equals(e.s) ? "Anvil Patron" : e.g != null && e.g.size() >= 2 ? "Anvil Champion" : "Anvil Supporter";
	}

	/**
	 * Hover inside a line's text (an Anvil line naming someone: "Tile complete: … — by ★Drenvox!"):
	 * the tier when {@code x} (pixels from the text's left edge) falls on a Supporter's name that is
	 * painted in their colours, else null. {@code width} measures raw chat text the way the chat font
	 * draws it (tags and icons included), so only the name itself answers, not the whole line.
	 */
	String tierInLine(String raw, int x, java.util.function.ToIntFunction<String> width) {
		if (raw == null || raw.isEmpty() || isEmpty() || x < 0) return null;
		// The visible characters, and where each one sits in the raw text.
		var plain = new StringBuilder();
		List<Integer> at = new ArrayList<>();
		for (int i = 0; i < raw.length(); i++) {
			char ch = raw.charAt(i);
			if (ch == '<') {
				int close = raw.indexOf('>', i);
				if (close < 0) break;
				i = close;
				continue;
			}
			plain.append(ch == '\u00A0' ? ' ' : Character.toLowerCase(ch));
			at.add(i);
		}
		var text = plain.toString();
		// Every place a painted word starts, and the bounded names that could start there:
		// a handful of lookups per line, however long the list.
		for (int from = 0; from < text.length(); from++) {
			if (from > 0 && Character.isLetterOrDigit(text.charAt(from - 1)) || !Character.isLetterOrDigit(text.charAt(from))) continue;
			var before = raw.substring(0, at.get(from));
			if (!paintedJustBefore(before)) continue;
			for (int to = Math.min(text.length(), from + MAX_NAME_LENGTH); to > from; to--) {
				if (to < text.length() && Character.isLetterOrDigit(text.charAt(to))) continue;
				var e = entry(text.substring(from, to));
				if (e == null) continue;
				int x0 = width.applyAsInt(before);
				int x1 = width.applyAsInt(raw.substring(0, at.get(to - 1) + 1));
				if (x >= x0 && x < x1) return tierLabel(e);
				break;
			}
		}
		return null;
	}

	/**
	 * The sender with their flair: icons kept, then the star (when {@code star} is given and they are
	 * a Patron), then the name in their gradient or colour. Null when they have none or the sender
	 * isn't a plain name (already decorated by something else).
	 */
	String decorate(String sender, String star) {
		return decorate(sender, star, 0);
	}

	/** The sender's look at one point in the Patron gradient's reflecting animation cycle. */
	String decorate(String sender, String star, double shift) {
		return decorate(sender, star, shift, null);
	}

	/** A sender using the palette derived once for the chat surface behind it. */
	String decorateReadable(String sender, String star, double shift, boolean opaque) {
		return decorate(sender, star, shift, opaque);
	}

	/**
	 * {@code safeName} (already markup-safe) in its owner's look for this chat surface: their own
	 * dark/light look as-is, else the adapted main one. Null when they wear none. Clan feed lines use
	 * this so a pushed name matches the same name in chat.
	 */
	String paintNameFor(String safeName, boolean opaque) {
		var e = safeName == null || safeName.isEmpty() ? null : entry(safeName);
		return e == null ? null : ChatPalette.paintName(safeName, readableColor(e, opaque), readableGradient(e, opaque), 0);
	}

	/** A tenure style's chat icon tag for a surface, coloured at gradient place p (set by the plugin). */
	interface TenureIcon {
		String get(Entry e, boolean opaque, double p);
	}

	TenureIcon tenureIcon;

	String decorate(String sender, String star, double shift, Boolean opaque) {
		if (sender == null || isEmpty()) return null;
		var m = SENDER.matcher(sender);
		if (!m.matches()) return null;
		var name = m.group(2);
		var e = entry(name);
		if (e == null) return null;
		var stops = opaque == null ? e.g : readableGradient(e, opaque);
		var color = opaque == null ? ChatPalette.nameColor(e.c) : readableColor(e, opaque);
		var moved = Boolean.TRUE.equals(e.s) ? shift : 0;
		var painted = ChatPalette.paintName(name, color, stops, moved);
		if (painted == null) return null;
		// The tenure icon wears the first letter's colour at this frame, so it moves with the name.
		var mark = star == null ? "" : e.t != null && tenureIcon != null ? tenureIcon.get(e, Boolean.TRUE.equals(opaque), moved) : Boolean.TRUE.equals(e.s) ? star : "";
		return m.group(1) + mark + painted;
	}

	static String readableColor(Entry e, boolean opaque) {
		var cached = opaque ? e.opaqueColor : e.darkColor;
		if (cached != null) return cached;
		var own = opaque ? e.l : e.d;
		var picked = own == null ? null : ChatPalette.nameColor(own.c);
		var source = ChatPalette.nameColor(e.c);
		var derived = picked != null ? picked : source == null ? null : ChatPalette.readableHex(source, opaque);
		if (opaque) {
			e.opaqueColor = derived;
		} else e.darkColor = derived;
		return derived;
	}

	static List<String> readableGradient(Entry e, boolean opaque) {
		var cached = opaque ? e.opaqueGradient : e.darkGradient;
		var own = opaque ? e.l : e.d;
		var picked = own != null && ChatPalette.nameColor(own.c) != null;
		if (cached != null || (e.g == null && !picked)) return cached;
		// The owner's own surface look is exactly what they chose: a solid one also drops the gradient here.
		List<String> source = picked ? (own.g == null ? new ArrayList<>() : own.g) : e.g;
		List<String> derived = new ArrayList<>(source.size());
		for (String stop : source) {
			var hex = ChatPalette.nameColor(stop);
			if (hex != null) derived.add("#" + (picked ? hex : ChatPalette.readableHex(hex, opaque)));
		}
		if (opaque) {
			e.opaqueGradient = derived;
		} else e.darkGradient = derived;
		return derived;
	}

	// ---- Display-time painting of chat widgets. The game's message data (MessageNode name / value) is
	// never touched: the chatbox builds its right-click options ("Message", "Add friend", "Remove
	// friend", reply, report) from that data, and a tagged name breaks the friend check and the action.

	/** Raw chat text's visible characters (tags out, nbsp as a space), and where each sits in the raw. */
	@RequiredArgsConstructor
	static final class Shown {
		final String text;
		final int[] at;
	}

	static Shown shown(String raw) {
		var plain = new StringBuilder(raw.length());
		int[] at = new int[raw.length()];
		for (int i = 0; i < raw.length(); i++) {
			char ch = raw.charAt(i);
			if (ch == '<') {
				int close = raw.indexOf('>', i);
				if (close < 0) break;
				i = close;
				continue;
			}
			at[plain.length()] = i;
			plain.append(ch == '\u00A0' ? ' ' : ch);
		}
		return new Shown(plain.toString(), at);
	}

	/**
	 * A sender as the chatbox shows it: optional "[channel]" / "[timestamp]" groups, then "From " / "To "
	 * on a private message, then the name and a colon. Group 2 is From/To, group 3 the name, group 4
	 * whatever follows the colon (empty in the chatbox's sender column; the message on a split-PM line).
	 */
	static final Pattern SENDER_SHOWN = Pattern.compile("^\\s*((?:\\[[^\\]]*\\]\\s*)*)(?:(From|To)\\s+)?([^:\\[\\]]{1,24}):(.*)$", Pattern.DOTALL);
	/** Chat kinds a screenshot can leave out (PluginConfigResponse.Me.Hide), as bits; 0 = keep. */
	static final int PM = 1, PUBLIC = 2, CLAN_OTHERS = 4, CLAN_SELF = 8, CHANNEL = 16, GROUP = 32;
	static final String[] HIDE_KEYS = {"pm", "public", "clanOthers", "clanSelf", "channel", "group"};

	/** The site's screenshot privacy as kind bits; PMs alone when it hasn't said. */
	static int hideMask(Map<String, Boolean> hide) {
		if (hide == null) return PM;
		int mask = 0;
		for (int i = 0; i < HIDE_KEYS.length; i++) if (Boolean.TRUE.equals(hide.get(HIDE_KEYS[i]))) mask |= 1 << i;
		return mask;
	}

	static final Pattern BRACKET = Pattern.compile("\\[([^\\]]*)\\]");

	/**
	 * Which kind of chat a chatbox SENDER COLUMN's text is ("From Bob:", "[Clan] Bob:", "Bob:"), given
	 * the clan, group ironman and chat channel names (null when not in one) and the local player's
	 * name; 0 when it isn't a sender or its "[channel]" is none of those. A "[12:00]" timestamp group is
	 * not a channel. The caller passes only widgets the layout says are sender columns.
	 */
	static int chatKind(String raw, String clan, String group, String channel, String me) {
		if (raw == null || raw.indexOf(':') < 0) return 0;
		var m = SENDER_SHOWN.matcher(shown(raw).text);
		if (!m.matches() || !m.group(4).trim().isEmpty()) return 0;
		if (m.group(2) != null) return PM;
		var b = BRACKET.matcher(m.group(1));
		var bracket = false;
		while (b.find()) {
			var g = b.group(1).trim();
			if (Rsn.same(g, clan)) return Rsn.same(m.group(3), me) ? CLAN_SELF : CLAN_OTHERS;
			if (Rsn.same(g, group)) return GROUP;
			if (Rsn.same(g, channel)) return CHANNEL;
			if (g.isEmpty() || !Character.isDigit(g.charAt(0))) bracket = true;
		}
		return bracket ? 0 : PUBLIC;
	}

	/** Leading "[channel]" / "[timestamp]" groups and spaces before a broadcast's text. */
	static final Pattern LEAD = Pattern.compile("^(?:\\s*\\[[^\\]]*\\])*\\s*");

	/**
	 * A chatbox SENDER COLUMN's text ("Name:", "[Clan] <icons>Name:", "From Name:", "To Name:") with the
	 * name painted; null when it isn't one (anything after the colon), the name has no flair, or it is
	 * painted already. Text alone proves nothing — anyone can type "[Clan] Bob:" — so the caller passes
	 * only the widget the layout says is a sender column (senderColumn).
	 */
	String paintSender(String raw, String star, boolean opaque) {
		return paintSender(raw, star, opaque, false, 0);
	}

	/** Paint a chatbox sender at one point in the Patron gradient's animation cycle. */
	String paintSender(String raw, String star, boolean opaque, double shift) {
		return paintSender(raw, star, opaque, false, shift);
	}

	/**
	 * A split-private-chat line ("From Name: hi" / "To Name: hi"), which the game writes as one widget:
	 * only for widgets of that container (never the chatbox), and only with From / To before the name.
	 */
	String paintPmLine(String raw, String star, boolean opaque) {
		return paintSender(raw, star, opaque, true, 0);
	}

	/** Paint a split-private-chat sender at one point in the Patron animation cycle. */
	String paintPmLine(String raw, String star, boolean opaque, double shift) {
		return paintSender(raw, star, opaque, true, shift);
	}

	String paintSender(String raw, String star, boolean opaque, boolean pmLine, double shift) {
		if (raw == null || raw.isEmpty() || isEmpty() || raw.indexOf(':') < 0) return null;
		var s = shown(raw);
		var m = SENDER_SHOWN.matcher(s.text);
		// A sender column ends at the colon; a split-PM line is "From/To Name: …". A typed "[Clan] Bob: hi"
		// in a message widget is neither.
		if (!m.matches() || (pmLine ? m.group(2) == null : !m.group(4).trim().isEmpty())) return null;
		int from = m.start(3);
		int to = m.end(3);
		while (from < to && s.text.charAt(from) == ' ') from++;
		while (to > from && s.text.charAt(to - 1) == ' ') to--;
		return from < to && to - from <= MAX_NAME_LENGTH ? paintAt(raw, s, from, to, star, opaque, shift) : null;
	}

	/** Whether a validated sender column belongs to a Patron with a movable gradient. */
	boolean movingSender(String raw) {
		if (raw == null || raw.isEmpty()) return false;
		var m = SENDER_SHOWN.matcher(shown(raw).text);
		if (!m.matches()) return false;
		var name = m.group(3).trim();
		return name.length() <= MAX_NAME_LENGTH && movingName(name);
	}

	/** Whether this name belongs to a Patron with a movable gradient. */
	boolean movingName(String name) {
		var e = entry(name);
		// A Legend's hex glints, so its lines repaint with the moving names.
		return e != null && (Boolean.TRUE.equals(e.s) && e.g != null && e.g.size() >= 2 || Integer.valueOf(AnvilPlugin.TENURE_STEPS).equals(e.t));
	}

	/** Whether an icon-prefixed plain sender/name belongs to a Patron with a movable gradient. */
	boolean movingDecoratedName(String sender) {
		var m = sender == null ? null : SENDER.matcher(sender);
		return m != null && m.matches() && movingName(m.group(2));
	}

	/**
	 * Chatbox layout, not text, says which widget is a sender column: one with a line's text beside it
	 * (same row, to its right, within the line's few widgets). A typed "[Clan] Bob:" is the message
	 * widget, the last on its row. {@code text(j)} is null for a hidden or missing widget.
	 */
	static boolean senderColumn(int i, int n, IntUnaryOperator x, IntUnaryOperator y,
		java.util.function.IntFunction<String> text) {
		for (int j = i + 1; j < n && j <= i + 3; j++) {
			var t = text.apply(j);
			if (t != null && !t.isEmpty() && y.applyAsInt(j) == y.applyAsInt(i) && x.applyAsInt(j) > x.applyAsInt(i)) return true;
		}
		return false;
	}

	/**
	 * A line text with a player's sender column to its left ("Name:" — someone typed it): never a
	 * broadcast, whatever it says. A broadcast's row has only the channel ("[The AFK Spot]") or nothing.
	 */
	static boolean typedBySomeone(int i, IntUnaryOperator x, IntUnaryOperator y,
		java.util.function.IntFunction<String> text) {
		for (int j = i - 1; j >= 0 && j >= i - 3; j--) {
			var t = text.apply(j);
			if (t != null && y.applyAsInt(j) == y.applyAsInt(i) && x.applyAsInt(j) < x.applyAsInt(i) && column(t)) return true;
		}
		return false;
	}

	/**
	 * Room in one row of chat widgets for a sender column that grew by {@code d} px (the Patron star):
	 * widen it, and move each shown widget on its row that starts right of it over by d. {@code ax/ay}
	 * place the widgets on screen (for "same row", "right of"); {@code x/w} are the values to change.
	 * {@code recX/recW} hold what was last set (MIN_VALUE: nothing), updated here: a widget still where
	 * it was put is not moved again, one the game laid out afresh is. True when anything changed.
	 * {@code need} is the whole name segment's drawn width (see {@link #need}), 0 when unknown.
	 */
	static boolean makeRoom(int at, int d, int need, int n, int[] ax, int[] ay, int[] x, int[] w, boolean[] shown, int[] recX, int[] recW) {
		if (d <= 0) return false;
		var moved = false;
		if (w[at] != recW[at]) {
			w[at] += d;
			recW[at] = w[at];
			moved = true;
		}
		for (int j = 0; j < n; j++) {
			if (j == at || !shown[j] || ay[j] != ay[at] || ax[j] <= ax[at] || x[j] == recX[j]) continue;
			int by = shift(d, need, ax[j] - ax[at]);
			x[j] += by;
			w[j] = Math.max(1, w[j] - by);
			recX[j] = x[j];
			moved = true;
		}
		return moved;
	}

	/**
	 * How far to move a message that starts {@code offset} px right of its sender: the star's own width
	 * {@code d}, or more when the name (all its icons and text, {@code need}) overruns where the game put
	 * the message, e.g. an icon another plugin added after the layout. 0 {@code need}: just {@code d}.
	 */
	static int shift(int d, int need, int offset) {
		return Math.max(d, need - offset);
	}

	/** The drawn width of a whole painted sender (every icon, the star, the text) plus a one-space gap; 0 with no font. */
	static int need(String painted, net.runelite.api.FontTypeFace font, IntUnaryOperator iconWidth) {
		return font == null ? 0 : measure(painted, font::getTextWidth, iconWidth) + font.getTextWidth(" ");
	}

	/** Another shown widget on row {@code at}'s line, to its left (left = true) or right. */
	static boolean beside(int at, int n, int[] ax, int[] ay, boolean[] shown, boolean left) {
		for (int j = 0; j < n; j++) {
			if (j != at && shown[j] && ay[j] == ay[at] && (left ? ax[j] < ax[at] : ax[j] > ax[at])) return true;
		}
		return false;
	}


	/**
	 * A player's right-click target ("<col=ffffff>Name<col=40ff00>  (level-71)") with their name in their
	 * colours, re-done after another plugin recoloured it: Player Indicators, on every client tick, drops
	 * the target's FIRST tag and puts its own colour in front, which turned the start of a gradient into
	 * its friend green. Null when it's ours already, the name isn't there or has no flair, or (override
	 * off) another plugin's colour is on it — not the game's white.
	 */
	String paintMenuTarget(String target, String name, boolean override) {
		return paintMenuTarget(target, name, override, 0);
	}

	/** A player-menu target at one point in the Patron animation cycle. */
	String paintMenuTarget(String target, String name, boolean override, double shift) {
		if (target == null || name == null || isEmpty()) return null;
		var d = decorateReadable(name, null, shift, false);
		if (d == null) return null;
		var s = shown(target);
		int from = s.text.indexOf(name.replace('\u00A0', ' '));
		if (from < 0) return null;
		int rs = s.at[from];
		int re = s.at[from + name.length() - 1] + 1;
		int k = shown(d).at[0];
		if (rs >= k && target.startsWith(d, rs - k)) return null;
		// The colour tags right before the name are whoever coloured it last: replaced with ours.
		int start = rs;
		String col = null;
		while (start > 0 && target.charAt(start - 1) == '>') {
			int open = target.lastIndexOf('<', start - 1);
			if (open < 0 || !(target.startsWith("<col=", open) || target.startsWith("</col>", open))) break;
			if (col == null && target.startsWith("<col=", open)) col = target.substring(open + 5, start - 1);
			start = open;
		}
		var theirs = !override && col != null && !col.equalsIgnoreCase("ffffff");
		var plain = s.text.substring(from, from + name.length());
		if (theirs && target.substring(rs, re).equals(plain)) return null;
		// Our paint ends with its own close: an old one after the name goes, or a repaint every tick would pile them up.
		while (target.startsWith("</col>", re)) re += 6;
		// Override off and their colour in front: they took only our first tag, so the rest of our gradient
		// is still inside the name. Strip it, and the whole name is in their colour.
		return theirs
			? target.substring(0, rs) + plain + target.substring(re)
			: target.substring(0, start) + d + target.substring(re);
	}

	/** A sender widget that is just the column ("…Name:"), not a whole line: the line's text sits beside it. */
	static boolean column(String raw) {
		var t = shown(raw).text.trim();
		return t.endsWith(":");
	}

	/**
	 * The part of a clan title after the clan's name (" (18)", the live member count), or null when the
	 * text isn't that clan's title. Markup is ignored so a game-coloured count still matches.
	 */
	static String clanTitleSuffix(String text, String name) {
		if (text == null || name == null || name.isEmpty()) return null;
		var plain = AnvilPlugin.MARKUP_TAG.matcher(text).replaceAll("");
		if (!plain.regionMatches(true, 0, name, 0, name.length())) return null;
		if (plain.length() == name.length()) return "";
		char next = plain.charAt(name.length());
		return Character.isWhitespace(next) || next == '(' ? plain.substring(name.length()) : null;
	}

	/**
	 * Whether a chatbox widget still holds the room made for its star: its value is the one we set AND it
	 * was set for this same sender line. A matching value from a different sender is the game's plain
	 * layout that happens to coincide, and still needs moving.
	 */
	static boolean alreadyRoomed(int value, int roomed, String plain, String roomedFor) {
		return value == roomed && plain != null && plain.equals(roomedFor);
	}

	/**
	 * Raw chat text's drawn width: the visible characters measured by the font ({@code textWidth}, given
	 * no tags), plus each {@code <img=n>} at {@code iconWidth(n)}. Colour tags take no room. The hover maths
	 * and the room a star needs both go through this, so an icon or the star never shifts them.
	 */
	static int measure(String raw, java.util.function.ToIntFunction<String> textWidth, IntUnaryOperator iconWidth) {
		var text = new StringBuilder(raw.length());
		int icons = 0;
		for (int i = 0; i < raw.length(); i++) {
			char ch = raw.charAt(i);
			if (ch == '<') {
				int close = raw.indexOf('>', i);
				if (close < 0) break;
				if (raw.startsWith("img=", i + 1)) {
					try {
						icons += iconWidth.applyAsInt(Integer.parseInt(raw.substring(i + 5, close)));
					} catch (NumberFormatException ignored) {
						// not an icon after all: no room
					}
				}
				i = close;
				continue;
			}
			text.append(ch);
		}
		return (text.length() == 0 ? 0 : textWidth.applyAsInt(text.toString())) + icons;
	}

	/**
	 * A broadcast's key ("Nisbro HCM has completed a quest: …" with tags and leading "[channel]" out) when
	 * it starts with a Supporter's name, else null. Kept at onChatMessage so the chatbox walk knows which
	 * widgets are those broadcasts without a name lookup per widget.
	 */
	String leadKey(String raw) {
		if (raw == null || raw.isEmpty() || isEmpty()) return null;
		var s = shown(raw);
		return leadName(s) < 0 ? null : key(s);
	}

	/** The same key for any text (no lookup): what the chatbox walk compares against the kept ones. */
	static String key(String raw) {
		return raw == null ? null : key(shown(raw));
	}

	static String key(Shown s) {
		var m = LEAD.matcher(s.text);
		return m.lookingAt() ? s.text.substring(m.end()) : s.text;
	}

	/** A broadcast widget with the leading name painted (icons and colours kept); null when none / already. */
	String paintLead(String raw, String star, boolean opaque) {
		return paintLead(raw, star, opaque, 0);
	}

	/** A broadcast's leading name at one point in the Patron animation cycle. */
	String paintLead(String raw, String star, boolean opaque, double shift) {
		if (raw == null || raw.isEmpty() || isEmpty()) return null;
		var s = shown(raw);
		int end = leadName(s);
		if (end < 0) return null;
		var m = LEAD.matcher(s.text);
		int from = m.lookingAt() ? m.end() : 0;
		return paintAt(raw, s, from, end, star, opaque, shift);
	}

	/** Whether a broadcast begins with a Patron name whose gradient should move. */
	boolean movingLead(String raw) {
		if (raw == null || raw.isEmpty()) return false;
		var s = shown(raw);
		int end = leadName(s);
		if (end < 0) return false;
		var m = LEAD.matcher(s.text);
		int from = m.lookingAt() ? m.end() : 0;
		return movingName(s.text.substring(from, end));
	}

	/**
	 * Paint every exact Supporter name in a trusted player-name interface (trade, challenge, raid
	 * boards). Callers scope this to those interfaces; arbitrary game text is never scanned.
	 */
	String paintNames(String raw, boolean opaque, double shift) {
		if (raw == null || raw.isEmpty() || isEmpty()) return null;
		var shown = shown(raw);
		var out = raw;
		var changed = false;
		for (int from = shown.text.length() - 1; from >= 0; from--) {
			if (from > 0 && nameChar(shown.text.charAt(from - 1))) continue;
			int limit = Math.min(shown.text.length(), from + MAX_NAME_LENGTH);
			for (int to = limit; to > from; to--) {
				if (to < shown.text.length() && nameChar(shown.text.charAt(to)) || entry(shown.text.substring(from, to)) == null) continue;
				var painted = paintAt(out, shown, from, to, null, opaque, shift);
				if (painted != null) {
					out = painted;
					changed = true;
				}
				break;
			}
		}
		return changed ? out : null;
	}

	/** Whether a trusted interface text contains at least one moving Patron name. */
	boolean movingNames(String raw) {
		if (raw == null || raw.isEmpty()) return false;
		var text = shown(raw).text;
		for (int from = 0; from < text.length(); from++) {
			if (from > 0 && nameChar(text.charAt(from - 1))) continue;
			for (int to = Math.min(text.length(), from + MAX_NAME_LENGTH); to > from; to--) {
				if ((to == text.length() || !nameChar(text.charAt(to))) && movingName(text.substring(from, to))) return true;
			}
		}
		return false;
	}

	/**
	 * Where the Supporter's name the text starts with ends (exclusive), or -1: the longest prefix of at
	 * most {@link #MAX_NAME_LENGTH} characters that ends on a word ("Bob" is not the start of "Bobby has…")
	 * and is on the list.
	 */
	int leadName(Shown s) {
		var t = s.text;
		var m = LEAD.matcher(t);
		int from = m.lookingAt() ? m.end() : 0;
		for (int to = Math.min(t.length(), from + MAX_NAME_LENGTH); to > from; to--) {
			if (!Character.isLetterOrDigit(t.charAt(to - 1)) || to < t.length() && nameChar(t.charAt(to))) continue;
			if (entry(t.substring(from, to)) != null) return to;
		}
		return -1;
	}

	static boolean nameChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_' || c == '-';
	}

	/**
	 * Replace the visible characters [from, to) — a plain name in the raw text — with the painted name,
	 * re-opening the colour the text had there so the rest of the line keeps it. Null when the name
	 * carries tags inside (gradient-painted already) or our paint is right before it (painted already).
	 */
	String paintAt(String raw, Shown s, int from, int to, String star, boolean opaque, double shift) {
		int rs = s.at[from];
		int re = s.at[to - 1] + 1;
		var name = raw.substring(rs, re);
		if (name.indexOf('<') >= 0) return null;
		var d = decorateReadable(name, star, shift, opaque);
		if (d == null) return null;
		int k = shown(d).at[0];
		if (rs >= k && raw.startsWith(d.substring(0, k), rs - k)) return null;
		var before = raw.substring(0, rs);
		int open = before.lastIndexOf("<col=");
		var reopen = open >= 0 && open > before.lastIndexOf("</col>") && before.indexOf('>', open) > 0
			? before.substring(open, before.indexOf('>', open) + 1) : "";
		return before + d + reopen + raw.substring(re);
	}

	/** The tags right before a point include a colour: what was there is painted, not plain text. */
	static boolean paintedJustBefore(String raw) {
		int end = raw.length();
		while (end > 0 && raw.charAt(end - 1) == '>') {
			int open = raw.lastIndexOf('<', end - 1);
			if (open < 0) return false;
			if (raw.startsWith("<col=", open)) return true;
			end = open;
		}
		return false;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.function.LongSupplier;


/**
 * Keeps {@link ChatFlair} at the site's version. A socket delta for the
 * version we hold is applied in place, no request; anything else — a missed message, a reconnect, a
 * "full" marker, nothing held yet — asks {@code chat-flair/v?since=} after a random 0–20 s (a change
 * reaches every plugin at once; this spreads their requests), which answers with the deltas when few,
 * else the whole versioned list (CDN-cached) is downloaded. Nothing about who the player sees is sent.
 */
@RequiredArgsConstructor
final class ChatFlairSync {
	interface Source {
		/** The site's version and the deltas from {@code v}; null on failure. Blocking. */
		ChatFlair.Since since(int v);

		/** The whole list at version {@code v}; null on failure. Blocking. */
		ChatFlair.Wire full(int v);
	}

	interface Scheduler {
		/** Run {@code r} after {@code ms}, off the client thread, where blocking HTTP is fine. */
		void schedule(Runnable r, long ms);
	}

	static final long JITTER_MS = 20_000;

	final ChatFlair flair;
	final Source source;
	final Scheduler scheduler;
	final LongSupplier jitter;
	/** After the list changed: repaint, save. */
	final Runnable changed;
	boolean pending;


	/** A {"t":"flair"} push: applied if it follows our version, else a jittered catch-up. */
	void pushed(ChatFlair.Wire d) {
		if (flair.apply(d)) {
			changed.run();
		} else if (d == null || d.v != flair.version() || d.v == 0) soon();
	}

	/** Catch up after the jitter; several asks before it runs are one. */
	synchronized void soon() {
		if (pending) return;
		pending = true;
		scheduler.schedule(() -> {
			synchronized (this) {
				pending = false;
			}
			sync();
		}, jitter.getAsLong());
	}

	/** Bring the list to the site's version now. Blocking. */
	void sync() {
		var s = source.since(flair.version());
		if (s == null) return;
		if (s.v == flair.version()) {
			// A dev client can retain a valid version number with an empty/corrupt disk snapshot. The
			// version endpoint then quite correctly says "current", but none of that client's names ever
			// recover. An empty current generation is cheap and safe to verify from the CDN-cached full list.
			var wrongSize = s.n != null && s.n >= 0 && flair.size() != s.n;
			if (s.v > 0 && (flair.isEmpty() || wrongSize) && flair.adopt(source.full(s.v))) changed.run();
			return;
		}
		var moved = false;
		if (s.deltas != null) {
			for (ChatFlair.Wire d : s.deltas) moved |= flair.apply(d);
		}
		if (flair.version() != s.v || s.n != null && s.n >= 0 && flair.size() != s.n) moved |= flair.adopt(source.full(s.v));
		if (moved) changed.run();
	}
}

package com.anvil;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Hover a Supporter's name in the chatbox: "Anvil Patron" (Champion, Supporter). Draws nothing; per
 * frame it only reads the mouse, and walks the chat lines only while the mouse is over them.
 */
final class ChatFlairTooltip extends Overlay {
	final Client client;
	final TooltipManager tooltips;
	final ChatFlair flair;
	final BooleanSupplier on;
	/** One chat line's height. */
	static final int LINE_H = 14;

	ChatFlairTooltip(Client client, TooltipManager tooltips, ChatFlair flair, BooleanSupplier on) {
		this.client = client;
		this.tooltips = tooltips;
		this.flair = flair;
		this.on = on;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g) {
		if (flair.isEmpty() || !on.getAsBoolean()) return null;
		var area = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		var mouse = client.getMouseCanvasPosition();
		if (area == null || area.isHidden() || mouse == null || !area.getBounds().contains(mouse.getX(), mouse.getY())) return null;
		var lines = area.getDynamicChildren();
		if (lines == null) return null;
		for (Widget w : lines) {
			if (w != null && !w.isHidden() && w.getBounds().contains(mouse.getX(), mouse.getY())) {
				var label = flair.tierOfSender(w.getText());
				if (label == null && w.getFont() != null && w.getCanvasLocation() != null
					&& mouse.getY() - w.getCanvasLocation().getY() < LINE_H) {
					// A name inside the line (an Anvil line naming its player): only over the name itself, and
					// only on the first line of a wrapped one, where the measured position holds.
					net.runelite.api.FontTypeFace font = w.getFont();
					label = flair.tierInLine(w.getText(), mouse.getX() - w.getCanvasLocation().getX(),
						raw -> ChatFlair.measure(raw, font::getTextWidth, this::iconWidth));
				}
				if (label != null) tooltips.add(new Tooltip(label));
				return null;
			}
		}
		return null;
	}

	/** An {@code <img=n>}'s drawn width: the chat icon's own (the star included), the usual 13 when unknown. */
	int iconWidth(int n) {
		net.runelite.api.IndexedSprite[] icons = client.getModIcons();
		net.runelite.api.IndexedSprite icon = icons != null && n >= 0 && n < icons.length ? icons[n] : null;
		return icon == null ? 13 : icon.getOriginalWidth();
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import java.awt.Color;

/**
 * What colour an Anvil chat line is (site lib/chatLook). Every line has a {@link Tone}; the site hands
 * the palette over with the login brief. Until then, and against a site without one, the Anvil
 * colours apply. "Plain" means the plugin's own text colour for everything (its existing setting).
 */

final class ChatPalette {
	enum Tone {
		DONE, NEAR, DROP, FEED, WARN, INFO;

		static Tone of(String s) {
			if (s != null) {
				for (Tone t : values()) {
					if (t.name().equalsIgnoreCase(s)) return t;
				}
			}
			return INFO;
		}
	}

	static final Pattern HEX = Pattern.compile("[0-9a-fA-F]{6}");
	static final String HEX_DIGITS = "0123456789abcdef";

	static final ChatPalette ANVIL = anvil();

	/**
	 * The Anvil tones on the OPAQUE chatbox: its parchment washes the bright set out, so the same tones
	 * in the dark inks the game itself uses there. A player's own (custom) palette is theirs, kept as is.
	 */
	static final Map<Tone, String> OPAQUE = new EnumMap<>(Tone.class);

	static {
		OPAQUE.put(Tone.DONE, "006a00");
		OPAQUE.put(Tone.NEAR, "7a4a00");
		OPAQUE.put(Tone.DROP, "a03c00");
		OPAQUE.put(Tone.FEED, "4d4d4d");
		OPAQUE.put(Tone.WARN, "9e0000");
		OPAQUE.put(Tone.INFO, "000000");
	}

	/** Null: plain. */
	final Map<Tone, String> colors;
	/** Custom palettes colour INFO too; the Anvil one leaves it to the player's own text colour. */
	final boolean custom;

	ChatPalette(Map<Tone, String> colors, boolean custom) {
		this.colors = colors;
		this.custom = custom;
	}

	static ChatPalette anvil() {
		Map<Tone, String> m = new EnumMap<>(Tone.class);
		m.put(Tone.DONE, "16c60c");
		m.put(Tone.NEAR, "ffb000");
		m.put(Tone.DROP, "ff7f27");
		m.put(Tone.FEED, "9a9a9a");
		m.put(Tone.WARN, "ff3b3b");
		m.put(Tone.INFO, "ffffff");
		return new ChatPalette(m, false);
	}

	/** The site's look ({palette, colors}); anything unreadable keeps the Anvil colour for that tone. */
	static ChatPalette from(String palette, Map<String, String> colors) {
		if ("plain".equals(palette)) return new ChatPalette(null, false);
		Map<Tone, String> m = new EnumMap<>(ANVIL.colors);
		if (colors != null) {
			for (Map.Entry<String, String> e : colors.entrySet()) {
				var v = e.getValue() == null ? "" : e.getValue().replace("#", "");
				if (HEX.matcher(v).matches()) m.put(Tone.of(e.getKey()), v.toLowerCase(Locale.ROOT));
			}
		}
		return new ChatPalette(m, "custom".equals(palette));
	}

	/** The text colour for {@code tone}, {@code ownText} being the player's configured text colour. */
	String text(Tone tone, String ownText, boolean opaque) {
		if (colors == null || (tone == Tone.INFO && !custom)) return ownText;
		var c = opaque && !custom ? OPAQUE.get(tone) : colors.get(tone);
		return c != null ? c : ownText;
	}

	/**
	 * A name drawn letter by letter across 2–4 gradient stops ("#rrggbb"), or null when fewer than two
	 * stops are valid. {@code safeName} must already be free of chat tags; spaces carry no colour.
	 */
	static String gradientName(String safeName, List<String> stops) {
		return gradientName(safeName, stops, 0);
	}

	/**
	 * The one chat-name renderer: callers choose the source or surface-derived palette, then this
	 * handles static versus gradient markup and animation sampling.
	 */
	static String paintName(String safeName, String color, List<String> stops, double shift) {
		var gradient = stops != null && stops.size() >= 2 ? gradientName(safeName, stops, shift) : null;
		var solid = nameColor(color);
		return gradient != null ? gradient
			: solid != null && safeName != null && !safeName.isEmpty() ? "<col=" + solid + ">" + safeName + "</col>" : null;
	}

	/**
	 * A gradient name sampled {@code shift} name-widths farther along a reflecting gradient. A shift
	 * from 0 to 2 is one seamless there-and-back animation cycle; zero is the ordinary static look.
	 */
	static List<int[]> rgbOf(List<String> stops) {
		List<int[]> rgb = new ArrayList<>();
		for (String s : stops == null ? new ArrayList<String>() : stops) {
			var hex = nameColor(s);
			if (hex != null && rgb.size() < 4) {
				int v = Integer.parseInt(hex, 16);
				rgb.add(new int[]{(v >> 16) & 0xff, (v >> 8) & 0xff, v & 0xff});
			}
		}
		return rgb;
	}

	/** The reflecting gradient's colour at {@code p} (0-1 across a name, +shift for the motion). */
	static int sample(List<int[]> rgb, double p) {
		p %= 2;
		if (p < 0) p += 2;
		p = p > 1 ? 2 - p : p;
		var t = p * (rgb.size() - 1);
		int seg = Math.min((int) t, rgb.size() - 2);
		var f = t - seg;
		int[] a = rgb.get(seg);
		int[] b = rgb.get(seg + 1);
		return (int) Math.round(a[0] + (b[0] - a[0]) * f) << 16
			| (int) Math.round(a[1] + (b[1] - a[1]) * f) << 8
			| (int) Math.round(a[2] + (b[2] - a[2]) * f);
	}

	static String gradientName(String safeName, List<String> stops, double shift) {
		var rgb = rgbOf(stops);
		if (rgb.size() < 2 || safeName == null || safeName.isEmpty()) return null;
		int n = safeName.codePointCount(0, safeName.length());
		var out = new StringBuilder(safeName.length() * 20);
		int last = -1;
		int i = 0;
		for (int off = 0; off < safeName.length(); ) {
			int cp = safeName.codePointAt(off);
			off += Character.charCount(cp);
			if (!Character.isWhitespace(cp) && !Character.isSpaceChar(cp)) {
				int c = sample(rgb, n == 1 ? shift : (double) i / (n - 1) + shift);
				if (c != last) {
					if (last >= 0) out.append("</col>");
					out.append("<col=");
					appendHex(out, c);
					out.append('>');
					last = c;
				}
			}
			out.appendCodePoint(cp);
			i++;
		}
		return out.append("</col>").toString();
	}

	/** Six lower-case hex digits without the allocation-heavy Formatter used by the static path. */
	static void appendHex(StringBuilder out, int rgb) {
		for (int shift = 20; shift >= 0; shift -= 4) out.append(HEX_DIGITS.charAt(rgb >> shift & 0xf));
	}

	// What the chatbox's text sits on: the opaque box's parchment, and a dark game scene behind the
	// transparent one (the worst case: night, a cave, the Wilderness). Approximations, not exact pixels.
	static final int OPAQUE_BG = 0xC4B48C;
	static final int TRANSPARENT_BG = 0x262626;
	/** WCAG's floor for large or bold text; chat text is small but heavy and shadowed on the dark box. */
	static final double MIN_CONTRAST = 3.0;
	static final Pattern COL = Pattern.compile("<col=([0-9a-fA-F]{6})>");

	/**
	 * Every {@code <col=…>} in a chat line made readable on this chatbox: a colour that already
	 * clears {@link #MIN_CONTRAST} is left exactly as it is; a fainter one is mixed towards black (on
	 * the parchment) or white (on the dark box) just until it does. Covers the tag, the tones, team
	 * and Supporter names and every letter of a gradient, whoever chose the colour.
	 */
	static String readable(String line, boolean opaque) {
		java.util.regex.Matcher m = COL.matcher(line);
		var out = new StringBuffer();
		while (m.find()) m.appendReplacement(out, "<col=" + readableHex(m.group(1), opaque) + ">");
		m.appendTail(out);
		return out.toString();
	}

	/**
	 * {@code hex} (with or without "#") as a Swing colour adapted like {@link #readableHex}; {@code fallback}
	 * when it isn't a colour. readableHex answers bare "rrggbb", which Ui.teamColor refuses, so every
	 * panel stop used to silently become its fallback (a white Tracking name, a one-colour Lookup name).
	 */
	static Color readableColor(String hex, boolean opaque, Color fallback) {
		var v = nameColor(hex);
		return v == null ? fallback : new Color(Integer.parseInt(readableHex(v, opaque), 16));
	}

	static String readableHex(String hex, boolean opaque) {
		int source = Integer.parseInt(hex, 16);
		int bg = opaque ? OPAQUE_BG : TRANSPARENT_BG;
		int toward = opaque ? 0x000000 : 0xFFFFFF;
		if (contrast(source, bg) >= MIN_CONTRAST) return hex.toLowerCase(Locale.ROOT);
		// The old 10% staircase made a moving gradient visibly snap whenever a glyph crossed into the
		// next darker/lighter band. Find the exact boundary instead; contrast is monotonic toward black
		// on parchment and toward white on the transparent dark box.
		double lo = 0;
		double hi = 1;
		int readable = toward;
		for (int i = 0; i < 12; i++) {
			double mid = (lo + hi) / 2;
			int candidate = mix(source, toward, mid);
			if (contrast(candidate, bg) >= MIN_CONTRAST) {
				hi = mid;
				readable = candidate;
			} else lo = mid;
		}
		char[] out = new char[6];
		for (int at = 5; at >= 0; at--) {
			out[at] = HEX_DIGITS.charAt(readable & 0xf);
			readable >>>= 4;
		}
		return new String(out);
	}

	static double contrast(int a, int b) {
		var la = luminance(a);
		var lb = luminance(b);
		return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
	}

	static double luminance(int rgb) {
		return 0.2126 * channel(rgb >> 16) + 0.7152 * channel(rgb >> 8) + 0.0722 * channel(rgb);
	}

	static double channel(int v) {
		var c = (v & 0xff) / 255.0;
		return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
	}

	static int mix(int a, int b, double t) {
		int r = (int) Math.round(((a >> 16) & 0xff) * (1 - t) + ((b >> 16) & 0xff) * t);
		int g = (int) Math.round(((a >> 8) & 0xff) * (1 - t) + ((b >> 8) & 0xff) * t);
		int bl = (int) Math.round((a & 0xff) * (1 - t) + (b & 0xff) * t);
		return (r << 16) | (g << 8) | bl;
	}

	/** A name colour from the site ("#rrggbb"), or null. */
	static String nameColor(String s) {
		var v = s == null ? "" : s.replace("#", "");
		return HEX.matcher(v).matches() ? v.toLowerCase(Locale.ROOT) : null;
	}
}

package com.anvil;

import static java.util.Collections.*;
import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;
import lombok.extern.slf4j.Slf4j;

/**
 * Every chat line the plugin reads, by a stable key, so the site can re-word one without a release.
 *
 * <p>The defaults live in {@code chat-patterns.json} beside this class — the same file the site's
 * pattern editor is built from, with each key's required named groups and real sample lines. When
 * Jagex rewords a line, the site serves an override for that key (GET /api/plugin/chat-patterns);
 * {@link #applyOverrides} vets each one and swaps the whole map at once, so a parser always reads one
 * consistent snapshot. A rejected override changes nothing: that key keeps its default.</p>
 *
 * <p>Parsers read groups BY NAME — an override may order its groups differently.</p>
 */
@Slf4j
final class ChatPatterns {
	ChatPatterns() {}

	static final class Sample {
		String line;
		Map<String, String> expect;
	}

	static final class Entry {
		String key;
		String description;
		List<String> types;
		String input;
		String match;
		String regex;
		List<String> groups;
		List<String> flags;
		/** Cheap substring the DEFAULT line always carries — checked before the regex runs. */
		String hint;
		List<Sample> samples;
	}

	static final class Catalog {
		int version;
		List<Entry> patterns;
	}

	/** One site override. A null regex means "use the default". */
	static final class SiteOverride {
		String key;
		String regex;
		/** Optional literal the new wording always carries — the pre-filter for this override. */
		String hint;
	}

	/** Body of GET /api/plugin/chat-patterns. */
	static final class OverridesResponse {
		int version;
		List<SiteOverride> overrides;
	}

	static final int MAX_LENGTH = 500;
	/** charAt calls one test input may cost; a backtracking bomb blows through this in microseconds. */
	static final long STEP_BUDGET = 2_000_000L;
	/**
	 * charAt calls an OVERRIDE may spend on one real chat line. Vetting can't foresee every line, and
	 * these run on the client thread — an override that overspends is dropped for the session.
	 */
	static final long LINE_BUDGET = 100_000L;
	static final Pattern NEVER = Pattern.compile("(?!)");

	static volatile Map<String, Entry> entries = emptyMap();
	static volatile Map<String, Pattern> defaults = emptyMap();
	/** The accepted overrides and their hints, swapped as ONE object so a reader never pairs mismatched halves. */
	static final class Live {
		final Map<String, Pattern> patterns;
		final Map<String, String> hints;

		Live(Map<String, Pattern> patterns, Map<String, String> hints) {
			this.patterns = unmodifiableMap(patterns);
			this.hints = unmodifiableMap(hints);
		}
	}

	static volatile Live live = new Live(new HashMap<>(), new HashMap<>());

	/** Read the bundled catalog. Idempotent; a broken resource leaves every key matching nothing. */
	static synchronized void loadDefaults(Gson gson) {
		if (!defaults.isEmpty()) return;
		try (InputStream in = ChatPatterns.class.getResourceAsStream("chat-patterns.json");
			Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
			var c = gson.fromJson(r, Catalog.class);
			Map<String, Entry> e = new HashMap<>();
			Map<String, Pattern> d = new HashMap<>();
			for (Entry p : c.patterns) {
				e.put(p.key, p);
				d.put(p.key, Pattern.compile(p.regex, flagsOf(p)));
			}
			entries = unmodifiableMap(e);
			defaults = unmodifiableMap(d);
		} catch (Exception ex) {
			log.warn("Chat patterns failed to load", ex);
		}
	}

	/** The live pattern for a key: the site's override if one was accepted, else the default. */
	static Pattern get(String key) {
		var p = live.patterns.get(key);
		if (p == null) p = defaults.get(key);
		return p == null ? NEVER : p;
	}

	/** A matcher that found {@code key} somewhere in {@code text}, or null. */
	static Matcher find(String key, String text) {
		return match(key, text, false);
	}

	/** A matcher for which {@code key} matched the whole of {@code text}, or null. */
	static Matcher full(String key, String text) {
		return match(key, text, true);
	}

	static Matcher match(String key, String text, boolean whole) {
		var l = live;
		var o = l.patterns.get(key);
		if (o != null) {
			var hint = l.hints.get(key);
			if (hint != null && !text.contains(hint)) return null;
			var m = o.matcher(new Budgeted(text, LINE_BUDGET));
			try {
				return (whole ? m.matches() : m.find()) ? m : null;
			} catch (BudgetExceeded ex) {
				drop(key, o);
				// fall through to the default — this line still deserves a reading
			}
		}
		var p = defaults.get(key);
		if (p == null) return null;
		var m = p.matcher(text);
		return (whole ? m.matches() : m.find()) ? m : null;
	}

	/** Retire an override that overspent on a real line. Only if it is still the live one. */
	static synchronized void drop(String key, Pattern bad) {
		var l = live;
		if (l.patterns.get(key) != bad) return;
		Map<String, Pattern> next = new HashMap<>(l.patterns);
		next.remove(key);
		Map<String, String> hints = new HashMap<>(l.hints);
		hints.remove(key);
		live = new Live(next, hints);
		log.warn("Chat pattern {} too slow; default this session", key);
	}

	/**
	 * Whether {@code text} could match {@code key} — the default's literal hint, a free pre-check on
	 * every chat line. An overridden key skips it: the new wording may not carry the old phrase.
	 */
	static boolean mayMatch(String key, String text) {
		var l = live;
		if (l.patterns.containsKey(key)) {
			var hint = l.hints.get(key);
			return hint == null || text.contains(hint);
		}
		var e = entries.get(key);
		return e == null || e.hint == null || text.contains(e.hint);
	}

	/**
	 * Replace the override set with {@code list}, keeping only the overrides that pass {@link #vet}.
	 * Keys not named fall back to their defaults. Returns one "key: reason" per rejection.
	 */
	static synchronized List<String> applyOverrides(List<SiteOverride> list) {
		Map<String, Pattern> next = new HashMap<>();
		Map<String, String> hints = new HashMap<>();
		List<String> rejected = new ArrayList<>();
		if (list != null) {
			for (SiteOverride o : list) {
				if (o == null || o.key == null || o.regex == null) continue;
				var e = entries.get(o.key);
				if (e == null) {
					rejected.add(o.key + ": unknown key");
					continue;
				}
				try {
					next.put(o.key, vet(e, o.regex));
					if (o.hint != null && !o.hint.isEmpty()) hints.put(o.key, o.hint);
				} catch (IllegalArgumentException ex) {
					rejected.add(o.key + ": " + ex.getMessage());
				}
			}
		}
		live = new Live(next, hints);
		return rejected;
	}

	/** Compile {@code regex} for {@code e}, or throw with the reason it can't stand in for the default. */
	static Pattern vet(Entry e, String regex) {
		if (regex.length() > MAX_LENGTH) throw new IllegalArgumentException("longer than " + MAX_LENGTH + " chars");
		int flags = flagsOf(e);
		Pattern p;
		Pattern probe;
		try {
			p = Pattern.compile(regex, flags);
			// Java 11 has no Pattern.namedGroups(). An empty alternative lets "" match, and group(name)
			// on a successful match throws only when the name doesn't exist.
			probe = Pattern.compile("(?:" + regex + ")|", flags);
		} catch (PatternSyntaxException ex) {
			throw new IllegalArgumentException("does not compile: " + ex.getDescription());
		}
		var m = probe.matcher("");
		if (!m.matches()) throw new IllegalArgumentException("does not compile cleanly");
		for (String g : e.groups) {
			try {
				m.group(g);
			} catch (IllegalArgumentException ex) {
				throw new IllegalArgumentException("missing named group (?<" + g + ">…)");
			}
		}
		for (String input : stressInputs(e)) {
			try {
				p.matcher(new Budgeted(input)).find();
			} catch (BudgetExceeded ex) {
				throw new IllegalArgumentException("too slow (catastrophic backtracking)");
			}
		}
		return p;
	}

	static List<String> stressInputs(Entry e) {
		List<String> out = new ArrayList<>();
		if (e.samples != null) {
			for (Sample s : e.samples) {
				out.add(s.line);
				out.add(s.line + s.line + s.line + s.line);
			}
		}
		char[] a = new char[MAX_LENGTH];
		Arrays.fill(a, 'a');
		out.add(new String(a));
		Arrays.fill(a, ' ');
		out.add(new String(a) + "!");
		return out;
	}

	static int flagsOf(Entry e) {
		int f = 0;
		if (e.flags != null) {
			for (String s : e.flags) {
				if ("CASE_INSENSITIVE".equals(s)) {
					f |= Pattern.CASE_INSENSITIVE;
				} else if ("DOTALL".equals(s)) f |= Pattern.DOTALL;
			}
		}
		return f;
	}

	static Map<String, Entry> entries() {
		return entries;
	}

	static final class BudgetExceeded extends RuntimeException {
		BudgetExceeded() {
			super(null, null, false, false);
		}
	}

	/** A CharSequence that gives up once the regex engine has read it too many times. */
	@RequiredArgsConstructor
	static final class Budgeted implements CharSequence {
		final String s;
		final long[] left;

		Budgeted(String s) {
			this(s, STEP_BUDGET);
		}

		Budgeted(String s, long budget) {
			this(s, new long[]{budget});
		}


		@Override
		public char charAt(int i) {
			if (--left[0] < 0) throw new BudgetExceeded();
			return s.charAt(i);
		}

		@Override
		public int length() {
			return s.length();
		}

		@Override
		public CharSequence subSequence(int start, int end) {
			return new Budgeted(s.substring(start, end), left);
		}

		@Override
		public String toString() {
			return s;
		}
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.Locale;

/**
 * Turns repeated reads of the Clan Coffer coin stack into auditable balance transitions.
 *
 * <p>The widget gives us the amount, not who moved it. A nearby server-authored chat line can name
 * the local player, but it is used only for attribution: the balance delta remains the source of
 * truth and an unconfirmed movement is still reported anonymously.</p>
 */
final class ClanCofferTracker {
	static final long ACTOR_WINDOW_MS = 15_000L;

	@RequiredArgsConstructor
	enum Kind {
		SNAPSHOT("snapshot"),
		DEPOSIT("deposit"),
		WITHDRAWAL("withdrawal");

		final String wire;

	}

	@RequiredArgsConstructor
	static final class Observation {
		final Kind kind;
		final int beforeBalance;
		final int afterBalance;
		final boolean actorConfirmed;

	}

	Integer lastBalance;
	Integer candidate;
	Kind recentSelfAction;
	long recentSelfActionAt;

	void reset() {
		lastBalance = null;
		candidate = null;
		recentSelfAction = null;
		recentSelfActionAt = 0L;
	}

	/** Remember a server-authored coffer line only when it names this account (or says “you”). */
	void onChatLine(String line, String localRsn, long now) {
		var action = selfAction(line, localRsn);
		if (action != null) {
			recentSelfAction = action;
			recentSelfActionAt = now;
		}
	}

	Observation observe(int balance, long now) {
		if (balance < 0) return null;
		// The coin stack can read empty for a tick while the container refreshes; a balance counts
		// only once two polls in a row agree on it.
		if (candidate == null || candidate != balance) {
			candidate = balance;
			return null;
		}
		if (lastBalance == null) {
			lastBalance = balance;
			return new Observation(Kind.SNAPSHOT, balance, balance, false);
		}
		int before = lastBalance;
		if (before == balance) return null;

		var kind = balance > before ? Kind.DEPOSIT : Kind.WITHDRAWAL;
		var confirmed = recentSelfAction == kind
			&& now >= recentSelfActionAt
			&& now - recentSelfActionAt <= ACTOR_WINDOW_MS;
		lastBalance = balance;
		// One chat line may explain one physical transition, never a later unrelated one.
		recentSelfAction = null;
		recentSelfActionAt = 0L;
		return new Observation(kind, before, balance, confirmed);
	}

	static Kind selfAction(String line, String localRsn) {
		if (line == null) return null;
		var plain = AnvilPlugin.MARKUP_TAG.matcher(line).replaceAll("").trim();
		var lower = plain.toLowerCase(Locale.ROOT);
		if (!lower.contains("coffer")) return null;
		var namesSelf = lower.startsWith("you ") || lower.startsWith("you've ");
		var self = Rsn.normalize(localRsn);
		if (!namesSelf && !self.isEmpty()) {
			var normalizedLine = Rsn.normalize(plain);
			namesSelf = normalizedLine.equals(self) || normalizedLine.startsWith(self + " ");
		}
		if (!namesSelf) return null;
		// "has/have deposited", "donated", "withdrew", "has/have withdrawn"…
		if (lower.contains("deposited") || lower.contains("donated")) return Kind.DEPOSIT;
		if (lower.contains("withdrew") || lower.contains("withdrawn")) return Kind.WITHDRAWAL;
		return null;
	}
}

package com.anvil;

import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.ToolTipManager;

/**
 * A label that says the rest of itself: when its text is cut short ("…") it shows the whole text as
 * its tooltip. A tooltip set on purpose still wins. Every label the panel draws is one of these, so
 * nothing truncated is ever unreadable.
 */
class ClipLabel extends JLabel {
	ClipLabel() {
		this("");
	}

	ClipLabel(String text) {
		super(text);
		ToolTipManager.sharedInstance().registerComponent(this);
	}

	ClipLabel(String text, int align) {
		super(text, align);
		ToolTipManager.sharedInstance().registerComponent(this);
	}

	@Override
	public String getToolTipText(MouseEvent e) {
		var own = super.getToolTipText(e);
		if (own != null) return own;
		var text = getText();
		if (text == null || text.isEmpty() || getWidth() <= 0 || getPreferredSize().width <= getWidth()) return null;
		// Shown as plain text: HTML labels wrap rather than clip, so a clipped one is plain already.
		return text.regionMatches(true, 0, "<html", 0, 5) ? null : Ui.wrapHtml(Ui.esc(text), 200);
	}
}

package com.anvil;

import java.awt.Toolkit;
import java.awt.datatransfer.*;
import lombok.extern.slf4j.Slf4j;

/**
 * Putting a path on the clipboard, which is as far as a hub plugin may go toward "open this folder".
 *
 * <p>RuneLite's LinkBrowser::open — the sanctioned way to hand a local path to the OS — is a
 * restricted API for plugin-hub releases, so the folder buttons can't launch a file manager. Copying
 * the path is the honest substitute: one paste into a file manager or a terminal, and nothing about
 * the plugin reaches outside its own directory.
 */
@Slf4j
final class Clipboards {
	Clipboards() {
	}

	/** True when the text made it onto the clipboard, so a caller can say so rather than assume. */
	static boolean copy(String value) {
		if (value == null || value.isEmpty()) return false;
		return set(new StringSelection(value));
	}

	static boolean set(Transferable contents) {
		try {
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(contents, null);
			return true;
		} catch (Exception e) {
			// A headless or locked-down desktop has no clipboard; the path still gets said out loud.
			return false;
		}
	}
}

package com.anvil;

import lombok.Getter;
import java.util.*;

/**
 * Collects a WHOLE collection log, as the server transmits it.
 *
 * <p>The client normally holds one page — whichever the player last drew — which is why the page
 * reader ({@link ClogPageReader}) can only ever report what someone has clicked through. But opening
 * the log and toggling its Search makes the server transmit EVERY entry, one script fire per item.
 * That's the whole log in one go, with no paging and nothing for the player to do but open the
 * interface. (Other plugins use the same technique.)
 *
 * <p>This class is the accumulator and the "have they stopped arriving yet" policy. It is
 * RuneLite-free on purpose: the awkward parts are the quiet period and the guards against half a
 * transmit being sent as if it were a log, and both are worth testing without a client.
 *
 * <p>Item ids only — no page names. The site owns the catalogue (src/data/clog.json) and maps ids to
 * pages on the way in, so a game update that shuffles pages is a dataset rebuild rather than a
 * plugin release.
 */
final class ClogFullSync {
	/**
	 * Items land over several ticks; wait this long after the last one before calling it complete.
	 * Two ticks and change — long enough that a transmit arriving in bursts isn't cut in half, short
	 * enough that a player who pressed a button isn't left watching an ellipsis.
	 */
	static final long QUIET_MS = 1_200;

	/**
	 * A transmit that yields fewer items than this is treated as noise rather than a log. The point
	 * is not to validate someone's collection — a genuinely empty log is possible — but to refuse to
	 * REPLACE a stored log with the tail end of an interrupted transmit (they closed the interface
	 * mid-flight, or another plugin's own search toggle fired one item).
	 */
	static final int MIN_ITEMS = 5;

	/** itemId -> quantity, in arrival order so a batch reads like the log does. */
	final Map<Integer, Integer> items = new LinkedHashMap<>();

	long lastItemAt;
	boolean receiving;
	/** Set when the player asked for this explicitly, so a no-change sync still gets sent + reported. */
	@Getter boolean manual;

	/** A transmit is starting (the log was opened / the button was pressed). Clears anything stale. */
	void begin(boolean manualRequest) {
		items.clear();
		receiving = true;
		manual = manual || manualRequest;
		lastItemAt = 0;
	}

	/** One item, straight off the transmit script. Ignored unless a transmit is actually in flight. */
	void onItem(int itemId, int quantity, long now) {
		if (!receiving || itemId <= 0) return;
		items.put(itemId, Math.max(1, quantity));
		lastItemAt = now;
	}

	/**
	 * Has a complete-looking transmit settled? True once nothing has arrived for {@link #QUIET_MS}
	 * and enough items landed to be a log rather than a fragment.
	 */
	boolean isDue(long now) {
		return receiving
			&& lastItemAt > 0
			&& items.size() >= MIN_ITEMS
			&& now - lastItemAt >= QUIET_MS;
	}

	/** Everything received, as an unmodifiable snapshot. Does not clear — see {@link #onSent}. */
	Map<Integer, Integer> snapshot() {
		return Collections.unmodifiableMap(new LinkedHashMap<>(items));
	}

	int size() {
		return items.size();
	}

	/**
	 * A cheap fingerprint of what was received, so an unchanged log isn't pushed twice.
	 *
	 * <p>The transmit re-sends everything every time the log is opened, and most opens change
	 * nothing. Order-independent (the game's transmit order is not ours to rely on) and includes
	 * quantities, so a second of the same item still counts as a change.
	 */
	synchronized long fingerprint() {
		long hash = items.size();
		for (Map.Entry<Integer, Integer> e : items.entrySet()) {
			// Mixed per entry then XORed in: adding an item changes it, and reordering doesn't.
			var h = e.getKey() * 0x9E3779B97F4A7C15L + e.getValue();
			hash ^= h ^ (h >>> 29);
		}
		return hash;
	}

	/** The push landed: drop the batch and stand down until the next transmit. */
	void onSent() {
		reset();
	}

	/**
	 * The push failed. Keeps the items so the next tick can retry, but stops the clock restarting —
	 * a site that is down must not cost the player their transmit.
	 */
	void onSendFailed(long now) {
		lastItemAt = now;
	}

	/** Account switch / logout: a half-received log belongs to nobody. */
	void reset() {
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}
}

package com.anvil;

import java.util.*;

/**
 * One collection-log page as the game drew it: the entry name, every item the account has obtained
 * on it, and the counters the log prints under the title ("Abyssal Sire kills: 1,204").
 *
 * <p>Deliberately RuneLite-free so the accumulator and its tests never need a client. Reading the
 * widgets is {@link ClogPageReader}'s job; deciding what to send is {@link ClogSync}'s.
 *
 * <p><b>Only obtained items are carried.</b> The site already ships the full 1,712-item catalogue
 * (src/data/clog.json), so the missing half is derivable — sending it would double every payload to
 * say "still nothing here".
 */
final class ClogPage {
	/** Entry title as the log prints it — "Abyssal Sire". The site maps it to its own page id. */
	final String name;
	/** Obtained item ids, in the order the log lists them. Parallel to {@link #quantities}. */
	final int[] itemIds;
	final int[] quantities;
	/** The log's own "Obtained: 5/9" pair — the site shows progress without owning the catalogue. */
	final int obtained;
	final int total;
	/** The counter lines under the title, label → value. Empty for pages that print none. */
	final Map<String, Integer> counts;
	/** 64-bit content hash — what makes "has this page changed?" a comparison, not a diff. */
	final long hash;

	ClogPage(String name, int[] itemIds, int[] quantities, int obtained, int total, Map<String, Integer> counts) {
		this.name = name;
		this.itemIds = itemIds;
		this.quantities = quantities;
		this.obtained = obtained;
		this.total = total;
		this.counts = counts == null || counts.isEmpty()
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new LinkedHashMap<>(counts));
		hash = computeHash();
	}

	/**
	 * FNV-1a over the page's contents.
	 *
	 * <p>Hand-rolled rather than {@code Objects.hash} / a JSON round-trip because this runs on the
	 * client thread every time the log redraws — which is every keystroke while a player scrolls the
	 * log. No boxing, no allocation, no string building; a page is folded in a few hundred nanoseconds
	 * and the result is what stops us re-sending 125 identical pages.
	 */
	long computeHash() {
		var h = 0xcbf29ce484222325L;
		h = fold(h, name == null ? 0 : name.hashCode());
		h = fold(h, obtained);
		h = fold(h, total);
		for (int i = 0; i < itemIds.length; i++) {
			h = fold(h, itemIds[i]);
			h = fold(h, quantities[i]);
		}
		for (Map.Entry<String, Integer> e : counts.entrySet()) {
			h = fold(h, e.getKey().hashCode());
			h = fold(h, e.getValue());
		}
		return h;
	}

	static long fold(long h, int value) {
		h ^= value;
		return h * 0x100000001b3L;
	}
}

package com.anvil;

import java.util.*;
import java.util.regex.*;
import net.runelite.api.Client;
import net.runelite.api.widgets.*;

/**
 * Reads the collection-log page the game is currently showing.
 *
 * <p>The client only ever holds ONE page — the log is drawn on demand, so an unopened page has no
 * items anywhere in memory. That's why a full sync means the player paging through their log once,
 * and why this is a read-what's-on-screen routine rather than a dump.
 *
 * <p><b>Self-verifying.</b> The header prints "Obtained: 5/9"; we count the items we believe are
 * obtained and only return a page when the two agree. A game update that changes how unobtained
 * items are drawn therefore makes this return null — the sync stalls and says so — instead of
 * quietly reporting that everybody lost half their collection log.
 *
 * <p>Runs on the client thread (its only caller is the COLLECTION_DRAW_LIST script hook), so it
 * allocates nothing beyond the page it returns and never blocks.
 */
final class ClogPageReader {
	ClogPageReader() {}

	/** "Obtained: 5/9" — the log's own progress line, and our correctness check. */
	static final Pattern OBTAINED = Pattern.compile("obtained:\\s*(\\d+)\\s*/\\s*(\\d+)");
	/** "Abyssal Sire kills: 1,204" / "Chest openings: 87" — label and value, commas stripped. */
	static final Pattern COUNT_LINE = Pattern.compile("^(.+?):\\s*([\\d,]+)$");
	/** Widget tags: the log wraps names in colour tags we don't want in the payload. */
	static final Pattern TAGS = Pattern.compile("<[^>]*>");

	/**
	 * The page on screen, or null when it isn't readable yet (mid-draw, empty, or the obtained
	 * count disagrees with what we read — see the class note).
	 */
	static ClogPage read(Client client) {
		var header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		var items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (header == null || items == null) return null;

		String name = null;
		int obtained = -1;
		int total = -1;
		// Allocated only if the page actually prints counters — most don't, and this runs on every
		// redraw of every page the player scrolls past.
		Map<String, Integer> counts = null;

		var lines = header.getStaticChildren();
		if (lines == null) return null;
		for (Widget line : lines) {
			if (line == null) continue;
			var text = strip(line.getText());
			if (text.isEmpty()) continue;
			// First non-empty line is the entry title; the rest are progress and counters.
			if (name == null) {
				name = text;
				continue;
			}
			var progress = OBTAINED.matcher(text.toLowerCase());
			if (progress.find()) {
				obtained = parseInt(progress.group(1));
				total = parseInt(progress.group(2));
				continue;
			}
			var count = COUNT_LINE.matcher(text);
			if (count.matches()) {
				int value = parseInt(count.group(2).replace(",", ""));
				if (value >= 0) {
					if (counts == null) counts = new LinkedHashMap<>(4);
					counts.put(count.group(1).trim(), value);
				}
			}
		}

		if (name == null || name.isEmpty() || obtained < 0 || total <= 0) return null;

		var cells = items.getDynamicChildren();
		if (cells == null) return null;

		// Two passes so the arrays are exactly sized — a page is at most a few dozen items, and this
		// avoids both an ArrayList's boxing and a grow-and-copy on every redraw.
		int found = 0;
		for (Widget cell : cells) {
			if (isObtained(cell)) found++;
		}
		// The log's own count is the authority. Disagreeing means we misread the page (or Jagex
		// changed the drawing); either way, committing it would corrupt a synced log.
		if (found != obtained) return null;

		int[] ids = new int[found];
		int[] quantities = new int[found];
		int i = 0;
		for (Widget cell : cells) {
			if (!isObtained(cell)) continue;
			ids[i] = cell.getItemId();
			// A quantity of 0 on an obtained item means "one, uncounted" for the handful of log
			// entries that predate stack tracking; storing 0 would read as "you don't have it".
			quantities[i] = Math.max(1, cell.getItemQuantity());
			i++;
		}

		return new ClogPage(name, ids, quantities, obtained, total, counts);
	}

	/**
	 * Whether a cell is an item the account has.
	 *
	 * <p>The log draws unobtained items dimmed (non-zero opacity) with no quantity; obtained ones are
	 * fully opaque and carry their count. Either signal alone has an edge case, so both are accepted
	 * and the header's "Obtained: N" arbitrates — see {@link #read}.
	 */
	static boolean isObtained(Widget cell) {
		if (cell == null || cell.getItemId() <= 0) return false;
		return cell.getOpacity() == 0 || cell.getItemQuantity() > 0;
	}

	static String strip(String raw) {
		if (raw == null) return "";
		// The regex is the expensive part and most lines carry no tags at all — one scan for '<'
		// saves building a Matcher on every header line of every redraw.
		if (raw.indexOf('<') < 0) return raw.trim();
		return TAGS.matcher(raw).replaceAll("").trim();
	}

	static int parseInt(String raw) {
		try {
			return Integer.parseInt(raw);
		} catch (NumberFormatException e) {
			return -1;
		}
	}
}

package com.anvil;

import java.util.*;
import java.util.function.*;

/**
 * Decides what of the collection log is worth sending, and when.
 *
 * <p>The game redraws a log page on every scroll, filter and tab click, so the naive "push what's on
 * screen" would be hundreds of identical requests per session. This keeps a hash per page and only
 * queues one that actually changed, then batches the queue behind a quiet period.
 *
 * <p>The hashes of pages we've already sent are persisted (see {@link #serializeState}), so logging
 * back in and opening the log doesn't re-send a log that hasn't moved. That's the difference between
 * a sync that costs one request a week and one that costs a request a minute forever.
 *
 * <p>RuneLite-free on purpose: the flush policy is the part with edge cases, and this way it's
 * unit-testable without a client. The plugin owns the widget hook, the scheduler and the HTTP.
 */
final class ClogSync {
	/** Wait this long after the last change before sending — a player paging through settles first. */
	static final long QUIET_MS = 2_500;
	/** Send at most this many pages per request; a full first sync becomes a handful of them. */
	static final int BATCH_PAGES = 25;
	/** Queue this many and go early — a bulk sync shouldn't sit waiting on the quiet timer. */
	static final int EAGER_AT = BATCH_PAGES;

	/** Last hash we successfully sent, per page name. The persisted half of the state. */
	final Map<String, Long> sent = new HashMap<>();
	/** Changed pages awaiting a push, newest write wins. Insertion-ordered so batches are stable. */
	final Map<String, ClogPage> pending = new LinkedHashMap<>();

	long lastChangeAt;

	/**
	 * Offer the page currently on screen. Cheap and idempotent — the common case is a hash compare
	 * against what we already sent, and no allocation at all.
	 *
	 * @return true when the page was queued (i.e. it's new or changed)
	 */
	boolean offer(ClogPage page, long now) {
		if (page == null || page.name == null || page.name.isEmpty()) return false;
		var alreadySent = sent.get(page.name);
		if (alreadySent != null && alreadySent == page.hash) return false;
		var queued = pending.get(page.name);
		if (queued != null && queued.hash == page.hash) return false;
		pending.put(page.name, page);
		lastChangeAt = now;
		return true;
	}

	/** Whether a flush should run now: the queue has settled, or it's big enough to go early. */
	boolean isDue(long now) {
		if (pending.isEmpty()) return false;
		return pending.size() >= EAGER_AT || now - lastChangeAt >= QUIET_MS;
	}

	/** Pages to send in the next request, oldest first. Does NOT clear them — see {@link #onSent}. */
	List<ClogPage> nextBatch() {
		List<ClogPage> batch = new ArrayList<>(Math.min(BATCH_PAGES, pending.size()));
		for (ClogPage page : pending.values()) {
			batch.add(page);
			if (batch.size() >= BATCH_PAGES) break;
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Only called after the server has accepted it, so a failed push leaves
	 * the pages queued and the next flush retries them — no bookkeeping, no lost pages.
	 */
	void onSent(Collection<ClogPage> batch) {
		for (ClogPage page : batch) {
			var queued = pending.get(page.name);
			// Left queued if it changed again while the request was in flight.
			if (queued != null && queued.hash == page.hash) pending.remove(page.name);
			sent.put(page.name, page.hash);
		}
	}

	int pendingCount() {
		return pending.size();
	}

	/** How many distinct pages we've delivered — the numerator of the "68% synced" nudge. */
	int syncedPages() {
		return sent.size();
	}

	/** Forget everything. Called when the account changes — one player's log is not another's. */
	void reset() {
		sent.clear();
		pending.clear();
		lastChangeAt = 0;
	}

	/**
	 * The sent-hash map as one config string: {@code <hex hash>|<page name>} per line.
	 *
	 * <p>Hash first, split on the first pipe: page names contain colons ("Chambers of Xeric:
	 * Challenge Mode") and spaces, so a name-first format would need escaping. A hex hash can't
	 * contain a pipe, which makes the parse total.
	 */
	String serializeState() {
		return writeLines(sent, Long::toHexString);
	}

	/** {@code <value>|<name>} per line — the shape this and {@link PersonalBests} persist. */
	static <V> String writeLines(Map<String, V> map, Function<V, String> value) {
		var out = new StringBuilder(map.size() * 24);
		for (Map.Entry<String, V> e : map.entrySet()) {
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0) continue;
			if (out.length() > 0) out.append('\n');
			out.append(value.apply(e.getValue())).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/** Each well-formed {@link #writeLines} line as (value, name); a line whose value won't parse is skipped. */
	static void readLines(String raw, BiConsumer<String, String> line) {
		if (raw == null || raw.isEmpty()) return;
		for (String l : raw.split("\n")) {
			int pipe = l.indexOf('|');
			if (pipe <= 0 || pipe == l.length() - 1) continue;
			try {
				line.accept(l.substring(0, pipe), l.substring(pipe + 1));
			} catch (NumberFormatException e) {
				// A truncated or hand-edited config line: drop it and let it re-sync.
			}
		}
	}

	/** Restore from {@link #serializeState}. Junk lines are skipped, never fatal. */
	void restoreState(String raw) {
		sent.clear();
		readLines(raw, (hash, page) -> sent.put(page, Long.parseUnsignedLong(hash, 16)));
	}
}

package com.anvil;

import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.extern.slf4j.Slf4j;

/**
 * A debounced push of ABSOLUTE counts — skill XP, boss kill counts, activity counters.
 *
 * <p>Values are queued per key and one request goes out once they stop moving, so a kill streak or
 * a training burst collapses into a single push of the newest numbers. Absolute values make a resend
 * harmless, which is what makes failure simple: the batch is folded back in (max-merged, so a newer
 * number queued meanwhile wins) and tried again — after a wait that doubles per failure up to
 * {@link #RETRY_CAP_MS}, so a site that is down isn't asked every 15 seconds. A permanent refusal
 * (a 4xx other than 401/408/429) drops the batch instead: resending it would never work. The network
 * send runs on the plugin's executor; nothing here touches the client thread.
 */
@Slf4j
final class CoalescedPush {
	interface Sender {
		void send(Map<String, Integer> batch) throws IOException;
	}

	final String what;
	final long delayMs;
	final Supplier<ScheduledExecutorService> executor;
	final BooleanSupplier allowed;
	final Sender sender;
	final Runnable afterSend;
	/** What the site last accepted, when only a RISE is worth sending; null to send every value. */
	final Map<String, Integer> sent;
	final Map<String, Integer> pending = new HashMap<>();
	ScheduledFuture<?> task;
	/** Failed sends since the last success; 0 = healthy. Drives the retry wait. */
	int failures;
	/** When the oldest unsent value was queued; 0 while nothing is waiting. */
	long holdingSince;
	/**
	 * Longest a value waits for the streak to settle. The settle timer restarts on every new value,
	 * so without a cap a non-stop skilling session (an XP drop every few seconds) never paused long
	 * enough to push at all: the site, the tracker and teammates saw nothing until the member stopped.
	 */
	static final long MAX_HOLD_MS = 60_000L;
	/** Longest wait between retries while the site keeps failing. */
	static final long RETRY_CAP_MS = 300_000L;

	CoalescedPush(String what, long delayMs, boolean onlyRises, Supplier<ScheduledExecutorService> executor,
		BooleanSupplier allowed, Sender sender, Runnable afterSend) {
		this.what = what;
		this.delayMs = delayMs;
		sent = onlyRises ? new HashMap<>() : null;
		this.executor = executor;
		this.allowed = allowed;
		this.sender = sender;
		this.afterSend = afterSend;
	}

	void queue(String key, int value) {
		queue(Collections.singletonMap(key, value));
	}

	/** Buffer {@code values} and restart the settle timer — unless nothing in them is new. */
	synchronized void queue(Map<String, Integer> values) {
		var ex = executor.get();
		if (ex == null || ex.isShutdown()) return;
		var queued = false;
		for (Map.Entry<String, Integer> e : values.entrySet()) {
			var last = sent == null ? null : sent.get(e.getKey());
			if (last == null || last < e.getValue()) {
				pending.put(e.getKey(), e.getValue());
				queued = true;
			}
		}
		// While backing off, new values ride the retry that's already waiting rather than pulling it
		// forward to the settle delay — a training session would otherwise retry every 15s regardless.
		if (queued && holdingSince == 0) holdingSince = System.currentTimeMillis();
		if (queued && !(failures > 0 && task != null && !task.isDone())) schedule(ex, settleWait(System.currentTimeMillis(), holdingSince, delayMs));
	}

	/** What's waiting to go — for saving across a logout or restart. */
	synchronized Map<String, Integer> snapshot() {
		return new HashMap<>(pending);
	}

	/**
	 * Fold saved values back in. They're absolute, so the larger of saved and queued wins per key —
	 * the same merge a failed send uses.
	 */
	synchronized void restore(Map<String, Integer> values) {
		if (values == null || values.isEmpty()) return;
		values.forEach((k, v) -> {
			if (k != null && v != null) pending.merge(k, v, Integer::max);
		});
		var ex = executor.get();
		if (ex != null && !ex.isShutdown()) schedule(ex, delayMs);
	}

	/** Send what's waiting now (a value that completes a tile) — unless backing off a failing site. */
	synchronized void sendNow() {
		var ex = executor.get();
		if (pending.isEmpty() || failures > 0 || ex == null || ex.isShutdown()) return;
		schedule(ex, 0);
	}

	/** The site is reachable again: send what's waiting now instead of sitting out the backoff. */
	synchronized void kick() {
		if (failures == 0 || pending.isEmpty()) return;
		failures = 0;
		var ex = executor.get();
		if (ex != null && !ex.isShutdown()) schedule(ex, 0);
	}

	/** Forget everything queued (and sent) — a new account, or the plugin stopping. */
	synchronized void reset() {
		pending.clear();
		holdingSince = 0;
		failures = 0;
		if (sent != null) sent.clear();
		if (task != null) {
			task.cancel(false);
			task = null;
		}
	}

	void schedule(ScheduledExecutorService ex, long waitMs) {
		if (task != null) task.cancel(false);
		task = ex.schedule(this::flush, waitMs, TimeUnit.MILLISECONDS);
	}

	/** The settle delay, cut short so nothing waits past {@link #MAX_HOLD_MS} from {@code holdingSince}. */
	static long settleWait(long now, long holdingSince, long delayMs) {
		return Math.max(0, Math.min(delayMs, holdingSince + MAX_HOLD_MS - now));
	}

	/** The wait before the next retry after {@code failures} straight failures. First retry = the settle delay. */
	static long retryDelayMs(int failures, long settleMs, double jitter) {
		return RetryPolicy.backoffMs(failures, settleMs, Math.max(settleMs, RETRY_CAP_MS), jitter);
	}

	/** Send the buffer (no screenshot). Requeues on failure. */
	void flush() {
		Map<String, Integer> batch;
		synchronized (this) {
			if (pending.isEmpty()) return;
			batch = new HashMap<>(pending);
			pending.clear();
			holdingSince = 0;
		}
		if (!allowed.getAsBoolean()) {
			return; // stopped being allowed between queue and flush — the hiscores side still has it
		}
		try {
			sender.send(batch);
		} catch (BingoApiClient.PermanentSubmissionException e) {
			// The site will never take this batch (a 4xx that isn't 401/408/429). Drop it rather than
			// resend it forever; newer values queued meanwhile still go on their own.
			log.warn("{} push refused: {}", what, e.getMessage());
			synchronized (this) {
				failures = 0;
			}
			return;
		} catch (IOException e) {
			synchronized (this) {
				failures++;
				batch.forEach((k, v) -> pending.merge(k, v, Integer::max));
				var wait = retryDelayMs(failures, delayMs, Math.random());
				log.warn("{} push failed, retry in {}s: {}", what, wait / 1000, e.getMessage());
				var ex = executor.get();
				if (ex != null && !ex.isShutdown()) schedule(ex, wait);
			}
			return;
		}
		synchronized (this) {
			failures = 0;
			if (sent != null) batch.forEach((k, v) -> sent.merge(k, v, Integer::max));
		}
		afterSend.run(); // pull back the updated progress / any completion the push triggered
	}
}

package com.anvil;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import java.util.Locale;
import net.runelite.api.gameval.VarbitID;

/**
 * The six Combat Achievement tiers, with the point value awarded for a task at that tier and the
 * varbit holding the cumulative points needed to unlock the tier's rewards. Used to detect both
 * individual task completions (chat message gives the tier name) and tier unlocks (a task pushing
 * total points across a threshold).
 */
@RequiredArgsConstructor
public enum CombatAchievementTier {
	EASY(VarbitID.CA_THRESHOLD_EASY),
	MEDIUM(VarbitID.CA_THRESHOLD_MEDIUM),
	HARD(VarbitID.CA_THRESHOLD_HARD),
	ELITE(VarbitID.CA_THRESHOLD_ELITE),
	MASTER(VarbitID.CA_THRESHOLD_MASTER),
	GRANDMASTER(VarbitID.CA_THRESHOLD_GRANDMASTER);

	@Getter final int thresholdVarbitId;


	/** "Easy" … "Grandmaster". */
	public String getDisplayName() {
		return name().charAt(0) + name().substring(1).toLowerCase(Locale.ROOT);
	}

	@Override
	public String toString() {
		return getDisplayName();
	}

	/** Resolves the tier from the word used in the completion message ("easy", "elite", …). */
	public static CombatAchievementTier byName(String name) {
		if (name == null) return null;
		for (CombatAchievementTier t : values()) {
			if (t.name().equalsIgnoreCase(name)) return t;
		}
		return null;
	}
}

package com.anvil;

import java.util.*;

/**
 * What killed us — as opposed to what we were killing.
 *
 * <p>The feed used to answer this with the last thing we landed a hit on, which is the only thing
 * the client volunteers and is wrong exactly when it matters. It reads fine at a boss, because the
 * boss you are hitting is the boss hitting you; it reads as nonsense the moment those differ, which
 * is why the clan feed filled up with "died to Abyssal portal", "died to Volatile earth" and, best
 * of all, "died to Jug". Those are things a player attacked. None of them killed anybody.
 *
 * <p>The game will not simply tell us. A hitsplat carries a type and an amount and no attacker
 * ({@link net.runelite.api.Hitsplat}), so "who dealt that damage" is not a question the API answers.
 * What it does answer is who is TARGETING us: an NPC or player acquiring us fires an interaction
 * change naming itself. So the killer is inferred from the things that had us in their sights when
 * we last took damage, which is a different guess from the old one and wrong in far fewer places.
 *
 * <p>When nothing was on us — a mechanic, a fall, poison after the fight — the answer is null and
 * the feed says only that someone died. That is a deliberate downgrade from the old behaviour: a
 * death with no killer is a smaller story than a death with the wrong one.
 *
 * <p>Pure and RuneLite-free so it is unit-tested directly (DeathAttributionTest). The plugin feeds
 * it names; it never holds an Actor, which would keep a dead NPC alive for as long as we did.
 */
final class DeathAttribution {
	/**
	 * How long an attacker stays a candidate after we last took a hit. Long enough to cover the
	 * gap between a killing blow and the death animation, short enough that the thing that killed
	 * us half a minute ago in another fight is not still on the list.
	 */
	static final long DAMAGE_WINDOW_MS = 15_000;

	/** Nothing sane has this many things attacking it; the cap is against a leak, not a crowd. */
	static final int MAX_ATTACKERS = 24;

	/** Who has us targeted, and when they acquired us. Insertion-ordered so "most recent" is cheap. */
	final Map<String, Long> attackers = new LinkedHashMap<>();
	/** Which of {@link #attackers} are players rather than NPCs. */
	final Set<String> players = new HashSet<>();

	/** When we last took damage from something other than ourselves. */
	long lastDamageAt;

	/**
	 * Something acquired us as its target.
	 *
	 * <p>Re-acquiring refreshes the timestamp: an NPC that switches away and back is a better
	 * candidate than one that has been plinking at us since the start of the fight, because the
	 * thing that just turned to face you is the thing that just started hitting you.
	 */
	synchronized void targetedUs(String name, boolean player, long nowMs) {
		if (name == null || name.isEmpty()) return;
		attackers.remove(name); // re-insert so iteration order stays "oldest first"
		attackers.put(name, nowMs);
		if (player) {
			players.add(name);
		} else players.remove(name);
		while (attackers.size() > MAX_ATTACKERS) stoppedTargetingUs(attackers.keySet().iterator().next());
	}

	/** Something stopped targeting us — it is no longer a candidate for killing us. */
	synchronized void stoppedTargetingUs(String name) {
		if (name == null) return;
		attackers.remove(name);
		players.remove(name);
	}

	/** Whether {@code name}, as {@link #killer} returned it, is a player that had us targeted. */
	synchronized boolean isPlayer(String name) {
		return name != null && players.contains(name);
	}

	/** We took a hit from something other than ourselves. Only the timing matters; see the class doc. */
	synchronized void tookDamage(long nowMs) {
		lastDamageAt = nowMs;
	}

	/** Forget everything. A new login, a new region, a fresh death — none of it carries over. */
	synchronized void clear() {
		attackers.clear();
		players.clear();
		lastDamageAt = 0;
	}

	/**
	 * The killer, or null when nothing can honestly be named.
	 *
	 * <p>Two rules, in order:
	 *
	 * <ol>
	 *   <li>if one of the things targeting us is the thing we were fighting, it is that one — a
	 *       mutual fight is the least ambiguous case there is, and it is most deaths;
	 *   <li>otherwise the one that acquired us most recently, because in a room where several
	 *       things are on you the one that just turned to face you is the one that finished it.
	 * </ol>
	 *
	 * <p>Null when nothing had us targeted, or when the last damage we took is too old to connect
	 * to this death at all.
	 *
	 * @param weWereFighting the last thing we landed a hit on, used only to break a tie
	 */
	synchronized String killer(String weWereFighting, long nowMs) {
		if (lastDamageAt <= 0 || nowMs - lastDamageAt > DAMAGE_WINDOW_MS || attackers.isEmpty()) return null;
		if (weWereFighting != null && !weWereFighting.isEmpty()) {
			for (String name : attackers.keySet()) {
				if (Rsn.same(name, weWereFighting)) return name;
			}
		}
		String newest = null;
		var newestAt = Long.MIN_VALUE;
		for (Map.Entry<String, Long> entry : attackers.entrySet()) {
			if (entry.getValue() >= newestAt) {
				newestAt = entry.getValue();
				newest = entry.getKey();
			}
		}
		return newest;
	}

	/** How many players had us targeted when we died (the site's "ganged by N players"); 0 once the last hit is stale. */
	synchronized int players(long nowMs) {
		if (lastDamageAt <= 0 || nowMs - lastDamageAt > DAMAGE_WINDOW_MS) return 0;
		int n = 0;
		for (String name : attackers.keySet()) {
			if (players.contains(name)) n++;
		}
		return n;
	}

	/** How many things currently have us targeted — for the log line that explains an attribution. */
	synchronized int attackerCount() {
		return attackers.size();
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.net.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * The plugin's "Sign in with Discord" — the home-native device-code flow (site: /api/plugin/auth/*).
 * Start → open the home's /link-device page in the member's browser → poll until approved → hand the
 * account token to the caller to store. Asynchronous: every step runs on the scheduler (approval polls
 * paced by delayed rescheduling, never a sleeping thread) and BOTH callbacks arrive on that executor
 * thread — marshal to the EDT before touching Swing. {@code done} fires exactly once.
 *
 * <p><b>Security:</b> no local listener — completion is detected purely by polling the home. The
 * browser URL is pinned to the CONFIGURED home origin (the one host the member explicitly typed
 * into the plugin config) + the fixed {@code /link-device} path: same anti-phishing shape as the
 * federation broker pin, anchored to user intent instead of a hardcoded host, which is what lets
 * this work for hosted, self-hosted, and fully-standalone sites alike.</p>
 */
@RequiredArgsConstructor
@Slf4j
public final class DeviceSignIn {
	/** Fixed path of the approval page on the home site — the only page this flow will ever open. */
	static final String LINK_PATH = "/link-device";

	/** Fallback pacing/deadline when the server response omits them. */
	static final int DEFAULT_INTERVAL_S = 5;
	static final int DEFAULT_EXPIRES_S = 600;

	public enum Outcome {
		SIGNED_IN, DENIED, EXPIRED, UNAVAILABLE
	}

	/** Result: outcome + the account token when {@link Outcome#SIGNED_IN}. */
	@RequiredArgsConstructor
	public static final class Result {
		public final Outcome outcome;
		public final String token;

	}

	final BingoApiClient apiClient;
	final BrowserOpener browserOpener;
	final PollScheduler scheduler;
	// Polling runs on RuneLite's shared executor, which outlives the plugin, so stopping it is ours to do.
	volatile boolean cancelled;

	/** Production binding — real system browser + delayed steps on the shared client executor. */
	public DeviceSignIn(BingoApiClient apiClient, ScheduledExecutorService executor) {
		this(apiClient, DeviceSignIn::browse,
			(step, delayMs) -> executor.schedule(step, delayMs, TimeUnit.MILLISECONDS));
	}

	/** Test seam — injectable browser opener + scheduler so the flow runs offline and fast. */

	/**
	 * Ask the desktop to open the sign-in page.
	 *
	 * <p>Returns whether we ASKED without throwing, which is all RuneLite lets us know:
	 * LinkBrowser.browse is void, so a browser that never appeared and one that opened fine are the
	 * same call from here. Everything downstream is written so that distinction doesn't matter — the
	 * address and the code go on screen either way.
	 */
	static boolean browse(String url) {
		LinkBrowser.browse(url);
		return true;
	}

	/** Run the whole flow. {@code status} receives short human-readable progress lines for the UI;
	 * {@code done} the terminal {@link Result}. Both called on the executor thread. */
	public void run(Consumer<String> status, Consumer<Result> done) {
		// The first step runs on the executor too — authStart is network I/O, keep it off the EDT.
		schedule(() -> start(status, done), 0, status, done);
	}

	void start(Consumer<String> status, Consumer<Result> done) {
		var start = apiClient.authStart();
		if (start == null || start.device_code == null || start.device_code.isEmpty()) {
			fail(status, done, "Couldn't reach " + SetupNudge.SITE_HOST + " — check your connection and try again.", Outcome.UNAVAILABLE);
			return;
		}

		var url = start.verification_url_complete != null && !start.verification_url_complete.isEmpty()
			? start.verification_url_complete : start.verification_url;
		// Checked against the fixed site, not the client's address — that stays empty until there is a
		// token (BingoApiClient.configure), which is exactly the state sign-in runs in.
		if (!isConfiguredHomeUrl(BingoApiClient.site(), url)) {
			// A response steering the browser anywhere but the member's own configured site is hostile.
			log.warn("Off-site sign-in URL: {}", url);
			fail(status, done, "Sign-in blocked — the site returned a suspicious login page.", Outcome.UNAVAILABLE);
			return;
		}
		// The address is on screen whether or not the browser opened. We can't tell the difference
		// (see browse), and the failure mode of assuming success is a player staring at a code with
		// nowhere to type it — while the cost of saying both is one extra clause.
		if (!browserOpener.open(url)) {
			status.accept("Couldn't open your browser — visit " + url + " and enter " + start.user_code + ".");
		} else status.accept("Approve code " + start.user_code + " in your browser. If it didn't open: " + url);

		var intervalMs = Math.max(1, start.interval > 0 ? start.interval : DEFAULT_INTERVAL_S) * 1000L;
		var deadline = System.currentTimeMillis()
			+ (start.expires_in > 0 ? start.expires_in : DEFAULT_EXPIRES_S) * 1000L;
		poll(status, done, start.device_code, intervalMs, deadline);
	}

	/** One scheduled approval poll; reschedules itself (server {@code slow_down} stretches the delay)
	 * until a terminal status or the deadline. */
	void poll(Consumer<String> status, Consumer<Result> done, String deviceCode, long intervalMs, long deadline) {
		if (System.currentTimeMillis() >= deadline) {
			fail(status, done, "The code expired — try again.", Outcome.EXPIRED);
			return;
		}
		schedule(() -> {
			var nextIntervalMs = intervalMs;
			var poll = apiClient.authPoll(deviceCode);
			if (poll != null && poll.status != null) {
				switch (poll.status) {
					case "complete":
						if (poll.token != null && !poll.token.isEmpty()) {
							status.accept("Signed in.");
							done.accept(new Result(Outcome.SIGNED_IN, poll.token));
						} else done.accept(new Result(Outcome.UNAVAILABLE, null));
						return;
					case "denied":
						fail(status, done, "Sign-in denied on the site.", Outcome.DENIED);
						return;
					case "expired":
						fail(status, done, "The code expired — try again.", Outcome.EXPIRED);
						return;
					case "slow_down":
						nextIntervalMs = Math.max(intervalMs, Math.max(1, poll.interval) * 1000L);
						break;
					default: // pending (a null/blank poll is a transient blip — keep polling until the deadline)
						break;
				}
			}
			poll(status, done, deviceCode, nextIntervalMs, deadline);
		}, intervalMs, status, done);
	}

	/** Schedule a flow step; an escaped {@link RuntimeException} would otherwise vanish inside the
	 * executor, so surface it as the terminal failure. */
	static void fail(Consumer<String> status, Consumer<Result> done, String message, Outcome outcome) {
		status.accept(message);
		done.accept(new Result(outcome, null));
	}

	/** Stop polling: any step not yet run is skipped and the callbacks never fire. */
	public void cancel() {
		cancelled = true;
	}

	void schedule(Runnable step, long delayMs, Consumer<String> status, Consumer<Result> done) {
		scheduler.schedule(() -> {
			if (cancelled) return;
			try {
				step.run();
			} catch (RuntimeException e) {
				fail(status, done, "Sign-in failed — try again.", Outcome.UNAVAILABLE);
			}
		}, delayMs);
	}

	/**
	 * True only for an HTTPS/HTTP URL on the EXACT home origin (scheme + host + port all matching
	 * {@link BingoApiClient#CANONICAL_SITE}) with the fixed {@link #LINK_PATH} path. No credentials.
	 * HTTP is tolerated only when the home itself is HTTP (local dev builds).
	 */
	static boolean isConfiguredHomeUrl(String configuredApiUrl, String url) {
		if (configuredApiUrl == null || configuredApiUrl.isEmpty() || url == null || url.isEmpty()) return false;
		try {
			var home = new URI(configuredApiUrl);
			var target = new URI(url);
			return target.getScheme() != null && target.getHost() != null && target.getUserInfo() == null
				&& target.getScheme().equalsIgnoreCase(home.getScheme())
				&& target.getHost().equalsIgnoreCase(home.getHost()) && target.getPort() == home.getPort()
				&& target.getPath() != null && target.getPath().startsWith(LINK_PATH);
		} catch (URISyntaxException e) {
			return false;
		}
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.*;
import net.runelite.client.util.Filepath;

/**
 * The few disk primitives the caches and the outbox share, all through RuneLite's {@link Filepath}.
 *
 * <p>Writes are atomic: the bytes go to a temp sibling first and are then renamed over the target, so
 * a client killed mid-write leaves the previous copy (or nothing), never half a JSON file. Every
 * method here blocks on disk — callers run them on the plugin executor, never the client thread.
 */
final class DiskFiles {
	DiskFiles() {
	}

	/** {@code dir}, created on demand; null when it can't be. */
	static Filepath ensureDir(Filepath dir) {
		if (dir == null) return null;
		try {
			if (!dir.exists()) dir.createDirectories();
			return dir;
		} catch (IOException | RuntimeException e) {
			return null;
		}
	}

	static void writeAtomic(Filepath target, byte[] data) throws IOException {
		OffThread.check("disk write");
		var tmp = target.getParent().joinSegment(target.getFileName() + ".tmp");
		tmp.write(data);
		try {
			tmp.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		} catch (AtomicMoveNotSupportedException e) {
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	static void writeAtomic(Filepath target, String text) throws IOException {
		writeAtomic(target, text.getBytes(StandardCharsets.UTF_8));
	}

	/** The file's bytes, or null when it is missing or unreadable. */
	static byte[] read(Filepath file) {
		OffThread.check("disk read");
		if (file == null || !file.isFile()) return null;
		try (InputStream in = file.openInputStream()) {
			return in.readAllBytes();
		} catch (IOException | RuntimeException e) {
			return null;
		}
	}

	static String readText(Filepath file) {
		var b = read(file);
		return b == null ? null : new String(b, StandardCharsets.UTF_8);
	}

	/** The file as a {@code type}, or null when it is missing, empty or not valid JSON (a truncated write). */
	static <T> T readJson(Gson gson, Filepath file, Class<T> type) {
		var text = readText(file);
		try {
			return text == null ? null : gson.fromJson(text, type);
		} catch (RuntimeException e) {
			return null;
		}
	}

	/** The files directly in {@code dir} whose names pass {@code name}; empty when there is no listing. */
	static List<Filepath> listFiles(Filepath dir, Predicate<String> name) {
		if (dir == null) return new ArrayList<>();
		try (Stream<Filepath> walk = dir.walk(1)) {
			return walk.filter(f -> f.isFile() && name.test(f.getFileName())).collect(Collectors.toList());
		} catch (IOException | RuntimeException e) {
			return new ArrayList<>();
		}
	}

	static void deleteQuietly(Filepath file) {
		if (file == null) return;
		try {
			file.deleteIfExists();
		} catch (IOException | RuntimeException ignored) {
			// Best effort: a leftover file is pruned by age on the next load.
		}
	}

	/**
	 * A short, stable, filename-safe stand-in for something that must never appear on disk itself
	 * (an Account Token) or that shouldn't be readable from a directory listing (a character).
	 */
	static String fingerprint(String secret) {
		if (secret == null || secret.trim().isEmpty()) return "";
		try {
			var digest = MessageDigest.getInstance("SHA-256").digest(secret.trim().getBytes(StandardCharsets.UTF_8));
			var sb = new StringBuilder();
			for (int i = 0; i < 8; i++) sb.append(String.format("%02x", digest[i]));
			return sb.toString();
		} catch (NoSuchAlgorithmException e) {
			throw new IllegalStateException(e);
		}
	}
}

package com.anvil;

import java.util.*;
import java.util.regex.Pattern;

/**
 * The reader for the server's {@code dropFacts}: which monster a pet is really from, and
 * whether an item was ever a roll at all. Both are the server's to know (a new boss is a dataset
 * regen there, a release here), so everything below degrades to the old behaviour on a null.
 *
 * <p>Pure and RuneLite-free, so it is unit-tested directly (DropSourceTest).
 */
final class DropSource {
	static final Pattern WIKI_QUALIFIER = Pattern.compile("\\s*\\([^)]*\\)\\s*$");

	DropSource() {
	}

	/**
	 * The in-game name for a wiki NPC name. The wiki tells same-named monsters apart with a
	 * parenthetical ("Armoured zombie (Zemouregal's Fort)"), but the game reports them all as plain
	 * "Armoured zombie", so a tile picked from the wiki list never matched. In-game NPC names carry
	 * no parentheses, so dropping the qualifier loses nothing that could have matched.
	 */
	static String inGameNpcName(String wikiName) {
		return wikiName == null ? null : WIKI_QUALIFIER.matcher(wikiName).replaceFirst("").trim();
	}



	/** True when the reported loot {@code source} is one of a tile's configured (wiki-named) NPCs. */
	static boolean sourceMatches(List<String> sourceNpcs, String source) {
		if (source == null || sourceNpcs == null) return false;
		for (String npc : sourceNpcs) {
			if (npc != null && (source.equalsIgnoreCase(npc) || source.equalsIgnoreCase(inGameNpcName(npc)))) return true;
		}
		return false;
	}

	/** The server's entry for a pet, or null when it has nothing to say about it. */
	static PluginConfigResponse.DropFacts.Pet petEntry(PluginConfigResponse.DropFacts facts, String petName) {
		if (facts == null || facts.pets == null || petName == null) return null;
		return facts.pets.get(petName.toLowerCase(Locale.ROOT).trim());
	}

	/**
	 * Which monster this pet actually came from.
	 *
	 * <p>A pet fires no loot event, so the only thing the client can offer is whatever loot it
	 * happened to see last — a minion, a stray kill, the chest rather than the raid. The pet's name
	 * is the reliable key, and the server holds the map from it. The rules, in order:
	 *
	 * <ol>
	 *   <li>if the loot the client saw IS one of the pet's real sources, that one — it is the most
	 *       specific answer available and disambiguates a pet with several (Vet'ion / Calvar'ion);
	 *   <li>if the pet has exactly one source, that one, whatever the client thought;
	 *   <li>otherwise the source the player has the most kills at, which is the likeliest of them;
	 *   <li>failing all of that, the pet's first listed source, and if there are none, null — a
	 *       skilling pet has no monster and a made-up one is worse than a shorter post.
	 * </ol>
	 *
	 * @param observed  the loot source the client saw around the drop; may be null
	 * @param killCount source name -> the player's kill count there, for the tie-break; may be null
	 */
	static String resolvePetSource(PluginConfigResponse.DropFacts facts, String petName, String observed,
								   Map<String, Integer> killCount) {
		var pet = petEntry(facts, petName);
		// Nothing known about this pet: an older site, or a pet the catalogue has not placed.
		// The observed source is then the best guess there is, which is where we started.
		if (pet == null || pet.sources == null || pet.sources.isEmpty()) return pet == null ? observed : null;
		var sources = pet.sources;
		if (observed != null && !observed.trim().isEmpty()) {
			for (String candidate : sources) {
				if (candidate.equalsIgnoreCase(observed.trim())) return candidate;
			}
		}
		if (sources.size() == 1) return sources.get(0);
		String best = null;
		int bestKc = -1;
		Map<String, Integer> counts = killCount == null ? Collections.emptyMap() : killCount;
		for (String candidate : sources) {
			Integer kc = counts.get(candidate.toLowerCase(Locale.ROOT));
			int value = kc == null ? -1 : kc;
			if (value > bestKc) {
				bestKc = value;
				best = candidate;
			}
		}
		return best != null ? best : sources.get(0);
	}
}

package com.anvil;

import java.util.*;
import java.util.function.Predicate;
import net.runelite.api.gameval.ItemID;

/**
 * Which item a "funny feeling" line was about.
 *
 * <p>A duplicate pet ("…would have been followed") and a duplicate champion's scroll ("…would have
 * received a Champion's scroll") name nothing: there is no item, no loot event and no collection-log
 * line. What the player was doing names it. A pet comes from what was just killed or looted, or from
 * the skill just trained; a champion's scroll comes from exactly one kind of monster.
 *
 * <p>Every answer here is a guess the site flags for staff, so ambiguity returns null rather than a
 * pick: a wrong credit costs a reviewer more than a manual proof does.
 */
final class DuplicateInference {
	DuplicateInference() {
	}

	/** The one pet {@code source} drops, or null when it drops none or several. */
	static String petForSource(PluginConfigResponse.DropFacts facts, String source) {
		var want = source == null ? "" : source.trim().toLowerCase(Locale.ROOT);
		return onlyPet(facts, want, pet -> pet.sources != null
			&& pet.sources.stream().anyMatch(s -> s != null && s.trim().toLowerCase(Locale.ROOT).equals(want)));
	}

	/** The one skilling pet {@code skill} gives, or null. */
	static String petForSkill(PluginConfigResponse.DropFacts facts, String skill) {
		var want = skill == null ? "" : skill.trim();
		return onlyPet(facts, want, pet -> "skill".equals(pet.kind) && want.equalsIgnoreCase(pet.skill));
	}

	/** The single pet matching {@code test}, or null when none or several do (or {@code want} is blank). */
	static String onlyPet(PluginConfigResponse.DropFacts facts, String want, Predicate<PluginConfigResponse.DropFacts.Pet> test) {
		if (facts == null || facts.pets == null || want.isEmpty()) return null;
		String found = null;
		for (Map.Entry<String, PluginConfigResponse.DropFacts.Pet> e : facts.pets.entrySet()) {
			if (e.getValue() != null && test.test(e.getValue())) {
				if (found != null) return null;
				found = e.getKey();
			}
		}
		return found;
	}

	// Champion's scrolls by NPC name, checked in order: "x*" is a prefix (hobgoblin before goblin),
	// "*x" a suffix, anything else the whole name.
	static final Map<String, Integer> CHAMPION_SCROLLS = new LinkedHashMap<>();
	static {
		CHAMPION_SCROLLS.put("hobgoblin*", ItemID.CHAMPIONS_CHALLENGE_HOBGOBLIN);
		CHAMPION_SCROLLS.put("goblin*", ItemID.CHAMPIONS_CHALLENGE_GOBLIN);
		CHAMPION_SCROLLS.put("imp", ItemID.CHAMPIONS_CHALLENGE_IMP);
		CHAMPION_SCROLLS.put("skeleton*", ItemID.CHAMPIONS_CHALLENGE_SKELETON);
		CHAMPION_SCROLLS.put("zombie*", ItemID.CHAMPIONS_CHALLENGE_ZOMBIE);
		CHAMPION_SCROLLS.put("ghoul", ItemID.CHAMPIONS_CHALLENGE_GHOUL);
		CHAMPION_SCROLLS.put("earth warrior", ItemID.CHAMPIONS_CHALLENGE_EARTHWARRIOR);
		CHAMPION_SCROLLS.put("jogre", ItemID.CHAMPIONS_CHALLENGE_JOGRE);
		CHAMPION_SCROLLS.put("lesser demon", ItemID.CHAMPIONS_CHALLENGE_LESSERDEMON);
		CHAMPION_SCROLLS.put("* giant", ItemID.CHAMPIONS_CHALLENGE_GIANT);
	}

	/** The champion's scroll item id {@code npc} drops, or null. */
	static Integer championScrollFor(String npc) {
		if (npc == null) return null;
		var n = npc.trim().toLowerCase(Locale.ROOT);
		for (Map.Entry<String, Integer> e : CHAMPION_SCROLLS.entrySet()) {
			var k = e.getKey();
			if (k.endsWith("*") ? n.startsWith(k.substring(0, k.length() - 1))
				: k.startsWith("*") ? n.endsWith(k.substring(1)) : n.equals(k)) {
				return e.getValue();
			}
		}
		return null;
	}
}

