/**
 * The server-driven UI's live list (node {@code feed}): drawn once from the
 * view, then grown by push rows that name its {@link #id} — never redrawn per row.
 *
 * Built to stay smooth under a thousand-player board: ONE {@link JList} with ONE reused row renderer
 * (Swing paints only the rows in view, so 300 rows cost what 20 do); arriving rows wait in a list and
 * a single timer adds them in one model change at most every {@link #FLUSH_MS}; the list is capped;
 * and a reader who has scrolled down is never pushed around — the rows go in above them and a
 * "↑ N new" line offers the way back up.
 *
 * With a {@code send} block it is the event chat: a box under the list posts the text and the line
 * comes back through the push like everybody else's. Clicks never redraw the view: a GZ (or one of a
 * row's {@code reacts} chips, a death's Sad / Sit) flips at once and is posted, a mod's menu action is
 * posted, and only an error line comes back.
 */

final class FeedList extends JPanel {
	/** "...+02:00" at the end of a timestamp. Compiled once: it runs for every row on each paint. */

	static final int FLUSH_MS = 400;
	/** How long after our own press's post answers before held reaction pushes are laid over it. */
	static final int SETTLE_MS = 1500;
	/** Reaction pushes held per pressed row, at most (the newest kept). */
	static final int HELD_CAP = 16;
	static final int ICON_W = 24;
	static final int ICON_H = 21;
	static final Color GOLD = new Color(0xFF_D3_5C);
	static final Color MINE_BG = new Color(0x2E_2A_22);
	static final Color CORAL = new Color(0xFF_7A_6B);
	static final Color SEG_BG = new Color(0x1E_1E_1E);
	static final Color SEG_ON = new Color(0x3A_3A_3A);

	final String id;
	final UiView.Host host;
	final ItemManager items;
	final SpriteManager sprites;
	final SkillIconManager skills;
	final Consumer<JsonObject> act;
	final int cap;
	final RowModel model = new RowModel();
	final JList<JsonObject> list = new JList<JsonObject>(model) {
		@Override
		public boolean getScrollableTracksViewportWidth() {
			return true;
		}

		/** A row's whole text, for when the width cut it short. */
		@Override
		public String getToolTipText(MouseEvent e) {
			int i = locationToIndex(e.getPoint());
			var b = i < 0 ? null : getCellBounds(i, i);
			if (b == null || !b.contains(e.getPoint())) return null;
			var r = model.getElementAt(i);
			// Over a reaction chip: who gave it, as the site put it ("GZ \u00b7 Mossy and 3 others").
			var chip = chipAt(r, getFontMetrics(SMALL), b.x + b.width - 6 - e.getX());
			var who = chip == null ? "" : str(chip, "who");
			if (!who.isEmpty()) return Ui.wrapHtml(esc(Ui.fontSafe(who)), 200);
			var title = str(r, "title");
			var line = title.isEmpty() ? (str(r, "who") + " " + str(r, "text")).trim()
				: title + " — " + str(r, "who") + (str(r, "tag").isEmpty() ? "" : " · " + str(r, "tag"));
			var value = str(r, "value");
			return line.isEmpty() ? null : Ui.wrapHtml(esc(Ui.fontSafe(line + (value.isEmpty() ? "" : " · " + value))), 200);
		}
	};
	final JScrollPane scroll;
	final JLabel empty;
	final JLabel newPill = new ClipLabel("", SwingConstants.CENTER);
	final JLabel error = new ClipLabel();
	final JLabel lockLine = new ClipLabel();
	final JLabel lockSub = new ClipLabel();
	/** In place of the message box while locked: the reason, coral when it's the viewer's own timeout. */
	final JPanel lockBox = new JPanel(new BorderLayout(0, 2));
	JPanel boxPanel;
	/** Chat: the channel switch over the list (My team | All teams | Announcements). */
	final List<Seg> segs = new ArrayList<>();
	JTextField input;
	JsonObject send;
	/** A chat (it has a message box): oldest at the top, newest at the bottom, pinned to the latest. */
	final boolean chat;
	/** Pinned to the newest line: true until the reader scrolls away from it. */
	boolean following = true;
	/** Whose lines are the viewer's own, re-read at each flush. */
	String me;
	/** Chat: every name the viewer's own lines carry (the site's `mine`: their characters and host name), per person. */
	final Set<String> mineNames = new HashSet<>();
	/** Arrived since the last flush, oldest first. */
	final List<JsonObject> pending = new ArrayList<>();
	final Set<String> pendingDel = new HashSet<>();
	/** Rows whose reaction chip this viewer just pressed: their pushes wait (see {@link #reaction}). */
	final Map<String, Held> held = new HashMap<>();
	final Timer flush = new Timer(FLUSH_MS, e -> flush());
	/** Repaints only the visible rows with a sliding name, ~25 times a second, and only while there are any. */
	final Timer slide = new Timer(40, e -> slideVisible());
	int unseen;
	final Map<Integer, Icon> icons = new HashMap<>();
	final Map<Integer, Icon> spriteIcons = new HashMap<>();
	final Map<String, Icon> skillIcons = new HashMap<>();

	FeedList(JsonObject n, UiView.Host host, ItemManager items, SpriteManager sprites, SkillIconManager skills, Consumer<JsonObject> act) {
		super(new BorderLayout(0, 4));
		id = str(n, "id");
		this.host = host;
		this.items = items;
		this.sprites = sprites;
		this.skills = skills;
		this.act = act;
		cap = n.has("cap") ? Math.max(20, n.get("cap").getAsInt()) : 200;
		int h = n.has("h") ? Math.max(120, n.get("h").getAsInt()) : 420;
		flush.setRepeats(false);
		setOpaque(false);
		chat = n.has("send") && n.get("send").isJsonObject();
		me = host == null ? null : host.myName();
		if (n.has("mine") && n.get("mine").isJsonArray()) {
			for (JsonElement e : n.getAsJsonArray("mine")) {
				if (e.isJsonPrimitive()) mineNames.add(ChatFlair.normalize(e.getAsString()));
			}
		}

		List<JsonObject> first = new ArrayList<>();
		if (n.has("rows") && n.get("rows").isJsonArray()) {
			for (JsonElement e : n.getAsJsonArray("rows")) {
				if (e.isJsonObject()) first.add(e.getAsJsonObject());
			}
		}
		List<JsonObject> kept = new ArrayList<>(first.size() > cap ? first.subList(0, cap) : first);
		// The site sends newest first; a chat reads top to bottom.
		if (chat) Collections.reverse(kept);
		model.reset(kept);

		var renderer = new RowRenderer();
		list.setCellRenderer(renderer);
		if (!chat) {
			// Every feed row is the same shape: measure one and never measure again.
			var probe = new JsonObject();
			probe.addProperty("id", "probe");
			probe.addProperty("title", "Probe");
			probe.addProperty("who", "Probe");
			probe.addProperty("value", "1m");
			probe.addProperty("glyph", "check");
			// With a reaction pill, so the fixed height has room for one.
			var probeGz = new JsonObject();
			probeGz.addProperty("n", 1);
			probe.add("gz", probeGz);
			list.setFixedCellHeight(renderer.getListCellRendererComponent(list, probe, 0, false, false).getPreferredSize().height);
		}
		list.setBackground(DARKER_GRAY_COLOR);
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setFocusable(false);
		javax.swing.ToolTipManager.sharedInstance().registerComponent(list);
		list.addMouseListener(new Clicks());
		// Over a pill you can press: a hand cursor and the pill lights, so reactions read as buttons.
		MouseAdapter hover = new MouseAdapter() {
			@Override
			public void mouseMoved(MouseEvent e) {
				int i = list.locationToIndex(e.getPoint());
				var b = i < 0 ? null : list.getCellBounds(i, i);
				int chip = -1;
				if (b != null && b.contains(e.getPoint())) {
					var c = chipsOf(model.getElementAt(i));
					int at = c == null ? -1 : reactAt(c, list.getFontMetrics(SMALL), b.x + b.width - 6 - e.getX());
					if (at >= 0 && c.get(at).getAsJsonObject().has("on")) chip = at;
				}
				setHover(chip >= 0 ? i : -1, chip);
			}

			@Override
			public void mouseExited(MouseEvent e) {
				setHover(-1, -1);
			}
		};
		list.addMouseMotionListener(hover);
		list.addMouseListener(hover);
		// Chat rows wrap to the width: a new width means new heights, so drop JList's cached ones.
		list.addComponentListener(new ComponentAdapter() {
			int lastW = -1;

			@Override
			public void componentResized(ComponentEvent e) {
				if (list.getWidth() != lastW) {
					lastW = list.getWidth();
					list.setFixedCellHeight(10);
					list.setFixedCellHeight(-1);
				}
				if (chat && following) toLatest();
			}
		});

		scroll = new JScrollPane(list, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().addChangeListener(e -> {
			var atLatest = atLatest();
			if (chat) following = atLatest;
			if (unseen > 0 && atLatest) {
				unseen = 0;
				newPill.setVisible(false);
			}
		});
		SlimScrollBarUI.applyTo(scroll);
		scroll.setPreferredSize(new Dimension(100, h));
		scroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));

		newPill.setFont(SMALL);
		newPill.setOpaque(true);
		newPill.setBackground(BRAND_ORANGE);
		newPill.setForeground(Color.BLACK);
		newPill.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
		newPill.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		newPill.setVisible(false);
		newPill.addMouseListener(new MouseAdapter() {
			@Override
			public void mouseClicked(MouseEvent e) {
				toLatest();
			}
		});

		// Wrapped, not cut: the empty line is the only thing in the list.
		empty = new ClipLabel(Ui.wrapHtml(esc(Ui.fontSafe(str(n, "empty"))), 170));
		empty.setFont(SMALL);
		empty.setForeground(MUTED);

		var top = new JPanel(new BorderLayout(0, 4));
		top.setOpaque(false);
		if (!chat) top.add(newPill, BorderLayout.NORTH);
		else if (n.has("chans") && n.get("chans").isJsonArray()) top.add(switchOf(n.getAsJsonArray("chans")), BorderLayout.NORTH);
		top.add(empty, BorderLayout.SOUTH);
		add(top, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);

		if (chat) {
			send = n.getAsJsonObject("send");
			var bottom = new JPanel(new BorderLayout(0, 4));
			bottom.setOpaque(false);
			bottom.add(newPill, BorderLayout.NORTH);
			bottom.add(boxPanel = sendBox(), BorderLayout.CENTER);
			bottom.add(lockBox, BorderLayout.SOUTH);
			add(bottom, BorderLayout.SOUTH);
			lock(str(n, "locked"), str(n, "lockSub"), n.has("lockWarn"));
			invokeLater(this::toLatest);
		}
		syncEmpty();
		setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
	}

	// ---- Push --------------------------------------------------------------------------------------

	/** Rows for this list, newest first as sent. Added on the next flush. */
	void add(JsonArray rows) {
		for (int i = rows.size() - 1; i >= 0; i--) {
			if (rows.get(i).isJsonObject()) pending.add(rows.get(i).getAsJsonObject());
		}
		schedule();
	}

	void remove(JsonArray ids) {
		for (JsonElement e : ids) pendingDel.add(e.getAsString());
		schedule();
	}

	/**
	 * A row's reactions as they now stand, pushed after anyone toggles one (site lib/panelRows
	 * emitReactionRows): {@code {t:"rowsreact", feeds, id:"m<moment>", gz, gold, sad, sit}}, and
	 * {@code who:{kind:line}} when the site says who gave them. Counts are absolute; this viewer's
	 * highlight only moves when the message carries it ({@code mineGz}, {@code mineSad}, ...: the copy
	 * sent to the reactor's own clients, so their other client follows). In place, never reordered.
	 *
	 * A chip this viewer just pressed is already showing where it's going: pushes for that row wait
	 * until the press settles (its post answered, plus {@link #SETTLE_MS}) and are then replayed in
	 * order, so the confirmation of our own toggle changes nothing and a quick on-off never flickers.
	 */
	void reaction(JsonObject update) {
		var rowId = str(update, "id");
		if (rowId.isEmpty()) return;
		var h = held.get(rowId);
		if (h != null) {
			if (h.queued.size() >= HELD_CAP) h.queued.remove(0);
			h.queued.add(update);
			return;
		}
		applyReactionToList(rowId, update);
	}

	void applyReactionToList(String rowId, JsonObject update) {
		for (JsonObject row : pending) {
			if (rowId.equals(str(row, "id"))) applyReaction(row, update);
		}
		int i = model.indexOf(rowId);
		if (i >= 0 && applyReaction(model.getElementAt(i), update)) model.changed(i);
	}

	/** Lays one push over a row's chips; true when any chip changed. Kinds the row has no chip for are ignored. */
	static boolean applyReaction(JsonObject row, JsonObject update) {
		List<JsonObject> chips = new ArrayList<>();
		if (row.has("reacts") && row.get("reacts").isJsonArray()) {
			for (JsonElement e : row.getAsJsonArray("reacts")) {
				if (e.isJsonObject()) chips.add(e.getAsJsonObject());
			}
		} else if (row.has("gz") && row.get("gz").isJsonObject()) {
			// The plain GZ chip carries no kind of its own.
			return applyChip(row.getAsJsonObject("gz"), "gz", update);
		}
		var changed = false;
		for (JsonObject chip : chips) changed |= applyChip(chip, str(chip, "kind"), update);
		return changed;
	}

	static boolean applyChip(JsonObject chip, String kind, JsonObject update) {
		if (kind.isEmpty()) return false;
		var changed = false;
		if (update.has(kind) && update.get(kind).isJsonPrimitive()) {
			int n = Math.max(0, update.get(kind).getAsInt());
			if (!chip.has("n") || chip.get("n").getAsInt() != n) {
				chip.addProperty("n", n);
				changed = true;
			}
		}
		var mineKey = "mine" + Character.toUpperCase(kind.charAt(0)) + kind.substring(1);
		if (update.has(mineKey) && update.get(mineKey).isJsonPrimitive()) {
			var mine = update.get(mineKey).getAsBoolean();
			if (!chip.has("mine") || chip.get("mine").getAsBoolean() != mine) {
				chip.addProperty("mine", mine);
				changed = true;
			}
		}
		if (update.has("who") && update.get("who").isJsonObject()) {
			var who = update.getAsJsonObject("who");
			if (who.has(kind)) {
				var line = str(who, kind);
				if (line.isEmpty()) {
					changed |= chip.remove("who") != null;
				} else if (!line.equals(str(chip, "who"))) {
					chip.addProperty("who", line);
					changed = true;
				}
			}
		}
		return changed;
	}

	/** A press on this row's chip just went out: hold its pushes until it settles. */
	void hold(String rowId) {
		held.computeIfAbsent(rowId, k -> new Held()).posts++;
	}

	/** One of the row's posts answered: once none are out, wait {@link #SETTLE_MS} and replay what was held. */
	void unhold(String rowId) {
		var h = held.get(rowId);
		if (h == null) return;
		h.posts = Math.max(0, h.posts - 1);
		if (h.posts > 0) return;
		int gen = ++h.gen;
		var t = new Timer(SETTLE_MS, e -> settle(rowId, gen));
		t.setRepeats(false);
		t.start();
	}

	void settle(String rowId, int gen) {
		var h = held.get(rowId);
		if (h == null || h.posts > 0 || h.gen != gen) return;
		held.remove(rowId);
		for (JsonObject update : h.queued) applyReactionToList(rowId, update);
	}

	/** For tests: every press whose post has answered settles now, without waiting out the timer. */
	void settleNow() {
		for (String rowId : new ArrayList<>(held.keySet())) {
			var h = held.get(rowId);
			if (h.posts == 0) settle(rowId, h.gen);
		}
	}

	/** Pushes for a row whose chip this viewer just pressed. */
	static final class Held {
		int posts;
		int gen;
		final List<JsonObject> queued = new ArrayList<>();
	}

	/**
	 * A box with this line (and a muted second one) in place of the message box, or the box back
	 * (empty {@code why}). {@code warn}: the viewer's own timeout or ban, drawn coral.
	 */
	void lock(String why, String sub, boolean warn) {
		if (input == null) return;
		var locked = why != null && !why.isEmpty();
		input.setEnabled(!locked);
		boxPanel.setVisible(!locked);
		lockBox.setVisible(locked);
		lockLine.setText(locked ? plainText(why) : "");
		lockLine.setForeground(warn ? CORAL : Color.WHITE);
		lockSub.setText(sub == null ? "" : plainText(sub));
		lockSub.setVisible(sub != null && !sub.isEmpty());
		lockBox.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(warn ? new Color(0x6A_3A_34) : new Color(0x4A_4A_4A)),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		revalidate();
	}

	boolean locked() {
		return lockBox.isVisible();
	}

	/** Lines arrived for these lists: a channel segment that names one, and isn't open, counts them. */
	void bump(Set<String> feeds, int count) {
		for (Seg g : segs) {
			if (!g.on && feeds.contains(g.feed)) {
				g.n += count;
				g.repaint();
			}
		}
	}

	int unread(String feed) {
		for (Seg g : segs) if (g.feed.equals(feed)) return g.n;
		return -1;
	}

	JPanel switchOf(JsonArray chans) {
		var bar = new JPanel(new java.awt.GridLayout(1, 0, 2, 0));
		bar.setBackground(SEG_BG);
		bar.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		for (JsonElement e : chans) {
			if (!e.isJsonObject()) continue;
			var c = e.getAsJsonObject();
			var g = new Seg(c);
			segs.add(g);
			if (!g.on && c.has("act") && c.get("act").isJsonObject()) Ui.onClick(g, () -> act.accept(c.getAsJsonObject("act")));
			bar.add(g);
		}
		return bar;
	}

	/** One channel on the switch: its name, lit when open, and an unread pill when not. */
	static final class Seg extends JComponent {
		final String label;
		final String feed;
		final boolean on;
		final boolean blue;
		int n;

		Seg(JsonObject c) {
			label = str(c, "label");
			feed = str(c, "feed");
			on = c.has("on") && c.get("on").getAsBoolean();
			blue = c.has("blue");
			n = c.has("n") ? c.get("n").getAsInt() : 0;
			setFont(SMALL);
			setPreferredSize(new Dimension(10, 22));
			// The label is often cut short at panel width ("Announceme…"): the full name on hover.
			var tip = str(c, "tip");
			setToolTipText(plainText(!tip.isEmpty() ? tip : label + (n > 0 ? " · " + n + " unread" : "")));
		}

		@Override
		protected void paintComponent(Graphics g0) {
			var g = Ui.smooth(g0);
			int w = getWidth(), h = getHeight();
			if (on) {
				g.setColor(SEG_ON);
				g.fillRoundRect(0, 0, w, h, 6, 6);
				g.setColor(BRAND_ORANGE);
				g.fillRect(2, h - 2, w - 4, 2);
			}
			var fm = g.getFontMetrics(getFont());
			g.setFont(getFont());
			var pill = !on && n > 0 ? (n > 99 ? "99+" : String.valueOf(n)) : null;
			int pw = pill == null ? 0 : Math.max(14, fm.stringWidth(pill) + 8);
			var text = label;
			while (text.length() > 1 && fm.stringWidth(text) + pw + (pw > 0 ? 3 : 0) > w - 4) text = text.substring(0, text.length() - 1);
			if (!text.equals(label)) text = text.substring(0, Math.max(1, text.length() - 1)) + "\u2026";
			int tw = fm.stringWidth(text) + (pw > 0 ? pw + 3 : 0);
			int x = (w - tw) / 2, base = (h + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(on ? Color.WHITE : MUTED);
			g.drawString(text, x, base);
			if (pill != null) {
				int px = x + fm.stringWidth(text) + 3, py = (h - 14) / 2;
				g.setColor(blue ? new Color(0x1B_2A_3A) : BRAND_ORANGE);
				g.fillRoundRect(px, py, pw, 14, 14, 14);
				g.setColor(blue ? new Color(0x8C_C8_FF) : new Color(0x1E_1E_1E));
				g.drawString(pill, px + (pw - fm.stringWidth(pill)) / 2, base);
			}
			g.dispose();
		}
	}

	boolean hasBox() {
		return input != null;
	}

	void stop() {
		flush.stop();
		slide.stop();
	}

	@Override
	public void addNotify() {
		super.addNotify();
		// Chat lines and Feed rows both slide a Patron's gradient; slideVisible repaints only the
		// visible rows that move, and nothing while the list is hidden or "Animated names" is off.
		slide.start();
	}

	@Override
	public void removeNotify() {
		super.removeNotify();
		slide.stop();
	}

	void slideVisible() {
		if (!list.isShowing() || !GradientLabel.animate || !GradientLabel.clientActive()) return;
		int first = list.getFirstVisibleIndex();
		int last = list.getLastVisibleIndex();
		for (int i = Math.max(0, first); i >= 0 && i <= last && i < model.getSize(); i++) {
			if (moves(model.getElementAt(i))) {
				var b = list.getCellBounds(i, i);
				if (b != null) list.repaint(b);
			}
		}
	}

	// For tests: what the list holds, newest first, and its box.
	int rowCount() {
		return model.getSize();
	}

	String rowId(int i) {
		return str(model.getElementAt(i), "id");
	}

	JsonObject reactionChip(int i, String kind) {
		var row = model.getElementAt(i);
		if (row.has("reacts") && row.get("reacts").isJsonArray()) {
			for (JsonElement e : row.getAsJsonArray("reacts")) {
				if (kind.equals(str(e.getAsJsonObject(), "kind"))) return e.getAsJsonObject();
			}
		}
		return "gz".equals(kind) && row.has("gz") ? row.getAsJsonObject("gz") : null;
	}

	JTextField box() {
		return input;
	}

	String errorLine() {
		return error.isVisible() ? error.getText() : null;
	}

	void schedule() {
		if (!flush.isRunning()) flush.start();
	}

	/** Everything that arrived since the last flush, in one model change. */
	void flush() {
		if (!pendingDel.isEmpty()) {
			model.removeIds(pendingDel);
			pending.removeIf(r -> pendingDel.contains(str(r, "id")));
			pendingDel.clear();
		}
		if (pending.isEmpty()) {
			syncEmpty();
			return;
		}
		List<JsonObject> fresh = new ArrayList<>();
		for (int i = pending.size() - 1; i >= 0; i--) {
			var r = pending.get(i);
			if (!model.has(str(r, "id"))) fresh.add(r);
		}
		pending.clear();
		if (fresh.isEmpty()) return;
		me = host == null ? null : host.myName();
		if (chat) {
			// Oldest first at the bottom; follow it down unless the reader has scrolled up.
			var stick = following;
			Collections.reverse(fresh);
			model.append(fresh, cap);
			if (stick) {
				invokeLater(this::toLatest);
			} else {
				unseen += fresh.size();
				newPill.setText("↓ " + unseen + " new");
				newPill.setVisible(true);
			}
			syncEmpty();
			return;
		}
		int y = scroll.getViewport().getViewPosition().y;
		model.prepend(fresh, cap);
		if (y > 2) {
			// Reading further down: keep the same rows under their eyes and say what's above.
			var added = list.getCellBounds(0, fresh.size() - 1);
			scroll.getViewport().setViewPosition(new Point(0, y + (added == null ? 0 : added.height)));
			unseen += fresh.size();
			newPill.setText("↑ " + unseen + " new");
			newPill.setVisible(true);
		}
		syncEmpty();
	}

	/** At the newest row: the bottom for a chat, the top for a feed. */
	boolean atLatest() {
		javax.swing.JViewport vp = scroll.getViewport();
		if (!chat) return vp.getViewPosition().y <= 2;
		return vp.getViewPosition().y + vp.getExtentSize().height >= list.getHeight() - 4;
	}

	void toLatest() {
		following = true;
		unseen = 0;
		newPill.setVisible(false);
		if (chat) {
			int last = model.getSize() - 1;
			if (last >= 0) {
				list.ensureIndexIsVisible(last);
				var b = list.getCellBounds(last, last);
				if (b != null) list.scrollRectToVisible(b);
			}
		} else scroll.getViewport().setViewPosition(new Point(0, 0));
	}

	void syncEmpty() {
		var none = model.getSize() == 0;
		if (empty.isVisible() != (none && !empty.getText().isEmpty())) {
			empty.setVisible(none && !empty.getText().isEmpty());
			revalidate();
		}
	}

	// ---- The message box ---------------------------------------------------------------------------

	JPanel sendBox() {
		var box = new JPanel(new BorderLayout(0, 2));
		box.setOpaque(false);
		input = new JTextField();
		styleSearch(input);
		input.setToolTipText(plainText(str(send, "hint")));
		int max = send.has("max") ? send.get("max").getAsInt() : 200;
		((AbstractDocument) input.getDocument()).setDocumentFilter(new MaxLength(max));
		input.addActionListener(e -> sendNow());
		// Escape hands the keyboard back to the game without sending.
		input.getInputMap().put(javax.swing.KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_ESCAPE, 0), "anvil-game");
		input.getActionMap().put("anvil-game", new javax.swing.AbstractAction() {
			@Override
			public void actionPerformed(java.awt.event.ActionEvent e) {
				host.gameFocus();
			}
		});
		JLabel hint = new ClipLabel(plainText(str(send, "hint") + " — Enter to send"));
		hint.setFont(SMALL);
		hint.setForeground(MUTED);
		error.setFont(SMALL);
		error.setForeground(PROGRESS_ERROR_COLOR);
		error.setVisible(false);
		lockLine.setFont(BOLD);
		lockSub.setFont(SMALL);
		lockSub.setForeground(MUTED);
		lockBox.setOpaque(false);
		lockBox.add(lockLine, BorderLayout.NORTH);
		lockBox.add(lockSub, BorderLayout.SOUTH);
		lockBox.setVisible(false);
		var lines = new JPanel(new BorderLayout());
		lines.setOpaque(false);
		lines.add(hint, BorderLayout.NORTH);
		lines.add(error, BorderLayout.CENTER);
		box.add(input, BorderLayout.NORTH);
		box.add(lines, BorderLayout.SOUTH);
		return box;
	}

	/** A send on its way: Enter again does nothing (the box is never disabled — that moves focus). */
	boolean sending;

	/**
	 * Post the line. Sent, the keyboard goes straight back to the game, so Key Remapping, WASD and
	 * Enter-to-chat work as before; refused, it stays in the box so the line can be fixed.
	 */
	void sendNow() {
		var text = input.getText().trim();
		if (text.isEmpty() || !input.isEnabled() || sending) return;
		sending = true;
		Map<String, String> fields = new HashMap<>();
		fields.put("msg", text);
		host.post(str(send, "act"), strings(send.get("args")), fields, v -> {
			sending = false;
			var err = errorOf(v);
			showError(err);
			if (err == null) {
				input.setText("");
				host.gameFocus();
			}
		});
	}

	void showError(String err) {
		error.setText(err == null ? "" : plainText(err));
		error.setVisible(err != null);
		revalidate();
	}

	/** An action's answer: null when it went through, else the line to show. */
	static String errorOf(JsonObject v) {
		if (v == null || !v.has("ui") || !v.get("ui").isJsonObject()) return "Couldn't reach Anvil — try again in a moment.";
		var ui = v.getAsJsonObject("ui");
		return "text".equals(str(ui, "t")) && "error".equals(str(ui, "color")) ? str(ui, "s") : null;
	}

	@RequiredArgsConstructor
	static final class MaxLength extends DocumentFilter {
		final int max;

		@Override
		public void insertString(FilterBypass fb, int offset, String s, AttributeSet a) throws BadLocationException {
			replace(fb, offset, 0, s, a);
		}

		@Override
		public void replace(FilterBypass fb, int offset, int length, String s, AttributeSet a) throws BadLocationException {
			var add = s == null ? "" : s;
			int room = max - (fb.getDocument().getLength() - length);
			if (room <= 0) return;
			super.replace(fb, offset, length, add.length() > room ? add.substring(0, room) : add, a);
		}
	}

	// ---- Clicks ------------------------------------------------------------------------------------

	final class Clicks extends MouseAdapter {
		@Override
		public void mousePressed(MouseEvent e) {
			popup(e);
		}

		@Override
		public void mouseReleased(MouseEvent e) {
			if (!popup(e) && SwingUtilities.isLeftMouseButton(e)) click(e);
		}

		int rowAt(MouseEvent e) {
			int i = list.locationToIndex(e.getPoint());
			var b = i < 0 ? null : list.getCellBounds(i, i);
			return b != null && b.contains(e.getPoint()) ? i : -1;
		}

		boolean popup(MouseEvent e) {
			if (!e.isPopupTrigger()) return false;
			int i = rowAt(e);
			var r = i < 0 ? null : model.getElementAt(i);
			if (r == null || !r.has("menu") || !r.get("menu").isJsonArray()) return true;
			var menu = new JPopupMenu();
			for (JsonElement el : r.getAsJsonArray("menu")) {
				var item = el.getAsJsonObject();
				var mi = new JMenuItem(plainText(str(item, "label")));
				var on = item.has("on") && item.get("on").isJsonObject() ? item.getAsJsonObject("on") : null;
				if (on == null) {
					mi.setEnabled(false);
				} else mi.addActionListener(ev -> quietly(on));
				menu.add(mi);
			}
			menu.show(list, e.getX(), e.getY());
			return true;
		}

		void click(MouseEvent e) {
			int i = rowAt(e);
			if (i < 0) return;
			var r = model.getElementAt(i);
			var b = list.getCellBounds(i, i);
			var chip = chipAt(r, list.getFontMetrics(SMALL), b.x + b.width - 6 - e.getX());
			if (chip != null) {
				press(i, chip);
				return;
			}
			if (r.has("on") && r.get("on").isJsonObject()) act.accept(r.getAsJsonObject("on"));
		}
	}

	/** A reaction chip pressed: flipped at once, posted, and the row's pushes held until the post settles. */
	void press(int i, JsonObject chip) {
		var mine = chip.has("mine") && chip.get("mine").getAsBoolean();
		int count = chip.has("n") ? chip.get("n").getAsInt() : 0;
		chip.addProperty("mine", !mine);
		chip.addProperty("n", Math.max(0, count + (mine ? -1 : 1)));
		model.changed(i);
		if (!chip.has("on") || !chip.get("on").isJsonObject()) return;
		var on = chip.getAsJsonObject("on");
		var rowId = str(model.getElementAt(i), "id");
		if (rowId.isEmpty() || !"post".equals(str(on, "a"))) {
			quietly(on);
			return;
		}
		hold(rowId);
		host.post(str(on, "act"), strings(on.get("args")), Collections.emptyMap(), v -> {
			unhold(rowId);
			showError(errorOf(v));
		});
	}

	/** For tests: press row {@code i}'s chip of this kind, as a click on it would. */
	void pressChip(int i, String kind) {
		var chip = reactionChip(i, kind);
		if (chip != null) press(i, chip);
	}

	/** A post that must not redraw the view: only an error line comes back. */
	void quietly(JsonObject on) {
		if (!"post".equals(str(on, "a"))) {
			act.accept(on);
			return;
		}
		host.post(str(on, "act"), strings(on.get("args")), Collections.emptyMap(), v -> showError(errorOf(v)));
	}

	// ---- The model: one list, changed in batches -------------------------------------------------

	static final class RowModel extends AbstractListModel<JsonObject> {
		final List<JsonObject> rows = new ArrayList<>();
		final Set<String> ids = new HashSet<>();

		@Override
		public int getSize() {
			return rows.size();
		}

		@Override
		public JsonObject getElementAt(int index) {
			return rows.get(index);
		}

		boolean has(String id) {
			return ids.contains(id);
		}

		void reset(List<JsonObject> next) {
			int was = rows.size();
			rows.clear();
			ids.clear();
			if (was > 0) fireIntervalRemoved(this, 0, was - 1);
			for (JsonObject r : next) {
				if (ids.add(str(r, "id"))) rows.add(r);
			}
			if (!rows.isEmpty()) fireIntervalAdded(this, 0, rows.size() - 1);
		}

		/** A chat's new lines at the bottom; the oldest past {@code cap} go from the top. */
		void append(List<JsonObject> fresh, int cap) {
			int at = rows.size();
			for (JsonObject r : fresh) ids.add(str(r, "id"));
			rows.addAll(fresh);
			fireIntervalAdded(this, at, rows.size() - 1);
			if (rows.size() > cap) {
				int gone = rows.size() - cap;
				for (JsonObject r : rows.subList(0, gone)) ids.remove(str(r, "id"));
				rows.subList(0, gone).clear();
				fireIntervalRemoved(this, 0, gone - 1);
			}
		}

		/** Newest first; the oldest past {@code cap} go. Two events however many rows. */
		void prepend(List<JsonObject> fresh, int cap) {
			for (JsonObject r : fresh) ids.add(str(r, "id"));
			rows.addAll(0, fresh);
			fireIntervalAdded(this, 0, fresh.size() - 1);
			if (rows.size() > cap) {
				int from = cap;
				int to = rows.size() - 1;
				for (JsonObject r : rows.subList(from, rows.size())) ids.remove(str(r, "id"));
				rows.subList(from, rows.size()).clear();
				fireIntervalRemoved(this, from, to);
			}
		}

		void removeIds(Set<String> gone) {
			for (int i = rows.size() - 1; i >= 0; i--) {
				var id = str(rows.get(i), "id");
				if (gone.contains(id)) {
					rows.remove(i);
					ids.remove(id);
					fireIntervalRemoved(this, i, i);
				}
			}
		}

		int indexOf(String id) {
			for (int i = 0; i < rows.size(); i++) {
				if (id.equals(str(rows.get(i), "id"))) return i;
			}
			return -1;
		}

		void changed(int i) {
			fireContentsChanged(this, i, i);
		}
	}

	// ---- One renderer, reused for every row --------------------------------------------------------

	Icon iconFor(JsonObject r) {
		if (r.has("item") && items != null) {
			int item = r.get("item").getAsInt();
			var cached = icons.get(item);
			if (cached != null) return cached;
			icons.put(item, new BlankIcon());
			var img = items.getImage(item);
			img.onLoaded(() -> invokeLater(() -> {
				icons.put(item, new ImageIcon(ImageUtil.resizeImage(img, ICON_W, ICON_H, true)));
				list.repaint();
			}));
			return icons.get(item);
		}
		if (r.has("sprite") && sprites != null) {
			int sprite = spriteId(str(r, "sprite"));
			if (sprite < 0) return null;
			var cached = spriteIcons.get(sprite);
			if (cached != null) return cached;
			spriteIcons.put(sprite, new BlankIcon());
			sprites.getSpriteAsync(sprite, 0, img -> invokeLater(() -> {
				if (img != null) {
					spriteIcons.put(sprite, new ImageIcon(ImageUtil.resizeImage(img, ICON_W, ICON_H, true)));
					list.repaint();
				}
			}));
			return spriteIcons.get(sprite);
		}
		if (r.has("skill") && skills != null) {
			var name = str(r, "skill").toUpperCase(java.util.Locale.ROOT);
			var cached = skillIcons.get(name);
			if (cached != null) return cached;
			try {
				var skill = Skill.valueOf(name);
				Icon icon = new ImageIcon(ImageUtil.resizeImage(skills.getSkillImage(skill, true), ICON_W, ICON_H, true));
				skillIcons.put(name, icon);
				return icon;
			} catch (IllegalArgumentException ignored) {
				return null;
			}
		}
		if (r.has("glyph")) {
			var g = str(r, "glyph");
			var shape = "star".equals(g) ? GlyphIcon.Shape.STAR : "chevron-right".equals(g) ? GlyphIcon.Shape.CHEVRON_RIGHT : GlyphIcon.Shape.CHECK;
			return new GlyphIcon(shape, 12, color(str(r, "glyphColor"), MUTED));
		}
		return null;
	}

	static int spriteId(String name) {
		switch (name) {
			case "quest":
				return SpriteID.QUESTS_PAGE_ICON_BLUE_QUESTS;
			case "diary":
				return SpriteID.QUESTS_PAGE_ICON_GREEN_ACHIEVEMENT_DIARIES;
			case "combat":
				return SpriteID.TAB_COMBAT;
			case "collection-log":
				return SpriteID.HISCORE_COLLECTIONS_LOGGED;
			case "total":
				return SpriteID.SKILL_TOTAL;
			default:
				return -1;
		}
	}

	/** A row's picture on a rounded tile of its kind's colour (purple rare, green done, coral death). */
	@RequiredArgsConstructor
	static final class Tinted implements Icon {
		final Icon in;
		final Color tint;

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y) {
			var g2 = Ui.smooth(g);
			g2.setColor(tint);
			g2.fillRoundRect(x, y, ICON_W, ICON_W - 2, 6, 6);
			g2.dispose();
			in.paintIcon(c, g, x + (ICON_W - in.getIconWidth()) / 2, y + (ICON_W - 2 - in.getIconHeight()) / 2);
		}

		@Override
		public int getIconWidth() {
			return ICON_W;
		}

		@Override
		public int getIconHeight() {
			return ICON_W - 2;
		}
	}

		static final class BlankIcon implements Icon {
		@Override
		public void paintIcon(Component c, Graphics g, int x, int y) {
		}

		@Override
		public int getIconWidth() {
			return ICON_W;
		}

		@Override
		public int getIconHeight() {
			return ICON_H;
		}
	}

	final ChatCell chatCell = new ChatCell();

	/**
	 * One chat line, painted straight onto the list: the name (and team, or HOST / MOD / TEAM) with
	 * the time, the message wrapped under it, and a run of lines from one person showing the name once.
	 *
	 * No HTML: a Swing HTML label parses its markup every time a row is measured or painted, and a list
	 * re-measures every row whenever one is added — 300 HTML rows cost ~100ms a flush on a fast PC. Here
	 * the wrapping is done once per row and width with plain font metrics and kept, so a flush is cheap
	 * however long the chat is, and nothing a player typed can ever become markup.
	 */
	final class ChatCell extends JComponent {
		static final int PAD_X = 8;
		final Map<String, List<String>> wraps = new HashMap<>();
		int wrapWidth = -1;
		JsonObject r;
		boolean grouped;
		boolean mine;
		List<String> lines = Collections.emptyList();
		int height;

		ChatCell() {
			setOpaque(true);
		}

		ChatCell show(JsonObject row, int index, int width, boolean mine) {
			this.r = row;
			this.mine = mine;
			var prev = index > 0 ? model.getElementAt(index - 1) : null;
			grouped = prev != null && sameRun(prev, row);
			// A few px spare: lines are measured off-screen and painted on it, and the two can round apart.
			int w = Math.max(80, width - PAD_X * 2 - 6);
			// Rows trimmed off the list leave their wrapping behind: start over once it holds well more
			// than the list does (the rows on screen re-wrap as they paint).
			if (w != wrapWidth || wraps.size() > 2 * Math.max(model.getSize(), 100)) {
				wraps.clear();
				wrapWidth = w;
			}
			lines = wraps.computeIfAbsent(str(row, "id"), k -> wrap(Ui.fontSafe(str(row, "text")), list.getFontMetrics(REGULAR), w));
			var fm = getFontMetrics(REGULAR);
			height = (grouped ? 0 : 6 + fm.getHeight()) + lines.size() * fm.getHeight() + 2;
			return this;
		}

		@Override
		public Dimension getPreferredSize() {
			return new Dimension(wrapWidth + PAD_X * 2, height);
		}

		@Override
		protected void paintComponent(Graphics g0) {
			var g = (Graphics2D) g0;
			g.setColor(mine ? MINE_BG : DARKER_GRAY_COLOR);
			g.fillRect(0, 0, getWidth(), getHeight());
			var fm = g.getFontMetrics(REGULAR);
			int y = 0;
			if (!grouped) {
				y = 6;
				int x = PAD_X;
				// A name in its team's colour; a Supporter keeps their own colour or gradient (their perk) with
				// a dot of their team's colour in front. Only a role (HOST / MOD / TEAM-only) is spelled out.
				var tag = Ui.fontSafe(str(r, "tag"));
				var role = isRole(tag);
				var team = !role && !tag.isEmpty();
				var grad = stops(r);
				var whoColor = str(r, "whoColor");
				var supporter = grad != null || (!whoColor.isEmpty() && !"white".equals(whoColor));
				if (supporter && team) {
					g.setColor(color(str(r, "tagColor"), MUTED));
					g.fillOval(x, y + fm.getAscent() - 7, 6, 6);
					x += 10;
				}
				// A Supporter's tenure badge in front of the name, in their colour.
				int step = UiView.tenureStep(str(r, "whoGlyph"));
				if (step > 0 && supporter) {
					g.drawImage(AnvilPlugin.tenureSprite(step, (grad != null ? grad[0] : color(whoColor, Color.WHITE)).getRGB() & 0xffffff, -1, AnvilPlugin.TENURE_PX), x, y + fm.getAscent() - 11, null);
					x += 15;
				}
				g.setFont(BOLD);
				var who = Ui.fontSafe(str(r, "who"));
				int nameW = g.getFontMetrics().stringWidth(who);
				if (grad != null) {
					var at = new float[grad.length];
					for (int i = 0; i < grad.length; i++) at[i] = (float) i / (grad.length - 1);
					// A Patron's gradient slides along (reflecting back), like everywhere else, unless the
					// player turned "Animated names" off.
					var shift = moves(r) ? (System.currentTimeMillis() % 6000) / 6000f * 2 * Math.max(1, nameW) : 0;
					g.setPaint(new java.awt.LinearGradientPaint(x - shift, 0, x - shift + Math.max(1, nameW), 0, at, grad,
						java.awt.MultipleGradientPaint.CycleMethod.REFLECT));
				} else g.setColor(supporter || !team ? color(whoColor, Color.WHITE) : color(str(r, "tagColor"), Color.WHITE));
				g.drawString(who, x, y + fm.getAscent());
				x += nameW + 6;
				g.setFont(SMALL);
				if (role) {
					g.setColor(color(str(r, "tagColor"), MUTED));
					g.drawString(tag, x, y + fm.getAscent());
				}
				var when = Ui.ago(str(r, "at")).replace(" ago", "");
				g.setColor(MUTED);
				g.drawString(when, getWidth() - PAD_X - g.getFontMetrics().stringWidth(when), y + fm.getAscent());
				y += fm.getHeight();
			}
			g.setFont(REGULAR);
			g.setColor(color(str(r, "textColor"), TEXT_COLOR));
			for (String line : lines) {
				g.drawString(line, PAD_X, y + fm.getAscent());
				y += fm.getHeight();
			}
		}
	}

	/**
	 * A moment's name line: the name in a Supporter's gradient (letter by letter; the panel's static
	 * form of it) or in {@code whoColor}, and "· Team" after it in the team's colour. A site that only
	 * sent the team (whoColor "muted") gets the name in the team's colour, as before.
	 */
	static String whoHtml(JsonObject r, String who, String tag, Color whoInk, Color tagInk) {
		var sb = new StringBuilder("<html>");
		whoRuns(r, who, tag, whoInk, tagInk, (text, ink) -> sb.append(font(ink, text)));
		return sb.toString();
	}

	/**
	 * The name line as coloured runs, in order: one per letter for a gradient (sliding like the chat
	 * lines: the same 6s cycle, reflecting back), else the whole name; then "· Team". Shared by
	 * {@link #whoHtml} and {@link WhoLine}, which paints the runs straight onto the row.
	 */
	static void whoRuns(JsonObject r, String who, String tag, Color whoInk, Color tagInk, java.util.function.BiConsumer<String, Color> out) {
		var grad = stops(r);
		var whoColor = str(r, "whoColor");
		var nameInk = !tag.isEmpty() && (whoColor.isEmpty() || "muted".equals(whoColor)) ? tagInk : whoInk;
		var name = Ui.fontSafe(who);
		if (grad != null && name.length() > 1) {
			var phase = moves(r) ? (System.currentTimeMillis() % 6000) / 6000f * 2 : 0;
			for (int i = 0; i < name.length(); i++) {
				var t = reflect((float) i / (name.length() - 1) + phase) * (grad.length - 1);
				int k = Math.min((int) t, grad.length - 2);
				out.accept(String.valueOf(name.charAt(i)), mix(grad[k], grad[k + 1], t - k));
			}
		} else out.accept(name, nameInk);
		if (!tag.isEmpty()) out.accept(" \u00b7 " + Ui.fontSafe(tag), tagInk);
	}

	/**
	 * A moment's name line, painted directly. It was an HTML label, and a sliding gradient changes
	 * its text every 40ms frame, so Swing re-parsed the markup 25 times a second for each visible
	 * moving row; drawing the same letters in the same colours costs only the drawString calls.
	 */
	static final class WhoLine extends JComponent {
		JsonObject r;
		String who = "";
		String tag = "";
		Color whoInk = Color.WHITE;
		Color tagInk = MUTED;

		void show(JsonObject r, String who, String tag, Color whoInk, Color tagInk) {
			this.r = r;
			this.who = who;
			this.tag = tag;
			this.whoInk = whoInk;
			this.tagInk = tagInk;
		}

		@Override
		public Dimension getPreferredSize() {
			var fm = getFontMetrics(SMALL);
			// Tall enough for a tenure badge beside the name.
			return new Dimension(0, Math.max(fm.getHeight(), UiView.tenureStep(r == null ? null : str(r, "whoGlyph")) > 0 ? AnvilPlugin.TENURE_PX : 0));
		}

		@Override
		protected void paintComponent(Graphics g0) {
			if (r == null) return;
			var g = (Graphics2D) g0;
			g.setFont(SMALL);
			var fm = g.getFontMetrics();
			int y = (getHeight() - fm.getHeight()) / 2 + fm.getAscent();
			int[] x = {0};
			int max = getWidth();
			// A Supporter's tenure badge in front of the name, at the art's own 13px.
			int step = UiView.tenureStep(str(r, "whoGlyph"));
			if (step > 0) {
				var grad = stops(r);
				var badge = AnvilPlugin.tenureSprite(step, (grad != null ? grad[0] : whoInk).getRGB() & 0xffffff, -1, AnvilPlugin.TENURE_PX);
				g.drawImage(badge, 0, (getHeight() - badge.getHeight()) / 2, null);
				x[0] = badge.getWidth();
			}
			whoRuns(r, who, tag, whoInk, tagInk, (text, ink) -> {
				if (x[0] >= max) return;
				g.setColor(ink);
				g.drawString(text, x[0], y);
				x[0] += fm.stringWidth(text);
			});
		}
	}

	static String font(Color c, String text) {
		return String.format("<font color='#%06x'>%s</font>", c.getRGB() & 0xffffff, Ui.esc(text));
	}

	static Color mix(Color a, Color b, float t) {
		return new Color(Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
				Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
				Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	/** A Supporter's name gradient ({@code grad}: 2+ "#rrggbb"), or null. */
	static Color[] stops(JsonObject r) {
		if (!r.has("grad") || !r.get("grad").isJsonArray() || r.getAsJsonArray("grad").size() < 2) return null;
		List<Color> out = new ArrayList<>();
		for (JsonElement e : r.getAsJsonArray("grad")) {
			var hex = ChatPalette.nameColor(e.isJsonPrimitive() ? e.getAsString() : null);
			if (hex == null) return null;
			out.add(new Color(Integer.parseInt(hex, 16)));
		}
		return out.toArray(new Color[0]);
	}

	/** A position along a reflecting gradient (0→1→0 every 2), as CycleMethod.REFLECT paints it. */
	static float reflect(float p) {
		var m = p % 2f;
		return m > 1f ? 2f - m : m;
	}

	/** A row whose name gradient should be sliding right now. */
	static boolean moves(JsonObject r) {
		return GradientLabel.animate && r.has("move") && r.get("move").getAsBoolean() && stops(r) != null;
	}

	/** HOST / MOD / TEAM: a role worth spelling out. Anything else in a row's tag is its team's name. */
	static boolean isRole(String tag) {
		return "HOST".equals(tag) || "MOD".equals(tag) || "TEAM".equals(tag);
	}

	/** Words into lines no wider than {@code width}; a word longer than a line is broken where it must be. */
	static List<String> wrap(String text, FontMetrics fm, int width) {
		List<String> out = new ArrayList<>();
		var line = new StringBuilder();
		for (String word : text.split(" ")) {
			if (word.isEmpty()) continue;
			var candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) <= width) {
				line.setLength(0);
				line.append(candidate);
				continue;
			}
			if (line.length() > 0) {
				out.add(line.toString());
				line.setLength(0);
			}
			while (fm.stringWidth(word) > width) {
				int cut = 1;
				while (cut < word.length() && fm.stringWidth(word.substring(0, cut + 1)) <= width) cut++;
				out.add(word.substring(0, cut));
				word = word.substring(cut);
			}
			line.append(word);
		}
		if (line.length() > 0 || out.isEmpty()) out.add(line.toString());
		return out;
	}

	final class RowRenderer extends JPanel implements ListCellRenderer<JsonObject> {
		final JLabel icon = new ClipLabel();
		final JLabel line1 = new ClipLabel();
		final WhoLine line2 = new WhoLine();
		final JLabel value = new ClipLabel();
		final JLabel gz = new ClipLabel();
		final Chips chips = new Chips();

		RowRenderer() {
			super(new BorderLayout(6, 0));
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 1, 0, DARK_GRAY_COLOR),
				BorderFactory.createEmptyBorder(4, 6, 4, 6)));
			icon.setVerticalAlignment(SwingConstants.TOP);
			icon.setPreferredSize(new Dimension(ICON_W, ICON_H));
			line1.setFont(REGULAR);
			value.setFont(SMALL);
			value.setForeground(GOLD);
			value.setHorizontalAlignment(SwingConstants.RIGHT);
			gz.setFont(SMALL);
			gz.setHorizontalAlignment(SwingConstants.RIGHT);
			var middle = new JPanel(new BorderLayout());
			middle.setOpaque(false);
			middle.add(line1, BorderLayout.NORTH);
			middle.add(line2, BorderLayout.SOUTH);
			var right = new JPanel(new BorderLayout());
			right.setOpaque(false);
			right.add(value, BorderLayout.NORTH);
			// The second line: reaction pills when the row has them, else the plain gz/time text.
			var bottom = new JPanel(new BorderLayout());
			bottom.setOpaque(false);
			bottom.add(gz, BorderLayout.CENTER);
			bottom.add(chips, BorderLayout.EAST);
			right.add(bottom, BorderLayout.SOUTH);
			add(icon, BorderLayout.WEST);
			add(middle, BorderLayout.CENTER);
			add(right, BorderLayout.EAST);
		}

		final javax.swing.border.Border feedBorder = BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 6, 4, 6));

		boolean mine(JsonObject r) {
			return (r.has("mine") && r.get("mine").getAsBoolean()) || (me != null && !me.isEmpty() && Rsn.same(me, str(r, "who")))
					|| (!mineNames.isEmpty() && mineNames.contains(ChatFlair.normalize(str(r, "who"))));
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends JsonObject> l, JsonObject r, int index, boolean selected, boolean focus) {
			if (chat) return chatCell.show(r, index, l.getWidth(), mine(r));
			setBorder(feedBorder);
			line1.setVisible(true);
			line2.setFont(SMALL);
			value.setVisible(true);
			setBackground(mine(r) ? MINE_BG : DARKER_GRAY_COLOR);
			var tint = color(str(r, "tint"), null);
			var ic = iconFor(r);
			if (tint != null) ic = new Tinted(ic != null ? ic : new BlankIcon(), tint);
			icon.setIcon(ic);
			icon.setVisible(ic != null);

			var who = str(r, "who");
			var whoInk = color(str(r, "whoColor"), Color.WHITE);
			var tag = str(r, "tag");
			var tagInk = color(str(r, "tagColor"), MUTED);
			var when = Ui.ago(str(r, "at")).replace(" ago", "");
			var title = str(r, "title");
			if (!title.isEmpty()) {
				// A moment: the item on top, who got it (and their team) under it.
				line1.setText(plainText(title));
				line1.setForeground(color(str(r, "textColor"), Color.WHITE));
				// Who got it, in the colours the site picked (a Supporter's own, else their team's), then
				// "· Team" in the team's colour on a board.
				line2.show(r, who, tag, whoInk, tagInk);
				line2.setVisible(true);
			} else {
				// A roll-up line ("+214 smaller drops…"): one plain line.
				line1.setText(plainText(str(r, "text")));
				line1.setForeground(color(str(r, "textColor"), MUTED));
				line2.setVisible(false);
			}
			value.setText(plainText(r.has("value") ? str(r, "value") : when));
			value.setForeground(r.has("value") ? GOLD : MUTED);
			var rowChips = chipsOf(r);
			if (rowChips != null) {
				// Reactions as pills (GZ / Sad / Sit), so they read as buttons rather than labels.
				chips.chips = rowChips;
				chips.hover = index == hoverRow ? hoverChip : -1;
				chips.setVisible(true);
				gz.setVisible(false);
			} else {
				chips.chips = null;
				chips.setVisible(false);
				gz.setText(r.has("value") ? plainText(when) : "");
				gz.setForeground(MUTED);
				gz.setVisible(r.has("value"));
			}
			return this;
		}
	}

	/** The row and pill under the mouse, lit by the renderer (-1: none). EDT. */
	int hoverRow = -1;
	int hoverChip = -1;

	void setHover(int row, int chip) {
		if (row == hoverRow && chip == hoverChip) return;
		int was = hoverRow;
		hoverRow = row;
		hoverChip = chip;
		list.setCursor(Cursor.getPredefinedCursor(row >= 0 ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
		for (int i : new int[]{was, row}) {
			var b = i < 0 || i >= model.getSize() ? null : list.getCellBounds(i, i);
			if (b != null) list.repaint(b);
		}
	}

	/** Inside a reaction pill: the text's side padding; and the space between two pills. */
	static final int CHIP_PAD = 6;
	static final int CHIP_SPACE = 3;
	/** Soft fills, no outline: quiet when idle, a little lighter under the mouse, tinted when yours. */
	static final Color CHIP_FILL = new Color(0x303030);
	static final Color CHIP_FILL_HOVER = new Color(0x404040);
	static final Color CHIP_MINE = new Color(255, 152, 31, 52);
	static final Color CHIP_MINE_HOVER = new Color(255, 152, 31, 84);
	static final Color CHIP_INK = new Color(0xb4b4b4);

	/** "Sit 3", or just "Sit" before anyone has. */
	static String chipText(JsonObject c) {
		int n = c.has("n") ? c.get("n").getAsInt() : 0;
		var label = str(c, "label");
		return n > 0 ? label + " " + n : label;
	}

	/** A row's reaction chips in drawing order: a death's {@code reacts}, else its one {@code gz}. */
	static JsonArray chipsOf(JsonObject r) {
		if (r.has("reacts") && r.get("reacts").isJsonArray()) return r.getAsJsonArray("reacts");
		if (r.has("gz") && r.get("gz").isJsonObject()) {
			var g = r.getAsJsonObject("gz");
			if (!g.has("label")) g.addProperty("label", "GZ");
			var one = new JsonArray();
			one.add(g);
			return one;
		}
		return null;
	}

	static int chipWidth(FontMetrics fm, JsonObject c) {
		return fm.stringWidth(chipText(c)) + 2 * CHIP_PAD;
	}

	/**
	 * The reaction chip {@code fromRight} px left of the row's right edge (inside its 6px inset), or
	 * null. The pills' own geometry ({@link Chips}), so a click or hover lands on exactly what is drawn.
	 */
	static JsonObject chipAt(JsonObject r, FontMetrics fm, int fromRight) {
		var c = chipsOf(r);
		int at = c == null ? -1 : reactAt(c, fm, fromRight);
		return at < 0 ? null : c.get(at).getAsJsonObject();
	}

	/** Which pill {@code fromRight} px left of the row's right edge falls on (2px of slack), or -1. */
	static int reactAt(JsonArray reacts, FontMetrics fm, int fromRight) {
		int edge = 0;
		for (int k = reacts.size() - 1; k >= 0; k--) {
			int w = chipWidth(fm, reacts.get(k).getAsJsonObject());
			// The rightmost pill also takes the row's 6px inset beside it, as the plain chips did.
			if (fromRight >= (edge == 0 ? -6 : edge - 2) && fromRight <= edge + w + 2) return k;
			edge += w + CHIP_SPACE;
		}
		return -1;
	}

	/** A row's reactions as small rounded buttons: outlined, filled when they're yours, lit on hover. */
	static final class Chips extends JComponent {
		JsonArray chips;
		int hover = -1;

		Chips() {
			setFont(SMALL);
			setOpaque(false);
		}

		@Override
		public Dimension getPreferredSize() {
			var fm = getFontMetrics(getFont());
			int w = 0;
			for (int k = 0; chips != null && k < chips.size(); k++) w += (k > 0 ? CHIP_SPACE : 0) + chipWidth(fm, chips.get(k).getAsJsonObject());
			return new Dimension(w, fm.getHeight() + 2);
		}

		@Override
		protected void paintComponent(Graphics g) {
			if (chips == null) return;
			var g2 = (Graphics2D) g.create();
			try {
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setFont(getFont());
				var fm = g2.getFontMetrics();
				int h = getHeight() - 1;
				int x = getWidth();
				for (int k = chips.size() - 1; k >= 0; k--) {
					var c = chips.get(k).getAsJsonObject();
					int w = chipWidth(fm, c);
					x -= w;
					var mine = c.has("mine") && c.get("mine").getAsBoolean();
					var live = c.has("on") && c.get("on").isJsonObject();
					var lit = live && k == hover;
					g2.setColor(mine ? (lit ? CHIP_MINE_HOVER : CHIP_MINE) : live ? (lit ? CHIP_FILL_HOVER : CHIP_FILL) : CHIP_FILL);
					g2.fillRoundRect(x, 0, w, h + 1, 7, 7);
					g2.setColor(mine ? BRAND_ORANGE : lit ? Color.WHITE : live ? CHIP_INK : MUTED);
					g2.drawString(chipText(c), x + CHIP_PAD, (h - fm.getHeight()) / 2 + fm.getAscent() + 1);
					x -= CHIP_SPACE;
				}
			} finally {
				g2.dispose();
			}
		}
	}

	/** A line joins the one before it (no name or time of its own) only from the same person within this. */
	static final long RUN_GAP_MS = 5 * 60_000L;

	/** Same person, same team tag, and close in time: a run shows its name and time once. */
	static boolean sameRun(JsonObject prev, JsonObject row) {
		if (!str(row, "who").equals(str(prev, "who")) || !str(row, "tag").equals(str(prev, "tag"))) return false;
		var a = millis(str(prev, "at"));
		var b = millis(str(row, "at"));
		return a > 0 && b > 0 && Math.abs(a - b) <= RUN_GAP_MS;
	}

	static long millis(String at) {
		if (at == null || at.isEmpty()) return 0;
		var iso = at.trim().replace(' ', 'T');
		if (!iso.endsWith("Z") && !Ui.HAS_OFFSET.matcher(iso).matches()) iso = iso + "Z";
		try {
			return java.time.Instant.parse(iso).toEpochMilli();
		} catch (RuntimeException e) {
			return 0;
		}
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import lombok.AllArgsConstructor;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Counters read off game values (varbits/varps) rather than a chat line: Tithe Farm points, Giants'
 * Foundry reputation, Doom delve completions, slayer task streaks. WHICH values, and the target name
 * each credits, come from the site (lib/gameCounters), so adding one is a
 * catalog line there and never a release here.
 *
 * <p>Generic delta rule: per source, a change in the entry's direction (default: increase) after the
 * baseline is credited with amount = the change; a change the other way (spending, a streak reset)
 * never subtracts and just becomes the new baseline. An entry with several sources sums them — or,
 * with {@code changes}, counts 1 per tick on which any source moved (one slayer task may bump both
 * the main streak and Mortimer's own). {@code unless} vetoes a tick on which another var moved.
 *
 * <p>A var that arrives AFTER settling (0, then the real value) is the one false-credit risk. Two
 * guards: {@code maxDelta} set per entry to one real action's ceiling, so a big balance re-baselines;
 * and {@code balance} entries never count a rise from 0.
 *
 * <p>The baseline is taken only once logged in and settled ({@link #SETTLE_TICKS} ticks): right at
 * login the client's vars are still arriving, and a 0 → real-balance jump read then would credit a
 * whole bank of points. A single source jump bigger than {@code maxDelta} is re-baselined instead of
 * credited — the honest sources move by tens or hundreds per action, so a bigger jump is a resync.
 *
 * <p>Pure (no client): {@link #tick} is handed a {@link Reader}, so the rules are unit-tested.
 */
final class GameValueCounters {
	/** Ticks after a session starts (or after a loading zone) before values count. */
	static final int SETTLE_TICKS = 5;
	/** Fallback per-source jump cap when the site sends none. */
	static final int DEFAULT_MAX_DELTA = 1000;

	@AllArgsConstructor
	static final class Source {
		/** "varbit" or "varp". */
		String type;
		int id;

		Source() {
		}

		boolean isVarp() {
			return "varp".equalsIgnoreCase(type);
		}

		boolean valid() {
			return id > 0 && ("varp".equalsIgnoreCase(type) || "varbit".equalsIgnoreCase(type));
		}

		String key() {
			return (isVarp() ? "p" : "b") + id;
		}
	}

	/** One catalog entry as the site ships it. */
	static final class Entry {
		String name;
		List<Source> sources;
		/** "increase" (default) or "decrease". */
		String direction;
		/** False until checked in game: credits carry the 'unverified_counter' flag. */
		boolean confirmed;
		/** Largest single per-source jump that is credited; 0 → {@link #DEFAULT_MAX_DELTA}. */
		int maxDelta;
		/** Count 1 per tick on which any source moved, instead of summing the deltas. */
		boolean changes;
		/**
		 * A points BALANCE (Tithe Farm, Foundry reputation): a rise from 0 is the value arriving late,
		 * not points earned, so it re-baselines. Costs one action for a player sitting on exactly 0;
		 * never set on streaks or pools where 0 → small is the normal case.
		 */
		boolean balance;
		/**
		 * Skip a tick on which any of these moved the same way: "other masters" is the main slayer
		 * streak rising when neither Mortimer's nor Krystilia's own did.
		 */
		List<Source> unless;

		Entry() {
		}

		Entry(String name, boolean confirmed, int maxDelta, Source... sources) {
			this.name = name;
			this.confirmed = confirmed;
			this.maxDelta = maxDelta;
			this.sources = java.util.Arrays.asList(sources);
		}

		boolean decreasing() {
			return "decrease".equalsIgnoreCase(direction);
		}

		int cap() {
			return maxDelta > 0 ? maxDelta : DEFAULT_MAX_DELTA;
		}

		boolean valid() {
			if (name == null || name.trim().isEmpty() || sources == null || sources.isEmpty()) return false;
			for (Source s : sources) {
				if (s == null || !s.valid()) return false;
			}
			if (unless != null) {
				for (Source s : unless) {
					if (s == null || !s.valid()) return false;
				}
			}
			return true;
		}
	}

	/** A change to credit under {@code entry.name}. */
	@RequiredArgsConstructor
	static final class Credit {
		final Entry entry;
		final int amount;
	}

	interface Reader {
		int read(boolean varp, int id);
	}

	// Baselines, keyed per entry name AND var, so two entries on one var each keep their own.
	final Map<String, Integer> last = new HashMap<>();
	List<Entry> entries = Collections.emptyList();
	List<Entry> source;
	boolean inGame;
	int settleTicks;

	/** Replace the catalog (a no-op for the same list as last time). Invalid entries are dropped. */
	void configure(List<Entry> next) {
		if (next == source && source != null) return;
		source = next;
		List<Entry> clean = new ArrayList<>();
		if (next != null) {
			for (Entry e : next) {
				if (e != null && e.valid()) clean.add(e);
			}
		}
		entries = clean;
	}

	List<Entry> entries() {
		return entries;
	}

	/**
	 * Called every logged-in tick (idempotent): the first one after a session ended — or after the
	 * plugin started mid-session — starts a fresh session whose values settle before counting.
	 */
	void onLoggedIn() {
		if (!inGame) {
			last.clear();
			inGame = true;
			settleTicks = 0;
		}
	}

	/** LOADING: same account, values persist — pause reads and resume after settling, keep baselines. */
	void onLoading() {
		settleTicks = 0;
	}

	/** Login screen / hop / connection lost: the next account's values are not this one's. */
	void onSessionEnd() {
		last.clear();
		inGame = false;
		settleTicks = 0;
	}

	/**
	 * One game tick. {@code wanted} names the entries worth reading (a tile targets one of their
	 * names); others are forgotten so a tile added later baselines fresh rather than crediting what
	 * moved meanwhile.
	 */
	List<Credit> tick(Reader reader, Predicate<Entry> wanted) {
		if (!inGame) return Collections.emptyList();
		if (settleTicks < SETTLE_TICKS) {
			settleTicks++;
			return Collections.emptyList();
		}
		List<Credit> out = null;
		for (Entry e : entries) {
			var prefix = e.name.toLowerCase(Locale.ROOT) + "|";
			if (!wanted.test(e)) {
				last.keySet().removeIf(k -> k.startsWith(prefix));
				continue;
			}
			int total = 0;
			var moved = false;
			for (Source s : e.sources) {
				int delta = delta(reader, e, prefix, s);
				if (delta > 0) {
					total += delta;
					moved = true;
				}
			}
			var vetoed = false;
			if (e.unless != null) {
				// Every veto source is read (not short-circuited) so each keeps its baseline current.
				for (Source s : e.unless) vetoed |= delta(reader, e, prefix + "!", s) > 0;
			}
			if (!moved || vetoed) continue;
			if (out == null) out = new ArrayList<>();
			out.add(new Credit(e, e.changes ? 1 : total));
		}
		return out == null ? Collections.emptyList() : out;
	}

	/**
	 * This source's change since last tick in the entry's direction, re-baselining as it goes; 0 for
	 * a first sighting, a change the other way (spend / reset) or a jump past the cap (a resync).
	 */
	int delta(Reader reader, Entry e, String prefix, Source s) {
		int now = reader.read(s.isVarp(), s.id);
		var before = last.put(prefix + s.key(), now);
		if (before == null) return 0;
		if (e.balance && before == 0 && !e.decreasing()) {
			return 0; // a balance reading 0 then a real number: it arrived, nobody earned it
		}
		int delta = e.decreasing() ? before - now : now - before;
		return delta <= 0 || delta > e.cap() ? 0 : delta;
	}
}

package com.anvil;

import java.awt.AlphaComposite;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Collections;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.stream.ImageInputStream;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.Timer;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

/**
 * A panel GIF decoded by us and played on our own clock, instead of handing raw bytes to AWT's
 * Toolkit decoder. That decoder stopped when its observers detached (an idle or hidden panel never
 * resumed), restarted blank when labels swapped, and sized its canvas from whatever the file
 * declared. Here every frame is composited once under a fixed pixel budget, it always loops, and it
 * advances only while a label showing it is on screen and the client window is in front — so after
 * idling it carries on from the frame it stopped at.
 */
final class GifIcon implements Icon {
	/** Decoded canvas pixels across all frames (~24 MB of ARGB): a 220x73 banner of 60 frames is ~1M. */
	static final long MAX_PIXELS = 6_000_000L;
	static final int MAX_FRAMES = 300;
	/** GIF delays are centiseconds; 0/1 means "as fast as possible", which browsers show as 100 ms. */
	static final int MIN_DELAY_MS = 20;
	static final int FALLBACK_DELAY_MS = 100;

	static final Set<GifIcon> LIVE = Collections.newSetFromMap(new WeakHashMap<>());
	static long lastTick;
	static final Timer TICK = new Timer(20, e -> tick());

	final BufferedImage[] frames;
	final int[] ends;
	final int total;
	final Map<Component, Boolean> hosts = new WeakHashMap<>();
	long playedMs;
	int shown;

	GifIcon(BufferedImage[] frames, int[] ends) {
		this.frames = frames;
		this.ends = ends;
		total = ends[ends.length - 1];
	}

	/** Its own clock for another label; the decoded frames are shared. */
	GifIcon copy() {
		return new GifIcon(frames, ends);
	}

	int frameCount() {
		return frames.length;
	}

	@Override
	public int getIconWidth() {
		return frames[0].getWidth();
	}

	@Override
	public int getIconHeight() {
		return frames[0].getHeight();
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y) {
		if (c != null && frames.length > 1) {
			hosts.put(c, Boolean.TRUE);
			if (LIVE.add(this) && !TICK.isRunning()) {
				lastTick = System.currentTimeMillis();
				TICK.start();
			}
		}
		g.drawImage(frames[shown], x, y, null);
	}

	/** EDT: advance every icon some showing label holds, while the client window is in front. */
	static void tick() {
		var now = System.currentTimeMillis();
		// Clamped, so a stalled EDT or a long idle never fast-forwards: playback resumes where it was.
		var dt = Math.max(0, Math.min(100, now - lastTick));
		lastTick = now;
		if (LIVE.isEmpty()) {
			TICK.stop();
			return;
		}
		var active = GradientLabel.clientActive();
		for (Iterator<GifIcon> it = LIVE.iterator(); it.hasNext(); ) {
			var icon = it.next();
			if (icon.hosts.isEmpty()) {
				it.remove();
				continue;
			}
			if (active && icon.anyShowing()) icon.advance(dt);
		}
	}

	boolean anyShowing() {
		for (Component c : hosts.keySet()) {
			if (c.isShowing()) return true;
		}
		return false;
	}

	void advance(long dt) {
		playedMs = (playedMs + dt) % total;
		int next = frameAt(playedMs);
		if (next != shown) {
			shown = next;
			for (Component c : hosts.keySet()) {
				if (c.isShowing()) c.repaint();
			}
		}
	}

	int frameAt(long t) {
		for (int i = 0; i < ends.length; i++) {
			if (t < ends[i]) return i;
		}
		return ends.length - 1;
	}

	int shownFrame() {
		return shown;
	}

	/**
	 * A GIF the site already sized to fit {@code w}x{@code h}: a {@link GifIcon} when animated, a still
	 * ImageIcon when it has one frame, null when it isn't a GIF or breaks a bound (canvas, any frame's
	 * size or position, frame count, total pixels).
	 */
	static Icon decode(byte[] bytes, int w, int h) {
		if (bytes == null || bytes.length < 10 || bytes[0] != 'G' || bytes[1] != 'I' || bytes[2] != 'F') return null;
		int lw = (bytes[6] & 0xff) | (bytes[7] & 0xff) << 8;
		int lh = (bytes[8] & 0xff) | (bytes[9] & 0xff) << 8;
		if (lw <= 0 || lh <= 0 || lw > w || lh > h) return null;
		try (ImageInputStream in = ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))) {
			var readers = in == null ? null : ImageIO.getImageReaders(in);
			if (readers == null || !readers.hasNext()) return null;
			var reader = readers.next();
			try {
				reader.setInput(in, false, false);
				int n = reader.getNumImages(true);
				if (n <= 0 || n > MAX_FRAMES || (long) lw * lh * n > MAX_PIXELS) return null;
				var frames = new BufferedImage[n];
				int[] ends = new int[n];
				var canvas = new BufferedImage(lw, lh, BufferedImage.TYPE_INT_ARGB);
				int at = 0;
				for (int i = 0; i < n; i++) {
					int fw = reader.getWidth(i), fh = reader.getHeight(i);
					var f = frameInfo(reader.getImageMetadata(i));
					if (f == null || fw <= 0 || fh <= 0 || f.x < 0 || f.y < 0 || f.x + fw > lw || f.y + fh > lh) return null;
					var before = "restoreToPrevious".equals(f.disposal) ? copyOf(canvas) : null;
					var raw = reader.read(i);
					var g = canvas.createGraphics();
					g.drawImage(raw, f.x, f.y, null);
					g.dispose();
					frames[i] = copyOf(canvas);
					at += f.delayMs;
					ends[i] = at;
					if ("restoreToBackgroundColor".equals(f.disposal)) {
						var clear = canvas.createGraphics();
						clear.setComposite(AlphaComposite.Clear);
						clear.fillRect(f.x, f.y, fw, fh);
						clear.dispose();
					} else if (before != null) canvas = before;
				}
				return n == 1 ? new ImageIcon(frames[0]) : new GifIcon(frames, ends);
			} finally {
				reader.dispose();
			}
		} catch (IOException | RuntimeException | OutOfMemoryError e) {
			return null;
		}
	}

	static final class Frame {
		int x;
		int y;
		int delayMs = FALLBACK_DELAY_MS;
		String disposal = "none";
	}

	static Frame frameInfo(IIOMetadata meta) {
		var root = meta == null ? null : meta.getAsTree("javax_imageio_gif_image_1.0");
		if (root == null) return null;
		var f = new Frame();
		var placed = false;
		for (Node n = root.getFirstChild(); n != null; n = n.getNextSibling()) {
			var a = n.getAttributes();
			if ("ImageDescriptor".equals(n.getNodeName())) {
				f.x = Integer.parseInt(a.getNamedItem("imageLeftPosition").getNodeValue());
				f.y = Integer.parseInt(a.getNamedItem("imageTopPosition").getNodeValue());
				placed = true;
			} else if ("GraphicControlExtension".equals(n.getNodeName())) {
				int cs = Integer.parseInt(a.getNamedItem("delayTime").getNodeValue());
				f.delayMs = cs <= 1 ? FALLBACK_DELAY_MS : Math.max(MIN_DELAY_MS, cs * 10);
				f.disposal = a.getNamedItem("disposalMethod").getNodeValue();
			}
		}
		return placed ? f : null;
	}

	static BufferedImage copyOf(BufferedImage src) {
		var out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		var g = out.createGraphics();
		g.setComposite(AlphaComposite.Src);
		g.drawImage(src, 0, 0, null);
		g.dispose();
		return out;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.awt.*;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * The sidebar's small symbols — chevrons, the external-link arrow, a tick, a cross, an ellipsis —
 * drawn as vector shapes instead of typed as characters.
 *
 * <p>Typed, they depended on the font: the RuneScape font has none of ‹ › ↗ ✓ ⋯, so each platform
 * substituted whatever its own fallback had. On macOS that was often nothing (an empty box or a
 * blank), and where a glyph did appear it sat on the text baseline, below the middle of the words
 * beside it. Drawn, they look the same everywhere, and Swing centres an icon against its label.
 *
 * <p>The colour follows the component's foreground (a hovered button's orange, a done tick's green)
 * unless one is fixed at construction.
 */
@RequiredArgsConstructor
final class GlyphIcon implements Icon {
	enum Shape {
		CHEVRON_LEFT, CHEVRON_RIGHT, EXTERNAL, CHECK, CLOSE, ELLIPSIS, GEAR, STAR, UP, DOWN
	}

	final Shape shape;
	final int size;
	final Color color;

	GlyphIcon(Shape shape, int size) {
		this(shape, size, null);
	}


	@Override
	public int getIconWidth() {
		return size;
	}

	@Override
	public int getIconHeight() {
		return size;
	}

	@Override
	public void paintIcon(Component c, Graphics graphics, int x, int y) {
		var g = (Graphics2D) graphics.create();
		try {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			var ink = color != null ? color : (c != null ? c.getForeground() : Color.WHITE);
			if (c != null && !c.isEnabled()) ink = ink.darker();
			g.setColor(ink);
			float s = size;
			g.setStroke(new BasicStroke(Math.max(1.4f, s / 7f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.translate(x, y);
			Path2D p = new Path2D.Float();
			switch (shape) {
				case CHEVRON_LEFT:
					g.draw(stroke(p, s, 0.62, 0.22, 0.34, 0.5, 0.62, 0.78));
					break;
				case CHEVRON_RIGHT:
					g.draw(stroke(p, s, 0.38, 0.22, 0.66, 0.5, 0.38, 0.78));
					break;
				case EXTERNAL:
					stroke(p, s, 0.28, 0.72, 0.72, 0.28);
					g.draw(stroke(p, s, 0.4, 0.28, 0.72, 0.28, 0.72, 0.6));
					break;
				case CHECK:
					g.draw(stroke(p, s, 0.2, 0.52, 0.42, 0.74, 0.8, 0.28));
					break;
				case CLOSE:
					stroke(p, s, 0.28, 0.28, 0.72, 0.72);
					g.draw(stroke(p, s, 0.72, 0.28, 0.28, 0.72));
					break;
				case ELLIPSIS:
					var d = Math.max(2f, s / 6f);
					for (int i = 0; i < 3; i++) {
						var cx = s * (0.25f + 0.25f * i);
						g.fill(new java.awt.geom.Ellipse2D.Float(cx - d / 2, s * 0.5f - d / 2, d, d));
					}
					break;
				case GEAR:
					// A ring with eight short teeth — the settings mark everyone reads without a label.
					var cx = s / 2f;
					var r = s * 0.24f;
					g.draw(new java.awt.geom.Ellipse2D.Float(cx - r, cx - r, r * 2, r * 2));
					for (int i = 0; i < 8; i++) {
						var a = Math.PI / 4 * i;
						p.moveTo(cx + Math.cos(a) * s * 0.33, cx + Math.sin(a) * s * 0.33);
						p.lineTo(cx + Math.cos(a) * s * 0.44, cx + Math.sin(a) * s * 0.44);
					}
					g.draw(p);
					break;
				case STAR:
					// Filled five points: an Anvil Supporter, beside their name.
					g.fill(star(p, s, 1));
					break;
				case UP:
				case DOWN:
					// A filled triangle: a rank moving up or down since the start of the day.
					var up = shape == Shape.UP;
					g.fill(stroke(p, s, 0.12, up ? 0.78 : 0.22, 0.5, up ? 0.22 : 0.78, 0.88, up ? 0.78 : 0.22));
					break;
				default:
					break;
			}
		} finally {
			g.dispose();
		}
	}

	/** A five-point star {@code k} of the icon's size, centred. */
	static Path2D star(Path2D p, float s, double k) {
		for (int i = 0; i < 10; i++) {
			var ang = -Math.PI / 2 + Math.PI / 5 * i;
			var rad = s * k * (i % 2 == 0 ? 0.5 : 0.21);
			var px = s / 2.0 + Math.cos(ang) * rad;
			var py = s * (0.5 + 0.03 * k) + Math.sin(ang) * rad;
			if (i == 0) p.moveTo(px, py);
			else p.lineTo(px, py);
		}
		p.closePath();
		return p;
	}

	/** Adds one polyline to {@code p}: x,y pairs as fractions of the icon's size {@code s}. */
	static Path2D stroke(Path2D p, float s, double... xy) {
		p.moveTo(s * xy[0], s * xy[1]);
		for (int i = 2; i < xy.length; i += 2) p.lineTo(s * xy[i], s * xy[i + 1]);
		return p;
	}
}

package com.anvil;

import lombok.Setter;
import java.awt.*;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.Collections;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

/**
 * A label whose text is painted with a left-to-right gradient (an Anvil Supporter's name). The icon
 * keeps its own colours (a team swatch is information) unless it's the supporter star, which the
 * gradient runs on through as the name's last letter. Swing has no gradient text, so the label
 * is drawn once to an image at the screen's scale (redrawn only when its size, text, font or scale
 * change) and each frame fills the text box through that image's pixels into a reused buffer.
 * A moving one (Patron) slides its gradient along: one shared timer repaints only those on screen.
 */
final class GradientLabel extends JLabel {
	/** Side-panel labels look faster at the same rate because they are compact; keep them at five seconds. */
	static final long PANEL_CYCLE_MS = 5000;
	/** RuneScape chat and widget names use the same calm five-second cycle as the side panel. */
	static final long GAME_CYCLE_MS = 5000;
	static final Set<GradientLabel> MOVING = Collections.newSetFromMap(new WeakHashMap<>());
	/** The player's "Animated names" setting: off, a moving gradient holds still. */
	@Setter static volatile boolean animate = true;
	static final Timer TICK = new Timer(40, e -> { if (animate && clientActive()) MOVING.forEach(l -> { if (l.isShowing()) l.repaint(); }); });

	/**
	 * Whether the client window is in front. WINDOW focus on purpose: RuneLite's FocusChanged follows
	 * the game canvas, so clicking the side panel would pause the panel's own gradients. Behind
	 * another app or minimised, moving names hold still to spare weak PCs; the phase stays on the
	 * wall clock, so on refocus they pick up where they'd be with no reset.
	 */
	static boolean clientActive() {
		// A field read, asked several times a frame from the client thread: kept by window events.
		return active;
	}

	static volatile boolean active = true;
	static Window watched;
	/** Follows the client window coming to the front and going behind (listening only, no input). */
	static final java.awt.event.WindowAdapter FRONT = new java.awt.event.WindowAdapter() {
		@Override
		public void windowActivated(java.awt.event.WindowEvent e) {
			active = true;
		}

		@Override
		public void windowDeactivated(java.awt.event.WindowEvent e) {
			active = false;
		}
	};

	/** Watch this window (the client's); null stops watching. On the EDT. */
	static void watch(Window w) {
		if (watched != null) watched.removeWindowListener(FRONT);
		watched = w;
		active = true;
		if (w != null) w.addWindowListener(FRONT);
	}

	/** Played animation time: starts at the wall clock (clients begin in step) and runs only while in front. */
	static long playedMs = System.currentTimeMillis();
	static long lastWallMs = playedMs;

	/**
	 * Shared phase clock for Swing labels and game widgets (EDT and client thread). It never resets on
	 * a panel rebuild, and it stands still while the client window is in the background, so names
	 * carry on from where they stopped instead of jumping to a new spot in the cycle.
	 */
	static synchronized long animationTimeMillis() {
		if (!animate) return 0;
		var now = System.currentTimeMillis();
		var dt = now - lastWallMs;
		lastWallMs = now;
		// Clamped: a long gap between frames (a stall, a hidden panel) never fast-forwards.
		if (dt > 0 && clientActive()) playedMs += Math.min(dt, 250);
		return playedMs;
	}

	final Color[] stops;
	final float[] fractions;
	final boolean moving;

	// The label as Swing draws it, plus a same-size buffer each frame is composed in.
	BufferedImage base;
	BufferedImage frame;
	final Rectangle textR = new Rectangle();
	final Rectangle iconR = new Rectangle();
	/** The supporter star takes the gradient too; any other icon keeps its colours. */
	boolean tintIcon;
	/** What the gradient fills: the text, or the text and the star. */
	final Rectangle fillR = new Rectangle();
	String baseKey;

	/** Paint the icon with the gradient too (the supporter star), not only the text. */
	void setTintIcon(boolean tintIcon) {
		this.tintIcon = tintIcon;
		baseKey = null;
		repaint();
	}

	GradientLabel(Color[] stops, boolean moving) {
		this.stops = stops;
		this.moving = moving;
		fractions = new float[stops.length];
		for (int i = 0; i < stops.length; i++) fractions[i] = stops.length == 1 ? 0f : (float) i / (stops.length - 1);
	}

	@Override
	public void addNotify() {
		super.addNotify();
		if (moving) {
			MOVING.add(this);
			TICK.start();
		}
	}

	@Override
	public void removeNotify() {
		super.removeNotify();
		MOVING.remove(this);
		if (MOVING.isEmpty()) TICK.stop();
		base = null;
		frame = null;
		baseKey = null;
	}

	@Override
	protected void paintComponent(Graphics g) {
		int w = getWidth();
		int h = getHeight();
		if (stops.length < 2 || w <= 0 || h <= 0 || isOpaque() || getText() == null || getText().isEmpty()) {
			super.paintComponent(g);
			return;
		}
		var g2d = (Graphics2D) g;
		var at = g2d.getTransform();
		var sx = Math.max(1, at.getScaleX());
		var sy = Math.max(1, at.getScaleY());
		int iw = (int) Math.ceil(w * sx);
		int ih = (int) Math.ceil(h * sy);

		var key = w + "x" + h + "@" + sx + "," + sy + "|" + getText() + "|" + getFont() + "|" + getForeground()
			+ "|" + System.identityHashCode(getIcon()) + "|" + getInsets();
		if (base == null || !key.equals(baseKey)) {
			drawBase(g2d, w, h, iw, ih, sx, sy);
			baseKey = key;
		}

		var fg = frame.createGraphics();
		try {
			fg.setComposite(AlphaComposite.Src);
			fg.drawImage(base, 0, 0, null);
			if (fillR.width > 0) {
				fg.scale(sx, sy);
				fg.setComposite(AlphaComposite.SrcIn);
				// REFLECT repeats every two widths, so a shift over that whole period wraps seamlessly.
				var period = 2f * fillR.width;
				var shift = moving && animate ? (animationTimeMillis() % PANEL_CYCLE_MS) / (float) PANEL_CYCLE_MS * period : 0;
				fg.setPaint(new LinearGradientPaint(fillR.x - shift, 0, fillR.x - shift + fillR.width, 0, fractions, stops,
					MultipleGradientPaint.CycleMethod.REFLECT));
				fg.fillRect(fillR.x, fillR.y, fillR.width, fillR.height);
			}
		} finally {
			fg.dispose();
		}

		var g2 = (Graphics2D) g.create();
		try {
			g2.scale(1 / sx, 1 / sy);
			g2.drawImage(frame, 0, 0, null);
		} finally {
			g2.dispose();
		}
	}

	void drawBase(Graphics2D g, int w, int h, int iw, int ih, double sx, double sy) {
		if (base == null || base.getWidth() != iw || base.getHeight() != ih) {
			base = new BufferedImage(iw, ih, BufferedImage.TYPE_INT_ARGB);
			frame = new BufferedImage(iw, ih, BufferedImage.TYPE_INT_ARGB);
		}
		var ig = base.createGraphics();
		try {
			ig.setComposite(AlphaComposite.Clear);
			ig.fillRect(0, 0, iw, ih);
			ig.setComposite(AlphaComposite.SrcOver);
			// Swing hands paintComponent a graphics already set to the label's font, colour and hints.
			ig.setRenderingHints(g.getRenderingHints());
			ig.scale(sx, sy);
			ig.setFont(getFont());
			ig.setColor(getForeground());
			super.paintComponent(ig);
		} finally {
			ig.dispose();
		}
		var in = getInsets();
		var view = new Rectangle(in.left, in.top, w - in.left - in.right, h - in.top - in.bottom);
		textR.setBounds(0, 0, 0, 0);
		iconR.setBounds(0, 0, 0, 0);
		SwingUtilities.layoutCompoundLabel(this, getFontMetrics(getFont()), getText(), getIcon(),
			getVerticalAlignment(), getHorizontalAlignment(), getVerticalTextPosition(), getHorizontalTextPosition(),
			view, iconR, textR, getIconTextGap());
		fillR.setBounds(tintIcon && getIcon() != null && !iconR.isEmpty() ? textR.union(iconR) : textR);
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.function.BooleanSupplier;

import net.runelite.api.*;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.*;

/**
 * An "Anvil" button in a game interface's title bar — the collection log's, beside other
 * plugins' buttons, and the clan window's.
 *
 * <p>WHY BUTTONS AND NOT THE TAB WE DELETED. The in-game clog TAB went in 5d2e425 — four thousand
 * lines of hand-drawn widgets nobody read, sitting between the side panel (progress at a glance) and
 * the site (real search). These are not that: one control each, in the place the player already is,
 * doing what the sidebar already does, for somebody whose hands are in the game interface rather
 * than in RuneLite's.
 *
 * <p>DRAWN AS A BUTTON, NOT AS A WORD. The first version was a bare text widget, which read as a
 * stray label rather than something to click — its neighbours have a raised stone frame and a hover
 * state, and beside them a floating "Anvil" looks like a rendering fault. So this is the game's own
 * button: the V2 stone button's nine sprites (a backing, four corners, four edges) with the text
 * laid over the whole area carrying the listeners, swapping to the pressed-in set on hover. There is
 * essentially one right answer here and every plugin with a button in these bars has found it — the
 * sprites are the same ids whether a codebase spells them the legacy way (WORLD_MAP_BUTTON_*,
 * EQUIPMENT_BUTTON_*_HOVERED) or the generated way used here.
 *
 * <p>POSITIONED FROM THE RIGHT EDGE, not off a measured neighbour. Everything in these bars is
 * anchored right — the close button, then each plugin's button walking left — so an absolute-right
 * offset lands in the same slot at any window size, where arithmetic off another plugin's
 * coordinates moves the moment they move theirs.
 *
 * <p>SURVIVES A NEIGHBOUR REBUILDING THE BAR. WikiSync clears every dynamic child of this container
 * before adding its own, on the same script we draw on, so whether our button exists comes down to
 * who ran last — which is plugin load order, and nobody's to rely on. The answer is not to fight it:
 * we keep hold of what we made, notice when it is no longer attached, and build it again.
 */
@RequiredArgsConstructor
final class HeaderButton {
	/** Matches the native header buttons: small, and tall enough to hit comfortably. */
	static final int WIDTH = 71;
	static final int FALLBACK_HEIGHT = 20;
	/** The dimensions the nine-slice sprites are cut at. Stretching a corner is what looks wrong. */
	static final int CORNER = 9;
	static final int EDGE = 4;

	/** The stone button as it sits: raised, on the light backing. */
	static final int[] SPRITES_IDLE = {
		SpriteID.TRADEBACKING,
		SpriteID.V2StoneButtonOut.A_TOP_LEFT,
		SpriteID.V2StoneButtonOut.A_TOP_RIGHT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_LEFT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_TOP,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_BOTTOM,
	};

	/** The same button pressed in, on the dark backing — the game's own hover state for it. */
	static final int[] SPRITES_HOVERED = {
		SpriteID.TRADEBACKING_DARK,
		SpriteID.V2StoneButtonIn.A_TOP_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonIn.A_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP,
		SpriteID.V2StoneButtonIn.A_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM,
	};

	/** The frame's nine pieces, then the text on top. */
	static final int PARTS = 10;
	static final int TEXT = 9;

	static final int TEXT_IDLE = 0xd6d6d6;
	static final int TEXT_HOVERED = 0xffffff;

	/**
	 * The menu TARGET. The game builds an entry as "&lt;action&gt; &lt;name&gt;", which is why the
	 * action passed in is a verb alone — spelling it in both produced "Sync to Anvil Anvil".
	 */
	static final String NAME = "Anvil";

	final Client client;
	/** The container to draw in — the one the neighbouring buttons use, so we share its space. */
	final int parentId;
	/** A native control in that bar, read for the row's height and vertical anchoring. */
	final int anchorId;
	/** Distance from the bar's right edge to our left edge, in the slot left of our neighbours. */
	final int rightOffset;
	/** Where to sit when the slot nearer the close button is empty. Equal to rightOffset when the
	 *  caller has no nearer slot to fall back to (the clan window, where we are already first). */
	final int nearOffset;
	final String label;
	/** The verb alone; the game appends {@link #NAME} to it. */
	final String action;
	/** Whether syncing is possible right now — no site or no token means no button. */
	final BooleanSupplier enabled;
	final Runnable onClick;

	/** What we drew last time. Null until the first render, stale after a neighbour clears the bar. */
	Widget[] parts;
	/** The slot those parts were drawn in, so a change of neighbours can be noticed and acted on. */
	int drawnAt = Integer.MIN_VALUE;

	HeaderButton(Client client, int parentId, int anchorId, int rightOffset, String label, String action,
			BooleanSupplier enabled, Runnable onClick) {
		this(client, parentId, anchorId, rightOffset, rightOffset, label, action, enabled, onClick);
	}

	/**
	 * Draw the button, or leave alone the one already there.
	 *
	 * <p>Safe to call on every draw of the interface. Must run on the client thread — and, because of
	 * the neighbour that clears this container, wants to run AFTER every other subscriber to the
	 * script has had its turn.
	 */
	void render() {
		var parent = client.getWidget(parentId);
		var anchor = client.getWidget(anchorId);
		if (parent == null || anchor == null || !enabled.getAsBoolean()) return;
		int x = slotFor(parent);
		if (stillAttached(parent)) {
			if (drawnAt == x) {
				return; // ours, intact, in the right slot — drawing again would only make a second one
			}
			// THE NEIGHBOURS MOVED. Enabling WikiSync mid-session fills the slot we took while it was
			// away, and returning early here left the two buttons stacked on the same spot: ours was
			// still attached, so nothing ever reconsidered where it should be. Hide the old copy and
			// draw again at the slot that is free now.
			hideParts();
		}

		int h = anchor.getOriginalHeight() > 0 ? anchor.getOriginalHeight() : FALLBACK_HEIGHT;
		int y = anchor.getOriginalY();
		int yMode = anchor.getYPositionMode();
		int span = WIDTH - (CORNER * 2);
		var made = new Widget[PARTS];

		// Background first so every edge draws over it, then the corners, then the edges between.
		made[0] = piece(parent, 0, x, y, WIDTH, h, yMode);
		made[1] = piece(parent, 1, x + WIDTH - CORNER, y, CORNER, CORNER, yMode);
		made[2] = piece(parent, 2, x, y, CORNER, CORNER, yMode);
		made[3] = piece(parent, 3, x + WIDTH - CORNER, y + h - CORNER, CORNER, CORNER, yMode);
		made[4] = piece(parent, 4, x, y + h - CORNER, CORNER, CORNER, yMode);
		made[5] = piece(parent, 5, x + WIDTH - CORNER, y + CORNER, CORNER, EDGE, yMode);
		made[7] = piece(parent, 7, x, y + CORNER, CORNER, EDGE, yMode);
		made[6] = piece(parent, 6, x + CORNER, y, span, CORNER, yMode);
		made[8] = piece(parent, 8, x + CORNER, y + h - CORNER, span, CORNER, yMode);

		// The text covers the whole button, so it is what the mouse actually meets: one layer owns
		// the click, the hover and the label, and the nine underneath are decoration.
		var text = child(parent, WidgetType.TEXT, x, y, WIDTH, h, yMode);
		text.setText(label);
		text.setTextColor(TEXT_IDLE);
		text.setFontId(FontID.PLAIN_11);
		text.setTextShadowed(true);
		text.setXTextAlignment(WidgetTextAlignment.CENTER);
		text.setYTextAlignment(WidgetTextAlignment.CENTER);
		text.setHasListener(true);
		text.setAction(0, action);
		text.setOnOpListener((JavaScriptCallback) e -> onClick.run());
		text.setOnMouseOverListener((JavaScriptCallback) e -> paint(made, SPRITES_HOVERED, TEXT_HOVERED));
		text.setOnMouseLeaveListener((JavaScriptCallback) e -> paint(made, SPRITES_IDLE, TEXT_IDLE));
		text.revalidate();
		made[TEXT] = text;

		parts = made;
		drawnAt = x;
		parent.revalidate();
	}

	/**
	 * Which slot to sit in — the far one when a neighbour holds the near one, the near one otherwise.
	 *
	 * The offsets stay FIXED; this only chooses between two of them. Deriving coordinates from
	 * another plugin's widget is what the class comment warns off, and this does not: it asks whether
	 * anything foreign is anchored in the near slot, which is a yes/no about occupancy rather than a
	 * position to copy.
	 *
	 * Without it the far offset was unconditional, so somebody with WikiSync disabled got a button
	 * floating a slot-width away from the close button with an empty gap between them — reserved for
	 * a plugin that was not running.
	 */
	int slotFor(Widget parent) {
		if (nearOffset >= rightOffset) return rightOffset;
		var children = parent.getDynamicChildren();
		if (children != null) {
			for (Widget child : children) {
				if (child == null || NAME.equals(child.getName())) {
					continue; // ours, from a previous render we are about to replace
				}
				if (child.getXPositionMode() != WidgetPositionMode.ABSOLUTE_RIGHT) continue;
				int childX = child.getOriginalX();
				if (childX >= nearOffset && childX < rightOffset) {
					return rightOffset; // somebody is in the near slot; take the one beyond it
				}
			}
		}
		return nearOffset;
	}

	/** One piece of the frame, by its index into the sprite sets. */
	Widget piece(Widget parent, int index, int x, int y, int w, int h, int yMode) {
		var piece = child(parent, WidgetType.GRAPHIC, x, y, w, h, yMode);
		piece.setSpriteId(SPRITES_IDLE[index]);
		piece.revalidate();
		return piece;
	}

	/** One of our widgets, named as ours and placed from the parent's right edge. */
	static Widget child(Widget parent, int type, int x, int y, int w, int h, int yMode) {
		var c = parent.createChild(-1, type);
		c.setName(NAME);
		c.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		c.setYPositionMode(yMode);
		c.setOriginalX(x);
		c.setOriginalY(y);
		c.setOriginalWidth(w);
		c.setOriginalHeight(h);
		return c;
	}

	/**
	 * Re-evaluate while the window is open: draw, move, or clear as the situation now stands.
	 *
	 * <p>Cheap enough for every tick. When the parent is gone there is nothing to do; when the button
	 * should not be there it is hidden once and then there is nothing to hide; when it is already
	 * right, render() returns on an identity scan.</p>
	 */
	void refresh() {
		var parent = client.getWidget(parentId);
		if (parent == null) {
			// The window is closed. Our widgets went with it, so forget them rather than hiding
			// objects that are no longer attached to anything.
			parts = null;
			drawnAt = Integer.MIN_VALUE;
			return;
		}
		if (!enabled.getAsBoolean()) {
			if (parts != null) hideParts();
			return;
		}
		render();
	}

	/**
	 * Hide what we drew, and forget it.
	 *
	 * <p>Hidden rather than deleted because a dynamic child cannot be removed on its own — the only
	 * removal the API offers clears the whole container, which would take the neighbours with it.
	 * A hidden widget does not render and is collected when the interface is next rebuilt.</p>
	 */
	void hideParts() {
		if (parts != null) {
			for (Widget w : parts) {
				if (w != null) w.setHidden(true);
			}
		}
		parts = null;
		drawnAt = Integer.MIN_VALUE;
	}

	/** Swap the frame between its idle and hovered sprite sets. */
	static void paint(Widget[] made, int[] sprites, int textColour) {
		for (int i = 0; i < TEXT; i++) {
			if (made[i] != null) made[i].setSpriteId(sprites[i]);
		}
		if (made[TEXT] != null) made[TEXT].setTextColor(textColour);
	}

	/**
	 * Is the button we last drew still a child of this bar?
	 *
	 * <p>Identity, not a name lookup. After a neighbour clears the container our widgets are still
	 * perfectly good objects — just no longer attached to anything — so the question is whether the
	 * bar still holds the one we made, which answers both "were we wiped" and "did the interface
	 * rebuild underneath us".
	 */
	boolean stillAttached(Widget parent) {
		if (parts == null || parts[TEXT] == null) return false;
		var children = parent.getDynamicChildren();
		if (children == null) return false;
		for (Widget w : children) {
			if (w == parts[TEXT]) return true;
		}
		return false;
	}
}

package com.anvil;

import lombok.AllArgsConstructor;
/**
 * Which level-ups a destination wants posted: 99s, every {@code skillStep} levels from
 * {@code skillFrom}, every {@code totalStep} total from {@code totalFrom}, and maxing. The site sends
 * one set for the clan's channel and one for the player's own webhooks; a null set wants nothing.
 * {@link #LEGACY_CLAN} is the fixed 99s-and-high-totals set the highlight feed keeps.
 */
@AllArgsConstructor
public class LevelRules {
	public boolean ninetyNines;
	public int skillStep;
	public int skillFrom;
	public int totalStep;
	public int totalFrom;
	public boolean maxTotal;

	@AllArgsConstructor
	public static class Sets {
		public LevelRules clan;
		public LevelRules personal;

		Sets() {
		}

	}

	static final LevelRules LEGACY_CLAN = new LevelRules(true, 0, 1, 100, 1800, true);

	LevelRules() {
	}

	/**
	 * The sets this site asks for, with the clan's dropped when it has no channel for level posts
	 * (the player's own webhooks can still want one — the site routes it). On a game-mode world
	 * ({@code mode} non-null) only the mode's own rules: its stats are a separate character.
	 */
	static Sets resolve(PluginConfigResponse cfg, boolean clanChannel, PluginConfigResponse.ModeThresholds mode) {
		if (mode != null) return new Sets(clanChannel ? mode.levelRules : null, null);
		var s = cfg != null && cfg.levelRules != null ? cfg.levelRules : new Sets();
		return new Sets(clanChannel ? s.clan : null, s.personal);
	}

	boolean matchesSkill(int level) {
		return (level == 99 && ninetyNines)
			|| (skillStep > 0 && level >= skillFrom && (level - skillFrom) % skillStep == 0);
	}

	/** The highest level crossed ({@code prev < L <= now}) that either set wants, or 0. */
	static int skillMilestone(int prev, int now, Sets s) {
		for (int l = now; l > prev; l--) {
			if ((s.clan != null && s.clan.matchesSkill(l)) || (s.personal != null && s.personal.matchesSkill(l))) return l;
		}
		return 0;
	}

	/** The highest round total crossed ({@code prev < M <= now}) that either set wants, or 0. */
	static int totalMilestone(int prev, int now, Sets s) {
		return Math.max(totalMilestone(prev, now, s.clan), totalMilestone(prev, now, s.personal));
	}

	static int totalMilestone(int prev, int now, LevelRules r) {
		if (r == null || r.totalStep <= 0) return 0;
		// The highest multiple reached; if that is under the floor, every lower one is too.
		int m = now / r.totalStep * r.totalStep;
		return m > prev && m >= r.totalFrom ? m : 0;
	}

	static boolean wantsMax(Sets s) {
		return (s.clan != null && s.clan.maxTotal) || (s.personal != null && s.personal.maxTotal);
	}
}

package com.anvil;

import java.awt.event.*;
import java.util.*;
import java.util.function.*;
import javax.swing.SwingUtilities;
import javax.swing.text.*;

/**
 * Type-ahead for the Lookup box, the way RuneLite's hiscores panel does it: as you type, the rest of
 * the first name that fits is written into the box, selected, so Enter takes it and the next letter
 * either follows it or throws it away and looks again. The names are the ones you just looked up,
 * your friends, your clan and whoever is around you — all read off the client, nothing asked of the site.
 *
 * <p>The game's lists live on the client thread, so they're read there into a {@link Names} snapshot
 * that the EDT completes from. Every keystroke asks for a fresh one; when it lands and the box still
 * has nothing completed, the same letters are tried again — someone who has only just walked into
 * view is picked up without typing another letter.</p>
 */
final class LookupSuggestions extends KeyAdapter {
	/** The game's name lists at one moment. Each list may be empty, never null. */
	static final class Names {
		static final Names EMPTY = new Names(null, null, null, null);

		final List<String> clanOnline;
		final List<String> friends;
		final List<String> nearby;
		final List<String> clan;

		Names(Collection<String> clanOnline, Collection<String> friends, Collection<String> nearby, Collection<String> clan) {
			this.clanOnline = copy(clanOnline);
			this.friends = copy(friends);
			this.nearby = copy(nearby);
			this.clan = copy(clan);
		}

		static List<String> copy(Collection<String> names) {
			return names == null ? Collections.emptyList() : new ArrayList<>(names);
		}
	}

	/**
	 * The first name that starts with {@code typed} and is longer than it — recent lookups, then
	 * friends, clan members online, players nearby and the rest of the clan — or null. Never your own.
	 */
	static String complete(String typed, List<String> recent, Names names, String me) {
		var q = Rsn.normalize(typed);
		if (q.isEmpty()) return null;
		var mine = Rsn.normalize(me);
		for (List<String> list : Arrays.asList(recent, names.friends, names.clanOnline, names.nearby, names.clan)) {
			if (list == null) continue;
			for (String raw : list) {
				if (raw == null) continue;
				var name = raw.replace(' ', ' ').trim();
				var key = Rsn.normalize(name);
				if (key.length() > q.length() && key.startsWith(q) && !key.equals(mine)) return name;
			}
		}
		return null;
	}

	final JTextComponent field;
	final BooleanSupplier enabled;
	final Supplier<List<String>> recent;
	final Supplier<String> me;
	final Consumer<Consumer<Names>> fetch;
	volatile Names names = Names.EMPTY;

	/**
	 * @param fetch reads the game's lists and hands them back on any thread (the client thread, live)
	 */
	LookupSuggestions(JTextComponent field, BooleanSupplier enabled, Supplier<List<String>> recent,
		Supplier<String> me, Consumer<Consumer<Names>> fetch) {
		this.field = field;
		this.enabled = enabled;
		this.recent = recent;
		this.me = me;
		this.fetch = fetch;
		field.addKeyListener(this);
	}

	/** Read the game's lists again, then retry the box if it is waiting on a name. */
	void refresh() {
		var asked = field.getText();
		fetch.accept(n -> SwingUtilities.invokeLater(() -> {
			names = n;
			// Only for the letters that asked, and only while nothing is filled in after them.
			if (asked.equals(field.getText()) && field.isFocusOwner() && field.getSelectionStart() == field.getSelectionEnd()
				&& field.getCaretPosition() == asked.length()) {
				fill(asked);
			}
		}));
	}

	@Override
	public void keyTyped(KeyEvent e) {
		char c = e.getKeyChar();
		if (!enabled.getAsBoolean() || Character.isISOControl(c) || !(Character.isLetterOrDigit(c) || c == ' ' || c == '_' || c == '-')
			|| field.getSelectionEnd() != field.getText().length()) {
			return;
		}
		int start = field.getSelectionStart();
		int end = field.getSelectionEnd();
		// The letter typed is the next one of the name already filled in: keep the name, move past it.
		if (start < end && Rsn.normalize(field.getText().substring(start, start + 1)).equals(Rsn.normalize(String.valueOf(c)))) {
			e.consume();
			field.select(start + 1, end);
			return;
		}
		// Otherwise the letter replaces the guess; once it's in, look for a name again.
		SwingUtilities.invokeLater(() -> {
			var typed = field.getText();
			if (field.getCaretPosition() == typed.length()) {
				fill(typed);
				refresh();
			}
		});
	}

	void fill(String typed) {
		var name = complete(typed, recent.get(), names, me.get());
		if (name == null || name.length() <= typed.length()) return;
		try {
			field.getDocument().insertString(typed.length(), name.substring(typed.length()), null);
			field.select(typed.length(), name.length());
		} catch (BadLocationException ignored) {
			// The box changed under us; the next letter tries again.
		}
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * The highlighted game messages seen on a game-mode world (Leagues, Deadman, ...), batched for
 * POST /api/plugin/mode-lines. The site decides which are relics, unlocks or tasks; this only keeps
 * the lines worth asking about (the game colours its announcements) and sends a few seconds at once.
 */
final class ModeLines {
	static final int MAX_BATCH = 20;
	static final long FLUSH_MS = 5_000;

	final List<String> pending = new ArrayList<>();
	long firstAt;
	String last;

	/** Keep one line if it looks like an announcement. True when kept. */
	synchronized boolean offer(String raw, long nowMs) {
		if (raw == null || raw.isEmpty() || raw.length() > 400
			|| (!raw.contains("<col=") && !raw.toLowerCase(Locale.ROOT).startsWith("congratulations"))) {
			return false;
		}
		// The game prints some lines on two channels; one copy is enough.
		if (raw.equals(last) || pending.size() >= MAX_BATCH) return false;
		last = raw;
		if (pending.isEmpty()) firstAt = nowMs;
		pending.add(raw);
		return true;
	}

	/** The batch once it has waited FLUSH_MS, else null. */
	synchronized List<String> drain(long nowMs) {
		if (pending.isEmpty() || nowMs - firstAt < FLUSH_MS) return null;
		List<String> out = new ArrayList<>(pending);
		pending.clear();
		return out;
	}
}

package com.anvil;

import com.google.gson.*;

/**
 * What a clan notification says happened, for the site to turn into a Discord post.
 *
 * <p>The plugin decides WHETHER to post (toggles, channel flags, tier floors, dedup, rarity) and
 * reports what only the client knows; the site's lib/pluginEmbeds.ts owns how it reads (titles,
 * colours, links, wording, number formatting). Sent as {@code {channel, kind, facts}} to
 * /api/plugin/notify. The site has to advertise {@code site-embeds} BEFORE a plugin sending these
 * ships — there is no local fallback. Unset values are left out. Kinds and their facts:
 *
 * <ul>
 * <li>death: message, source, sourceKind (the site validates a {@code fought} source as a boss)</li>
 * <li>drop: items[{id,name,qty,value}] (several = one combined haul), source, sourceKind, kc,
 *     dropRate, guaranteed, troll, notable ("loot"|"unlock"), earned, spoon, note</li>
 * <li>pet: name, itemId, duplicate, source, skill, kc, dropRate</li>
 * <li>clogSlot: item, itemId, slots, slotsMax, source, kc</li>
 * <li>caTask: task, tier ("Easy".."Grandmaster"), totalPoints, nextThreshold</li>
 * <li>caTier: tier — diary: area, tier — quest: quest, difficulty ("Novice".."Grandmaster")</li>
 * <li>level: skill, level, at99, skills (level99 without level, to a site lacking level-rules) —
 *     totalLevel: total, milestone, maxed, current, max</li>
 * <li>line: k (the site's watch kind), line — ge: item, itemId, qty, value, sold — trade / storage:
 *     items (qty below 0 = gave or deposited) — ext: source, text</li>
 * </ul>
 * Every kind also carries {@code rsn} when known.
 */
final class NotifyFacts {
	final String kind;
	final JsonObject facts = new JsonObject();

	NotifyFacts(String kind, String rsn) {
		this.kind = kind;
		put("rsn", rsn);
	}

	NotifyFacts put(String key, String value) {
		if (value != null && !value.isEmpty()) facts.addProperty(key, value);
		return this;
	}

	NotifyFacts put(String key, Number value) {
		if (value != null) facts.addProperty(key, value);
		return this;
	}

	NotifyFacts flag(String key, boolean value) {
		if (value) facts.addProperty(key, true);
		return this;
	}

	/** Adds one entry to the drop's {@code items}. */
	NotifyFacts item(int id, String name, int qty, long value) {
		var items = facts.getAsJsonArray("items");
		if (items == null) {
			items = new JsonArray();
			facts.add("items", items);
		}
		var it = new JsonObject();
		it.addProperty("id", id);
		it.addProperty("name", name);
		it.addProperty("qty", qty);
		it.addProperty("value", value);
		items.add(it);
		return this;
	}

	/**
	 * Matches {@code s} against a site watch, ignoring case: {@code *} is any text, {@code #} a number
	 * (digits and commas). Returns the last number matched (0 if none), or -1. One backtrack point, so
	 * the cost is at most pattern x line.
	 */
	static long glob(String p, String s) {
		int i = 0, j = 0, si = -1, sj = 0;
		long n = 0;
		while (j < s.length()) {
			char c = i < p.length() ? p.charAt(i) : 0;
			if (c == '#' && Character.isDigit(s.charAt(j))) {
				long v = 0;
				for (; j < s.length() && (Character.isDigit(s.charAt(j)) || s.charAt(j) == ','); j++) {
					if (s.charAt(j) != ',') v = Math.min(v * 10 + s.charAt(j) - '0', 1L << 40);
				}
				n = v;
				i++;
			} else if (c == '*') {
				si = ++i;
				sj = j;
			} else if (c != 0 && c != '#' && Character.toLowerCase(c) == Character.toLowerCase(s.charAt(j))) {
				i++;
				j++;
			} else if (si >= 0) {
				i = si;
				j = ++sj;
			} else {
				return -1;
			}
		}
		while (i < p.length() && p.charAt(i) == '*') i++;
		return i == p.length() ? n : -1;
	}
}

package com.anvil;

import lombok.Setter;
import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import java.util.stream.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Clan notifications (POST /api/plugin/notify) the site didn't take, kept and resent.
 *
 * <p>The happy path never comes here: a notification is sent straight away, exactly as before, and
 * only lands in the outbox when that attempt failed for a reason that may clear (no network, a 5xx,
 * 401/408/429). A permanent refusal is dropped where it happened. Each entry keeps the URL and the
 * identity headers (X-RSN, X-Account-Hash) it was first sent with, so a retry after a character switch
 * still speaks for the character the 99 or the pet belonged to.
 *
 * <p>On disk under {@code <plugin dir>/outbox/notify/} as {@code <id>.json} plus {@code <id>.png} when
 * there's a screenshot, so a client restart mid-outage loses nothing. Bounded: at most
 * {@link #MAX_ITEMS} entries, {@link #MAX_BYTES} of screenshots and {@link #MAX_AGE_MS} old — the
 * oldest go first; a notification a day late is news nobody wants.
 *
 * <p>Retries back off from {@link #FIRST_RETRY_MS} to {@link #MAX_RETRY_MS} with jitter, and one
 * failed send ends a pass: with the site down there is no point dialling it once per queued entry.
 * Sends run on the OkHttp pool, never the client thread; disk writes on the thread that enqueued
 * (an OkHttp callback) or that pool.
 */
@RequiredArgsConstructor
@Slf4j
final class NotifyOutbox {
	static final int MAX_ITEMS = 100;
	static final long MAX_AGE_MS = 24L * 60 * 60 * 1000;
	static final long MAX_BYTES = 20L * 1024 * 1024;
	static final long FIRST_RETRY_MS = 15_000L;
	static final long MAX_RETRY_MS = 300_000L;

	enum Result {
		SENT, PERMANENT, RETRY
	}

	interface Sender {
		Result send(Item item, byte[] png);
	}

	/** One queued notification. Serialized as-is; the PNG lives beside it. */
	static final class Item {
		String id;
		String url;
		String channel;
		/** The payload_json exactly as first sent. */
		String payload;
		String filename;
		String rsn;
		String accountHash;
		/** Fingerprint of the token it was sent with: another account's sign-in doesn't send it. */
		String account;
		int pngBytes;
		long createdAt;
		int attempts;
		long nextAttemptAt;
		/** The screenshot, held in memory only when there is no directory to write it to. */
		transient byte[] png;
	}

	final Gson gson;
	final Supplier<ScheduledExecutorService> scheduler;
	final Supplier<ExecutorService> sendPool;
	@Setter volatile Filepath dir;
	@Setter volatile Sender sender;
	final List<Item> items = new ArrayList<>();
	ScheduledFuture<?> task;
	boolean pumping;


	synchronized int size() {
		return items.size();
	}

	/** A fresh entry: first retry after {@link #FIRST_RETRY_MS} (jittered). */
	static Item newItem(long now) {
		var it = new Item();
		it.id = now + "-" + UUID.randomUUID().toString().substring(0, 8);
		it.createdAt = now;
		it.attempts = 1;
		it.nextAttemptAt = now + RetryPolicy.backoffMs(1, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random());
		return it;
	}

	/**
	 * The entries to evict, given the queue (oldest first): everything past {@code maxAge}, then the
	 * oldest until at most {@code maxItems} remain and their screenshots fit in {@code maxBytes}.
	 */
	static List<Item> overflow(List<Item> queue, long now, int maxItems, long maxAge, long maxBytes) {
		List<Item> evict = new ArrayList<>();
		List<Item> kept = new ArrayList<>();
		long bytes = 0;
		for (Item it : queue) {
			if (now - it.createdAt > maxAge) {
				evict.add(it);
			} else {
				kept.add(it);
				bytes += Math.max(0, it.pngBytes);
			}
		}
		int i = 0;
		while (i < kept.size() && (kept.size() - i > maxItems || bytes > maxBytes)) {
			var oldest = kept.get(i++);
			bytes -= Math.max(0, oldest.pngBytes);
			evict.add(oldest);
		}
		return evict;
	}

	/** Read what a previous session left. Blocking (disk); call off the client thread. */
	void load() {
		List<Item> found = new ArrayList<>();
		List<Filepath> pngs = new ArrayList<>();
		for (Filepath f : DiskFiles.listFiles(DiskFiles.ensureDir(dir), n -> n.endsWith(".json") || n.endsWith(".png"))) {
			if (f.getFileName().endsWith(".png")) {
				pngs.add(f);
				continue;
			}
			var it = DiskFiles.readJson(gson, f, Item.class);
			if (it != null && it.id != null && it.url != null && it.payload != null && f.getFileName().equals(it.id + ".json")) {
				found.add(it);
			} else DiskFiles.deleteQuietly(f);
		}
		// A screenshot whose entry never made it to disk is an orphan nothing will read.
		for (Filepath png : pngs) {
			var id = png.getFileName().substring(0, png.getFileName().length() - 4);
			if (found.stream().noneMatch(it -> it.id.equals(id))) DiskFiles.deleteQuietly(png);
		}
		if (found.isEmpty()) return;
		synchronized (this) {
			for (Item it : found) {
				if (items.stream().noneMatch(x -> x.id.equals(it.id))) items.add(it);
			}
			items.sort(Comparator.comparingLong(x -> x.createdAt));
			prune(System.currentTimeMillis());
			log.info("{} notification(s) waiting", items.size());
			schedule(FIRST_RETRY_MS);
		}
	}

	/** Keep a notification that just failed to send. Blocking (disk); never on the client thread. */
	void enqueue(Item item, byte[] png) {
		var d = DiskFiles.ensureDir(dir);
		item.pngBytes = png == null ? 0 : png.length;
		if (d != null) {
			try {
				if (png != null && png.length > 0) DiskFiles.writeAtomic(d.joinSegment(item.id + ".png"), png);
				DiskFiles.writeAtomic(d.joinSegment(item.id + ".json"), gson.toJson(item));
			} catch (IOException | RuntimeException e) {
				item.png = png; // keep it for this session at least
			}
		} else item.png = png;
		synchronized (this) {
			items.add(item);
			prune(System.currentTimeMillis());
			if (task == null || task.isDone()) schedule(Math.max(0, item.nextAttemptAt - System.currentTimeMillis()));
		}
	}

	/** The site is back: try everything now. */
	synchronized void kick() {
		if (items.isEmpty()) return;
		for (Item it : items) it.nextAttemptAt = 0;
		schedule(0);
	}

	/** Signed out: nothing queued may go out under whoever signs in next. */
	void clear() {
		List<Item> all;
		synchronized (this) {
			all = new ArrayList<>(items);
			items.clear();
			cancel();
		}
		all.forEach(this::deleteFiles);
	}

	/** Plugin stopping: cancel the timer; the files stay for next time. */
	synchronized void stop() {
		cancel();
	}

	void cancel() {
		if (task != null) {
			task.cancel(false);
			task = null;
		}
	}

	/** Call with the monitor held. */
	void prune(long now) {
		var evict = overflow(items, now, MAX_ITEMS, MAX_AGE_MS, MAX_BYTES);
		if (evict.isEmpty()) return;
		items.removeAll(evict);
		log.info("Dropped {} stale notification(s)", evict.size());
		var pool = sendPool.get();
		if (pool != null && !pool.isShutdown()) pool.submit(() -> evict.forEach(this::deleteFiles));
	}

	/** Call with the monitor held. */
	void schedule(long waitMs) {
		var ex = scheduler.get();
		if (ex == null || ex.isShutdown()) return;
		cancel();
		task = ex.schedule(this::handOff, Math.max(0, waitMs), TimeUnit.MILLISECONDS);
	}

	/** On the timer: run the pass on the HTTP pool, never the plugin's one thread. */
	void handOff() {
		var pool = sendPool.get();
		if (pool != null && !pool.isShutdown()) pool.submit(this::pump);
	}

	/** One pass over what's due. Blocking HTTP; runs on the OkHttp pool. */
	void pump() {
		var s = sender;
		List<Item> due;
		synchronized (this) {
			if (pumping || s == null) return;
			pumping = true;
			var now = System.currentTimeMillis();
			prune(now);
			due = items.stream().filter(it -> it.nextAttemptAt <= now).collect(Collectors.toList());
		}
		try {
			for (int i = 0; i < due.size(); i++) {
				var it = due.get(i);
				var png = it.pngBytes > 0 ? screenshot(it) : null;
				if (it.pngBytes > 0 && png == null) {
					remove(it); // its screenshot is gone; nothing sensible left to send
					continue;
				}
				var r = s.send(it, png);
				if (r != Result.RETRY) {
					if (r == Result.PERMANENT) log.warn("Queued {} notification refused", it.channel);
					remove(it);
					continue;
				}
				// Still down. Push this one back, and don't dial again for the rest — same wait for all.
				var now = System.currentTimeMillis();
				long next;
				synchronized (this) {
					it.attempts++;
					next = now + RetryPolicy.backoffMs(it.attempts, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random());
					for (int j = i; j < due.size(); j++) due.get(j).nextAttemptAt = Math.max(due.get(j).nextAttemptAt, next);
				}
				rewrite(it);
				break;
			}
		} finally {
			synchronized (this) {
				pumping = false;
				long soonest = items.stream().mapToLong(it -> it.nextAttemptAt).min().orElse(-1);
				if (soonest >= 0) schedule(soonest - System.currentTimeMillis());
			}
		}
	}

	byte[] screenshot(Item it) {
		if (it.png != null) return it.png;
		var d = dir;
		return d == null ? null : DiskFiles.read(d.joinSegment(it.id + ".png"));
	}

	void remove(Item it) {
		synchronized (this) {
			items.remove(it);
		}
		deleteFiles(it);
	}

	void rewrite(Item it) {
		var d = dir;
		if (d == null) return;
		try {
			DiskFiles.writeAtomic(d.joinSegment(it.id + ".json"), gson.toJson(it));
		} catch (IOException | RuntimeException e) {
		}
	}

	void deleteFiles(Item it) {
		var d = dir;
		if (d == null || it.id == null) return;
		try {
			DiskFiles.deleteQuietly(d.joinSegment(it.id + ".json"));
			DiskFiles.deleteQuietly(d.joinSegment(it.id + ".png"));
		} catch (RuntimeException ignored) {
			// joinSegment refusing a name read back from disk: nothing of ours to delete.
		}
	}
}

package com.anvil;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;

/**
 * A tripwire for blocking work on the two threads that must never wait: the client thread (the game
 * loop) and the EDT (the side panel, and the game's mouse and keyboard on their way in). A network
 * round trip or a disk write on either is a freeze; 1.10.1 shipped one. Every blocking primitive
 * calls {@link #check} first, so a new caller that slips onto either thread is named in the log —
 * once per kind of call, with the stack that got it there — rather than felt as a hitch.
 */
@Slf4j
final class OffThread {
	static volatile BooleanSupplier onClientThread = () -> false;
	static final Set<String> reported = ConcurrentHashMap.newKeySet();

	OffThread() {
	}

	/** Bound by the plugin at startUp ({@code client::isClientThread}); unbound reads as "not". */
	static void bindClientThread(BooleanSupplier check) {
		onClientThread = check == null ? () -> false : check;
	}

	/** {@code what} is about to block. Warns if that's on the client thread or the EDT. */
	static void check(String what) {
		var thread = where();
		if (thread != null && reported.add(what + "@" + thread)) log.warn("{} blocked the {}", what, thread, new Throwable("called from"));
	}

	/** The thread that must not block, if this is one; null otherwise. */
	static String where() {
		if (SwingUtilities.isEventDispatchThread()) return "Swing thread (side panel)";
		try {
			return onClientThread.getAsBoolean() ? "client thread (game)" : null;
		} catch (RuntimeException e) {
			return null;
		}
	}
}

package com.anvil;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Progress this client has seen on a tile that the site hasn't confirmed yet — a kill, a drop, a KC
 * line, an XP drop — so the sidebar and the pinned tracker move the moment it happens instead of on
 * the next poll after the push lands.
 *
 * <p>A floor, not a replacement: every surface shows {@code max(site count, floor)}. It lives outside
 * the polled config, so a config refresh that lands before the push doesn't wind the count back. Each
 * floor goes away once the site reaches it, when the push failed ({@link #clear}), or after
 * {@link #TTL_MS} — a floor the site never reaches was wrong, and the site's number wins.
 */
final class OptimisticProgress {
	// Tile ids may be negative: a capped tile's cap counters carry virtual ids (-(tileId * 8 + slot),
	// TileNotes). Only 0 means "no tile".
	static final long TTL_MS = 120_000;

	/** tileId → {floor, expiresAt}. */
	final Map<Integer, long[]> floors = new ConcurrentHashMap<>();
	/**
	 * tileId → the highest count the site has been seen at, from any source (a tile push, the config).
	 * The next gain builds on this rather than on the caller's possibly older count: a teammate's
	 * progress pushed onto the tracker otherwise sat above our floor, and our own gains looked frozen
	 * until they climbed past it. Building on it can only undercount for a moment (if our earlier
	 * gains hadn't reached the site yet), never overcount.
	 */
	final Map<Integer, Long> seenSite = new ConcurrentHashMap<>();
	/** Told when the site's count for a tile went DOWN (a deleted submission): views showing the old one redraw. */
	volatile Runnable onDrop;

	void onDrop(Runnable r) {
		onDrop = r;
	}

	/** This client now has the tile at {@code current} (an absolute team count it just bumped to). */
	void raise(int tileId, long current, long now) {
		if (tileId == 0 || current <= 0) return;
		floors.merge(tileId, new long[]{current, now + TTL_MS},
			(old, add) -> new long[]{Math.max(old[0], add[0]), add[1]});
	}

	/** This client gained {@code delta} on a tile the site last put at {@code siteCurrent}. */
	void add(int tileId, long siteCurrent, long delta, long now) {
		if (tileId == 0 || delta <= 0) return;
		var f = live(tileId, siteCurrent, now);
		var base = Math.max(Math.max(siteCurrent, seenSite.getOrDefault(tileId, 0L)), f == null ? 0 : f[0]);
		raise(tileId, base + delta, now);
	}

	/** What to show for a tile the site puts at {@code siteCurrent}. */
	long apply(int tileId, long siteCurrent, long now) {
		seen(tileId, siteCurrent);
		var f = live(tileId, siteCurrent, now);
		return f == null ? siteCurrent : Math.max(siteCurrent, f[0]);
	}

	/**
	 * The floor alone (0 when none or expired), without deciding it's been reached. For a caller that
	 * holds a count already including it — the panel's on-screen number — which must never be passed
	 * to {@link #apply} as the site's: that would read as "caught up" and throw the floor away.
	 */
	long floor(int tileId, long now) {
		var f = floors.get(tileId);
		return f == null || now > f[1] ? 0 : f[0];
	}

	/**
	 * The site has this tile at {@code siteCurrent} (see {@link #seenSite}). A LOWER number than seen
	 * before means the site took progress away (a staff member deleted a submission, a reset): that
	 * wins at once, and this client's floor for the tile goes with it — else the old high mark stayed
	 * on screen, and every later gain built on it, until the client restarted.
	 */
	void seen(int tileId, long siteCurrent) {
		if (tileId == 0 || siteCurrent < 0) return;
		var before = seenSite.get(tileId);
		if (before != null && siteCurrent < before) {
			seenSite.put(tileId, siteCurrent);
			floors.remove(tileId);
			var r = onDrop;
			if (r != null) r.run();
			return;
		}
		if (siteCurrent > 0) seenSite.merge(tileId, siteCurrent, Math::max);
	}

	/** The push behind this tile's floor failed — back to what the site says. */
	void clear(int tileId) {
		floors.remove(tileId);
		seenSite.remove(tileId);
	}

	void reset() {
		floors.clear();
		seenSite.clear();
	}

	/** The tile's floor while it still means something; drops it once the site caught up or it expired. */
	long[] live(int tileId, long siteCurrent, long now) {
		var f = floors.get(tileId);
		if (f == null) return null;
		if (siteCurrent >= f[0] || now > f[1]) {
			floors.remove(tileId, f);
			return null;
		}
		return f;
	}
}

package com.anvil;

import lombok.Setter;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import java.io.*;
import java.util.*;

@Slf4j
@Singleton
public class PendingSubmissionStore {
	// Garbage-collect pending submissions older than this. Prevents unbounded disk growth
	// when retries keep failing (e.g. site URL permanently wrong) and the user never clears.
	static final long MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000; // 7 days

	/**
	 * The plugin's own directory, handed over by AnvilPlugin — the only class allowed to ask for it.
	 *
	 * THE ROOT ITSELF, not a subfolder, and that is the migration's doing rather than a preference:
	 * `legacyDataDirectory` MOVES `.runelite/osrs-bingo-pending` to BE the plugin directory, so
	 * everything that folder held arrives at its root. Reading from anywhere else would mean not
	 * finding the very files the migration exists to carry across.
	 *
	 * Null until startUp resolves it, and null forever if that failed. Every method treats that as
	 * "no store": nothing queues, nothing loads, and the caller's own error path takes over — which
	 * is the same thing that happened when the disk was full.
	 */
	@Setter volatile Filepath root;

	final Gson gson;

	@Inject
	public PendingSubmissionStore(Gson gson) {
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	public static class PendingSubmission {
		public int eventId;
		public int tileId;
		public int teamId;
		public int amount;
		public String label;
		public String note;
		public String screenshotFile;
		public long timestamp;
		// itemId / durationSeconds / inferred / note: read from proofs older builds saved (legacyFacts).
		public Integer itemId;
		public Integer durationSeconds;
		public String capturedRsn; // character the drop was obtained on; only re-submitted while on it
		public String inferred; // the item was worked out, not seen (DuplicateInference); the site flags it for review
		// Shared kills/runs: teammates seen + party size at the time (lib/coopRuns on the site). Null
		// when the tile doesn't ask; kept on disk so a retried proof still says who was there.
		public List<String> coopGroup;
		public int coopPartySize;
		// A proof the plugin can't auto-submit to a specific tile (pet drop, duplicate Champion's
		// scroll — the "would have received" line names no item), captured so the player has a ready
		// screenshot to attach when they submit by hand on the site. The retry loop skips these.
		public boolean manual;
		// What the site draws the proof's banner from (lib/proofStamp); null on an older capture.
		public JsonObject proof;
		// Another board's clan slug (TrackedTile.board), null for the active board: where a retry posts.
		public String clan;
		// The facts this screenshot proves still to credit (posted image-less to /api/plugin/facts; the
		// site picks the tiles), and each credit's proof key → its tiles' labels, the screenshot still owed.
		public JsonArray facts;
		public JsonObject keys = new JsonObject();
		public long keyAt; // when the last key came: the site reverses a credit a minute after it
	}

	/**
	 * A proof an older build saved for one tile (no facts) as the same submission in a `tile` fact:
	 * its note marks it as one, and the site keeps that note and the saved banner.
	 */
	static JsonArray legacyFacts(PendingSubmission p) {
		var f = new JsonObject();
		f.addProperty("k", "tile");
		f.addProperty("t", p.tileId);
		f.addProperty("n", Math.max(1, p.amount));
		if (p.durationSeconds != null) f.addProperty("sec", p.durationSeconds);
		if (p.itemId != null) f.addProperty("item", p.itemId);
		if (p.inferred != null) f.addProperty("inf", p.inferred);
		f.addProperty("note", p.note == null ? "" : p.note);
		var a = new JsonArray();
		a.add(f);
		return a;
	}

	/** The directory, created on demand, or null when there is nowhere to write. */
	Filepath dir() {
		return DiskFiles.ensureDir(root);
	}

	public String save(PendingSubmission sub, byte[] pngBytes) {
		var dir = dir();
		if (dir == null) return null;
		var id = sub.tileId + "-" + sub.timestamp;

		// Both atomic: a client killed mid-write leaves no half file for the retry loop to choke on.
		var ext = BingoApiClient.isJpeg(pngBytes) ? ".jpg" : ".png";
		var png = dir.joinSegment(id + ext);
		try {
			DiskFiles.writeAtomic(png, pngBytes);
		} catch (IOException e) {
			log.error("Proof image save failed: {}", e.getMessage());
			return null;
		}

		sub.screenshotFile = id + ext;
		try {
			DiskFiles.writeAtomic(dir.joinSegment(id + ".json"), gson.toJson(sub));
		} catch (IOException e) {
			log.error("Proof save failed: {}", e.getMessage());
			// The PNG without its metadata is an orphan nothing will ever read.
			DiskFiles.deleteQuietly(png);
			return null;
		}

		log.info("Saved proof {}", id);
		return id;
	}

	/**
	 * Every queued submission. Depth 1 rather than a full walk: the migration drops these at the root
	 * of the plugin directory alongside `sounds/`, and descending would read a banner clip's
	 * neighbours looking for JSON. An empty or truncated file reads as nothing and is skipped.
	 */
	public List<PendingSubmission> loadAll() {
		List<PendingSubmission> result = new ArrayList<>();
		var now = System.currentTimeMillis();
		for (Filepath f : DiskFiles.listFiles(dir(), n -> n.endsWith(".json"))) {
			var sub = DiskFiles.readJson(gson, f, PendingSubmission.class);
			if (sub == null) {
				log.warn("Failed to read pending submission {}", f.getFileName());
				continue;
			}
			if (sub.timestamp > 0 && (now - sub.timestamp) > MAX_AGE_MS) {
				log.info("Pruning expired pending submission '{}' ({} days old)",
					sub.label, (now - sub.timestamp) / (24 * 60 * 60 * 1000));
				remove(sub);
				continue;
			}
			if (sub.facts == null && !sub.manual) sub.facts = legacyFacts(sub);
			result.add(sub);
		}
		return result;
	}

	/** The facts the site's answer says to send again (their filing failed for a passing reason), or null. */
	static JsonArray retries(JsonObject reply) {
		var a = reply != null && reply.has("retry") && reply.get("retry").isJsonArray() ? reply.getAsJsonArray("retry") : null;
		return a == null || a.size() == 0 ? null : a;
	}

	/** Rewrite a saved proof's metadata (what is still to credit and upload); its screenshot stays. */
	void update(PendingSubmission sub) {
		var dir = dir();
		if (dir == null || sub.screenshotFile == null) return;
		try {
			DiskFiles.writeAtomic(dir.joinSegment(sub.screenshotFile.replaceAll("\\.(png|jpg)$", "") + ".json"), gson.toJson(sub));
		} catch (IOException e) {
			log.error("Proof update failed: {}", e.getMessage());
		}
	}

	public byte[] readScreenshot(PendingSubmission sub) {
		var dir = dir();
		if (dir == null || sub.screenshotFile == null) return null;
		// joinSegment, not join: it refuses a separator, so a screenshotFile read back out of a JSON
		// file cannot walk anywhere with "../" in it.
		try (InputStream in = dir.joinSegment(sub.screenshotFile).openInputStream()) {
			return in.readAllBytes();
		} catch (IOException | RuntimeException e) {
			log.error("Unreadable proof {}: {}", sub.screenshotFile, e.getMessage());
			return null;
		}
	}

	public void remove(PendingSubmission sub) {
		var dir = dir();
		if (dir == null || sub.screenshotFile == null) return;
		var baseName = sub.screenshotFile.replaceAll("\\.(png|jpg)$", "");
		try {
			dir.joinSegment(sub.screenshotFile).deleteIfExists();
			dir.joinSegment(baseName + ".json").deleteIfExists();
			log.info("Removed proof {}", baseName);
		} catch (IOException | RuntimeException e) {
			log.warn("Can't remove proof {}: {}", baseName, e.getMessage());
		}
	}

}

package com.anvil;

import java.util.regex.*;

/**
 * Pulls a personal best out of a completion message.
 *
 * <p>Two shapes, and the difference matters — reading the wrong number would record a slow run as
 * somebody's best:
 * <pre>
 *   "Duration: 2:58.03 (new personal best)"          → the PB is the duration, 2:58.03
 *   "Challenge duration: 10:24. Personal best: 7:59." → the PB is 7:59, NOT this run's 10:24
 * </pre>
 *
 * <p>Times are returned in <b>centiseconds</b>. The game prints hundredths and a leaderboard that
 * rounded to whole seconds would tie runs the game itself separates.
 *
 * <p>The activity is deliberately NOT parsed here: the plugin already extracts it from the adjacent
 * "Your X kill count is: N" line for kill crediting, so PB capture reuses that instead of running a
 * second regex over every line of chat. RuneLite-free, so the fragile part is unit-tested.
 */
final class PersonalBestParser {
	PersonalBestParser() {}

	/** An [h:]mm:ss[.cc] token. The game never prints a bare seconds count for a PB. */
	static final Pattern TIME = Pattern.compile("(\\d{1,3}):(\\d{2})(?::(\\d{2}))?(?:\\.(\\d{1,2}))?");
	/** "personal best: 7:59" — the explicit form, where this run was NOT the best. */
	static final Pattern EXPLICIT = Pattern.compile("personal best:\\s*");

	/**
	 * The personal best this line reports, in centiseconds, or null when it reports none.
	 */
	static Integer parseCentis(String message) {
		if (message == null) return null;
		var lower = message.toLowerCase();
		int marker = lower.indexOf("personal best");
		if (marker < 0) return null;

		// "Personal best: <time>" — read the time AFTER the label, and only that one.
		var explicit = EXPLICIT.matcher(lower);
		if (explicit.find(marker)) {
			var time = TIME.matcher(lower);
			if (time.find(explicit.end())) return toCentis(time);
			return null;
		}

		// "(new personal best)" — this run IS the best, so the line's own duration is the number.
		var time = TIME.matcher(lower);
		if (time.find()) return toCentis(time);
		return null;
	}

	static Integer toCentis(Matcher m) {
		try {
			int centis = TimedClearParser.clockSeconds(m.group(1), m.group(2), m.group(3)) * 100;
			var fraction = m.group(4);
			if (fraction != null) {
				// ".3" is three tenths — pad to hundredths rather than reading it as three.
				centis += fraction.length() == 1
					? Integer.parseInt(fraction) * 10
					: Integer.parseInt(fraction);
			}
			return centis > 0 ? centis : null;
		} catch (NumberFormatException e) {
			return null;
		}
	}
}

package com.anvil;

import java.util.*;

/**
 * The account's best times, kept locally and pushed to the clan site.
 *
 * <p>Two ways in, because neither alone is enough:
 * <ul>
 *   <li><b>Live</b> — the completion messages the plugin already reads for timed tiles also carry
 *       "(new personal best)" / "Personal best: 7:59". Free: no extra chat parsing, and no waiting.</li>
 *   <li><b>Seed</b> — RuneLite's own chat-commands plugin has been recording these into its config
 *       for years. Importing that once turns a blank profile into a complete one on first login,
 *       which is what makes this feel like a sync rather than a slow accrual. The plugin reads it;
 *       this class only receives the numbers ({@link #seed}).</li>
 * </ul>
 *
 * <p>Times are centiseconds — the game separates runs by hundredths and so should a leaderboard.
 *
 * <p>The activity is supplied by the caller from the "Your X kill count is: N" line it already
 * parses, so a PB costs no additional regex on the chat hot path. Correlation works in both
 * directions because the game is inconsistent about ordering: the Inferno prints the duration
 * before the kill count, most bosses print it after.
 *
 * <p>RuneLite-free, so the correlation and flush rules are unit-testable without a client.
 */
final class PersonalBests {
	/** How long a kill-count line and a duration line can be apart and still be the same kill. */
	static final long CORRELATION_MS = 6_000;
	/** Settle time before a push — a raid prints several lines at once. */
	static final long QUIET_MS = 3_000;

	/** Best known time per activity, keyed lowercase. Lower is better; that's the whole model. */
	final Map<String, Integer> best = new HashMap<>();
	/** What the server already has, so an unchanged PB is never re-sent. */
	final Map<String, Integer> sent = new HashMap<>();
	/** Activities whose best has moved since the last successful push. */
	final Set<String> dirty = new LinkedHashSet<>();

	/** The most recent activity name from a kill-count line, and when we saw it. */
	String recentActivity;
	long recentActivityAt;
	/** A PB that arrived before its activity did (Inferno ordering), awaiting a name. */
	int orphanCentis;
	long orphanAt;

	long lastChangeAt;

	/** The activity a kill-count line just named. Cheap: two field writes, no parsing. */
	void onActivitySeen(String activity, long now) {
		if (activity == null || activity.isEmpty()) return;
		recentActivity = activity.toLowerCase(Locale.ROOT);
		recentActivityAt = now;
		// A duration that arrived first now has its name.
		if (orphanCentis > 0 && now - orphanAt <= CORRELATION_MS) {
			record(recentActivity, orphanCentis, now);
			orphanCentis = 0;
		}
	}

	/**
	 * Offer a chat line. Returns true when it produced a new best.
	 *
	 * <p>Lines with no personal best in them cost one {@code indexOf} — this runs on every line of
	 * chat, so the negative path is the one that has to be free.
	 */
	boolean onChatLine(String message, long now) {
		var centis = PersonalBestParser.parseCentis(message);
		if (centis == null) return false;
		if (recentActivity != null && now - recentActivityAt <= CORRELATION_MS) return record(recentActivity, centis, now);
		// No name yet — hold it for the kill-count line that's about to arrive.
		orphanCentis = centis;
		orphanAt = now;
		return false;
	}

	/**
	 * Import times recorded by another source (RuneLite's chat-commands store).
	 *
	 * @return how many were adopted as new bests
	 */
	int seed(Map<String, Integer> centisByActivity, long now) {
		if (centisByActivity == null || centisByActivity.isEmpty()) return 0;
		int adopted = 0;
		for (Map.Entry<String, Integer> e : centisByActivity.entrySet()) {
			if (e.getKey() == null || e.getValue() == null) continue;
			if (record(e.getKey().toLowerCase(Locale.ROOT), e.getValue(), now)) adopted++;
		}
		return adopted;
	}

	/** Keep the fastest. A PB only ever goes down, so a slower number is noise, not an update. */
	boolean record(String activity, int centis, long now) {
		if (activity == null || activity.isEmpty() || centis <= 0) return false;
		var current = best.get(activity);
		if (current != null && current <= centis) return false;
		best.put(activity, centis);
		dirty.add(activity);
		lastChangeAt = now;
		return true;
	}

	boolean isDue(long now) {
		return !dirty.isEmpty() && now - lastChangeAt >= QUIET_MS;
	}

	/** The pending bests, activity → centiseconds. */
	Map<String, Integer> nextBatch() {
		Map<String, Integer> batch = new LinkedHashMap<>(dirty.size());
		for (String activity : dirty) {
			var centis = best.get(activity);
			if (centis != null) batch.put(activity, centis);
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Anything that improved again mid-flight stays dirty, so the better
	 * time is sent next round rather than being silently dropped.
	 */
	void onSent(Map<String, Integer> batch) {
		for (Map.Entry<String, Integer> e : batch.entrySet()) {
			sent.put(e.getKey(), e.getValue());
			var current = best.get(e.getKey());
			if (current != null && current.equals(e.getValue())) dirty.remove(e.getKey());
		}
	}

	int pendingCount() {
		return dirty.size();
	}

	/** Forget everything — the next account's bests are not this one's. */
	void reset() {
		best.clear();
		sent.clear();
		dirty.clear();
		recentActivity = null;
		orphanCentis = 0;
		lastChangeAt = 0;
	}

	/**
	 * The delivered bests as one config string: {@code <centis>|<activity>} per line.
	 *
	 * <p>Value first for the same reason as the collection log's state: activity names contain
	 * colons and spaces, an integer can't contain a pipe, so the parse needs no escaping.
	 */
	String serializeState() {
		return ClogSync.writeLines(sent, String::valueOf);
	}

	/**
	 * Restore delivered state. These count as known bests too — otherwise every login would re-push
	 * the whole set to tell the server what it already stored.
	 */
	void restoreState(String raw) {
		// A truncated or hand-edited line is dropped; the next kill re-establishes it.
		ClogSync.readLines(raw, (value, activity) -> {
			int centis = Integer.parseInt(value);
			if (centis > 0) {
				sent.put(activity, centis);
				best.merge(activity, centis, Math::min);
			}
		});
	}
}

package com.anvil;

import java.util.*;

public class PluginConfigResponse {
	/** When this config was asked for (client clock): what it says about completions is as of then. Not on the wire. */
	transient long asOf;
	/**
	 * The site's capability list. The plugin never gates on site versions (the site deploys first);
	 * the only one read is {@code push-ws}, a runtime switch. Contract: docs/PLUGIN_WIRE.md in the site repo.
	 */
	public ServerInfo server;

	public static class ServerInfo {
		public List<String> capabilities;
	}

	public boolean serverSupports(String capability) {
		return server != null && server.capabilities != null && server.capabilities.contains(capability);
	}

	// ── WHICH CLAN, AND WHICH OTHERS ──────────────────────────────────────────────────────────
	//
	// One Anvil serves every clan, so the site address names none of them and the server picks
	// one from the token: a live event first, then the latest-started of several, then the newest
	// seat. That guess is nearly always right and completely invisible, which is the problem — a
	// member on two boards had no way to see which one their drops were filing into.
	//
	// So the server says which clan it answered for, and lists the rest. The plugin addresses the one
	// it means with a /c/<slug> prefix from then on, and offers the list as a dropdown.
	//
	// Null on a site that predates this (see the `clan-switch` capability): then there is one clan,
	// the address names it, and there was never a choice to make.

	/** The clan THIS response is about — whatever named it: a path, a host, or the token. */
	public ClanRef activeClan;

	/** Every clan the token's owner holds a seat in. Empty/null on an older site. */
	public List<ClanRef> clans;

	public static class ClanRef {
		public String slug;
		public String name;
		/** Verified in-game clan-channel name; may differ from the site's display name. */
		public String gameName;
		/** Clan boost level in force; zero on older sites. */
		public int boostLevel;
		/** Clan-admin chosen boosted-name palette; null on older sites or the default look. */
		public List<String> boostNameStops;
		/** The clan's own look for dark / light surfaces (null: adapt boostNameStops). Drawn as-is. */
		public List<String> boostNameDarkStops;
		/** 'member' or 'guest' — a dropdown says which of these is your home. Null on activeClan. */
		public String kind;
		/** The most relevant thing running here, or null. */
		public ClanBoard live;
		/**
		 * How many things are running here in total — boards plus the competition.
		 *
		 * {@link #live} is one line in a dropdown, so it names ONE. Without this a clan running five
		 * boards reads exactly like a clan running one, and the named board is an arbitrary pick
		 * presented as the whole answer. Zero on a site too old to send it, which is indistinguishable
		 * from "nothing running" — and on such a site there is no count to show anyway.
		 */
		public int liveCount;
		/**
		 * A creator space, not a clan. One person can be in several of each, so every dropdown row
		 * says which it is. False on an older site.
		 */
		public boolean space;
	}

	/**
	 * A live board in one of the person's clans.
	 *
	 * A {@link HomeBoard} plus its kind. The event id is load-bearing: a co-hosted event belongs to
	 * every host, so the same board arrives listed under each of them and the id is the only thing
	 * that says so.
	 */
	public static class ClanBoard extends HomeBoard {
		/**
		 * "bingo" or "weekly" — and half of this thing's identity.
		 *
		 * A board id and a competition id come out of different tables and collide freely, so anything
		 * deduping across clans has to key on the PAIR. Null on a site that predates the field, where
		 * only boards were ever reported.
		 */
		public String kind;
		// tilesComplete is zero on a weekly: a competition has a leaderboard, not a board to fill.

		/** True for a SOTW/BOTW — no board to fill, so no progress bar and no tile tally. */
		public boolean isWeekly() {
			return "weekly".equals(kind);
		}
	}

	/**
	 * The clans worth offering in a switcher, home first.
	 *
	 * A single clan is not a choice, so it is not a dropdown — the panel hides the control entirely
	 * rather than showing one option that does nothing.
	 */
	public List<ClanRef> switchableClans() {
		return clans == null ? Collections.emptyList() : clans;
	}

	/** The slug this response was resolved for, or null on a site that does not say. */
	public String activeClanSlug() {
		return activeClan == null || activeClan.slug == null || activeClan.slug.isEmpty()
			? null
			: activeClan.slug;
	}

	public EventInfo event;
	public TeamInfo team;
	public PlayerInfo player;
	/** The clan's display name (sidebar clan-filter label + logged-out home card). Null on older sites. */
	public String clanName;
	/**
	 * Server-resolved board summary keyed to the token's USER (linked member → live enrollment) —
	 * lets the sidebar show the home board at the login screen, before an in-game account resolves.
	 * Null when the user isn't enrolled in a live event (or on older sites).
	 */
	public HomeBoard homeBoard;

	public static class HomeBoard extends BoardTally {
		/**
		 * WHICH board this is. Zero on a site that predates the field.
		 *
		 * <p>Load-bearing for the same reason {@link ClanBoard#eventId} is: a co-hosted board is
		 * reported by every host, so the panel has to be able to say that the summary it is
		 * rendering and a row under "Also live" are one event rather than two.</p>
		 */
		public int eventId;
		public String eventName;
	}

	/** Every live board this character is on, the addressed one first: the plugin tracks them all. */
	public List<HomeBoard> boards;

	/** Is any board live? Its tiles ride the tracked lists and the rule table, tagged by board. */
	public boolean live() {
		return boards != null && !boards.isEmpty();
	}

	/** Is this board one of them? */
	public boolean live(int eventId) {
		return boards != null && boards.stream().anyMatch(b -> b.eventId == eventId);
	}

	/**
	 * THE WHOLE BOARD'S FRACTION, from the server — not from what this plugin can see.
	 *
	 * <p>The tracked lists carry only tiles the plugin can DETECT: a drop, a KC, an XP goal. A manual
	 * tile never arrives, so counting the rows in hand denominated a 25-tile board at 10 and reported
	 * "5 / 10 tiles · 50%" beside a website, a Discord post and this same plugin's clan-switcher row
	 * all saying 5 / 25. Null on a site that predates the field, where the local count is all there is.</p>
	 */
	public BoardTally board;

	/** Earned/total for the board as a whole — points on a points board, tiles otherwise. */
	public static class BoardTally {
		public int tilesComplete;
		public int tilesTotal;
	}

	/**
	 * How a BOARD is named across clans, so every side of the dedup builds the same string.
	 *
	 * A board id and a competition id come out of different tables and collide freely, which is why
	 * the kind is half of it — see {@link ClanBoard#identity()}.
	 */
	public static String boardIdentity(int eventId) {
		return "bingo:" + eventId;
	}

	// Activity names for the personal-best import. RuneLite files its stored bests in a config scope
	// a plugin can READ by key but cannot LIST, so the import has to ask by name — and the names come
	// from the site so a new boss doesn't need a plugin release. Null on older sites.
	public List<String> pbActivities;
	/**
	 * The player varps combat-achievement completion is bit-packed into, in bit order. Read them,
	 * send the numbers, and let the site decode: which task each bit is belongs with the catalogue,
	 * not here, so a game update that adds a varp is a data change there rather than a release here.
	 * Null on sites that predate it — then nothing is read.
	 */
	public List<Integer> caVarps;
	/**
	 * Counters read off a varbit/varp (site lib/gameCounters): each
	 * positive change credits kill tiles targeting the entry's name (GameValueCounters). Null on
	 * sites that predate it — then nothing is read.
	 */
	public List<GameValueCounters.Entry> gameCounters;

	// STARTING SHOT — the anti-stack proof (site: lib/startProof). Non-null only on an event that
	// requires one; null everywhere else, so the button simply never appears there.
	public StartProof startProof;

	public static class StartProof {
		/** Does this event ask for a starting shot at all? */
		public boolean required;
		/** Has the location been drawn (i.e. has the event gone live)? Nothing exists before this. */
		public boolean drawn;
		/** Where the player must be standing. Null until the draw. */
		public String location;
		/**
		 * The same place as game coordinates, when the host pinned it on the site's map. Null when
		 * they only named it (and on sites that predate the pin), in which case position isn't
		 * checked at all — see {@link StartProofRules}.
		 */
		public Spot spot;
		/**
		 * How long this game session may have been running when the shot is taken, in minutes.
		 * 0 = the host isn't asking. The point is the LOGOUT before it: hiscores only flush then,
		 * so a session older than the event start means a stale baseline for every stat tile.
		 */
		public int maxSessionMinutes;
		/** This player's own keyword, derived server-side from the draw stamp. Null until the draw. */
		public String keyword;
		/** True while this player still owes a shot (never filed one, or theirs was rejected). */
		public boolean needsUpload;
		/** ISO instant when the ask lapses. Null before the draw, and on sites too old to send it. */
		public String windowEndsAt;
		/** "pending" | "accepted" | "rejected", or null when nothing is on file. */
		public String status;

		/** The drawn spot on the world map: where, and how many squares from it still counts. */
		public static class Spot {
			public int x;
			public int y;
			public int radius;
		}
	}
	// Set on a no-active-event response when the logged-in RSN IS a player in a live bingo but this
	// account isn't linked to it — the plugin warns so tracking isn't silently off. Null otherwise.
	public String unlinkedActiveEvent;

	/**
	 * Whose the logged-in character is: {@code yours} | {@code other} (claimed by another Anvil
	 * account — nothing tracks for this token) | {@code ignored} (marked Not my account) |
	 * {@code unclaimed}. {@code null} at the login screen and on older sites.
	 */
	public String accountStanding;
	/** Every tracked tile's count, for the panel's live counts and a combo's part lines. */
	public List<TileCount> tiles;
	// Site stat keys ("cluesElite", "collectionsLogged") for the hiscores counters that are neither a
	// boss nor a skill. Pushed by KEY rather than in-game name — the plugin reads each from a named
	// varbit, so there's nothing to map — and only for the ones the client can actually answer
	// (see ActivityStats).
	public List<String> trackedActivityKeys;
	public List<RosterEntry> pvpRoster;           // event roster (RSN -> teamId) for 'team:other' matching; empty unless a pvp tile exists
	public List<CompletedTile> completedTiles;   // team-level tile completions (all tile types)
	public List<TrackedCombo> trackedCombos;     // combo tiles: their parts ride the lists above (partOf)
	public List<RollTable> rollTables;           // bosses whose vestige is on a fixed roll rotation

	// Merged read-bootstrap (GET /api/plugin/config now returns these so login is one call):
	public Me me;
	public List<String> alwaysNotifyItems;             // server-managed always-post item names (prestige drops)
	public List<Integer> alwaysNotifyItemIds;          // ^ resolved to item ids server-side, for reliable id-match
	public boolean showKillCount = true;               // server toggle: include boss/raid KC on rare-drop posts
	// Clan-wide rare-drop rarity floor (1-in-N). A member may post only drops at least this rare;
	// their own setting can be stricter but not looser. 0 / absent = no clan floor. Lets an admin
	// quiet a noisy channel for everyone from the site instead of asking each member to edit config.
	// What the SERVER knows about a drop and the client cannot:
	// which monster a pet actually comes from, and which items a source hands over every kill.
	// Null against an older site, and every read of it degrades to the old guess-from-context
	// behaviour rather than to nothing.
	public DropFacts dropFacts;

	/**
	 * Items that count toward luck on this site: reported as moments
	 * whatever they sell for, so an untradeable unique reaches the event's luck boards and not only
	 * its first collection-log unlock. Null on older sites.
	 */
	public List<Integer> luckItemIds;
	/** Which level-ups the clan and the player's own webhooks want; null on older sites. */
	public LevelRules.Sets levelRules;
	/**
	 * On a game-mode world, that mode's own thresholds: the loosest of the player's clans', each clan
	 * re-checking its own on the site. 0 / null = the main-game gate. Null on the main game.
	 */
	public ModeThresholds modeThresholds;

	public static class ModeThresholds {
		public LevelRules levelRules;
	}
	/**
	 * Server-supplied drop knowledge. Both maps are keyed by LOWERCASED name — the item's for
	 * {@code guaranteed}, the pet's for {@code pets} — because that is what the client has in hand
	 * when a post is being written, and it survives an item-id variant swap.
	 */
	public static class DropFacts {
		/** Pet name -> where it really comes from. */
		public Map<String, Pet> pets;

		public static class Pet {
			/** Every source that drops this pet. Empty for a skilling pet — there is no monster. */
			public List<String> sources;
			/** "npc" (killable, so a rate and a KC exist), "event" (raid/minigame), or "skill". */
			public String kind;
			/** For a skilling pet, the skill it comes from. Null otherwise. */
			public String skill;
		}
	}

	/** What this person's posts do, resolved by the site (lib/notifyPrefs): their /settings choices AND the clan's channels. */
	public static class Me {
		public boolean drops, pets, deaths, pvp, clog, levels, levelsClan, diaries;
		/** Screenshot gates: the site judges the post itself. */
		public long dropMin, keyMin;
		/** CombatAchievementTier names that post; quest difficulties that post ("*" = all). */
		public List<String> ca = new ArrayList<>(), quests = new ArrayList<>();
		/** Screenshot privacy: {pm, public, clanOthers, clanSelf, channel, group} (ChatFlair.hideMask). */
		public Map<String, Boolean> hide;
		/** Game lines that post, as the site resolved them (NotifyFacts.glob). */
		public List<Watch> watch = new ArrayList<>();
		/** Post kinds (or channels) whose announcement goes without a screenshot. Never tile proofs. */
		public List<String> noShot = new ArrayList<>();
		/** Hook kinds that are on, with their floor: "ge" (gp), "ext". */
		public Map<String, Long> on;
	}

	public static class Watch {
		public String k, g;
		public long every, min;
		public boolean shot;
	}


	public static class EventInfo {
		public int id;
		public String name;
		public String startDate;
		public String endDate;
		public String forceEndedAt;
		// Drives which in-game Anvil view opens for the player's own active event:
		//   format="tilerace" -> race track; format="bingo" + scoringMode="points" -> accordion;
		//   format="bingo" + scoringMode="tiles" -> square grid. May be null on older servers.
		public String format;         // "tilerace" | "bingo" | "ladder" | null
		// Reveal-policy events (showdown / lucky draw / bounty / ladder rotation) only — null/0 on
		// classic events and older servers. The tracked* lists already contain ONLY revealed, still-open
		// tiles.
		public String revealPolicy;   // "scheduled" | "interval" | "bounty" | "rotating" | null
		// Open missions on a reveal-mode board (revealed + still-open), for the in-game "New mission!"
		// banner. Absent on classic boards.
		public List<Mission> missions;
		// Lock-out (bounty / lockout) events: the most recent EVENT-WIDE claims, so the plugin can
		// announce "X claimed <mission>" to other players. Absent on non-lockout events.
		public List<Claim> recentClaims;
