	 * A COMBO tile: done when its parts satisfy the rule ("any" one, "all", or at least {@code needed}
	 * of them — "nOf"). The parts ride the ordinary tracked lists tagged {@code partOf}; this says how
	 * they fold together. The site counts {@code done} and decides completion.
	 */
	public static class TrackedCombo extends TrackedTile {
		public String rule;
		public int needed;
		public int done;
		public int percent; // rule "mix" only: weighted progress 0–100, done at 100
		public List<ComboPart> parts;
		public boolean completed;
	}

	public static class ComboPart {
		public int tileId;
		public String label;
		public boolean completed;
	}

	// One event participant, for 'team:other' matching. Only players with a team are included.
	public static class RosterEntry {
		public String name;    // RSN as enrolled on the site
		public int teamId;
	}

	public static class TileCount {
		public int t;
		public long have;
		public long of;
		public boolean set; // a set / collection tile: counts pieces, not what the panel shows
	}
}

package com.anvil;

/**
 * Schedules one step of a polling flow to run later, off the Swing EDT.
 *
 * Production binds RuneLite's shared {@link java.util.concurrent.ScheduledExecutorService}; tests
 * bind a scheduler that runs the step inline, so a sign-in loop that would take two minutes of
 * wall-clock finishes in a millisecond and asserts deterministically.
 *
 * <p>Hoisted out of the federation data source for the same reason as {@link BrowserOpener}: the
 * device sign-in poll outlives federation.</p>
 */
@FunctionalInterface
public interface PollScheduler {
	void schedule(Runnable step, long delayMs);
}

package com.anvil;

import lombok.Setter;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.function.Predicate;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.eventbus.*;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.util.*;

/**
 * "Anvil" on a player's right-click menu: opens their character page, {@code /p/<rsn>}.
 *
 * <p>Two places a name can be clicked, wired the two ways RuneLite allows. A player standing in the
 * world gets a player-menu item (MenuManager owns those slots, shared with every other plugin). A name
 * in a list — friends, ignore, chat channel, clan panels, the chatbox, private messages — gets an
 * entry slotted next to the game's own options, the same placement the hiscores "Lookup" uses, so it
 * sits where a person already looks for "who is this".</p>
 *
 * <p>Where it lands: the side panel's Lookup tab when the site serves player cards, the browser when
 * it doesn't (an older site, or signed out).</p>
 *
 * <p>Your own card is the side panel's You tab, not this: the game offers no player menu on
 * yourself.</p>
 *
 * <p>The URL is built here and nowhere else. It always points at {@link BingoApiClient#CANONICAL_SITE}
 * — character pages are not clan-scoped, a character belongs to its player wherever they play.</p>
 */
@Singleton
final class ProfileLookup {
	static final String OPTION = "Anvil";

	/** List options our entry goes AFTER (below) / BEFORE (above), matching the hiscores plugin. */
	static final Set<String> AFTER_OPTIONS = Set.of("Message", "Add ignore", "Remove friend", "Delete", "Kick", "Reply");
	static final Set<String> BEFORE_OPTIONS = Set.of("Add friend", "Remove ignore");

	final Client client;
	final MenuManager menuManager;
	final AnvilConfig config;
	final EventBus eventBus;

	boolean playerItemShown;
	/** Opens a name in the side panel's Lookup tab; false when it can't (no card support), and we browse. */
	@Setter volatile Predicate<String> panelOpener;

	@Inject
	ProfileLookup(Client client, MenuManager menuManager, AnvilConfig config, EventBus eventBus) {
		this.client = client;
		this.menuManager = menuManager;
		this.config = config;
		this.eventBus = eventBus;
	}

	/** {@code rsn} as a path segment, or null when there is no name to look up. */
	static String pathName(String rsn) {
		if (rsn == null) return null;
		// The game pads names with U+00A0; the site folds case and spacing itself, so only the
		// padding has to go. Path-encoded, not form-encoded: '+' in a path is a literal plus.
		var name = rsn.replace(' ', ' ').trim();
		return name.isEmpty() ? null : URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The character page for {@code rsn}, or null when there is no name to look up. */
	static String profileUrl(String rsn) {
		var name = pathName(rsn);
		return name == null ? null : BingoApiClient.site() + "/p/" + name;
	}


	/** Open {@code rsn}'s character page in the system browser. False when there was no name. */
	static boolean open(String rsn) {
		var url = profileUrl(rsn);
		if (url == null) return false;
		LinkBrowser.browse(url);
		return true;
	}

	/** The name lists (friends, ignores, chat channels, clans, raid party, private chat) that get the entry. */
	static final Set<Integer> NAME_LISTS = Set.of(InterfaceID.FRIENDS, InterfaceID.IGNORE, InterfaceID.CHATCHANNEL_CURRENT,
		InterfaceID.CLANS_SIDEPANEL, InterfaceID.CLANS_GUEST_SIDEPANEL, InterfaceID.RAIDS_SIDEPANEL, InterfaceID.PM_CHAT);

	/**
	 * Which side of a list option our entry goes on: +1 after it, -1 before it, 0 not a list entry we
	 * add to. The chatbox's "Kick" is a clan-chat moderation entry, not a name menu, so it is skipped
	 * there — the same carve-out the hiscores plugin makes.
	 */
	static int listPlacement(int groupId, String option) {
		var nameList = NAME_LISTS.contains(groupId) || (groupId == InterfaceID.CHATBOX && !"Kick".equals(option));
		if (!nameList || option == null) return 0;
		if (AFTER_OPTIONS.contains(option)) return 1;
		return BEFORE_OPTIONS.contains(option) ? -1 : 0;
	}

	/** Whether the per-surface setting lets the entry onto names in this interface. */
	boolean surfaceOn(int groupId) {
		switch (groupId) {
			case InterfaceID.CHATBOX:
			case InterfaceID.PM_CHAT:
				return config.lookupChat();
			case InterfaceID.CLANS_SIDEPANEL:
			case InterfaceID.CLANS_GUEST_SIDEPANEL:
				return config.lookupClan();
			case InterfaceID.CHATCHANNEL_CURRENT:
				return config.lookupFriendsChat();
			default:
				return config.lookupLists();
		}
	}

	/**
	 * The menu index for our entry. {@code -1} goes on top of the option just added, which in the
	 * chat makes it the top row — the left-click on a name. Chat names always take {@code -2}, under
	 * that option, so a click on a name never opens a lookup.
	 */
	static int menuIndex(int groupId, int placement) {
		var chat = groupId == InterfaceID.CHATBOX || groupId == InterfaceID.PM_CHAT;
		return placement > 0 || chat ? -2 : -1;
	}

	static boolean sameTarget(String a, String b) {
		return Text.removeTags(a == null ? "" : a).equals(Text.removeTags(b == null ? "" : b));
	}

	void startUp() {
		eventBus.register(this);
		syncPlayerItem();
	}

	void shutDown() {
		eventBus.unregister(this);
		if (playerItemShown) {
			menuManager.removePlayerMenuItem(OPTION);
			playerItemShown = false;
		}
	}

	/** The panel's Lookup tab when it can show cards, the browser when it can't. */
	void lookUp(String rsn) {
		var opener = panelOpener;
		if (opener != null && rsn != null && opener.test(rsn)) return;
		open(rsn);
	}

	/** Add or remove the in-world player item to match the settings. Called on start and config change. */
	void syncPlayerItem() {
		var want = config.profileLookupMenu() && config.lookupPlayers();
		if (want == playerItemShown) return;
		if (want) {
			menuManager.addPlayerMenuItem(OPTION);
		} else menuManager.removePlayerMenuItem(OPTION);
		playerItemShown = want;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (!config.profileLookupMenu()) return;
		int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
		int placement = listPlacement(groupId, event.getOption());
		if (placement == 0 || !surfaceOn(groupId)) return;
		// One per name. A name's menu often carries two of the options we sit beside ("Add friend" and
		// "Add ignore" on a stranger in chat), and each used to add its own "Anvil".
		for (MenuEntry existing : client.getMenu().getMenuEntries()) {
			if (OPTION.equals(existing.getOption()) && sameTarget(existing.getTarget(), event.getTarget())) return;
		}
		client.getMenu().createMenuEntry(menuIndex(groupId, placement))
			.setOption(OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.onClick(e -> lookUp(Text.removeTags(e.getTarget())));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event.getMenuAction() != MenuAction.RUNELITE_PLAYER || !OPTION.equals(event.getMenuOption())) return;
		var player = event.getMenuEntry().getPlayer();
		if (player != null) lookUp(player.getName());
	}
}

package com.anvil;

import com.google.gson.*;
import java.util.Map;

/**
 * A team view from the live push ({@link PushSocket}) laid over the config this plugin holds. The
 * site builds it once for the whole team with no caller in it, so per-member tiles take our own
 * number from {@code members} here. (The panel's rows are the site's own view now.)
 */
final class PushMerge {
	PushMerge() {
	}

	/**
	 * {@code held} with {@code team}'s fields over it (one level deep, so the event's and panel's
	 * caller-only fields survive), then our own numbers from {@code mine} ({@code c}: progress by
	 * tile; null when we have none).
	 */
	static JsonObject merge(JsonObject held, JsonObject team, JsonObject mine) {
		var out = held.deepCopy();
		for (Map.Entry<String, JsonElement> e : team.deepCopy().entrySet()) {
			var cur = out.get(e.getKey());
			if (cur != null && cur.isJsonObject() && e.getValue().isJsonObject()) {
				for (Map.Entry<String, JsonElement> f : e.getValue().getAsJsonObject().entrySet()) cur.getAsJsonObject().add(f.getKey(), f.getValue());
			} else {
				// The push is the addressed board's: another board's rows (tagged) stay as they were.
				if (cur != null && cur.isJsonArray() && e.getValue().isJsonArray()) {
					for (JsonElement r : cur.getAsJsonArray()) if (r.isJsonObject() && r.getAsJsonObject().has("board")) e.getValue().getAsJsonArray().add(r);
				}
				out.add(e.getKey(), e.getValue());
			}
		}
		var c = mine != null && mine.has("c") ? mine.getAsJsonObject("c") : new JsonObject();
		for (Map.Entry<String, JsonElement> e : out.entrySet()) {
			// The tracked lists carry tileId/currentAmount, the count list ({@code tiles}) t/have.
			var counts = e.getKey().equals("tiles");
			if ((counts || e.getKey().startsWith("tracked")) && e.getValue().isJsonArray()) {
				for (JsonElement row : e.getValue().getAsJsonArray()) {
					var r = row.isJsonObject() ? row.getAsJsonObject() : null;
					var id = r == null ? null : r.get(counts ? "t" : "tileId");
					var tile = id == null ? null : id.getAsString();
					if (tile != null && c.has(tile)) r.add(counts ? "have" : "currentAmount", c.get(tile));
				}
			}
		}
		return out;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import com.google.gson.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

/**
 * The site's live channel: a socket that sends the team's progress, the
 * board and pinned-tile numbers as they change (docs/PLUGIN_WIRE.md), so the polls can slow right
 * down while it's up. Down or refused, nothing breaks: the plugin polls as it always did.
 *
 * <p>{@link #scope} is the whole interface. A new scope (another board or team) re-tickets, since the
 * ticket is what decides what this client hears; null closes it.</p>
 */
@Slf4j
@RequiredArgsConstructor
final class PushSocket extends WebSocketListener {
	static final long FIRST_RETRY_MS = 2_000;
	static final long MAX_RETRY_MS = 5 * 60_000;
	/** Close code for "ticket expired": reconnect at once with a fresh one. */
	static final int TICKET_EXPIRED = 4001;

	final BingoApiClient api;
	final ScheduledExecutorService executor;
	final Gson gson;
	final Consumer<JsonObject> onMessage;

	String scope;
	volatile WebSocket socket;
	ScheduledFuture<?> pending;
	int failures;
	volatile boolean live;

	/** Up and hearing changes, so polls may slow down. */
	boolean live() {
		return live;
	}

	/** Listen for this board-and-team, or stop listening (null). Same scope again is a no-op. */
	synchronized void scope(String next) {
		if (Objects.equals(next, scope)) return;
		scope = next;
		failures = 0;
		close();
		if (next != null) retryIn(0);
	}

	void close() {
		live = false;
		if (pending != null) {
			pending.cancel(false);
			pending = null;
		}
		if (socket != null) {
			socket.close(1000, null);
			socket = null;
		}
	}

	synchronized void retryIn(long ms) {
		if (scope == null || pending != null) return;
		try {
			pending = executor.schedule(this::connect, ms, TimeUnit.MILLISECONDS);
		} catch (RejectedExecutionException e) {
			// shutting down
		}
	}

	void connect() {
		// Flags after the board and team (AnvilPlugin.syncPush): ":f" chat-feed lines, ":r" panel rows.
		boolean feed;
		boolean rows;
		synchronized (this) {
			pending = null;
			feed = scope != null && scope.matches(".*:f(:r)?$");
			// Always: this plugin reads panel rows, and the site only sends them to one that says so
			// (an older plugin would log each). ":r" only decides whether to connect with no board.
			rows = true;
		}
		// A blocking HTTP call: on OkHttp's pool, not the one executor thread every push and flush shares
		// (a hung site would stall all of it for the read timeout, on every retry).
		try {
			api.interactiveExecutor().execute(() -> withTicket(api.fetchPushTicket(feed, rows)));
		} catch (RejectedExecutionException e) {
			// shutting down
		}
	}

	void withTicket(BingoApiClient.PushTicket ticket) {
		synchronized (this) {
			if (scope == null || socket != null) return;
			if (ticket == null || ticket.url == null || ticket.ticket == null) {
				retryIn(RetryPolicy.backoffMs(++failures, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random()));
				return;
			}
			socket = api.openPush(ticket, this);
		}
	}

	@Override
	public void onMessage(WebSocket ws, String text) {
		JsonObject m;
		try {
			m = gson.fromJson(text, JsonObject.class);
		} catch (RuntimeException e) {
			return;
		}
		if (m == null || ws != socket || !m.has("t")) return;
		if ("hello".equals(m.get("t").getAsString())) {
			// Connected; the site sends our team's view straight after.
			synchronized (this) {
				failures = 0;
			}
			live = true;
		}
		onMessage.accept(m);
	}

	@Override
	public void onClosing(WebSocket ws, int code, String reason) {
		ws.close(1000, null);
		dropped(ws, code == TICKET_EXPIRED);
	}

	@Override
	public void onFailure(WebSocket ws, Throwable t, Response response) {
		dropped(ws, false);
	}

	synchronized void dropped(WebSocket ws, boolean ticketExpired) {
		if (ws != socket) {
			return; // an old socket we already replaced or closed
		}
		socket = null;
		live = false;
		retryIn(ticketExpired ? 0 : RetryPolicy.backoffMs(++failures, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random()));
	}
}

package com.anvil;

import lombok.Setter;
import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Unsent KC / XP / activity counts and highlight-feed moments, saved per CHARACTER across a logout or a
 * client restart and handed back when that character logs in again.
 *
 * <p>Per character because every one of these is sent as whoever is logged in (X-RSN): restoring one
 * character's kill counts into another's session would credit the wrong account. The file is
 * {@code <plugin dir>/outbox/pushes-<fingerprint>.json}, the fingerprint a truncated SHA-256 of the
 * account hash (or the name when the hash isn't known), and reading it deletes it. Anything older
 * than {@link #MAX_AGE_MS} is ignored — the hiscores have caught up by then, and a day-old moment is
 * old news. All methods block on disk: executor only.
 */
@RequiredArgsConstructor
@Slf4j
final class PushStash {
	static final long MAX_AGE_MS = 24L * 60 * 60 * 1000;

	/** One character's waiting pushes. Plain fields only: it round-trips through Gson as-is. */
	static final class Data {
		long savedAt;
		Map<String, Integer> kc = new HashMap<>();
		Map<String, Integer> xp = new HashMap<>();
		Map<String, Integer> activity = new HashMap<>();
		List<SavedMoment> moments = new ArrayList<>();

		boolean isEmpty() {
			return empty(kc) && empty(xp) && empty(activity) && (moments == null || moments.isEmpty());
		}

		static boolean empty(Map<?, ?> m) {
			return m == null || m.isEmpty();
		}
	}

	/** {@link AnvilMoments.Moment} as stored — a plain DTO, so nothing final needs reconstructing. */
	static final class SavedMoment {
		String kind;
		Integer itemId;
		String itemName;
		int quantity;
		Long valueGp;
		String source;
		String sourceKind;
		Integer kc;
		String taskName;
		String tier;
		long at;
		String key;

		static SavedMoment of(AnvilMoments.Moment m) {
			var s = new SavedMoment();
			s.kind = m.kind;
			s.itemId = m.itemId;
			s.itemName = m.itemName;
			s.quantity = m.quantity;
			s.valueGp = m.valueGp;
			s.source = m.source;
			s.sourceKind = m.sourceKind;
			s.kc = m.kc;
			s.taskName = m.taskName;
			s.tier = m.tier;
			s.at = m.at;
			s.key = m.key;
			return s;
		}

		AnvilMoments.Moment toMoment() {
			return new AnvilMoments.Moment(kind, itemId, itemName, quantity, valueGp, source, sourceKind, kc,
				taskName, tier, at, key);
		}
	}

	final Gson gson;
	@Setter volatile Filepath dir;


	/** The file stem for a character: by account hash when known, else by name. Null when neither is. */
	static String keyFor(String rsn, String accountHash) {
		if (accountHash != null && !accountHash.isEmpty()) return DiskFiles.fingerprint("h:" + accountHash);
		if (rsn != null && !rsn.trim().isEmpty()) return DiskFiles.fingerprint("r:" + rsn.trim().toLowerCase(Locale.ROOT));
		return null;
	}

	/** Merge two stashes — counts are absolute, so the larger wins; moments by key, newer wins. */
	static Data merge(Data older, Data newer) {
		// Either side can be missing: no stash on disk yet, or nothing left to take for this character.
		if (older == null || newer == null) return older == null ? newer : older;
		var out = new Data();
		out.savedAt = Math.max(older.savedAt, newer.savedAt);
		mergeMax(out.kc, older.kc, newer.kc);
		mergeMax(out.xp, older.xp, newer.xp);
		mergeMax(out.activity, older.activity, newer.activity);
		Map<String, SavedMoment> byKey = new LinkedHashMap<>();
		for (List<SavedMoment> list : Arrays.asList(older.moments, newer.moments)) {
			if (list != null) {
				for (SavedMoment m : list) {
					if (m != null && m.key != null) byKey.put(m.key, m);
				}
			}
		}
		out.moments = new ArrayList<>(byKey.values());
		return out;
	}

	static void mergeMax(Map<String, Integer> into, Map<String, Integer> a, Map<String, Integer> b) {
		for (Map<String, Integer> m : Arrays.asList(a, b)) {
			if (m != null) {
				m.forEach((k, v) -> {
					if (k != null && v != null) into.merge(k, v, Integer::max);
				});
			}
		}
	}

	Filepath file(String key) {
		var d = DiskFiles.ensureDir(dir);
		return d == null || key == null ? null : d.joinSegment("pushes-" + key + ".json");
	}

	/** Save {@code data} for the character {@code key}, folded into anything already saved. */
	void save(String key, Data data) {
		var f = file(key);
		if (f == null || data == null || data.isEmpty()) return;
		var merged = merge(DiskFiles.readJson(gson, f, Data.class), data);
		try {
			DiskFiles.writeAtomic(f, gson.toJson(merged));
		} catch (IOException | RuntimeException e) {
		}
	}

	/** What was saved for {@code key} (deleting it), or null when nothing fresh was. */
	Data take(String key, long now) {
		var f = file(key);
		var d = DiskFiles.readJson(gson, f, Data.class);
		DiskFiles.deleteQuietly(f);
		return d == null || now - d.savedAt > MAX_AGE_MS ? null : d;
	}

	/** Signed out: drop every character's saved pushes. */
	void clearAll() {
		DiskFiles.listFiles(DiskFiles.ensureDir(dir), n -> n.startsWith("pushes-")).forEach(DiskFiles::deleteQuietly);
	}
}

package com.anvil;

import java.util.*;

/**
 * The raid-run gates a timed or deathless tile can add on top of "the raid was completed": the ToA
 * raid level the run ended at, and who was in it. Each returns null when the run passes, else the
 * reason it doesn't, worded for the player's chat box.
 */
final class RaidGates {
	RaidGates() {
	}

	/** Only ToA has a raid level; a floor on any other raid's tile is ignored rather than failing it. */
	static boolean isToa(String activity) {
		return activity != null && activity.toLowerCase(Locale.ROOT).contains("tombs of amascut");
	}

	/**
	 * {@code level} is the raid level the raid ENDED at — read at the chest, because a failed
	 * time-limit invocation only takes its cut once the party reaches the chest room (the caller
	 * holds the run until then). 0 = it couldn't be read.
	 */
	static String raidLevel(String activity, int minLevel, int level) {
		if (minLevel <= 0 || !isToa(activity)) return null;
		if (level <= 0) return "couldn't read the raid level";
		return level >= minLevel ? null : "raid level " + level + ", tile requires " + minLevel;
	}

	/**
	 * Every player seen in the raid is on the team. {@code seen} is everyone rendered in the instance
	 * (you included) and {@code partySize} the party the game reports: seeing fewer names than that
	 * means someone was never on screen, so the run can't be vouched for.
	 */
	static String wholePartyFromTeam(Collection<String> seen, Set<String> team, int partySize) {
		if (team == null || team.isEmpty()) return "the team roster isn't loaded";
		int named = 0;
		for (String name : seen) {
			var n = Rsn.normalize(name);
			if (n.isEmpty()) continue;
			if (!team.contains(n)) return name + " isn't on your team";
			named++;
		}
		if (partySize > named) return "only saw " + named + " of the party of " + partySize;
		return null;
	}
}

package com.anvil;

import lombok.Setter;
import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The last good {@code /api/plugin/config} and active {@code /api/plugin/board} answers, kept on disk
 * per signed-in account so the next launch can draw the side panel straight away and open with a
 * conditional GET instead of a full download.
 *
 * <p>DISPLAY ONLY. What comes back from here is never handed to tracking — an event can end, a team
 * can change and a token can be revoked between sessions — so the plugin shows it until the site's
 * first live answer and then forgets it (see AnvilPlugin#sidebarConfig).
 *
 * <p>Files live in {@code <plugin dir>/cache/}, named {@code <kind>-<fingerprint>.json}, where the
 * fingerprint is a truncated SHA-256 of the Account Token: the token itself never touches disk. Not
 * at the plugin directory's root, where PendingSubmissionStore reads every JSON file as a proof.
 */
@RequiredArgsConstructor
@Slf4j
final class ResponseDiskCache {
	static final String CONFIG = "config";
	static final String CHAT_PATTERNS = "chat-patterns";
	/** The Supporter name list (ChatFlair): public, the same for every account, so one shared file.
	 * Renamed whenever the wire gains a field: an old file at the same version would never refetch. */
	static final String CHAT_FLAIR = "chat-flair-2";
	/** A board bigger than this isn't worth the disk; the next launch just downloads it. */
	static final int MAX_BODY_CHARS = 2_000_000;

	/** One saved answer. */
	static final class Entry {
		String url;
		String etag;
		String body;
		/** The character the request was made as (X-RSN, else the launcher hint), or null. */
		String rsn;
		long savedAt;
	}

	final Gson gson;
	@Setter volatile Filepath dir;
	/** Fingerprint of the token in use, "" when signed out. */
	volatile String account = "";
	/** kind → etag (or body hash) last written, so an unchanged 30s poll doesn't rewrite the file. */
	final Map<String, String> written = new ConcurrentHashMap<>();


	/**
	 * Point at the account behind {@code token}. Returns the fingerprint whose files should now be
	 * deleted (signing out, or a different account signing in), else null. Memory only — the caller
	 * deletes off the client thread.
	 */
	String switchAccount(String token) {
		var next = DiskFiles.fingerprint(token);
		var prev = account;
		if (next.equals(prev)) return null;
		account = next;
		written.clear();
		return prev.isEmpty() ? null : prev;
	}

	Filepath file(String kind, String acct) {
		var d = DiskFiles.ensureDir(dir);
		return d == null || acct == null || acct.isEmpty() ? null : d.joinSegment(kind + "-" + acct + ".json");
	}

	/** The saved answer of {@code kind} for the current account, or null. Blocking. */
	Entry load(String kind) {
		// Missing or unreadable reads as nothing saved; the next fresh answer overwrites a bad file.
		var e = DiskFiles.readJson(gson, file(kind, account), Entry.class);
		if (e == null || e.body == null || e.url == null) return null;
		written.put(kind, e.etag != null ? e.etag : Integer.toString(e.body.hashCode()));
		return e;
	}

	/** Save a fresh 200 body. Blocking; called from the HTTP worker that fetched it, never the client thread. */
	void store(String kind, String url, String etag, String body, String rsn) {
		if (body == null || body.length() > MAX_BODY_CHARS) return;
		var acct = account;
		var marker = etag != null ? etag : Integer.toString(body.hashCode());
		if (marker.equals(written.get(kind))) return;
		var f = file(kind, acct);
		if (f == null) return;
		var e = new Entry();
		e.url = url;
		e.etag = etag;
		e.body = body;
		e.rsn = rsn;
		e.savedAt = System.currentTimeMillis();
		try {
			DiskFiles.writeAtomic(f, gson.toJson(e));
			written.put(kind, marker);
		} catch (IOException | RuntimeException ex) {
		}
	}

	/** A saved copy of public data the same for everyone ({@code <kind>.json}), or null. Blocking. */
	<T> T loadShared(String kind, Class<T> type) {
		var d = DiskFiles.ensureDir(dir);
		return d == null ? null : DiskFiles.readJson(gson, d.joinSegment(kind + ".json"), type);
	}

	/** Save {@link #loadShared}'s copy. Blocking; never the client thread. */
	void storeShared(String kind, Object value) {
		var d = DiskFiles.ensureDir(dir);
		if (d == null) return;
		try {
			DiskFiles.writeAtomic(d.joinSegment(kind + ".json"), gson.toJson(value));
		} catch (IOException | RuntimeException ex) {
		}
	}

	/** Delete every saved answer for {@code acct}. Blocking. */
	void clear(String acct) {
		if (acct == null || acct.isEmpty()) return;
		DiskFiles.deleteQuietly(file(CONFIG, acct));
	}
}

package com.anvil;

/**
 * The two questions every retry path asks, answered once: is this refusal worth trying again, and how
 * long to wait before doing so.
 */
final class RetryPolicy {
	RetryPolicy() {
	}

	/**
	 * A refusal that will never succeed however often it is resent: a 4xx, except 401 (the token may
	 * refresh, and a push fired in the second after login, before X-RSN is stamped, is refused with one
	 * that the next attempt clears), 408 (timed out) and 429 (slow down). 5xx and network failures
	 * are transient; anything below 400 is not a refusal at all.
	 */
	static boolean isPermanent(int code) {
		return code >= 400 && code < 500 && code != 401 && code != 408 && code != 429;
	}

	/**
	 * The wait before attempt {@code failures + 1}: {@code firstMs} doubling per failure, capped at
	 * {@code capMs}, spread ±20% by {@code jitter} (a uniform draw in [0, 1)) so a clan's clients that
	 * all lost the site at the same moment don't all come back at the same moment. Never above the cap.
	 */
	static long backoffMs(int failures, long firstMs, long capMs, double jitter) {
		if (failures <= 0) return 0;
		var base = firstMs;
		for (int i = 1; i < failures && base < capMs; i++) base *= 2;
		base = Math.min(base, capMs);
		var j = Math.max(0, Math.min(1, jitter));
		return Math.min(capMs, Math.round(base * (0.8 + 0.4 * j)));
	}
}

package com.anvil;

import java.awt.*;
import javax.swing.JPanel;

/**
 * A panel drawn as a rounded rectangle: a card, a raised row, a track step. {@code fill} null draws no
 * ground until hovered; {@code edge} is a 1px outline (an accent card, a row marked on the way back).
 * Never opaque to Swing, so the corners show what's behind; "opaque" only switches the fill on.
 */
final class Round extends JPanel {
	final int arc;
	final Color hover;
	Color edge;
	boolean filled;

	Round(LayoutManager layout, int arc, Color fill, Color edge, Color hover) {
		super(layout);
		this.arc = arc;
		this.edge = edge;
		this.hover = hover;
		if (fill != null) setBackground(fill);
		filled = fill != null;
		super.setOpaque(false);
	}

	boolean filled() {
		return filled;
	}

	@Override
	public void setOpaque(boolean on) {
		filled = on;
		super.setOpaque(false);
	}

	@Override
	protected void paintComponent(Graphics g) {
		var g2 = Ui.smooth(g);
		if (filled) {
			g2.setColor(getBackground());
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), arc * 2, arc * 2);
		}
		if (edge != null) {
			g2.setColor(edge);
			g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc * 2, arc * 2);
		}
		g2.dispose();
	}
}

package com.anvil;

import java.util.Locale;

/**
 * One way to fold an OSRS name into a comparison key — the SAME way the site does it.
 *
 * <p>Every use of this is the same shape: take a name the client read out of the game, take a name
 * the server sent, and decide whether they are the same account. That only works if both sides fold
 * identically. There were three of these in the plugin, agreeing with each other about half the
 * time and with the server never.</p>
 *
 * <p><b>The rule</b> is the server's ({@code Anvil.Site src/lib/auth.ts normalizeRsn}):
 * lower-case, and collapse every run of whitespace <em>or underscore</em> to one space.</p>
 *
 * <p><b>Underscores are the part that was missing.</b> OSRS treats space and underscore as the same
 * character in a name: the game renders "GIM Nisbro", while logins, hiscores lookups and
 * hand-entered roster rows carry "GIM_nisbro". The server folds them together deliberately —
 * without it a roster sync reports one member left and another joined for the same person. The
 * plugin did not, so any name holding an underscore on the site failed to match the account playing
 * it: no bounty credit, no drop attribution, no "that's you" in a standings list.</p>
 *
 * <p><b>Two places where Java quietly disagrees with JavaScript</b>, both of which this has to bridge
 * because the server is the JavaScript one:</p>
 * <ul>
 *   <li>{@code String.trim()} in Java strips only characters up to U+0020, so it leaves a
 *       non-breaking space where JS strips it. OSRS names are full of U+00A0 — that is how the game
 *       encodes their spaces so a name never wraps a line. Folded to a plain space first.</li>
 *   <li>Java's {@code \\s} does not match U+00A0 either; JS's does. Spelled out in the class.</li>
 * </ul>
 *
 * <p>{@link Locale#ROOT} rather than the default locale, and that is not pedantry: a Turkish client
 * lower-cases 'I' to 'ı', so "IRON MIKE" would fold to something the server has never seen and that
 * player would silently stop matching their own roster row.</p>
 */
public final class Rsn {
	Rsn() {
	}

	/** Whitespace-or-underscore runs. U+00A0 is named explicitly — Java's {@code \s} omits it. */
	static final java.util.regex.Pattern FOLD =
		java.util.regex.Pattern.compile("[\\s\\u00a0_]+");

	/**
	 * The comparison key for a name, or "" when there is no name.
	 *
	 * <p>Never null, because every caller compares the result and a null check at each of them is a
	 * check somebody eventually forgets. An empty key never matches a real one — callers guard on
	 * {@code !me.isEmpty()} before comparing, so an unknown local name matches nobody rather than
	 * everybody.</p>
	 */
	public static String normalize(String rsn) {
		if (rsn == null) return "";
		// U+00A0 → space BEFORE trimming, so a name padded with them trims like it does on the server.
		var plain = rsn.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
		return FOLD.matcher(plain).replaceAll(" ").trim();
	}

	/** Do these two names denote the same account? Empty never matches, including empty itself. */
	public static boolean same(String a, String b) {
		var left = normalize(a);
		return !left.isEmpty() && left.equals(normalize(b));
	}
}

package com.anvil;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.*;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;
import java.util.function.Predicate;

/**
 * The site's rule table (GET /api/plugin/rules), run locally. It decides only
 * what can't wait for the site: whether a moment deserves a screenshot, and the chat line to print
 * right away. The site matches the reported facts to tiles (POST /api/plugin/facts) and its answer
 * corrects each rule's count. Pure and RuneLite-free (RuleEngineTest).
 *
 * Counts are touched from two threads: the client thread raises them per event, the executor overwrites
 * them with the site's answer. Every method that reads or writes a count holds the engine's lock; each
 * runs in microseconds, so the client thread never waits on anything slow.
 */
final class RuleEngine {
	static final class Table {
		Map<String, List<DropRule>> drops = new HashMap<>();
		Map<String, List<KillRule>> kills = new HashMap<>();
		List<ValueRule> values = new ArrayList<>();
		List<StatRule> stats = new ArrayList<>();
		List<EventRule> events = new ArrayList<>();
		Proof proof = new Proof();
		Map<String, String> say = new HashMap<>();
		/** Source key ("pp:" for pickpocketing) -> item ids rare enough to maybe post: screenshot and let the site judge. */
		Map<String, Set<Integer>> rare = new HashMap<>();
		/** Every drop tile is done: item gains stop counting (the site's rule). */
		boolean blackout;
	}

	static class Rule {
		int t;
		String label;
		long have;
		long of;
		List<String> src;
	}

	static final class DropRule extends Rule {
		List<String> npcs;
		boolean simple;
	}

	static final class KillRule extends Rule {
		String unit;
		boolean quiet;
		boolean coop;
	}

	static final class ValueRule extends Rule {
		long min;
	}

	static final class StatRule extends Rule {
		String on;
		List<String> names;
		long step;
		int[] active;
	}

	/**
	 * A tile judged on the spot (timed, deathless, lms, pvp, pvpLoot, diary, ca, clog, page, gain): the
	 * event must name one of {@code keys} ("*" or none = any), as the site expanded them; for timed and
	 * deathless the key is the activity the clear parser matches. {@code of} 0 = never counted.
	 */
	static final class EventRule extends Rule {
		String on;
		Set<String> keys;
		/** Keys that never hit, even through a wildcard (a combat task the tile already counts). */
		Set<String> no;
		/** The event's value must be at most this (null = no cap) and at least {@code min}. */
		Long max;
		long min;
		int party;
		int lvl;
		boolean team;
		boolean coop;
		Set<Integer> need;
		String say;

		String key() {
			return keys == null || keys.isEmpty() ? "" : keys.iterator().next();
		}
	}

	static final class Proof {
		int min = 25;
		double frac = 0.25;
	}

	/** What one event comes to: lines to print now, the fact for the site, and whether to screenshot it. */
	static final class Out {
		final List<String> say = new ArrayList<>();
		final List<JsonObject> facts = new ArrayList<>();
		boolean shot;
		boolean coop;
		/** A gain was held for its tile's batch: flushGains sends it. */
		boolean held;
		/** A stat tile reached its goal: the stat push goes now. */
		boolean done;
		/** Tile id → its local count after this event, for the panel's optimistic rows. */
		final Map<Integer, Long> raised = new HashMap<>();
		/** Drop tiles this event moved, as they stood, for the in-game "tile progress" popup. */
		final List<Rule> toasts = new ArrayList<>();
	}

	static final long DEDUP_MS = 3_000;

	volatile Table table;
	final Map<Integer, Long> seenItems = new HashMap<>();
	final Map<String, TreeSet<Long>> xpMinutes = new HashMap<>();
	/** Gains held per tile until the batch goes or the tile completes. */
	final Map<Integer, Long> held = new HashMap<>();
	/** This client's unconfirmed count for a tile: event rules build on it when the table is older. */
	volatile IntToLongFunction floor = t -> 0;

	synchronized void set(Table t) {
		table = t;
	}

	/** Could this item be rare enough to post? An npc or pickpocket drop on the site's rare table. */
	boolean rare(String kind, String source, int itemId) {
		var t = table;
		var p = "npc".equals(kind) ? "" : "pickpocket".equals(kind) ? "pp:" : null;
		var ids = t == null || p == null || source == null ? null : t.rare.get(p + source.toLowerCase());
		return ids != null && ids.contains(itemId);
	}

	boolean active() {
		return table != null;
	}

	boolean blackout() {
		var t = table;
		return t != null && t.blackout;
	}

	/** Drop or value tiles to credit: those also credit off the game's drop line. */
	boolean dropLines() {
		var t = table;
		return t != null && !(t.drops.isEmpty() && t.values.isEmpty());
	}

	boolean tracksKill(String name) {
		var t = table;
		return t != null && name != null && t.kills.containsKey(name.toLowerCase(Locale.ROOT));
	}

	/** Item ids some drop tile tracks (clog lines and inferred drops look items up by name). */
	Set<Integer> dropItemIds() {
		var t = table;
		Set<Integer> ids = new HashSet<>();
		if (t != null) t.drops.keySet().forEach(k -> ids.add(Integer.valueOf(k)));
		return ids;
	}

	/** One kill/open/counter event: each moved name and its amount; a tile reached by several takes the largest, once. */
	synchronized Out kill(Map<String, Integer> moved, Collection<String> unverified, String inferred) {
		var out = new Out();
		var t = table;
		if (t == null) return out;
		Map<KillRule, Integer> byRule = new IdentityHashMap<>();
		for (Map.Entry<String, Integer> e : moved.entrySet()) {
			for (KillRule r : t.kills.getOrDefault(e.getKey().toLowerCase(Locale.ROOT), Collections.emptyList())) byRule.merge(r, e.getValue(), Math::max);
		}
		var any = false;
		for (Map.Entry<KillRule, Integer> e : byRule.entrySet()) {
			var r = e.getKey();
			if (r.have >= r.of) continue;
			any = true;
			var n = Math.min(e.getValue(), r.of - r.have);
			r.have += n;
			out.raised.put(r.t, r.have);
			out.coop |= r.coop;
			out.shot |= r.have >= r.of || milestone(n, r.have, r.of, t.proof);
			if (!r.quiet) out.say.add(fill(t, "kill", r, "{unit}", r.unit == null ? "kill" : r.unit));
		}
		if (!any) return out;
		var f = fact("kill");
		var n = new JsonObject();
		moved.forEach(n::addProperty);
		f.add("n", n);
		if (unverified != null && !unverified.isEmpty()) {
			var u = new JsonArray();
			unverified.forEach(u::add);
			f.add("unv", u);
		}
		if (inferred != null) f.addProperty("inf", inferred);
		out.facts.add(f);
		return out;
	}

	/** One loot event ({@code items} as [id, qty]); a repeat of an item within the dedup window is the same loot fired twice. */
	synchronized Out loot(String source, String kind, List<int[]> items, Integer party, String inferred, long now) {
		var out = new Out();
		var t = table;
		if (t == null || items == null) return out;
		var sent = new JsonArray();
		Set<DropRule> said = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int[] it : items) {
			var rules = t.drops.get(String.valueOf(it[0]));
			if (rules == null) continue;
			var last = seenItems.put(it[0], now);
			if (last != null && now - last < DEDUP_MS) continue;
			var any = false;
			for (DropRule r : rules) {
				if (!sourceOk(r, source, kind) || (r.simple && r.have >= r.of)) continue;
				any = true;
				if (r.simple) {
					r.have = Math.min(r.of, r.have + Math.max(1, it[1]));
					out.raised.put(r.t, r.have);
					out.say.add(fill(t, "drop", r));
					out.toasts.add(snap(r));
				} else if (said.add(r)) {
					out.say.add(fill(t, "dropPlain", r));
					out.toasts.add(snap(r));
				}
			}
			if (any) {
				var pair = new JsonArray();
				pair.add(it[0]);
				pair.add(it[1]);
				sent.add(pair);
			}
		}
		if (sent.size() == 0) return out;
		out.shot = true;
		var f = fact("loot");
		f.addProperty("src", source);
		f.addProperty("kind", kind);
		f.add("items", sent);
		if (party != null) f.addProperty("party", party);
		if (inferred != null) f.addProperty("inf", inferred);
		out.facts.add(f);
		return out;
	}

	/** A priced haul, for loot-value tiles. */
	synchronized Out value(String source, String kind, long gp) {
		var out = new Out();
		var t = table;
		if (t == null || gp <= 0) return out;
		for (ValueRule r : t.values) {
			var total = r.min <= 0;
			if ((total ? r.have >= r.of : gp < r.min) || !valueSourceOk(r.src, source, kind)) continue;
			r.have = total ? Math.min(r.of, r.have + gp) : r.of;
			out.raised.put(r.t, r.have);
			out.say.add(fill(t, "value", r, "{gp}", gp(gp)));
		}
		if (out.say.isEmpty()) return out;
		out.shot = true;
		var f = fact("value");
		f.addProperty("src", source);
		f.addProperty("kind", kind);
		f.addProperty("gp", gp);
		out.facts.add(f);
		return out;
	}

	/** Is any event rule of this kind open? */
	boolean has(String on) {
		var t = table;
		return t != null && t.events.stream().anyMatch(r -> on.equals(r.on));
	}

	/** Hits a rule taking any of these keys, or any key ("*", or none listed), unless it lists one as {@code no}. */
	static Predicate<EventRule> named(String... ks) {
		return r -> (r.no == null || Arrays.stream(ks).noneMatch(r.no::contains))
				&& (r.keys == null || r.keys.contains("*") || Arrays.stream(ks).anyMatch(r.keys::contains));
	}

	/**
	 * Open rules of kind {@code on} that {@code hit} names, {@code claim}ed, whose gates pass: the value
	 * against max/min, the exact party, the whole party from the team ({@code teamWhy} says why not).
	 * A refusal with a template ({@code on.max}, {@code on.party}, ...) is said into {@code no}. Counts nothing.
	 */
	synchronized List<EventRule> match(String on, Predicate<EventRule> hit, long value, String x, int party, String teamWhy, IntPredicate claim, List<String> no) {
		List<EventRule> out = new ArrayList<>();
		var t = table;
		if (t == null) return out;
		for (EventRule r : t.events) {
			if (!on.equals(r.on) || r.of > 0 && Math.max(r.have, floor.applyAsLong(r.t)) >= r.of || !hit.test(r) || claim != null && !claim.test(r.t)) continue;
			var why = r.max != null && value > r.max ? "max" : value < r.min ? "min" : r.party > 0 && party != r.party ? "party" : r.team && teamWhy != null ? "team" : null;
			if (why == null) out.add(r);
			else if (t.say.containsKey(on + "." + why)) no.add(fill(t, on + "." + why, r, "{x}", x, "{seen}", String.valueOf(party), "{party}", String.valueOf(r.party), "{why}", teamWhy));
		}
		return out;
	}

	/**
	 * Count a matched rule by {@code n} (no more than it still needs), say its line ({x} filled) and add
	 * its tile fact with the extras {@code kv}. A gain is held for its tile's batch until it completes the tile.
	 */
	synchronized Out credit(Out o, EventRule r, long n, String x, Object... kv) {
		var t = table;
		if (t == null) return o;
		if (r.of > 0) {
			r.have = Math.max(r.have, floor.applyAsLong(r.t));
			if (r.have >= r.of) return o;
			n = Math.min(n, r.of - r.have);
			r.have += n;
			o.raised.put(r.t, r.have);
		}
		var gain = "gain".equals(r.on);
		var key = r.say != null ? r.say : r.on;
		if (t.say.containsKey(key) && !(gain && held.containsKey(r.t))) o.say.add(fill(t, key, r, "{x}", x));
		if (gain) {
			n = held.merge(r.t, n, Long::sum);
			if (r.have < r.of) {
				o.held = true;
				return o;
			}
			held.remove(r.t);
		}
		o.shot = true;
		o.coop |= r.coop;
		o.facts.add(tile(r.t, n, kv));
		return o;
	}

	/** One event against the rules of kind {@code on}: each one it names and passes, credited (a gain by {@code value}, else 1). */
	synchronized Out event(String on, Predicate<EventRule> hit, long value, String x, IntPredicate claim, Object... kv) {
		var o = new Out();
		for (EventRule r : match(on, hit, value, x, 0, null, claim, o.say)) credit(o, r, "gain".equals(on) ? value : 1, x, kv);
		return o;
	}

	/** Every held gain, as count-only facts (the batch timer, logout, hop). */
	synchronized Out flushGains() {
		var o = new Out();
		held.forEach((t, n) -> o.facts.add(tile(t, n)));
		held.clear();
		return o;
	}

	/** A multi-run timed tile's {have, of}; null for anything else. */
	synchronized long[] runs(int id) {
		var t = table;
		if (t != null) {
			for (EventRule r : t.events) {
				if (r.t == id && "timed".equals(r.on) && r.of > 1) return new long[]{r.have, r.of};
			}
		}
		return null;
	}

	/** A `tile` fact: the tile, the amount, and extras in pairs (a null value is left out). */
	static JsonObject tile(int id, long n, Object... kv) {
		var f = fact("tile");
		f.addProperty("t", id);
		f.addProperty("n", n);
		for (int i = 0; i + 1 < kv.length; i += 2) {
			var v = kv[i + 1];
			if (v instanceof Number) f.addProperty((String) kv[i], (Number) v);
			else if (v instanceof Boolean) f.addProperty((String) kv[i], (Boolean) v);
			else if (v != null) f.addProperty((String) kv[i], v.toString());
		}
		return f;
	}

	/** Skill XP gained: a line per clean step crossed, only while the skill is actually being trained. */
	synchronized Out xp(String skill, long gained, long now) {
		TreeSet<Long> minutes = xpMinutes.computeIfAbsent(key(skill), k -> new TreeSet<>());
		var minute = now / 60_000;
		minutes.add(minute);
		minutes.headSet(minute - 60).clear();
		return stat("xp", skill, gained, minutes, minute);
	}

	/** A boss / activity count moved (a KC line). */
	synchronized Out kc(String name, long gained) {
		return stat("kc", name, gained, null, 0);
	}

	/** A stat name as the site spells rule names: letters and digits, so "Kree'Arra" and "kree arra" meet. */
	static String key(String s) {
		return s == null ? "" : s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	Out stat(String on, String name, long gained, TreeSet<Long> minutes, long minute) {
		var out = new Out();
		var t = table;
		if (t == null || gained <= 0 || name == null) return out;
		var key = key(name);
		for (StatRule r : t.stats) {
			if (!on.equals(r.on) || r.names == null || !r.names.contains(key) || r.have >= r.of) continue;
			var before = r.have;
			r.have = Math.min(r.of, r.have + gained);
			out.raised.put(r.t, r.have);
			if (r.have >= r.of) {
				out.done = true;
				out.say.add(fill(t, "done", r));
			} else if (r.step > 0 && r.have / r.step > before / r.step && busy(r.active, minutes, minute)) out.say.add(fill(t, on, r));
		}
		return out;
	}

	/** Gains in at least active[0] distinct minutes of the last active[1]; no gate when none is set. */
	static boolean busy(int[] active, TreeSet<Long> minutes, long minute) {
		if (active == null || active.length < 2 || minutes == null) return true;
		return minutes.subSet(minute - active[1] + 1, true, minute, true).size() >= active[0];
	}

	/** The site's answer: every touched tile's real count replaces the local guess. Returns lines to print. */
	synchronized List<String> adopt(JsonObject reply) {
		List<String> lines = new ArrayList<>();
		var t = table;
		if (t == null || reply == null) return lines;
		if (reply.has("credits")) {
			for (JsonElement el : reply.getAsJsonArray("credits")) {
				var c = el.getAsJsonObject();
				// A refused credit's count isn't the tile's: the next config's table says what is.
				if (c.has("ok") && !c.get("ok").getAsBoolean()) continue;
				int id = c.get("t").getAsInt();
				var have = c.get("have").getAsLong();
				var of = c.get("of").getAsLong();
				for (Rule r : all(t)) {
					if (r.t == id && r.of > 0) {
						r.have = have;
						r.of = of;
					}
				}
			}
		}
		if (reply.has("notes")) reply.getAsJsonArray("notes").forEach(n -> lines.add(n.getAsString()));
		return lines;
	}

	/** A live push's counts (tile id → the team's count): every rule on that tile, stats too, rises to it. */
	synchronized void raise(Map<Integer, Long> have) {
		var t = table;
		if (t == null) return;
		var rules = all(t);
		rules.addAll(t.stats);
		for (Rule r : rules) {
			var n = have.get(r.t);
			if (n != null && r.of > 0) r.have = Math.max(r.have, n);
		}
	}

	/** The rule as it stands now, for the popup: read outside the lock, it must not see the next answer land. */
	static Rule snap(Rule r) {
		var s = new Rule();
		s.t = r.t;
		s.label = r.label;
		s.have = r.have;
		s.of = r.of;
		return s;
	}

	static List<Rule> all(Table t) {
		List<Rule> out = new ArrayList<>(t.values);
		t.drops.values().forEach(out::addAll);
		t.kills.values().forEach(out::addAll);
		out.addAll(t.events);
		return out;
	}

	/** A grindy kill tile screenshots only on proof steps (and completion); a small one on every credit. */
	static boolean milestone(long added, long current, long required, Proof p) {
		if (required < p.min) return true;
		var step = Math.max(1.0, required * p.frac);
		return Math.floor(current / step) > Math.floor((current - added) / step);
	}

	static boolean sourceOk(DropRule r, String source, String kind) {
		if (r.src != null && !r.src.isEmpty() ? !r.src.contains(kind) : "pvp".equals(kind)) return false;
		return r.npcs == null || r.npcs.isEmpty() || DropSource.sourceMatches(r.npcs, source);
	}

	static boolean valueSourceOk(List<String> sources, String source, String kind) {
		if (sources == null || sources.isEmpty()) return true;
		for (String s : sources) {
			if (s != null && (s.equalsIgnoreCase("PvP") ? "pvp".equals(kind) : s.equalsIgnoreCase(source))) return true;
		}
		return false;
	}

	static JsonObject fact(String k) {
		var f = new JsonObject();
		f.addProperty("k", k);
		return f;
	}

	static String fill(Table t, String key, Rule r, String... extra) {
		var s = t.say.getOrDefault(key, "{label} ({have}/{of})");
		var big = r.of >= 10_000;
		s = s.replace("{label}", r.label == null ? "" : r.label)
			.replace("{have}", big ? String.format(Locale.ROOT, "%,d", r.have) : String.valueOf(r.have))
			.replace("{of}", big ? String.format(Locale.ROOT, "%,d", r.of) : String.valueOf(r.of))
			.replace("{pct}", String.valueOf(r.of > 0 ? r.have * 100 / r.of : 0));
		for (int i = 0; i + 1 < extra.length; i += 2) s = s.replace(extra[i], extra[i + 1] == null ? "" : extra[i + 1]);
		return s;
	}

	/** One line per kind per board (label's " · board"), "+N more"; past 3 boards, "Tracked kill on 5 boards: …". */
	static List<String> fold(List<String> lines) {
		return fold(lines, 3);
	}

	/** {@code maxBoards}: past this many boards one kind becomes a single "… on N boards" line. */
	static List<String> fold(List<String> lines, int maxBoards) {
		Map<String, Map<String, List<String>>> by = new LinkedHashMap<>();
		for (String s : lines) {
			int c = s.indexOf(": "), b = s.lastIndexOf(" \u00b7 ");
			by.computeIfAbsent(c < 0 ? s : s.substring(0, c), k -> new LinkedHashMap<>())
				.computeIfAbsent(b < 0 ? "" : s.substring(b).replaceAll(" \\([^(]*\\)!?$|!$", ""), k -> new ArrayList<>()).add(s);
		}
		List<String> out = new ArrayList<>();
		by.forEach((head, boards) -> {
			if (boards.size() > maxBoards) {
				var first = boards.values().iterator().next().get(0);
				out.add(more(head + " on " + boards.size() + " boards" + first.substring(head.length()), boards.values().stream().mapToInt(List::size).sum()));
			} else boards.values().forEach(l -> out.add(more(l.get(0), l.size())));
		});
		return out;
	}

	static String more(String s, int n) {
		return n > 1 ? s + " +" + (n - 1) + " more" : s;
	}

	static String gp(long gp) {
		return gp >= 1_000_000 ? String.format(Locale.ROOT, "%.1fM gp", gp / 1_000_000.0)
			: gp >= 1_000 ? String.format(Locale.ROOT, "%.0fk gp", gp / 1_000.0) : gp + " gp";
	}
}

package com.anvil;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Boss nicknames both ways, so a search finds a thing by whichever name the player knows it by:
 * "toa" finds Tombs of Amascut, and "tombs" finds a tile someone labelled "ToA uniques".
 */
final class SearchAliases {
	/** {nickname, full name} as both read once lower-cased with punctuation turned to spaces. */
	static final String[][] PAIRS = {
		{"toa", "tombs of amascut"}, {"tob", "theatre of blood"}, {"cox", "chambers of xeric"}, {"tfa", "fractured archive"},
		{"cm", "challenge mode"}, {"hm", "hard mode"}, {"jad", "tztok jad"}, {"fight caves", "tztok jad"},
		{"zuk", "tzkal zuk"}, {"inferno", "tzkal zuk"}, {"colo", "sol heredit"}, {"colosseum", "sol heredit"},
		{"kq", "kalphite queen"}, {"kbd", "king black dragon"}, {"dks", "dagannoth"}, {"corp", "corporeal beast"},
		{"cerb", "cerberus"}, {"gg", "grotesque guardians"}, {"nm", "nightmare"}, {"pnm", "phosani"},
		{"cg", "corrupted gauntlet"}, {"sire", "abyssal sire"}, {"hydra", "alchemical hydra"}, {"vork", "vorkath"},
		{"zul", "zulrah"}, {"muspah", "phantom muspah"}, {"kril", "k ril tsutsaroth"}, {"zammy", "k ril tsutsaroth"},
		{"zily", "commander zilyana"}, {"sara", "commander zilyana"}, {"kree", "kree arra"}, {"arma", "kree arra"},
		{"bandos", "general graardor"}, {"graardor", "general graardor"}, {"gwd", "god wars"}, {"levi", "leviathan"},
		{"whisp", "whisperer"}, {"vard", "vardorvis"}, {"duke", "duke sucellus"}, {"dt2", "desert treasure"},
		{"rax", "araxxor"}, {"huey", "hueycoatl"}, {"amox", "amoxliatl"}, {"scur", "scurrius"},
		{"titans", "royal titans"}, {"wt", "wintertodt"}, {"gotr", "guardians of the rift"}, {"tempo", "tempoross"},
		{"mole", "giant mole"}, {"vene", "venenatis"}, {"calv", "calvar ion"}, {"sepulchre", "hallowed sepulchre"},
		{"ba", "barbarian assault"}, {"lms", "last man standing"}, {"pc", "pest control"}, {"ca", "combat achievement"},
	};

	static final Pattern NON_ALNUM = Pattern.compile("[^a-z0-9]+");

	SearchAliases() {
	}

	/** Lower-cased with every run of punctuation and spaces turned into one space: "K'ril  Tsutsaroth" → "k ril tsutsaroth". */
	static String fold(String s) {
		return NON_ALNUM.matcher(s.toLowerCase(Locale.ROOT)).replaceAll(" ").trim();
	}

	/** {@code text} plus the other name of every boss it mentions — search it like any other text. */
	static String augment(String text) {
		if (text == null || text.isEmpty()) return "";
		var words = " " + fold(text) + " ";
		var out = new StringBuilder(text);
		for (String[] p : PAIRS) {
			if (words.contains(" " + p[0] + " ")) {
				out.append(' ').append(p[1]);
			} else if (words.contains(" " + p[1] + " ")) out.append(' ').append(p[0]);
		}
		return out.toString();
	}
}

package com.anvil;

/**
 * What the plugin says in chat about its own setup, and how often.
 *
 * <p>THE STATE THAT SAID NOTHING. Somebody who installed Anvil and never opened the side panel used
 * to get complete silence forever: the plugin's whole surface is a panel they have no reason to
 * click, and nothing in the game ever mentioned that there was a step left. There is one setting to
 * have now — the Account Token, which Sign in fills in — so the only question is "signed in yet?".</p>
 *
 * <p>That mattered less when Anvil was something your clan admin set up for you and handed you a
 * token for. It is now a per-person account that works with no clan at all, so a fresh install is
 * the normal way in rather than a clan's leftover, and the thing it needs to know is where to go.</p>
 *
 * <p>NUDGE, NOT NAG. The first-run line is capped — {@link #FIRST_RUN_NUDGES} logins, counted in
 * config so the cap survives a restart — because somebody who has decided not to connect has
 * answered the question, and a message that repeats forever is how a plugin gets uninstalled.</p>
 *
 * <p>Pure, and RuneLite-free, so the decision can be tested without a client: the plugin supplies
 * the token and the count, and gets back what to print.</p>
 */
public final class SetupNudge {
	/** How many logins a never-configured install is told where to go before it stops asking. */
	static final int FIRST_RUN_NUDGES = 3;

	/** The site, as it reads in a chat line — one source of truth with the address the plugin uses. */
	static final String SITE_HOST = BingoApiClient.site().replaceFirst("^https?://", "");

	public enum Kind {
		/** Connected, or done asking. Say nothing. */
		NONE,
		/** Not signed in — the fresh install. */
		FIRST_RUN,
	}

	/**
	 * @param firstRunShown how many times the first-run line has already been printed on this install
	 */
	public static Kind decide(String token, int firstRunShown) {
		if (token != null && !token.trim().isEmpty()) return Kind.NONE;
		return firstRunShown < FIRST_RUN_NUDGES ? Kind.FIRST_RUN : Kind.NONE;
	}

	/**
	 * The chat lines for a decision, in order. Empty for {@link Kind#NONE}.
	 *
	 * <p>The first-run pair is two lines on purpose: the first is the instruction — one button, in a
	 * panel they are being told exists — and the second is the reason anyone would press it, which
	 * for a person with no clan is the part that is not obvious. Neither line is a request to go
	 * anywhere but the one site this plugin talks to.</p>
	 */
	public static String[] lines(Kind kind) {
		switch (kind) {
			case FIRST_RUN:
				return new String[]{
					"Not connected yet — open the Anvil panel (the anvil icon on the right) and press \"Sign in with Discord\".",
					"A free account on " + SITE_HOST + " tracks your collection log, personal bests and records. No clan needed — and starting one is free.",
				};
			default:
				return new String[0];
		}
	}

	SetupNudge() {
	}
}

package com.anvil;

import static net.runelite.client.ui.ColorScheme.*;
import java.awt.*;
import javax.swing.*;
import javax.swing.plaf.basic.BasicScrollBarUI;

/**
 * A thin, flat scrollbar for the side panel: no arrow buttons, a rounded thumb that lightens under
 * the mouse, and a track the colour of the panel. The default bar is 17px of a 225px-wide panel,
 * which on a small client is a lot of width spent on chrome.
 */
final class SlimScrollBarUI extends BasicScrollBarUI {
	static final int WIDTH = 7;

	static final Color THUMB = MEDIUM_GRAY_COLOR;
	static final Color THUMB_HOVER = LIGHT_GRAY_COLOR;

	/** Restyle every scroll pane directly under {@code root} (the PluginPanel's wrapper). */
	static void applyTo(Container root) {
		if (root == null) return;
		for (Component c : root.getComponents()) {
			if (c instanceof JScrollPane) style(((JScrollPane) c).getVerticalScrollBar());
		}
	}

	static void style(JScrollBar bar) {
		bar.setUI(new SlimScrollBarUI());
		bar.setPreferredSize(new Dimension(WIDTH, 0));
		bar.setOpaque(true);
		bar.setBackground(DARK_GRAY_COLOR);
		bar.setBorder(null);
		bar.setUnitIncrement(16);
	}

	@Override
	protected JButton createDecreaseButton(int orientation) {
		return zeroButton();
	}

	@Override
	protected JButton createIncreaseButton(int orientation) {
		return zeroButton();
	}

	static JButton zeroButton() {
		var b = new JButton();
		var none = new Dimension(0, 0);
		b.setPreferredSize(none);
		b.setMinimumSize(none);
		b.setMaximumSize(none);
		return b;
	}

	@Override
	protected void paintTrack(Graphics g, JComponent c, Rectangle r) {
		g.setColor(DARK_GRAY_COLOR);
		g.fillRect(r.x, r.y, r.width, r.height);
	}

	@Override
	protected void paintThumb(Graphics g, JComponent c, Rectangle r) {
		if (r.isEmpty() || !scrollbar.isEnabled()) return;
		var g2 = Ui.smooth(g);
		g2.setColor(isThumbRollover() || isDragging ? THUMB_HOVER : THUMB);
		int inset = 1;
		g2.fillRoundRect(r.x + inset, r.y + inset, r.width - inset * 2, r.height - inset * 2, WIDTH, WIDTH);
		g2.dispose();
	}

	@Override
	protected Dimension getMinimumThumbSize() {
		return new Dimension(WIDTH, 24);
	}
}

package com.anvil;

import java.awt.*;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;

/**
 * The starting shot, on screen from the whistle until it's filed: where to stand and the same live
 * checks the sidebar card shows, then a short "you're tracked" before it gets out of the way. Shares
 * its toggle with the arrow to the spot (config startSpotGuide).
 */
class StartProofOverlay extends OverlayPanel {
	/** How long "you're tracked" stays up once the shot is filed. */
	static final long DONE_SHOWN_MS = 10_000;
	static final Color ORANGE = new Color(255, 152, 31);

	final AnvilPlugin plugin;
	final AnvilConfig config;

	@Inject
	StartProofOverlay(AnvilPlugin plugin, AnvilConfig config) {
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.startSpotGuide()) return null;
		if (plugin.needsStartProof()) {
			var cfg = plugin.getPluginConfig();
			var proof = cfg == null ? null : cfg.startProof;
			if (proof == null) return null;
			title("Starting shot needed", ORANGE);
			if (proof.location != null) line("Go to", proof.location, Color.WHITE);
			for (StartProofRules.Check c : plugin.startProofChecks(proof)) {
				panelComponent.getChildren().add(LineComponent.builder().left(c.text).leftColor(
					c.state == StartProofRules.Check.State.OK ? Color.GREEN
						: c.state == StartProofRules.Check.State.BAD ? Color.RED : Color.LIGHT_GRAY).build());
			}
			if (plugin.startProofSending()) {
				line("Checking tracking", "sending…", Color.YELLOW);
			} else {
				line(plugin.autoStartShotEnabled() ? "Taken automatically once all green" : "Press Take starting shot in the Anvil panel",
					"", Color.LIGHT_GRAY);
			}
			return super.render(graphics);
		}
		var filedAt = plugin.startProofFiledAt();
		if (filedAt > 0 && System.currentTimeMillis() - filedAt < DONE_SHOWN_MS) {
			title("You're tracked", Color.GREEN);
			line("Starting shot filed — drops and tiles count now", "", Color.WHITE);
			return super.render(graphics);
		}
		return null;
	}

	void title(String text, Color color) {
		panelComponent.getChildren().add(TitleComponent.builder().text(text).color(color).build());
	}

	void line(String left, String right, Color rightColor) {
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).rightColor(rightColor).build());
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;

/**
 * The client-side half of the STARTING SHOT rule (site lib/startProof).
 *
 * <p>Two things the site can ask for beyond the screenshot itself, both of which only this client can
 * answer, and both of which are far more useful checked BEFORE the frame is grabbed than filed and
 * argued about afterwards:
 *
 * <ul>
 *   <li><b>Where you are.</b> A drawn spot the host pinned on the map comes down as coordinates, so
 *       "go to Edgeville bank" stops being an instruction nobody can verify.</li>
 *   <li><b>How old this session is.</b> Hiscores only flush on LOGOUT, so a player who has been
 *       logged in since before the event started has a stale start baseline — every gain they made
 *       beforehand lands in the event's first sweep. Making them log out and back in right before
 *       the shot is what actually stops that, and the screenshot is just the receipt.</li>
 * </ul>
 *
 * <p>Pure and static so it unit-tests without a client: the plugin supplies the numbers.
 */
final class StartProofRules {
	/** {@code sessionLoginAtMs} when we never saw the login — a plugin enabled mid-session. */
	static final long UNKNOWN_LOGIN = 0L;

	StartProofRules() {
	}

	/**
	 * Squares from the drawn spot, the way OSRS measures "within N squares" — the longer axis, not
	 * the diagonal. -1 when there is nothing to measure (no pin, or no position to compare).
	 */
	static int distance(PluginConfigResponse.StartProof proof, Integer x, Integer y) {
		if (proof == null || proof.spot == null || x == null || y == null) return -1;
		return Math.max(Math.abs(x - proof.spot.x), Math.abs(y - proof.spot.y));
	}

	/**
	 * Why this shot can't be filed yet, as a sentence for chat — or null when it can.
	 *
	 * <p>Every check fails OPEN: an older site sends no spot and no window, an unpinned location has
	 * no coordinates, and a client that can't read its own position skips the distance test. The
	 * rule only ever blocks on something we positively know is wrong.
	 */
	static String blockReason(
		PluginConfigResponse.StartProof proof,
		long sessionLoginAtMs,
		long nowMs,
		Integer x,
		Integer y) {
		if (proof == null) return null;

		if (proof.maxSessionMinutes > 0) {
			if (sessionLoginAtMs == UNKNOWN_LOGIN) {
				// The plugin was switched on (or the client reconnected) mid-session, so we can't
				// vouch for the logout that flushed the hiscores. One relog settles it.
				return "Log out and back in before your starting shot — that's what saves your hiscores"
					+ " so your starting totals are right.";
			}
			var minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
			if (minutes > proof.maxSessionMinutes) {
				return "You've been logged in for " + describeMinutes(minutes) + " — log out and back in,"
					+ " then take your starting shot within " + proof.maxSessionMinutes + " min."
					+ " Hiscores only save on logout, so this is what sets your starting totals.";
			}
		}

		int away = distance(proof, x, y);
		if (away >= 0 && away > proof.spot.radius) {
			return "You're " + away + " squares from " + (proof.location != null ? proof.location : "the start spot")
				+ " — go there, then take your starting shot.";
		}

		return null;
	}

	/**
	 * May the plugin take the shot by itself right now? Stricter than {@link #blockReason}, which fails
	 * open: a manual click on an unpinned spot is the player vouching they're there, but nobody is
	 * vouching for an automatic one — so it needs a pin, a known position inside it, and (when the
	 * host asks) a known, fresh session. {@code stillTicks} is how long the player has stood on this
	 * square; a moment's pause keeps the frame from catching them mid-run or mid-teleport.
	 */
	static boolean autoReady(PluginConfigResponse.StartProof proof, long sessionLoginAtMs, long nowMs,
		Integer x, Integer y, int stillTicks) {
		if (proof == null || proof.spot == null || x == null || y == null || stillTicks < AUTO_STILL_TICKS) return false;
		return blockReason(proof, sessionLoginAtMs, nowMs, x, y) == null;
	}

	/** Ticks (0.6s each) standing on one square before an automatic shot. */
	static final int AUTO_STILL_TICKS = 3;

	/** One live requirement on the starting-shot card: met, not met, or not knowable yet. */
	@RequiredArgsConstructor
	static final class Check {
		enum State {
			OK, BAD, UNKNOWN
		}

		final State state;
		final String text;

	}

	/**
	 * The session-age requirement as the card shows it, or null when the host isn't asking. Same
	 * thresholds as {@link #blockReason}, so the card going green means the button won't refuse.
	 */
	static Check sessionCheck(PluginConfigResponse.StartProof proof, long sessionLoginAtMs, long nowMs) {
		if (proof == null || proof.maxSessionMinutes <= 0) return null;
		if (sessionLoginAtMs == UNKNOWN_LOGIN) return new Check(Check.State.BAD, "Log out and back in (then under " + proof.maxSessionMinutes + " min)");
		var minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
		if (minutes > proof.maxSessionMinutes) {
			return new Check(Check.State.BAD, "Session " + describeMinutes(minutes) + ": relog (under "
				+ proof.maxSessionMinutes + " min)");
		}
		return new Check(Check.State.OK, "Fresh session: " + describeMinutes(minutes) + " of " + proof.maxSessionMinutes + " min");
	}

	/** The position requirement as the card shows it, or null when the spot has no pin to measure from. */
	static Check positionCheck(PluginConfigResponse.StartProof proof, Integer x, Integer y) {
		if (proof == null || proof.spot == null) return null;
		int away = distance(proof, x, y);
		if (away < 0) return new Check(Check.State.UNKNOWN, "Position unknown until you're logged in");
		if (away > proof.spot.radius) return new Check(Check.State.BAD, away + " squares away (within " + proof.spot.radius + ")");
		return new Check(Check.State.OK, "At the spot");
	}

	/**
	 * How long is left before the site stops asking for a shot, as a sentence fragment — or null
	 * when there is no deadline to quote (an older site that doesn't send one, or an unreadable
	 * stamp). The window closing is not a failure state: the ask simply expires, so this reads as a
	 * countdown rather than a threat.
	 */
	static String describeWindow(PluginConfigResponse.StartProof proof, long nowMs) {
		if (proof == null || proof.windowEndsAt == null || proof.windowEndsAt.isEmpty()) return null;
		long endsMs;
		try {
			endsMs = java.time.Instant.parse(proof.windowEndsAt).toEpochMilli();
		} catch (java.time.format.DateTimeParseException e) {
			return null;
		}
		var minutes = (endsMs - nowMs) / 60_000L;
		return minutes <= 0 ? null : describeMinutes(minutes);
	}

	/** "12 min" / "2h 05m" — a session age a player reads at a glance. */
	static String describeMinutes(long minutes) {
		if (minutes < 60) return minutes + " min";
		return (minutes / 60) + "h " + String.format("%02dm", minutes % 60);
	}
}

package com.anvil;

import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.*;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.*;
import net.runelite.client.util.ImageUtil;

/**
 * Points the way to the starting shot's drawn spot while one is owed: the game's own hint arrow (over
 * the tile up close, on the minimap edge from afar) and a world-map pin that clamps to the map's edge
 * and jumps there on click. {@link #route} asks the Shortest Path plugin, when installed, for the
 * whole route; without it the message simply goes unheard.
 */
@Singleton
class StartSpotMarker {
	static final BufferedImage PIN = ImageUtil.resizeImage(
		ImageUtil.loadImageResource(StartSpotMarker.class, "/com/anvil/sidebar_icon.png"), 20, 20);

	final Client client;
	final WorldMapPointManager mapPoints;
	final EventBus eventBus;

	WorldPoint shown;
	WorldMapPoint mapPoint;

	@Inject
	StartSpotMarker(Client client, WorldMapPointManager mapPoints, EventBus eventBus) {
		this.client = client;
		this.mapPoints = mapPoints;
		this.eventBus = eventBus;
	}

	/** The spot to mark, or null for none. Spots are drawn on the surface, so the plane is 0. */
	static WorldPoint target(PluginConfigResponse.StartProof proof) {
		return proof == null || proof.spot == null ? null : new WorldPoint(proof.spot.x, proof.spot.y, 0);
	}

	/**
	 * Client thread, every tick. Sets the arrow and pin once when the target appears or moves and takes
	 * them down when it goes, so a quest's own hint arrow is only ever replaced while a shot is owed.
	 */
	void update(WorldPoint target, String label) {
		if (Objects.equals(target, shown)) return;
		clear();
		if (target == null) return;
		client.setHintArrow(target);
		mapPoint = WorldMapPoint.builder()
			.worldPoint(target)
			.image(PIN)
			.name("Anvil starting shot")
			.tooltip("Anvil starting shot" + (label != null ? ": " + label : ""))
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		mapPoints.add(mapPoint);
		shown = target;
	}

	/** Client thread. Takes down our arrow (never someone else's) and our pin. */
	void clear() {
		if (shown != null && client.hasHintArrow() && shown.equals(client.getHintArrowPoint())) client.clearHintArrow();
		if (mapPoint != null) {
			mapPoints.remove(mapPoint);
			mapPoint = null;
		}
		shown = null;
	}

	/** Ask Shortest Path for a route to {@code target}. Client thread. */
	void route(WorldPoint target) {
		if (target != null) eventBus.post(new PluginMessage("shortestpath", "path", Collections.singletonMap("target", target)));
	}
}

package com.anvil;

import java.util.concurrent.ThreadLocalRandom;
import java.util.function.DoubleSupplier;
import lombok.RequiredArgsConstructor;

/**
 * How long to wait before trying a failed push again.
 *
 * <p>The profile syncs run off a fixed 30s tick, so a push that keeps failing is a request every 30
 * seconds for as long as the player stays logged in — against a site that has already said no. That
 * is rude to a clan's server and pointless for the player: the two cases are "your site is down"
 * (which wants patience) and "your site doesn't accept this" (which wants stopping altogether).
 *
 * <p>This covers the first: doubling waits from 30s to a 10-minute ceiling ({@link RetryPolicy#backoffMs},
 * so a clan's clients that lost the site together don't all come back together), reset by any success.
 * The second is the caller's job — a permanent failure drops the batch instead of backing off.
 */
@RequiredArgsConstructor
final class SyncBackoff {
	static final long FIRST_MS = 30_000L;
	static final long MAX_MS = 600_000L;

	final long firstMs;
	final long maxMs;
	/** A uniform draw in [0, 1) spreading each wait ±20%; 0.5 gives the exact doubling. */
	final DoubleSupplier jitter;
	long nextAttemptAt;
	int failures;

	SyncBackoff() {
		this(FIRST_MS, MAX_MS);
	}

	SyncBackoff(long firstMs, long maxMs) {
		this(firstMs, maxMs, () -> ThreadLocalRandom.current().nextDouble());
	}

	/** Is a push allowed right now? True until something fails. */
	boolean ready(long now) {
		return now >= nextAttemptAt;
	}

	/** A push worked — back to normal cadence. */
	void onSuccess() {
		nextAttemptAt = 0;
		failures = 0;
	}

	/** A push failed for a reason that might clear on its own. Waits twice as long each time. */
	void onFailure(long now) {
		failures++;
		nextAttemptAt = now + RetryPolicy.backoffMs(failures, firstMs, maxMs, jitter.getAsDouble());
	}

	/** Seconds until the next attempt, for a log line that explains the silence. */
	long secondsUntilReady(long now) {
		return Math.max(0, (nextAttemptAt - now + 999) / 1000);
	}

	void reset() {
		onSuccess();
	}
}

package com.anvil;

import com.anvil.PluginConfigResponse.ComboPart;
import com.anvil.PluginConfigResponse.TrackedCombo;
import java.util.*;

/**
 * The extra progress lines a tile carries beyond its own count — "3/5 runs" on a multi-run timed tile
 * (Barracuda Trials ranks), and a COMBO's parts ("1 of 2 done", then one line per part) — plus the
 * virtual-id rule behind capped counters.
 *
 * <p>A capped counter tile's cap counters carry a VIRTUAL negative tileId, {@code -(capOf * 8 + slot)};
 * they are never rows, pins or chat subjects of their own.
 *
 * <p>A combo's parts ride the ordinary tracked lists with {@code partOf} set; they credit as usual and
 * fold under their combo, which is what pins.
 *
 * <p>No RuneLite dependencies, so it is unit-testable.
 */
final class TileNotes {
	TileNotes() {
	}



	/** Only real tiles can be pinned (the site serves no progress for a virtual id). */
	static boolean pinnable(int tileId) {
		return tileId > 0;
	}

	/** "3/5 runs" for a tile needing several qualifying runs; null for a plain one-clear timed tile. */
	static String runs(long done, int required) {
		if (required <= 1) return null;
		return fmt(Math.max(0, Math.min(done, required))) + "/" + fmt(required) + " runs";
	}


	/** Part tileId → its combo's tileId. */
	static Map<Integer, Integer> partCombos(List<TrackedCombo> combos) {
		if (combos == null || combos.isEmpty()) return Collections.emptyMap();
		Map<Integer, Integer> out = new HashMap<>();
		for (TrackedCombo c : combos) {
			if (c != null && c.parts != null) {
				for (ComboPart p : c.parts) {
					if (p != null) out.put(p.tileId, c.tileId);
				}
			}
		}
		return out;
	}

	/**
	 * A pinned combo's lines: "1 of 2 done", then each part — "Zulrah pet  done" once done, else its label
	 * with its count when it has one ("Searches 37/100"). {@code counts} maps a part's tileId to
	 * {current, required} at this client's newest count; a part missing from it shows just its label.
	 */
	static List<String> comboLines(TrackedCombo combo, Map<Integer, long[]> counts) {
		List<String> out = new ArrayList<>();
		int needed = Math.max(1, combo.needed);
		// A "mix" combo is weighted shares, so it reads as the server's percentage instead.
		out.add("mix".equals(combo.rule)
			? Math.max(0, Math.min(100, combo.percent)) + "%"
			: fmt(Math.min(combo.done, needed)) + " of " + fmt(needed) + " done");
		if (combo.parts != null) {
			for (ComboPart p : combo.parts) {
				if (p == null) continue;
				var label = p.label == null ? "Part" : p.label.trim();
				var c = counts == null ? null : counts.get(p.tileId);
				if (p.completed) {
					out.add(label + "  done");
				} else if (c != null && c[1] > 1) {
					out.add(label + "  " + fmt(Math.max(0, Math.min(c[0], c[1]))) + "/" + fmt(c[1]));
				} else out.add(label);
			}
		}
		return out;
	}

	/** A part named with its combo, for chat: "GOTR rare or searches — 100 searches". */
	static String partLabel(String comboLabel, String partLabel) {
		if (comboLabel == null || comboLabel.trim().isEmpty()) return partLabel;
		return comboLabel.trim() + " \u2014 " + (partLabel == null ? "" : partLabel.trim());
	}

	static String plural(String noun) {
		var n = noun.toLowerCase(Locale.ROOT);
		if (n.endsWith("s") || n.endsWith("x") || n.endsWith("z") || n.endsWith("sh") || n.endsWith("ch")) return noun + "es";
		if (n.length() > 1 && n.endsWith("y") && "aeiou".indexOf(n.charAt(n.length() - 2)) < 0) return noun.substring(0, noun.length() - 1) + "ies";
		return noun + "s";
	}

	static String fmt(long n) {
		return String.format(Locale.ROOT, "%,d", n);
	}
}

package com.anvil;

import lombok.Setter;
import java.awt.*;
import java.util.*;
import java.util.List;
import javax.inject.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;
import java.util.function.IntFunction;
import java.util.function.ToLongBiFunction;
import java.time.*;
import java.util.function.Supplier;
import java.util.function.Consumer;

/**
 * Tiles pinned from the sidebar as in-game widgets ("Track on screen"): one movable, resizable
 * overlay per tile showing every team's progress and each team's top contributors, read from
 * {@code GET /api/plugin/event/<id>/tile/<tileId>/progress}.
 *
 * <p>Fetched only while something is pinned: on the plugin's 30s config tick, and a few seconds after
 * this account progresses a pinned tile, so your own kill shows without waiting a full poll. Each pin
 * keeps its board: pins from several live boards sit side by side (tile ids are unique across boards).
 * They can go up before it starts (the widget counts down, then goes live on the first poll after the
 * whistle) and a board's pins are forgotten once the site says it's over.
 *
 * <p>A pin your team finishes shows "Done" for a moment and then takes itself down. A done tile can't be
 * pinned — the sidebar offers no button for it.
 */

@Singleton
public class TileTracker {
	static final int MAX_PINS = 3;
	static final String CFG_PINS = "trackedTiles";
	static final Color GOLD = new Color(255, 215, 0);
	static final int OTHER_TEAMS_SHOWN = 4;
	/** The blank line between pins in the shared panel; one instance serves every gap. */
	static final LineComponent GAP = LineComponent.builder().build();
	/** How long a just-finished pin keeps showing "Done" before it unpins (hidden on the next fetch after). */
	static final long DONE_LINGER_MS = 10_000;
	/** Failed fetches of a pin that never loaded before it is let go (30s apart). */
	static final int MAX_FAILS = 6;

	final OverlayManager overlayManager;
	final ConfigManager configManager;
	final BingoApiClient apiClient;

	/** tileId → its widget, in pin order. Guarded by {@code this}. */
	final Map<Integer, Widget> pins = new LinkedHashMap<>();
	/** The logged-in account's hash, or -1 at the login screen: pins are saved per account. */
	long account = -1;
	/**
	 * (tileId, site count) → what to show for your team: the plugin's own newer count when it has one,
	 * so a pinned tile moves on your kill. Identity until the plugin sets it.
	 */
	@Setter volatile ToLongBiFunction<Integer, Long> shownProgress = (id, site) -> site;
	/**
	 * tileId → the plugin's extra lines for it ("3/5 runs", a combo's parts, TileNotes), read from
	 * the polled config each frame. None until the plugin sets it.
	 */
	@Setter volatile IntFunction<List<String>> notes = id -> Collections.emptyList();
	/** The live boards' ids, to find the board of a pin saved without one. */
	volatile Supplier<List<Integer>> boards = Collections::emptyList;
	/** Says why a pin came down (a chat line). */
	volatile Consumer<String> told = m -> { };
	/**
	 * One panel holding every pin (the default) or a movable widget per pin. One panel can't end up
	 * with pins on top of each other, and is one thing to place; separate ones can be put anywhere.
	 */
	boolean onePanel = true;
	final Combined combined = new Combined();
	/**
	 * The pins as the frame draw sees them: replaced whole on every change, read without a lock.
	 * The shared panel renders on the client thread every frame, which must never wait on a lock.
	 */
	volatile List<Widget> drawn = new ArrayList<>();

	@Inject
	TileTracker(OverlayManager overlayManager, ConfigManager configManager, BingoApiClient apiClient) {
		this.overlayManager = overlayManager;
		this.configManager = configManager;
		this.apiClient = apiClient;
	}

	/**
	 * {@code doneSeen}: a pin just started showing "Done" (tileId) — the plugin asks again after the
	 * linger, so it comes down on time instead of on the next 30s poll. {@code unpinned}: a finished pin
	 * came down, so whatever lists the pins (the panel's "Tracked on screen") asks again.
	 */
	void setDoneHooks(java.util.function.IntConsumer doneSeen, Runnable unpinned) {
		this.doneSeen = doneSeen;
		this.unpinned = unpinned;
	}

	volatile java.util.function.IntConsumer doneSeen = id -> { };
	volatile Runnable unpinned = () -> { };

	void setBoards(Supplier<List<Integer>> live, Consumer<String> tell) {
		boards = live;
		told = tell;
	}

	/** Switch between one panel and a widget per pin, moving whatever is pinned across. */
	synchronized void setOnePanel(boolean one) {
		if (one == onePanel) return;
		hideAll();
		onePanel = one;
		showAll();
	}

	void hideAll() {
		overlayManager.remove(combined);
		for (Widget w : pins.values()) overlayManager.remove(w);
	}

	void showAll() {
		if (pins.isEmpty()) return;
		if (onePanel) {
			overlayManager.add(combined);
		} else {
			for (Widget w : pins.values()) overlayManager.add(w);
		}
	}

	Widget removePin(int tileId) {
		var w = pins.remove(tileId);
		drawn = new ArrayList<>(pins.values());
		return w;
	}

	/** Take one pin's widget down, and the shared panel with the last one. */
	void hide(Widget w) {
		overlayManager.remove(w);
		if (pins.isEmpty()) overlayManager.remove(combined);
	}

	/** Pins saved before they were kept per account, handed to the first account that logs in. */
	String legacyPins;

	/**
	 * A fresh start: the next login restores its pins even if it's the account that was logged in when
	 * the plugin stopped. Pins saved before they were kept per account go to the first account seen —
	 * almost always the one that pinned them — rather than being lost on the upgrade.
	 */
	synchronized void startUp() {
		account = -1;
		var old = configManager.getConfiguration("osrsbingo", CFG_PINS);
		if (old != null) {
			legacyPins = old;
			configManager.unsetConfiguration("osrsbingo", CFG_PINS);
		}
	}

	/**
	 * The account now logged in ({@code -1} at the login screen): take the last one's pins down and
	 * restore this one's ("eventId:tileId,tileId;eventId:tileId"). One client plays several accounts,
	 * and an alt that isn't on the event has no board to unpin them from.
	 */
	synchronized void forAccount(long hash) {
		if (hash == account) return;
		shutDown();
		account = hash;
		var saved = hash == -1 ? null : configManager.getConfiguration("osrsbingo", key());
		if (saved == null && hash != -1 && legacyPins != null) {
			saved = legacyPins;
			configManager.setConfiguration("osrsbingo", key(), saved);
		}
		if (hash != -1) legacyPins = null;
		if (saved == null || saved.isEmpty()) return;
		try {
			parse(saved).forEach((tile, event) -> {
				if (pins.size() < MAX_PINS) add(event, tile);
			});
		} catch (RuntimeException e) {
			shutDown();
			save();
		}
	}

	synchronized void shutDown() {
		hideAll();
		pins.clear();
		drawn = new ArrayList<>();
	}

	synchronized boolean isPinned(int eventId, int tileId) {
		var w = pins.get(tileId);
		return w != null && w.event == eventId;
	}

	/**
	 * Pin ({@code on}) or unpin — an explicit state, not a flip, so a button drawn before the pin took
	 * itself down (a finished tile) can't put it back up when clicked.
	 */
	synchronized void set(int eventId, int tileId, boolean on) {
		if (isPinned(eventId, tileId) != on) toggle(eventId, tileId);
	}

	/** Pin or unpin. */
	synchronized void toggle(int eventId, int tileId) {
		if (!TileNotes.pinnable(tileId)) {
			return; // a cap counter's virtual entry is never pinned
		}
		if (isPinned(eventId, tileId)) {
			hide(removePin(tileId));
		} else {
			if (pins.size() >= MAX_PINS) return;
			// A done tile can't be pinned (the sidebar offers no button), so a pin that turns out done
			// on its first fetch was finished in between — it comes down like any other.
			add(eventId, tileId).keepWhenDone = false;
		}
		save();
	}

	/** The 30s tick: refetch every pin. Blocking; call off the client thread. */
	void poll() {
		List<Integer> ids;
		synchronized (this) {
			ids = new ArrayList<>(pins.keySet());
		}
		for (int id : ids) refresh(id);
	}

	/** Refetch one pinned tile (no-op when it isn't pinned). Blocking. */
	void refresh(int tileId) {
		Widget w;
		synchronized (this) {
			w = pins.get(tileId);
		}
		if (w == null) return;
		var p = fetch(w);
		if (letGo(w, p)) {
			drop(w, p == Progress.LOCKED ? "not open for you" : p == Progress.GONE ? "tile removed" : "couldn't load");
		} else if (p != null && p != Progress.GONE) {
			if (p.phase != null && p.phase.contains("ended")) clear(w.event);
			else show(w.event, tileId, w, p);
		}
	}

	/**
	 * Note one fetch on the pin and say whether to take it down: the site says the tile is gone, or it has failed {@link #MAX_FAILS} times without ever loading.
	 */
	static boolean letGo(Widget w, Progress p) {
		if (p == Progress.GONE || p == Progress.LOCKED) return true; // deleted (a reseed) or off your boards: final, no retry
		if (p == null) return w.progress == null && ++w.fails >= MAX_FAILS;
		w.fails = 0;
		return false;
	}

	/** The board's fetch; a pin with no board tries each live one. */
	Progress fetch(Widget w) {
		if (w.event > 0) return apiClient.fetchTileProgress(w.event, w.tileId);
		var last = Progress.GONE;
		for (int b : boards.get()) {
			var p = apiClient.fetchTileProgress(b, w.tileId);
			if (p != null && p != Progress.GONE) {
				w.event = b;
				save();
				return p;
			}
			if (p == null) last = null;
		}
		return last;
	}

	synchronized void drop(Widget w, String why) {
		if (pins.get(w.tileId) != w) return;
		hide(removePin(w.tileId));
		save();
		told.accept("Stopped tracking " + (w.label != null ? w.label : "a tile") + " (" + why + ")");
	}

	/**
	 * A tile's numbers from the live push: the whole board's view, so ours is marked here (team first,
	 * as the route ranks it for a caller), then shown like a fetch.
	 */
	void pushed(int event, int tileId, Progress p, int myTeam, int myPlayer) {
		Widget w;
		synchronized (this) {
			w = pins.get(tileId);
		}
		if (w == null || w.event != event || p == null || p.teams == null || p.phase == null || p.phase.contains("ended")) return;
		for (Team t : p.teams) {
			t.mine = t.teamId == myTeam;
			if (t.members != null) t.members.forEach(m -> m.mine = m.id > 0 && m.id == myPlayer);
		}
		p.teams.sort((a, b) -> Boolean.compare(b.mine, a.mine));
		show(event, tileId, w, p);
	}

	void show(int event, int tileId, Widget w, Progress p) {
		w.progress = p;
		w.label = p.label;
		int step = afterFetch(w, p, System.currentTimeMillis());
		if (step == UNPIN) unpinDone(event, tileId, w);
		else if (step == DONE_SHOWN) doneSeen.accept(tileId);
	}

	static final int KEEP = 0, DONE_SHOWN = 1, UNPIN = 2;

	/** What a fetch means for the pin: nothing, "Done" just went up (ask again after the linger), or take it down. */
	static int afterFetch(Widget w, Progress p, long now) {
		var was = w.doneSinceMs;
		if (finishedAndShown(w, p, now)) return UNPIN;
		return was == 0 && w.doneSinceMs != 0 ? DONE_SHOWN : KEEP;
	}

	/**
	 * Note this fetch on the widget and say whether it should now come down: the viewer's team has
	 * finished the tile, the pin isn't one made on an already-done tile, and "Done" has been up for
	 * {@link #DONE_LINGER_MS}.
	 */
	static boolean finishedAndShown(Widget w, Progress p, long now) {
		var done = ownTeamDone(p);
		if (w.keepWhenDone == null) w.keepWhenDone = done;
		if (!done || w.keepWhenDone) return false;
		if (w.doneSinceMs == 0) {
			w.doneSinceMs = now;
			return false;
		}
		return now - w.doneSinceMs >= DONE_LINGER_MS;
	}

	static boolean ownTeamDone(Progress p) {
		if (p.teams == null || "upcoming".equals(p.phase)) return false;
		for (Team t : p.teams) {
			if (t.mine) return t.complete;
		}
		return false;
	}

	synchronized void unpinDone(int event, int tileId, Widget w) {
		if (pins.get(tileId) == w) {
			hide(removePin(tileId));
			save();
			unpinned.run();
		}
	}

	/** The tiles pinned for this event, in pin order. */
	synchronized List<Integer> pinned(int eventId) {
		List<Integer> out = new ArrayList<>();
		pins.values().forEach(w -> {
			if (w.event == eventId) out.add(w.tileId);
		});
		return out;
	}

	/** The widget's right-click "Unpin": one pin, or every pin from the shared panel. */
	synchronized boolean unpinFrom(Overlay overlay, String option) {
		if (option == null || !option.startsWith("Unpin")) return false;
		if (overlay == combined) {
			shutDown();
		} else if (overlay instanceof Widget && pins.get(((Widget) overlay).tileId) == overlay) {
			hide(removePin(((Widget) overlay).tileId));
		} else return false;
		save();
		return true;
	}

	/** Take every pin for this event down. */
	synchronized void clear(int eventId) {
		for (int id : pinned(eventId)) hide(removePin(id));
		save();
	}

	/** Asked from the client thread on every credited kill, so read off the snapshot, lock-free. */
	boolean tracks(int tileId) {
		for (Widget w : drawn) {
			if (w.tileId == tileId) return true;
		}
		return false;
	}

	Widget add(int eventId, int tileId) {
		int slot = 0;
		while (slotTaken(slot)) slot++;
		var w = new Widget(slot, tileId, (id, site) -> shownProgress.applyAsLong(id, site));
		w.event = eventId;
		w.notes = id -> notes.apply(id);
		pins.put(tileId, w);
		drawn = new ArrayList<>(pins.values());
		if (onePanel) {
			overlayManager.remove(combined); // re-added, so it is never in twice
			overlayManager.add(combined);
		} else overlayManager.add(w);
		return w;
	}

	boolean slotTaken(int slot) {
		return pins.values().stream().anyMatch(w -> w.slot == slot);
	}

	String key() {
		return CFG_PINS + "." + account;
	}

	void save() {
		if (account == -1) return;
		if (pins.isEmpty()) {
			configManager.unsetConfiguration("osrsbingo", key());
			return;
		}
		configManager.setConfiguration("osrsbingo", key(), format(pins.values()));
	}

	/** Saved pins, tile → its board: "event:tile,tile;event:tile" (one board's "event:tile,tile" too). */
	static Map<Integer, Integer> parse(String saved) {
		Map<Integer, Integer> out = new LinkedHashMap<>();
		for (String board : saved.split(";")) {
			// "event:tile,tile"; a bare "tile,tile" (saved before pins kept a board) gets board 0, found at fetch.
			var parts = board.contains(":") ? board.split(":", 2) : new String[]{"0", board};
			int event;
			try {
				event = Integer.parseInt(parts[0].trim());
			} catch (NumberFormatException e) {
				continue;
			}
			for (String id : parts[1].split(",")) {
				try {
					out.put(Integer.valueOf(id.trim()), event);
				} catch (NumberFormatException e) {
					// skip a bad id, keep the rest
				}
			}
		}
		return out;
	}

	static String format(Collection<Widget> pins) {
		var sj = new StringJoiner(";");
		pins.forEach(w -> sj.add(w.event + ":" + w.tileId));
		return sj.toString();
	}

	/** Every pin in one movable panel, in pin order, a blank line between them — name and bar each. */
	class Combined extends OverlayPanel {
		Combined() {
			addUnpin(this, "Unpin all");
			setPosition(OverlayPosition.TOP_LEFT);
			setResizable(true);
			setMovable(true);
		}

		@Override
		public String getName() {
			return "AnvilTileTrackerPanel";
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			if (AnvilPlugin.capturing) return null;
			var shown = drawn; // no lock on the frame path
			for (int i = 0; i < shown.size(); i++) {
				if (i > 0) panelComponent.getChildren().add(GAP);
				shown.get(i).drawInto(panelComponent, true);
			}
			return shown.isEmpty() ? null : super.render(graphics);
		}
	}

	static void addUnpin(Overlay overlay, String option) {
		overlay.getMenuEntries().add(new OverlayMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, option, "Anvil tile"));
	}

	/** The site's answer (lib/tileTracker): the viewer's team first, then the rest by progress. */
	static class Progress {
		/** lib/eventTime's phase: "upcoming", "active", "ended" or "force-ended". */
		String phase;
		String startsAt;
		int tileId;
		String label;
		int points;
		int goal;
		List<Team> teams;
		/** Fetch result for "the site says this tile is not on your boards". */
		static final Progress GONE = new Progress();
		/** Fetch result for "exists, but not open for you" (a race step ahead, a closed tile). */
		static final Progress LOCKED = new Progress();
	}

	static class Team {
		int teamId;
		String name;
		String color;
		long current;
		boolean complete;
		boolean mine;
		List<Member> members;
	}

	static class Member {
		/** Participant id, so a view sent to the whole board can be marked as ours. */
		int id;
		String name;
		long amount;
		boolean mine;
	}

	/**
	 * One pinned tile. Alt-drag moves it and drags its edge to resize, like any overlay; each slot has
	 * its own name so RuneLite remembers where every one was put.
	 */
	static class Widget extends OverlayPanel {
		final int slot;
		final int tileId;
		/** The board it's on. */
		int event;
		final ToLongBiFunction<Integer, Long> shown;
		/** This tile's extra lines (TileTracker.notes); none by default. */
		volatile IntFunction<List<String>> notes = id -> Collections.emptyList();
		List<String> builtNotes = Collections.emptyList();
		volatile Progress progress;
		/** The tile's name once seen; fetches failed with nothing shown. */
		String label;
		int fails;
		/**
		 * Stay up after the team finishes? Pins restored from config start false, so a tile finished
		 * while the client was closed still comes down; a fresh pin is decided by its first fetch.
		 */
		Boolean keepWhenDone = false;
		/** When this pin was first seen done, or 0. */
		long doneSinceMs;
		/**
		 * The lines drawn every frame, built once per fetch (or layout switch) on the client thread — the
		 * frame only moves your team's bar, your own count and the countdown, and only when they change.
		 */
		final List<LayoutableRenderableEntity> lines = new ArrayList<>();
		Progress builtFor;
		boolean builtCompact;
		Team mine;
		ProgressBarComponent bar;
		LineComponent you;
		LineComponent startsIn;
		Instant startsAt;
		long youBase;
		long shownAhead;
		long shownSecs;

		Widget(int slot, int tileId, ToLongBiFunction<Integer, Long> shown) {
			this.slot = slot;
			this.tileId = tileId;
			this.shown = shown;
			addUnpin(this, "Unpin");
			setPosition(OverlayPosition.TOP_LEFT);
			setResizable(true);
			setMovable(true);
		}

		@Override
		public String getName() {
			return "AnvilTileTracker" + slot;
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			if (AnvilPlugin.capturing) return null;
			drawInto(panelComponent, false);
			return super.render(graphics);
		}

		/**
		 * This pin's lines, into its own widget or the shared panel. {@code compact} (the shared panel)
		 * is the tile's name and your team's bar only — three pins with every member and rival team
		 * each made a panel taller than the game view.
		 */
		void drawInto(PanelComponent panelComponent, boolean compact) {
			var p = progress;
			var n = notes.apply(tileId);
			if (n == null) n = Collections.emptyList();
			if (p != builtFor || compact != builtCompact || lines.isEmpty() || !n.equals(builtNotes)) {
				builtNotes = n;
				build(p, compact);
			}
			if (startsIn != null && startsAt != null) {
				var s = Math.max(0, Duration.between(Instant.now(), startsAt).getSeconds());
				if (s != shownSecs) {
					shownSecs = s;
					startsIn.setRight(s >= 3600 ? (s / 3600) + "h " + (s % 3600 / 60) + "m" : s >= 60 ? (s / 60) + "m " + (s % 60) + "s" : s + "s");
				}
			}
			if (bar != null && !mine.complete) {
				// Your own kill counts here the moment it happens; the fetch after the push confirms it.
				var current = shown.applyAsLong(tileId, mine.current);
				bar.setValue(Math.min(current, p.goal));
				var ahead = Math.max(0, current - mine.current);
				if (you != null && ahead != shownAhead) {
					shownAhead = ahead;
					you.setRight(Ui.count(youBase + ahead));
				}
			}
			panelComponent.getChildren().addAll(lines);
		}

		void build(Progress p, boolean compact) {
			builtFor = p;
			builtCompact = compact;
			lines.clear();
			mine = null;
			bar = null;
			you = startsIn = null;
			shownAhead = shownSecs = -1;
			if (p == null || (p.teams == null && p.label == null)) {
				lines.add(TitleComponent.builder().text("Anvil: loading tile…").color(GOLD).build());
				return;
			}
			lines.add(TitleComponent.builder().text(p.label).color(GOLD).build());
			for (String note : builtNotes) lines.add(LineComponent.builder().left(note).leftColor(Color.LIGHT_GRAY).build());
			if ("upcoming".equals(p.phase)) {
				// Nothing counts before the start, so there is no progress to draw yet — only when.
				lines.add(LineComponent.builder().left("Goal").right(Ui.count(p.goal)).build());
				startsIn = LineComponent.builder().left("Starts in").right("soon").rightColor(Color.YELLOW).build();
				lines.add(startsIn);
				try {
					startsAt = Instant.parse(p.startsAt);
				} catch (RuntimeException e) {
					startsAt = null;
				}
				return;
			}
			if (p.teams == null) return; // named, nothing to rank yet
			int others = 0;
			for (Team t : p.teams) {
				if (t.mine) {
					buildOwnTeam(p, t, compact);
				} else if (!compact && others++ < OTHER_TEAMS_SHOWN) {
					lines.add(LineComponent.builder()
						.left(t.name)
						.leftColor(Ui.teamColor(t.color, Color.WHITE))
						.right(t.complete ? "Done" : Ui.count(t.current) + "/" + Ui.count(p.goal))
						.rightColor(t.complete ? Color.GREEN : Color.WHITE)
						.build());
				}
			}
		}

		void buildOwnTeam(Progress p, Team t, boolean compact) {
			mine = t;
			bar = new ProgressBarComponent();
			bar.setMaximum(Math.max(1, p.goal));
			bar.setValue(p.goal);
			bar.setForegroundColor(t.complete ? new Color(0, 160, 0) : Ui.teamColor(t.color, Color.WHITE).darker());
			bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.FULL);
			lines.add(bar);
			if (compact || t.members == null) return;
			for (Member m : t.members) {
				var line = LineComponent.builder()
					.left(m.mine ? "You" : m.name)
					.leftColor(m.mine ? GOLD : Color.LIGHT_GRAY)
					.right(Ui.count(m.amount))
					.build();
				if (m.mine && !t.complete) {
					you = line;
					youBase = m.amount;
				}
				lines.add(line);
			}
		}
	}
}

package com.anvil;

import java.util.*;
import java.util.regex.*;

/**
 * Pure, side-effect-free parsing for timed-clear tiles. Kept out of the plugin so the fragile,
 * game-version-specific bits (the exact completion strings) are unit-testable against real chat
 * messages without standing up RuneLite.
 *
 * Two responsibilities:
 *   1. {@link #parseDurationSeconds} — pull a clear time out of a "...duration: mm:ss(.ff)" /
 *      "...completion time: mm:ss" message (raids, gauntlet, colosseum, inferno, ToB/ToA).
 *   2. {@link #messageMatchesActivity} — decide whether a chat line identifies a given tile's
 *      activity, via a signature table. The identifying line is usually NOT the duration line
 *      (it's the adjacent "Your X kill/completion count is:" line), which is why the plugin
 *      correlates the two across a short window.
 *
 * Real message formats this was built against (verify/extend as Jagex changes them):
 *   Inferno      "Duration: 2:58.03 (new personal best)"  +  "Your TzKal-Zuk kill count is: 1."
 *   TzHaar-Ket-Rak "Challenge duration: 8:54.00"  +  "Your completion count for TzHaar-Ket-Rak's ... is: 1."
 *   Nightmare    "Team size: Solo Fight duration: 24:35"  +  "Your Nightmare kill count is: 11."
 *   Colosseum    "Wave 12 completed! Wave duration: 33:32.40"  +  "Your Sol Heredit kill count is: 100."
 *   CoX          "...your raid is complete! Duration: 15:39"  +  "Your completed Chambers of Xeric count is: 306."
 *   Boss timers  "Fight duration: 1:36 (new personal best)"  +  "Your <boss> kill count is: N." — the
 *                generic pair for every boss with an in-game kill timer (GWD, Zulrah, Vorkath, Hydra,
 *                Grotesque Guardians, Muspah, the DT2 four, Scurrius, Araxxor, Yama, etc.); the
 *                identity line names the boss, so the activity-name fallback covers them.
 *   Gauntlet     "Challenge duration: 10:24. Personal best: 7:59."  +  "Your Gauntlet completion count is: 45."
 *   Barracuda Trials (Sailing)
 *                "You have completed the Gwenith Glide and achieved the Marlin rank."
 *                + "Time: 6:04.20 (new personal best)."  +  "Your Gwenith Glide completion count is: 49"
 *                — no signature entry needed: both flanking lines name the trial, so the
 *                activity-name fallback matches tiles like "gwenith glide" / "tempor tantrum".
 */
final class TimedClearParser {
	TimedClearParser() {}

	static final Pattern SPACES = Pattern.compile("\\s+");
	static final Pattern TRAILING_NON_LETTERS = Pattern.compile("[^a-z]+$");

	// A duration keyword followed (within a few non-digits) by an [h:]mm:ss token. Fractional
	// ".ff" tails are intentionally left out of the capture group. Minutes go to three digits:
	// slow Inferno/Zuk clears print raw minutes past 99 ("Duration: 172:18. Personal best:
	// 134:52") rather than rolling into h:mm:ss. Keyword family, mirroring the formats
	// RuneLite's chat-commands PB tracker knows:
	//   duration        — "Fight/Wave/Challenge/Corrupted challenge duration:", raid "Duration:"
	//   completion time — ToB/ToA "total completion time:"
	//   time:           — Barracuda Trials "Time: 6:04.20", Sepulchre "Floor 5 time:"/"Overall
	//                     time:". Colon fused so countdown lines ("Time remaining: 5:00") don't
	//                     parse as a clear.
	//   subdued in      — Tempoross "Subdued in 6:32"
	// ToA's per-room / per-challenge sub-times also match "duration"/"time:" but are filtered
	// out before this (see RAID_SUBTIME) — they're not the raid clear time.
	// → chat-patterns.json "timed.duration" (ChatPatterns).

	// ToA reports several *sub*-times before the raid total, each carrying its own duration:
	//   "Challenge complete: The Wardens. Duration: 7:05"     — one room
	//   "Challenge time: 10:23"                                — one challenge
	//   "Tombs of Amascut: Expert Mode challenge completion time: 30:16" — rooms only, no overhead
	// None of these is the raid clear time — a "clear the raid under X" tile must use the
	// "… total completion time:" line (or CoX's "raid is complete! Duration:"). Crediting a room
	// duration was letting a 34:50 raid pass a 25-minute tile off its 7:05 final room. These are
	// the only "challenge …"/"… completion time" phrasings we reject; "Challenge duration:"
	// (Gauntlet / Corrupted Gauntlet / TzHaar-Ket-Rak) and "total completion time" are kept.
	// → chat-patterns.json "timed.raid_subtime" (ChatPatterns).

	// Lowercased activity (as configured on the tile) -> substrings that, if present in a nearby
	// chat line, identify that activity. The identifying line is typically the boss/raid
	// kill/completion-count message, which names the boss rather than the activity (e.g. Inferno
	// -> "tzkal-zuk", Colosseum -> "sol heredit"). Default signature is the activity name itself.
	static final Map<String, List<String>> SIGNATURES = new HashMap<>();

	// {"activity|alias…", signature…}
	static final String[][] SIGNATURE_TABLE = {
		// Zuk's kill-count line only — never the bare word: TzHaar-Ket-Rak's challenges end with
		// "You need to complete the Inferno to unlock …", which credited a 3:11 Jad challenge
		// to a 65-minute Inferno tile.
		{"inferno", "tzkal-zuk"},
		{"fight caves", "tztok-jad", "fight cave"},
		// Raid-mode shorthands, so a mode tile matches however the admin phrased it. Colons and
		// spacing are already folded away by norm(), so we only enumerate the abbreviations here;
		// each pins the EXACT game count-line substring. A CM/HM/Expert tile must carry the full
		// mode text so a *base*-mode clear (whose line omits it) can't wrongly complete it — while a
		// base-raid tile keeps matching every harder mode (the mode line contains the base name).
		{"chambers of xeric|cox", "chambers of xeric"},
		{"cox cm|cox challenge mode|chambers of xeric cm", "chambers of xeric challenge mode"},
		{"theatre of blood|tob", "theatre of blood"},
		{"tob hm|tob hard mode|theatre of blood hm", "theatre of blood hard mode"},
		{"tombs of amascut|toa", "tombs of amascut"},
		{"toa em|toa expert|toa expert mode|tombs of amascut em", "tombs of amascut expert mode"},
		// Raids 4: "Your completed Fractured Archive count is: N" carries no article.
		{"the fractured archive|fractured archive|tfa", "fractured archive"},
		{"fortis colosseum|colosseum", "sol heredit", "colosseum"},
		{"the nightmare|nightmare", "nightmare"},
		{"phosani's nightmare", "phosani's nightmare"},
		{"tzhaar-ket-rak", "tzhaar-ket-rak"},
		// The completion line reads "Your Gauntlet completion count is: N" — it never contains
		// "the gauntlet", so a self-signature could never match. "your gauntlet completion" is
		// also Corrupted-safe: CG's line reads "your corrupted gauntlet completion count".
		{"the gauntlet", "your gauntlet completion", "the gauntlet"},
		{"corrupted gauntlet", "corrupted gauntlet"},
		// Bosses whose kill-count line drops the article ("Your Leviathan kill count is: N"),
		// so a tile named with "The …" would miss on the plain-substring fallback.
		{"the leviathan", "leviathan"},
		{"the whisperer", "whisperer"},
		{"the hueycoatl", "hueycoatl"},
		{"the royal titans", "royal titans"},
		// "nex" is too short for the contains-fallback — "next" in any nearby line would
		// false-match. Pin it to the real kill-count line.
		{"nex", "your nex kill count"},
		// Sailing Barracuda Trials: no chat line ever says "barracuda", so a generic
		// any-trial tile needs the three course names. Tiles naming a specific course
		// ("Gwenith Glide") ride the plain fallback — both flanking lines name it.
		{"barracuda trials|barracuda trial", "tempor tantrum", "jubbly jive", "gwenith glide"},
		// Hallowed Sepulchre full runs: no chat line says "sepulchre" either — the exit
		// message is "Overall time: 26:39.20", which both carries the time and identifies
		// the run. Floor tiles ("Floor 5") ride the fallback against "Floor 5 time: ...".
		{"hallowed sepulchre|sepulchre", "overall time"}
	};

	static {
		for (String[] row : SIGNATURE_TABLE) {
			for (String activity : row[0].split("\\|")) SIGNATURES.put(activity, Arrays.asList(row).subList(1, row.length));
		}
	}

	/** Returns the clear time in whole seconds, or null if the message carries no duration. */
	static Integer parseDurationSeconds(String message) {
		if (message == null) return null;
		var lower = message.toLowerCase();
		// A ToA per-room / per-challenge sub-time — never the raid clear time. Ignore it so a
		// slow raid can't pass a timed tile off a fast final room (see RAID_SUBTIME).
		if (ChatPatterns.find("timed.raid_subtime", lower) != null) return null;
		var m = ChatPatterns.find("timed.duration", lower);
		if (m == null) return null;
		var p = m.group("time").split(":");
		try {
			int s = clockSeconds(p[0], p[1], p.length == 3 ? p[2] : null);
			return s > 0 ? s : null;
		} catch (NumberFormatException e) {
			return null;
		}
	}

	static List<String> signaturesFor(String activity) {
		var a = norm(activity);
		var s = SIGNATURES.get(a);
		if (s != null) return s;
		return a.isEmpty() ? Collections.emptyList() : Collections.singletonList(a);
	}

	/**
	 * Folds the punctuation/spacing admins add inconsistently so an activity string still matches the
	 * game's count line. Colons especially: the game writes CoX Challenge Mode with NO colon, yet
	 * "Chambers of Xeric: Challenge Mode" is the natural way to type it, and ToB/ToA modes DO carry a
	 * colon — dropping it on BOTH sides of the compare makes colons irrelevant either way.
	 */
	static String norm(String s) {
		if (s == null) return "";
		return SPACES.matcher(s.toLowerCase(Locale.ROOT).replace(':', ' ')).replaceAll(" ").trim();
	}

	// A TzHaar-Ket-Rak challenge clear kills TzTok-Jad and mentions the Inferno nearby, so without a
	// veto it reads as a Fight Caves (boss just died) or Inferno clear. Its count line is unique.
	static final String KET_RAK_CLEAR = "your completion count for tzhaar-ket-rak";

	/**
	 * True when the lines around a duration show it belongs to a different activity than
	 * {@code activity} — currently a TzHaar-Ket-Rak challenge, for any non-Ket-Rak tile.
	 */
	static boolean clearBelongsElsewhere(Iterable<String> nearbyLines, String activity) {
		if (norm(activity).contains("tzhaar-ket-rak")) return false;
		for (String line : nearbyLines) {
			if (line != null && line.toLowerCase(Locale.ROOT).contains(KET_RAK_CLEAR)) return true;
		}
		return false;
	}

	/** True when {@code message} contains any of the activity's identifying signatures. */
	static boolean messageMatchesActivity(String message, String activity) {
		if (message == null) return false;
		var nmsg = norm(message);
		// Every signature is already in norm() form: the table is written that way, the fallback is norm()ed.
		for (String sig : signaturesFor(activity)) {
			if (nmsg.contains(sig)) return true;
		}
		return false;
	}

	static String formatClock(int totalSeconds) {
		int mm = totalSeconds / 60;
		int ss = totalSeconds % 60;
		return mm + ":" + (ss < 10 ? "0" + ss : String.valueOf(ss));
	}

	// ── Barracuda Trials (Sailing) rank tiles ──────────────────────────────────────────────────────
	// Each course awards a rank by time, but the three ranks are SEPARATE challenges (different routes,
	// each with its own PB) — so a rank tile must match the EXACT rank the game reports, never a time
	// cap (a Shark run is not just a slow Marlin run). The completion line names both:
	//   "You have completed the Gwenith Glide and achieved the Marlin rank."
	static final String[] TRIAL_COURSES = { "tempor tantrum", "jubbly jive", "gwenith glide" };
	static final String[] TRIAL_RANKS = { "swordfish", "shark", "marlin" };
	// → chat-patterns.json "timed.trial_completion" (ChatPatterns).

	/** {course, rank} from a Barracuda Trials completion line, or null if this line isn't one. */
	static String[] parseTrialCompletion(String message) {
		if (message == null) return null;
		var m = ChatPatterns.find("timed.trial_completion", message.toLowerCase());
		if (m == null) return null;
		var course = norm(m.group("course"));
		var rank = m.group("rank");
		for (String c : TRIAL_COURSES) {
			if (course.endsWith(c)) {
				for (String r : TRIAL_RANKS) {
					if (rank.equals(r)) {
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}

	/** {course, rank} a tile's activity targets (e.g. "Gwenith Glide — Marlin"), or null if it's not a rank tile. */
	static String[] trialTileTarget(String activity) {
		var a = norm(activity);
		if (a.isEmpty()) return null;
		for (String r : TRIAL_RANKS) {
			if (a.endsWith(" " + r)) {
				var course = TRAILING_NON_LETTERS.matcher(a.substring(0, a.length() - r.length())).replaceFirst("");
				for (String c : TRIAL_COURSES) {
					if (course.equals(c) || course.endsWith(c)) {
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}

	/** {@code a:b:c} as h:mm:ss, or {@code a:b} as mm:ss when {@code c} is null. Throws on a non-number. */
	static int clockSeconds(String a, String b, String c) {
		return c != null
			? Integer.parseInt(a) * 3600 + Integer.parseInt(b) * 60 + Integer.parseInt(c)
			: Integer.parseInt(a) * 60 + Integer.parseInt(b);
	}
}

package com.anvil;

import static net.runelite.client.ui.ColorScheme.*;
import java.awt.*;
import java.awt.event.*;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import javax.swing.*;
import net.runelite.client.ui.*;
import javax.swing.event.DocumentEvent;

/**
 * The side panel's shared Swing pieces — the labels, rows, cards and click wiring every view builds
 * the same way, so the sidebar and the card views can't drift apart in how they look.
 */
final class Ui {
	/** A copy of {@code g} that draws antialiased; the caller disposes it. */
	static Graphics2D smooth(Graphics g) {
		var g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return g2;
	}

	/** "...+02:00" at the end of a timestamp. Compiled once: it runs for every row on each paint. */
	static final java.util.regex.Pattern HAS_OFFSET = java.util.regex.Pattern.compile(".*[+-]\\d\\d:\\d\\d$");

	// FontManager hands out the same static instances every call, so holding them changes nothing.
	static final Font SMALL = FontManager.getRunescapeSmallFont();
	static final Font REGULAR = FontManager.getRunescapeFont();
	static final Font BOLD = FontManager.getRunescapeBoldFont();

	/** Secondary text: counts, hints, the quieter half of a row. */
	static final Color MUTED = new Color(0xa8_a8_a8);

	Ui() {
	}

	/**
	 * Neutralize a site-supplied string for Swing. A {@link JLabel}/{@link javax.swing.JToolTip} renders as
	 * HTML when its text begins (ignoring leading whitespace, case-insensitive) with {@code <html}, so an
	 * untrusted clan/tile/activity name could inject markup. Such strings get their markup chars escaped so they
	 * render only as literal text; ordinary strings pass through. An explicit sanitize rather than reliance on
	 * {@code html.disable}; every server-supplied field the panel renders routes through here.
	 *
	 * <p>Use {@link #esc} instead when the string is being placed INSIDE markup we are building: there the
	 * leading-{@code <html} test does not apply and every occurrence has to be escaped.</p>
	 */
	static String plainText(String s) {
		if (s == null) return "";
		s = fontSafe(s);
		int i = 0;
		while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
		return s.regionMatches(true, i, "<html", 0, 5) ? esc(s) : s;
	}

	/**
	 * The RuneScape fonts have no curly quotes or long dashes: on macOS they drew as a box ("You?re").
	 * The site writes proper typography, so it is folded to the plain ASCII the font does have.
	 */
	static String fontSafe(String s) {
		if (s == null) return null;
		return s.replace('\u2019', '\'').replace('\u2018', '\'')
			.replace('\u201C', '"').replace('\u201D', '"')
			.replace('\u2013', '-').replace('\u2014', '-')
			.replace("\u2026", "...");
	}

	/** Escape markup characters for text placed inside HTML we build ourselves. */
	static String esc(String s) {
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** {@code html} wrapped to {@code widthPt} so a long line breaks instead of clipping at the panel's edge. */
	static String wrapHtml(String html, int widthPt) {
		return "<html><body style='width:" + widthPt + "pt'>" + html + "</body></html>";
	}

	/** A label in {@code font} and {@code color}, its text sanitized ({@link #plainText}). */
	static JLabel label(String text, Font font, Color color) {
		JLabel l = new ClipLabel(plainText(text));
		l.setFont(font);
		l.setForeground(color);
		return l;
	}

	static JLabel small(String text, Color color) {
		return label(text, SMALL, color);
	}

	static JLabel title(String text) {
		return label(text, BOLD, Color.WHITE);
	}

	/**
	 * Cap a component's height at what it wants right now, so a vertical BoxLayout stops stretching it.
	 * Call once it's filled — the cap is the preferred height at the time of the call.
	 */
	static <T extends JComponent> T capH(T c) {
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return c;
	}

	static <T extends JComponent> T left(T c) {
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	static final String CLICKS = "anvil.clicks";

	/**
	 * A hand cursor and a left click (a press and a release inside: Swing's mouseClicked drops a click
	 * whose mouse moved a pixel) that runs {@code action}. Its whole tree listens: a label with a tooltip
	 * (every ClipLabel) takes the mouse for itself and Swing doesn't hand the click up. A part inside
	 * with a click of its own keeps it.
	 */
	static <T extends JComponent> T onClick(T c, Runnable action) {
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.putClientProperty(CLICKS, Boolean.TRUE);
		AnvilSidebarPanel.addMouseListenerToTree(c, new MouseAdapter() {
			boolean down;

			@Override
			public void mousePressed(MouseEvent e) {
				down = SwingUtilities.isLeftMouseButton(e) && ownClick(c, e);
			}

			@Override
			public void mouseReleased(MouseEvent e) {
				if (down && SwingUtilities.isLeftMouseButton(e) && c.contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), c))) action.run();
				down = false;
			}
		});
		return c;
	}

	/** Whether the press is {@code c}'s: no clickable part inside it is nearer the pointer. */
	static boolean ownClick(JComponent c, MouseEvent e) {
		for (Component at = e.getComponent(); at != null && at != c; at = at.getParent())
			if (at instanceof JComponent && ((JComponent) at).getClientProperty(CLICKS) != null) return false;
		return true;
	}

	/** Lights up under the mouse and does {@code onClick} — so a row or tile says it can be opened. */
	static void hoverable(JComponent c, Color base, Runnable onClick) {
		c.setOpaque(true);
		c.setBackground(base);
		onClick(c, onClick).addMouseListener(new MouseAdapter() {
			@Override
			public void mouseEntered(MouseEvent e) {
				c.setBackground(DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e) {
				if (c.getMousePosition(true) == null) c.setBackground(base); // into a child is still inside
			}
		});
	}

	/** A left-aligned vertical stack on the panel background. */
	static JPanel column() {
		var p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(DARK_GRAY_COLOR);
		return left(p);
	}

	/** A {@link #column} as a card: the darker surface with an 8px inset. */
	static JPanel block() {
		var p = column();
		p.setBackground(DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return p;
	}

	/** A transparent, left-aligned BorderLayout row with {@code hgap} between its parts. */
	static JPanel row(int hgap) {
		var p = new JPanel(new BorderLayout(hgap, 0));
		p.setOpaque(false);
		return left(p);
	}

	/** {@link #row(int)} on an opaque {@code bg}. */
	static JPanel row(int hgap, Color bg) {
		var p = row(hgap);
		p.setOpaque(true);
		p.setBackground(bg);
		return p;
	}

	static Component gap(int h) {
		return Box.createVerticalStrut(h);
	}

	/** The search fields' look: white text and caret on the darker surface, an orange selection. */
	static void styleSearch(JTextField f) {
		f.setBackground(DARKER_GRAY_COLOR);
		f.setForeground(Color.WHITE);
		f.setCaretColor(Color.WHITE);
		f.setSelectionColor(BRAND_ORANGE);
		f.setSelectedTextColor(Color.BLACK);
		f.setFont(REGULAR);
	}

	/** Runs {@code changed} on every edit of the field's text. */
	static void onEdit(javax.swing.text.JTextComponent f, Runnable changed) {
		f.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
			@Override
			public void insertUpdate(DocumentEvent e) {
				changed.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e) {
				changed.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e) {
				changed.run();
			}
		});
	}

	/** The panel's flat 0–100 progress bar: no text, no border, {@code h} px tall. */
	static JProgressBar bar(int percent, Color fg, Color bg, int h) {
		var bar = new JProgressBar(0, 100);
		bar.setValue(percent);
		bar.setStringPainted(false);
		bar.setBorderPainted(false);
		bar.setForeground(fg);
		bar.setBackground(bg);
		bar.setPreferredSize(new Dimension(0, h));
		return bar;
	}

	/** A transparent, left-aligned grid {@code cols} across. */
	static JPanel grid(int cols, int hgap, int vgap) {
		var grid = left(new JPanel(new GridLayout(0, cols, hgap, vgap)));
		grid.setOpaque(false);
		return grid;
	}

	/** A section's orange name, with an optional white figure at the right. */
	static JPanel header(String left, String right) {
		var row = row(0);
		row.add(small(left, BRAND_ORANGE), BorderLayout.WEST);
		if (right != null) row.add(small(right, Color.WHITE), BorderLayout.EAST);
		return capH(row);
	}

	/** {@code part} of {@code whole} as 0..100, rounded down so a goal never reads as reached before it is. */
	static int percent(long part, long whole) {
		return whole <= 0 ? 0 : (int) Math.max(0, Math.min(100, Math.floor(part * 100.0 / whole)));
	}

	/**
	 * The one way a count is shown, panel and overlays alike: "9,999", "12K", "4.1M", "4.6B" — the game's
	 * own capital suffixes, rounded down so a goal never reads as reached before it is.
	 */
	static String count(long n) {
		if (n < 10_000) return String.format(Locale.ROOT, "%,d", n);
		if (n < 1_000_000) return n / 1000 + "K";
		var b = n >= 1_000_000_000;
		var tenths = n / (b ? 100_000_000 : 100_000);
		return tenths / 10 + (tenths % 10 == 0 ? "" : "." + tenths % 10) + (b ? "B" : "M");
	}

	/** "1 player", "1,204 players". */
	static String plural(long n, String one) {
		return plural(n, one, one + "s");
	}

	static String plural(long n, String one, String many) {
		return String.format(Locale.ROOT, "%,d %s", n, n == 1 ? one : many);
	}

	/** A team's colour; the server stores "#rrggbb", and anything else reads as {@code fallback}. */
	static Color teamColor(String hex, Color fallback) {
		return hex != null && hex.matches("#[0-9a-fA-F]{6}") ? new Color(Integer.parseInt(hex.substring(1), 16)) : fallback;
	}

	/** "3d ago" from either timestamp format the site sends ("2026-10-12 08:00:00" or ISO). */
	static String ago(String at) {
		return ago(at, Instant.now());
	}

	static String ago(String at, Instant now) {
		if (at == null || at.isEmpty()) return "";
		var iso = at.trim().replace(' ', 'T');
		if (!iso.endsWith("Z") && !HAS_OFFSET.matcher(iso).matches()) iso = iso + "Z";
		try {
			var minutes = Math.max(0, Duration.between(Instant.parse(iso), now).toMinutes());
			if (minutes < 60) return minutes <= 1 ? "just now" : minutes + "m ago";
			var hours = minutes / 60;
			if (hours < 24) return hours + "h ago";
			var days = hours / 24;
			if (days < 14) return days + "d ago";
			if (days < 60) return (days / 7) + "w ago";
			if (days < 730) return (days / 30) + "mo ago";
			return (days / 365) + "y ago";
		} catch (DateTimeParseException e) {
			return "";
		}
	}

	/** JTextField has no placeholder API; paint one without putting fake text into the query. */
	static final class SearchField extends JTextField {
		final String placeholder;

		SearchField(String placeholder, String value) {
			super(value == null ? "" : value);
			this.placeholder = placeholder;
			addFocusListener(new FocusAdapter() {
				@Override public void focusGained(FocusEvent e) { repaint(); }
				@Override public void focusLost(FocusEvent e) { repaint(); }
			});
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			super.paintComponent(graphics);
			if (!getText().isEmpty() || isFocusOwner()) return;
			var g = (Graphics2D) graphics.create();
			g.setColor(MUTED);
			g.setFont(getFont());
			var metrics = g.getFontMetrics();
			var insets = getInsets();
			int y = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
			g.drawString(placeholder, insets.left, y);
			g.dispose();
		}
	}

	/**
	 * The server's UTC stamp — ISO ({@code 2026-07-29T12:00:00.000Z}), the space-separated SQLite
	 * {@code yyyy-MM-dd HH:mm:ss} form, or a bare date (midnight UTC) — as epoch millis; -1 if unparseable.
	 */
	static long utcMillis(String ts) {
		var s = ts == null ? "" : ts.trim().replace(' ', 'T');
		try {
			return s.length() == 10
				? LocalDate.parse(s).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli()
				: Instant.parse(s.endsWith("Z") ? s : s + "Z").toEpochMilli();
		} catch (RuntimeException e) {
			return -1;
		}
	}

}

package com.anvil;

import static net.runelite.client.ui.ColorScheme.*;
import lombok.RequiredArgsConstructor;
import com.google.gson.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import net.runelite.api.Skill;
import net.runelite.client.game.*;
import net.runelite.client.hiscore.*;
import net.runelite.client.ui.components.ProgressBar;

import static com.anvil.Ui.*;
import java.awt.image.BufferedImage;
import javax.swing.Timer;

/**
 * A panel view the site built ({@code GET /api/plugin/ui}): the site
 * decides every line, colour and click, and this draws it from a dozen building blocks (site
 * lib/pluginUi/nodes has the shape). Pictures arrive as game ids drawn with RuneLite's own managers —
 * never a URL — and a click is one of the fixed actions in {@link #act}; the ones that reach the site
 * go back to the same route through {@link Host} and nowhere else.
 *
 * <p>One of these per tab body. {@link #show} replaces everything it holds; a {@code slot} inside it
 * can be refilled on its own (a log page, the CA filters, the goals form) without redrawing the rest.
 * Answers that arrive after a newer request for the same place are dropped.</p>
 */

final class UiView extends JPanel {
	/** Where this view's fetches and outward clicks go: the panel. Calls arrive on the EDT. */
	interface Host {
		/** {@code GET /api/plugin/ui?v=view&args}; {@code done} gets the view (null on failure) on the EDT. */
		void load(String view, Map<String, String> args, Consumer<JsonObject> done);

		/** {@code POST /api/plugin/ui}; same answer as {@link #load}. */
		void post(String act, Map<String, String> args, Map<String, String> fields, Consumer<JsonObject> done);

		void site(String path);

		void lookup(String rsn);

		void clan(String slug);

		/** Pin (or unpin) a tile's in-game tracker on this client; tile 0 unpins every tile on the event. */
		void pin(int event, int tile, boolean on);

		/** Point the plugin at another of the member's clans. */
		void switchClan(String slug);

		/** Open one of the panel's own tabs by name ("feed"). Unknown names do nothing. */
		default void openTab(String name, Map<String, String> args) {
		}

		/** A part only the plugin can draw (it reads the game), or null for none. */
		JComponent nativePart(String name);

		/** This client's newest count for a tile (its own progress, the live push's), or -1 for none. */
		/** Give the keyboard back to the game (after a chat line is sent from the panel). */
		default void gameFocus() {
		}

		/** The signed-in character's name, so a live list can mark the viewer's own lines. */
		default String myName() {
			return null;
		}

		default long count(int tile) {
			return -1;
		}

		/** A picture by site path (node {@code img}); motion may be frozen by client preference. */
		default void image(String path, int w, int h, boolean motion, Consumer<Icon> done) {
		}
	}

	/** Toggle faces and section choices outlive a redraw (and the card), like the old virtual-levels switch. */
	static final Map<String, Boolean> FLIPS = new HashMap<>();
	static final Map<String, String> TABS = new HashMap<>();
	static final int WRAP_PT = 170;
	static final Color DONE_DOT = new Color(0x5fd35f);

	final Host host;
	final ItemManager items;
	final SpriteManager sprites;
	final SkillIconManager skills;

	final Map<String, Slot> slots = new HashMap<>();
	final Map<String, List<Runnable>> toggles = new HashMap<>();
	final Map<String, Supplier<String>> inputs = new LinkedHashMap<>();
	/** The last request for each place, for {@link #refresh}. */
	final Map<String, Object[]> lastLoads = new LinkedHashMap<>();
	/** When each warmed load (view and args) was last fetched ahead, so a redraw doesn't ask again. */
	final Map<String, Long> warmed = new HashMap<>();
	/** A clickable part's marker, so the row around it leaves its clicks to it. */
	/** How long after a click a background refresh waits before redrawing. */
	static final long CLICK_SETTLE_MS = 400;
	boolean pressing;
	long pressedAt;
	static final long PRESS_STALE_MS = 2_000;
	static final long WARM_EVERY_MS = 60_000;

	/** What each place last drew, so an unchanged answer leaves it alone (its scroll, its open folds). */
	final Map<String, JsonElement> drawn = new HashMap<>();
	/**
	 * The pane each slot was switched to, kept while the view refreshes so a new answer doesn't throw
	 * the reader back to the first page. Going somewhere (a load, a new view) forgets them.
	 */
	final Map<String, String> openPanes = new HashMap<>();
	/** Countdowns on screen, run once a second while there are any. */
	final List<Runnable> tickers = new ArrayList<>();
	/** The counts on screen that move without asking the site again ({@code live}), see {@link #tickLive}. */
	final List<Runnable> lives = new ArrayList<>();
	final Timer ticker = new Timer(1000, e -> tickers.forEach(Runnable::run));
	/** Live lists on screen (node {@code feed}): push rows find them by id, see {@link #feedPush}. */
	final List<FeedList> feeds = new ArrayList<>();
	/**
	 * The latest request for each place (a slot's id, "null" for the whole view). An answer carrying
	 * any other number is for something no longer there; numbers are never reused.
	 */
	final Map<String, Integer> seq = new HashMap<>();
	int requests;

	@RequiredArgsConstructor
	static final class Slot {
		final JPanel holder;
		final JsonObject panes;
		/** {@code nav}: a pane replaces the page; the panes left keep their build and the row clicked to leave. */
		final String first;
		final Map<String, JComponent> built = new HashMap<>();
		final Map<String, JComponent> from = new HashMap<>();
		Round marked;
	}

	/** The last thing clicked, so a nav slot can mark it when the reader comes back. */
	JComponent lastClicked;
	/** Where each nav pane was scrolled to ("slot:pane"), kept across redraws. */
	final Map<String, Integer> scrolls = new HashMap<>();
	static final Color RAISED = new Color(0x3a3a3a);
	static final Color RAISED_HOVER = new Color(0x474747);

	UiView(Host host, ItemManager items, SpriteManager sprites, SkillIconManager skills) {
		super(new BorderLayout());
		setBackground(DARK_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);
		this.host = host;
		this.items = items;
		this.sprites = sprites;
		this.skills = skills;
	}

	/** Fetch a view and show it in place of everything; {@code waiting} shows meanwhile. */
	void show(String view, Map<String, String> args, String waiting) {
		openPanes.clear();
		if (waiting != null) {
			drawn.remove("null");
			replace(this, message(waiting));
		}
		fetch(null, view, args);
	}

	/**
	 * Ask again for what's on screen — the board moved. Each slot that was loaded since the view was
	 * drawn asks for its latest; with none, the whole view does (nothing typed into it can be lost).
	 * What's drawn stays until the answer lands, then swaps once. False when nothing was loaded yet.
	 */
	boolean refresh() {
		return refresh(false);
	}

	/**
	 * {@code whole}: the page itself asks again (a tile just completed — the race road, "Up next" and
	 * the standings all live on the page, not in a slot). A slot no longer on screen (a nav pane left
	 * behind, Back from a tile's detail) is never what a refresh asks for: it has nowhere to land, and
	 * it used to stand in for the page, so the page stayed stale until something else redrew it.
	 */
	boolean refresh(boolean whole) {
		lastLoads.keySet().removeIf(k -> {
			if ("null".equals(k)) return false;
			var s = slots.get(k);
			return s == null || !SwingUtilities.isDescendingFrom(s.holder, this);
		});
		Map<String, Object[]> loads = new LinkedHashMap<>(lastLoads);
		var root = loads.remove("null");
		if (whole && root != null) {
			fetch(null, (String) root[0], (Map<String, String>) root[1], true);
			return true;
		}
		if (loads.isEmpty() && root != null) fetch(null, (String) root[0], (Map<String, String>) root[1], true);
		loads.forEach((place, l) -> fetch(place, (String) l[0], (Map<String, String>) l[1], true));
		return root != null || !loads.isEmpty();
	}

	/** Force the next answers to rebuild their nodes, even when their JSON is structurally unchanged. */
	void invalidateDrawn() {
		drawn.clear();
	}

	/** Show a line of text in place of everything, dropping any answer still on its way. */
	void say(String text) {
		bump(null);
		drawn.remove("null");
		replace(this, message(text));
	}

	/** Draw a view already in hand. */
	void render(JsonObject view) {
		feeds.forEach(FeedList::stop);
		feeds.clear();
		slots.clear();
		toggles.clear();
		inputs.clear();
		tickers.clear();
		lives.clear();
		drawn.keySet().removeIf(k -> !"null".equals(k));
		// The slots are gone, so whatever they were waiting for is too.
		seq.keySet().removeIf(k -> !"null".equals(k));
		lastLoads.keySet().removeIf(k -> !"null".equals(k));
		replace(this, view == null || !view.has("ui") ? message("Couldn't reach Anvil — try again in a moment.") : node(view.getAsJsonObject("ui")));
		if (tickers.isEmpty()) {
			ticker.stop();
		} else ticker.start();
	}

	/**
	 * Push rows for the live lists ({@code {t:'rows'|'rowsdel'|'rowslock'|'rowsreact', feeds:[…]}}): each list
	 * named takes them; nothing is redrawn. A lock names id prefixes (a board's every chat list).
	 */
	void feedPush(JsonObject m) {
		// A list whose slot was redrawn is no longer under this view: forget it.
		feeds.removeIf(f -> !SwingUtilities.isDescendingFrom(f, this));
		if (feeds.isEmpty() || !m.has("feeds") || !m.get("feeds").isJsonArray()) return;
		Set<String> named = new HashSet<>();
		for (JsonElement e : m.getAsJsonArray("feeds")) named.add(e.getAsString());
		var t = str(m, "t");
		for (FeedList f : feeds) {
			if ("rowslock".equals(t)) {
				if (f.hasBox() && named.stream().anyMatch(p -> f.id.equals(p) || f.id.startsWith(p + ":"))) f.lock(str(m, "locked"), str(m, "sub"), m.has("warn"));
			} else if (!named.contains(f.id)) {
				// Another channel's line: its segment on the chat's switch counts it.
				if ("rows".equals(t) && m.has("rows") && m.get("rows").isJsonArray()) f.bump(named, m.getAsJsonArray("rows").size());
			} else {
				if ("rows".equals(t) && m.has("rows") && m.get("rows").isJsonArray()) {
					f.add(m.getAsJsonArray("rows"));
				} else if ("rowsdel".equals(t) && m.has("ids") && m.get("ids").isJsonArray()) {
					f.remove(m.getAsJsonArray("ids"));
				} else if ("rowsreact".equals(t)) f.reaction(m);
			}
		}
	}

	/** The panel went off screen (or the plugin stopped): no countdowns tick unseen. */
	void stop() {
		ticker.stop();
	}

	/** Back on screen: the countdowns drawn before resume. */
	void resume() {
		if (!tickers.isEmpty()) ticker.start();
	}

	int bump(String place) {
		seq.put(String.valueOf(place), ++requests);
		return requests;
	}

	void fetch(String into, String view, Map<String, String> args) {
		fetch(into, view, args, false);
	}

	/** {@code background}: a refresh nobody clicked for, which waits for a click in progress to finish. */
	void fetch(String into, String view, Map<String, String> args, boolean background) {
		lastLoads.put(String.valueOf(into), new Object[]{view, args});
		int n = bump(into);
		host.load(view, args, v -> land(into, n, v, background));
	}

	/** The slot node with this id inside an answer (not inside panes or other slots' loads), or null. */
	static JsonObject ownSlot(JsonElement e, String id) {
		if (e == null) return null;
		if (e.isJsonArray()) {
			for (JsonElement x : e.getAsJsonArray()) {
				var hit = ownSlot(x, id);
				if (hit != null) return hit;
			}
			return null;
		}
		if (!e.isJsonObject()) return null;
		var o = e.getAsJsonObject();
		if ("slot".equals(str(o, "t")) && id.equals(str(o, "id"))) return o;
		for (Map.Entry<String, JsonElement> kv : o.entrySet()) {
			if (kv.getKey().equals("panes") || kv.getKey().equals("on") || kv.getKey().equals("menu") || kv.getKey().equals("load")) continue;
			var hit = ownSlot(kv.getValue(), id);
			if (hit != null) return hit;
		}
		return null;
	}

	void land(String into, int n, JsonObject answer, boolean background) {
		var view = answer;
		if (seq.getOrDefault(String.valueOf(into), 0) != n) return;
		// A press older than PRESS_STALE_MS is over: a redraw under it can swallow its release, and the
		// flag would otherwise hold every later background refresh off for good.
		var sincePress = System.currentTimeMillis() - pressedAt;
		if (background && ((pressing && sincePress < PRESS_STALE_MS) || sincePress < CLICK_SETTLE_MS)) {
			// Redrawing now would swap the row out from under the press, and the click would be lost.
			var later = new Timer((int) CLICK_SETTLE_MS, e -> land(into, n, answer, true));
			later.setRepeats(false);
			later.start();
			return;
		}
		if (into != null && view != null && view.has("ui") && view.get("ui").isJsonObject()) {
			// A slot only ever takes its own inner content: a whole page answered into it (one that carries
			// this same slot) would stack the page's header again on every answer, so keep just that slot's part.
			var own = ownSlot(view.getAsJsonObject("ui"), into);
			if (own != null && own.has("c") && own.get("c").isJsonObject()) {
				view = view.deepCopy();
				view.add("ui", own.get("c"));
			}
		}
		var ui = view == null ? null : view.get("ui");
		if (ui != null && ui.equals(drawn.get(String.valueOf(into)))) {
			return; // the same answer: leave what's on screen alone
		}
		drawn.put(String.valueOf(into), ui);
		var slot = into == null ? null : slots.get(into);
		if (into == null || slot == null) {
			render(view);
		} else if (slot.first != null && view != null && view.has("ui")) {
			// A page fetched into a nav slot is a page of its own: the pane left is kept for Back.
			var vp = leave(slot, into, "~" + n);
			replace(slot.holder, node(view.getAsJsonObject("ui")));
			if (vp != null) vp.setViewPosition(new Point(0, 0));
		} else replace(slot.holder, view == null || !view.has("ui") ? small("Couldn't reach Anvil — try again in a moment.", MUTED) : node(view.getAsJsonObject("ui")));
	}

	static void replace(JPanel holder, Component c) {
		holder.removeAll();
		holder.add(c, BorderLayout.CENTER);
		holder.revalidate();
		holder.repaint();
	}

	static JPanel message(String text) {
		var p = block();
		JLabel l = small("", MUTED);
		l.setText(wrapHtml(esc(text), WRAP_PT));
		p.add(l);
		return capH(p);
	}

	// ---- Actions -----------------------------------------------------------------------------------

	void act(JsonObject a) {
		var into = str(a, "into");
		switch (str(a, "a")) {
			case "site":
				var path = str(a, "path");
				// A path on the site, never a host: "//" and a backslash ("/\\evil.example") both resolve
				// to another host.
				if (path.startsWith("/") && !path.startsWith("//") && path.indexOf('\\') < 0)
				{
					host.site(path);
				}
				break;
			case "lookup":
				host.lookup(str(a, "rsn"));
				break;
			case "clan":
				host.clan(str(a, "slug"));
				break;
			case "load":
				openPanes.clear();
				if (a.has("open") && a.get("open").isJsonObject()) {
					var open = a.getAsJsonObject("open");
					openPanes.put(str(open, "into"), str(open, "pane"));
				}
				var busy = into.isEmpty() ? null : slots.get(into);
				if (busy != null && busy.first == null) {
					// The click registers at once: the slot says it is loading until the answer lands.
					drawn.remove(into);
					replace(busy.holder, small("Loading…", MUTED));
				}
				fetch(into.isEmpty() ? null : into, str(a, "v"), strings(a.get("args")));
				break;
			case "pane":
				lastLoads.remove(into); // the reader is on a pane now, not on the page last fetched: a refresh must not replay it
				var slot = slots.get(into);
				var pane = slot == null || slot.panes == null ? null : slot.panes.get(str(a, "pane"));
				if (pane != null && pane.isJsonObject() && slot.first != null) {
					go(slot, into, str(a, "pane"), pane.getAsJsonObject());
				} else if (pane != null && pane.isJsonObject()) {
					openPanes.put(into, str(a, "pane"));
					drawn.remove(into);
					replace(slot.holder, node(pane.getAsJsonObject()));
				}
				break;
			case "flip":
				var key = str(a, "key");
				FLIPS.merge(key, true, (x, y) -> !x);
				toggles.getOrDefault(key, Collections.emptyList()).forEach(Runnable::run);
				break;
			case "post":
				Map<String, String> fields = new HashMap<>();
				inputs.forEach((k, v) -> fields.put(k, v.get()));
				if (a.has("ask")) {
					var answer = JOptionPane.showInputDialog(this, plainText(str(a, "ask")), "Anvil", JOptionPane.PLAIN_MESSAGE, null, null, str(a, "askValue"));
					if (answer == null) {
						return; // cancelled
					}
					fields.put("note", answer.toString());
				}
				var place = into.isEmpty() ? null : into;
				int n = bump(place);
				host.post(str(a, "act"), strings(a.get("args")), fields, v -> land(place, n, v, false));
				break;
			case "switch":
				host.switchClan(str(a, "slug"));
				break;
			case "tab":
				// With args: that list on the tab (a board's feed or chat), not the tab's own default.
				host.openTab(str(a, "tab"), strings(a.get("args")));
				break;
			case "pin":
				host.pin(num(a, "event", 0), num(a, "tile", 0), bool(a, "on"));
				if (a.has("then") && a.get("then").isJsonObject()) act(a.getAsJsonObject("then"));
				break;
			default:
				// An action this version doesn't know does nothing.
		}
	}

	/**
	 * A nav slot's pane replaces the page. The pane left keeps its build, its scroll and the row that
	 * was clicked to leave it, so going back lands where the reader was, that row outlined.
	 */
	/** Keeps the pane being left (its build, scroll, clicked row) and names the one entered; returns the viewport. */
	JViewport leave(Slot s, String into, String name) {
		var from = openPanes.getOrDefault(into, s.first);
		var vp = (JViewport) SwingUtilities.getAncestorOfClass(JViewport.class, s.holder);
		if (s.holder.getComponentCount() > 0) s.built.put(from, (JComponent) s.holder.getComponent(0));
		if (lastClicked != null && SwingUtilities.isDescendingFrom(lastClicked, s.holder)) s.from.put(from, lastClicked);
		if (vp != null) scrolls.put(into + ":" + from, vp.getViewPosition().y);
		openPanes.put(into, name);
		return vp;
	}

	void go(Slot s, String into, String name, JsonObject pane) {
		var vp = leave(s, into, name);
		drawn.remove(into);
		var back = s.built.containsKey(name);
		replace(s.holder, back ? s.built.get(name) : node(pane));
		if (s.marked != null) s.marked.edge = (Color) s.marked.getClientProperty("edge");
		var was = s.from.get(name);
		s.marked = back && was instanceof Round ? (Round) was : null;
		if (s.marked != null) {
			s.marked.putClientProperty("edge", s.marked.edge);
			s.marked.edge = BRAND_ORANGE;
			// A brief "you were here", not a stuck focus ring: the outline lets go after a moment.
			var m = s.marked;
			Timer fade = new Timer(1500, e -> {
				if (s.marked != m) return;
				m.edge = (Color) m.getClientProperty("edge");
				s.marked = null;
				m.repaint();
			});
			fade.setRepeats(false);
			fade.start();
		}
		int y = back ? scrolls.getOrDefault(into + ":" + name, 0) : 0;
		if (vp != null) {
			vp.setViewPosition(new Point(0, y));
			SwingUtilities.invokeLater(() -> vp.setViewPosition(new Point(0, y)));
		}
	}

	/** An input's own action: its args plus every input's current value, so a search keeps its filter. */
	void fire(JsonObject on) {
		var a = on.deepCopy();
		var args = a.has("args") && a.get("args").isJsonObject() ? a.getAsJsonObject("args") : new JsonObject();
		inputs.forEach((k, v) -> args.addProperty(k, v.get()));
		a.add("args", args);
		act(a);
	}

	// ---- Nodes -------------------------------------------------------------------------------------

	JComponent node(JsonObject n) {
		JComponent c;
		switch (str(n, "t")) {
			case "col":
				c = col(n);
				break;
			case "row":
				c = row(n);
				break;
			case "grid":
				c = grid(n);
				break;
			case "text":
				c = text(n);
				break;
			case "icon":
				c = icon(n);
				break;
			case "img":
				c = img(n);
				break;
			case "hero":
				c = hero(n);
				break;
			case "bar":
				c = bar(n);
				break;
			case "tabs":
				c = tabs(n);
				break;
			case "fold":
				c = fold(n);
				break;
			case "filter":
				c = filter(n);
				break;
			case "slot":
				c = slot(n);
				break;
			case "toggle":
				c = toggle(n);
				break;
			case "input":
				c = input(n);
				break;
			case "button":
				var on = n.has("on") ? n.getAsJsonObject("on") : new JsonObject();
				JPanel button = AnvilSidebarPanel.fullWidthButton(Ui.plainText(str(n, "label")), tip(n), () -> act(on));
				button.getComponent(0).setEnabled(!bool(n, "off"));
				return left(button);
			case "gap":
				c = (JComponent) gap(num(n, "h", 0));
				break;
			case "countdown":
				c = countdown(n);
				break;
			case "segs":
				c = segs(n);
				break;
			case "step":
				c = step(n);
				break;
			case "warm":
				warm(n.has("on") && n.get("on").isJsonObject() ? n.getAsJsonObject("on") : null);
				return left(new JPanel());
			case "native":
				var part = host.nativePart(str(n, "name"));
				// Left-aligned like every other node: one centred child in a BoxLayout column shifts all
				// of its siblings sideways (an absent start-proof card indented a whole board page).
				return left(part == null ? new JPanel() : part);
			case "feed": {
				var f = new FeedList(n, host, items, sprites, skills, this::act);
				feeds.add(f);
				return left(f);
			}
			default:
				return left(new JPanel()); // a block this version doesn't know is left out
		}
		var tip = tip(n);
		if (tip != null) {
			c.setToolTipText(tip);
			// Swing shows the tooltip of the component under the mouse: a card's picture and text are
			// their own components, so the card's tip only showed in the gaps. They share it now (a
			// child with a tip of its own keeps it).
			inheritTip(c, tip);
		}
		// An input's action fires on a change, not on a click of the box.
		if (n.has("on") && n.get("on").isJsonObject() && !"input".equals(str(n, "t"))) {
			var on = n.getAsJsonObject("on");
			clickable(c, () -> act(on));
		}
		if (n.has("menu") && n.get("menu").isJsonArray()) menu(c, n.getAsJsonArray("menu"));
		return left(c);
	}

	static void inheritTip(Container parent, String tip) {
		for (Component child : parent.getComponents()) {
			if (child instanceof JComponent && ((JComponent) child).getToolTipText() == null) {
				((JComponent) child).setToolTipText(tip);
				inheritTip((JComponent) child, tip);
			}
		}
	}

	List<JComponent> children(JsonObject n, String key) {
		List<JComponent> out = new ArrayList<>();
		if (n.has(key) && n.get(key).isJsonArray()) {
			for (JsonElement e : n.getAsJsonArray(key)) {
				if (e.isJsonObject()) out.add(node(e.getAsJsonObject()));
			}
		}
		return out;
	}

	/**
	 * A col's or row's ground: a rounded card, a raised row ({@code bg:'raised'}), a 1px outline
	 * ({@code edge}), or none. Anything clickable is a {@link Round} so its hover is rounded too.
	 */
	static JPanel surface(JsonObject n, LayoutManager layout, boolean card) {
		var bg = str(n, "bg");
		var edge = color(str(n, "edge"), null);
		var fill = card || "card".equals(bg) ? DARKER_GRAY_COLOR
			: "raised".equals(bg) ? RAISED : "panel".equals(bg) ? DARK_GRAY_COLOR : null;
		if (fill == null && edge == null && !n.has("on")) {
			var p = new JPanel(layout);
			p.setOpaque(false);
			return left(p);
		}
		return left(new Round(layout, card ? num(n, "rad", 6) : 4, fill, edge, "raised".equals(bg) ? RAISED_HOVER : null));
	}

	JComponent col(JsonObject n) {
		var card = bool(n, "card");
		var p = surface(n, null, card);
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		int inset = num(n, "inset", card ? 8 : 0);
		if (inset > 0) p.setBorder(BorderFactory.createEmptyBorder(inset, inset, inset, inset));
		int gap = num(n, "gap", 0);
		for (JComponent c : children(n, "c")) {
			if (gap > 0 && p.getComponentCount() > 0) p.add(gap(gap));
			p.add(c);
		}
		return p;
	}

	JComponent row(JsonObject n) {
		var p = surface(n, new BorderLayout(num(n, "gap", 6), 0), false);
		int pad = num(n, "pad", 0);
		int inset = num(n, "inset", pad);
		p.setBorder(BorderFactory.createEmptyBorder(pad, inset, pad, pad));
		String[][] parts = {{"l", BorderLayout.WEST}, {"c", BorderLayout.CENTER}, {"r", BorderLayout.EAST}};
		for (String[] part : parts) {
			if (n.has(part[0]) && n.get(part[0]).isJsonObject()) p.add(node(n.getAsJsonObject(part[0])), part[1]);
		}
		return capH(p);
	}

	JComponent grid(JsonObject n) {
		var g = Ui.grid(Math.max(1, num(n, "cols", 1)), num(n, "gap", 0), num(n, "vgap", 0));
		children(n, "c").forEach(g::add);
		return g;
	}

	JComponent text(JsonObject n) {
		var s = n.has("at") ? ago(str(n, "at")) : str(n, "s");
		var ink = color(str(n, "color"), Color.WHITE);
		var chip = color(str(n, "chip"), null);
		JLabel l = n.has("grad") && n.get("grad").isJsonArray() ? gradient(n.getAsJsonArray("grad"), ink, bool(n, "move"))
			: chip != null ? new ClipLabel() {
				@Override
				protected void paintComponent(Graphics g) {
					var g2 = smooth(g);
					g2.setColor(chip);
					g2.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
					g2.dispose();
					super.paintComponent(g);
				}
			} : new ClipLabel();
		if (chip != null) l.setBorder(BorderFactory.createEmptyBorder(1, 6, 1, 6));
		l.setFont(font(str(n, "font")));
		l.setForeground(ink);
		var align = str(n, "align");
		l.setHorizontalAlignment("r".equals(align) ? SwingConstants.RIGHT : "c".equals(align) ? SwingConstants.CENTER : SwingConstants.LEADING);
		if (n.has("icon") && n.get("icon").isJsonObject()) {
			var spec = n.getAsJsonObject("icon");
			l.setIconTextGap(4);
			if (bool(n, "iconAfter")) l.setHorizontalTextPosition(SwingConstants.LEADING);
			if (!draw(l, spec) && !str(spec, "alt").isEmpty()) {
				// No picture for it: the name has to carry it, or it's an unlabelled number.
				s = str(spec, "alt") + " " + s;
			} else if (l instanceof GradientLabel && "star".equals(str(spec, "glyph"))) {
				// A supporter's star is part of their name: the gradient runs through it.
				((GradientLabel) l).setTintIcon(true);
			}
		}
		// wrap: true, or the width in pt where the text sits deeper in than a card.
		var wrap = bool(n, "wrap") || num(n, "wrap", 0) > 0;
		int width = num(n, "wrap", 0) > 0 ? num(n, "wrap", 0) : WRAP_PT;
		if (n.has("runs") && n.get("runs").isJsonArray()) {
			// Runs in their own colours (names in team colours), always wrapped.
			var h = new StringBuilder();
			for (JsonElement e : n.getAsJsonArray("runs")) {
				var r = e.getAsJsonObject();
				h.append(String.format("<font color='#%06x'>", color(str(r, "color"), ink).getRGB() & 0xffffff)).append(esc(fontSafe(str(r, "s")))).append("</font>");
			}
			l.setText(wrapHtml(h.toString(), width));
		} else l.setText(wrap ? wrapHtml(esc(s), width) : plainText(s));
		live(n, (v, goal) -> l.setText(liveText(str(n.getAsJsonObject("live"), "fmt"), v, goal)));
		int w = num(n, "w", 0);
		if (w > 0 && chip != null) {
			// A badge: a square that size, its letter centred.
			l.setBorder(null);
			l.setPreferredSize(new Dimension(w, w));
			l.setMaximumSize(new Dimension(w, w));
		} else if (w > 0) l.setPreferredSize(new Dimension(w, l.getPreferredSize().height));
		if (bool(n, "cell")) {
			l.setBorder(BorderFactory.createEmptyBorder(3, 4, 3, 4));
			l.setOpaque(true);
			l.setBackground(DARK_GRAY_COLOR);
		}
		return l;
	}

	/** A Supporter's name: up to four "#rrggbb" stops ({@code move}: sliding); else the plain colour. */
	static JLabel gradient(JsonArray grad, Color fallback, boolean move) {
		List<Color> stops = new ArrayList<>();
		for (JsonElement e : grad) {
			if (stops.size() < 4 && e.isJsonPrimitive()) stops.add(ChatPalette.readableColor(e.getAsString(), false, fallback));
		}
		return stops.size() < 2 ? new ClipLabel() : new GradientLabel(stops.toArray(new Color[0]), move);
	}

	JComponent icon(JsonObject n) {
		var dim = bool(n, "dim");
		JLabel l = new ClipLabel() {
			@Override
			protected void paintComponent(Graphics g) {
				if (!dim) {
					super.paintComponent(g);
					return;
				}
				var g2 = (Graphics2D) g.create();
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.25f));
				super.paintComponent(g2);
				g2.dispose();
			}
		};
		l.setHorizontalAlignment(SwingConstants.CENTER);
		int w = num(n, "w", 0);
		if (w > 0) l.setPreferredSize(new Dimension(w, num(n, "h", w)));
		if (!draw(l, n) && n.has("or") && n.get("or").isJsonObject()) draw(l, n.getAsJsonObject("or"));
		return l;
	}

	/**
	 * A header card: a 56px banner (picture cover-fitted, else the gradient) full-bleed under the card's
	 * rounded top corners; the body starts 18px up over it, so its first row's badge overlaps the edge.
	 */
	JComponent hero(JsonObject n) {
		int bannerH = 74, up = 18; // about 3:1 at panel width, the shape banners are uploaded in
		var b = new JsonObject();
		b.add("c", n.get("c"));
		b.addProperty("gap", 6);
		var body = (JPanel) col(b);
		body.setBorder(BorderFactory.createEmptyBorder(0, 10, 10, 10));
		var pic = new Icon[1];
		var g = n.has("grad") && n.get("grad").isJsonArray() ? n.getAsJsonArray("grad") : null;
		var from = g != null && g.size() > 1 ? color(g.get(0).getAsString(), DARK_GRAY_COLOR) : DARK_GRAY_COLOR;
		var to = g != null && g.size() > 1 ? color(g.get(1).getAsString(), from) : from;
		JComponent strip = new JComponent() {
			@Override
			protected void paintComponent(Graphics gr) {
				var g2 = (Graphics2D) gr.create();
				g2.setPaint(new GradientPaint(0, 0, from, getWidth(), 0, to));
				g2.fillRect(0, 0, getWidth(), getHeight());
				if (pic[0] != null) {
					g2.clipRect(0, 0, getWidth(), getHeight()); // intersect: setClip would drop the card's rounded clip
					// Cover: scale to fill the strip at its real size, crop the overflow (a GIF scales as it plays).
					int iw = Math.max(1, pic[0].getIconWidth()), ih = Math.max(1, pic[0].getIconHeight());
					var k = Math.max((double) getWidth() / iw, (double) getHeight() / ih);
					g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
					g2.translate((getWidth() - iw * k) / 2, (getHeight() - ih * k) / 2);
					g2.scale(k, k);
					pic[0].paintIcon(this, g2, 0, 0);
				}
				g2.dispose();
			}
		};
		if (n.has("src")) {
			host.image(str(n, "src"), 480, 160, bool(n, "motion"), image -> {
				pic[0] = image;
				strip.repaint();
			});
		}
		JPanel card = new JPanel(null) {
			@Override
			protected void paintComponent(Graphics gr) {
				var g2 = smooth(gr);
				g2.setColor(DARKER_GRAY_COLOR);
				g2.fillRoundRect(0, 0, getWidth(), getHeight(), 22, 22);
				g2.dispose();
			}

			@Override
			protected void paintChildren(Graphics gr) {
				var g2 = (Graphics2D) gr.create();
				g2.setClip(new java.awt.geom.RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), 22, 22));
				super.paintChildren(g2);
				g2.dispose();
			}
		};
		card.setOpaque(false);
		card.setLayout(new LayoutManager() {
			@Override public void addLayoutComponent(String name, Component comp) { }
			@Override public void removeLayoutComponent(Component comp) { }
			@Override public Dimension preferredLayoutSize(Container p) { return new Dimension(0, bannerH - up + body.getPreferredSize().height); }
			@Override public Dimension minimumLayoutSize(Container p) { return preferredLayoutSize(p); }
			@Override
			public void layoutContainer(Container p) {
				strip.setBounds(0, 0, p.getWidth(), bannerH);
				body.setBounds(0, bannerH - up, p.getWidth(), p.getHeight() - bannerH + up);
			}
		});
		card.add(body); // first = painted last, over the strip
		card.add(strip);
		return capH(left(card));
	}

	/** A site picture: it takes no room until a valid image has decoded. */
	JComponent img(JsonObject n) {
		int w = Math.max(1, Math.min(240, num(n, "w", 64)));
		int h = Math.max(1, Math.min(240, num(n, "h", 40)));
		var l = new JLabel();
		l.setHorizontalAlignment(SwingConstants.CENTER);
		l.setOpaque(false);
		l.setBackground(DARKER_GRAY_COLOR);
		var d = new Dimension(w, h);
		var empty = new Dimension(0, 0);
		l.setPreferredSize(empty);
		l.setMinimumSize(empty);
		l.setMaximumSize(empty);
		l.setVisible(false);
		host.image(str(n, "src"), w, h, bool(n, "motion"), image -> {
			if (image != null) {
				l.setIcon(bool(n, "round") || num(n, "rad", 0) > 0 ? roundIcon(image, w, h, num(n, "rad", 0)) : image);
				l.setPreferredSize(d);
				l.setMinimumSize(d);
				l.setMaximumSize(d);
				l.setVisible(true);
				growCappedAncestors(l);
				l.revalidate();
			} else {
				// A missing/invalid banner never flashes or leaves a permanent black hole above a card.
				l.setPreferredSize(empty);
				l.setMinimumSize(empty);
				l.setMaximumSize(empty);
				l.setVisible(false);
				l.revalidate();
			}
		});
		return l;
	}

	/**
	 * A row is height-capped ({@link Ui#capH}) when built, while its picture is still hidden at 0x0; once
	 * the picture decodes, lift each capped ancestor to its new preferred height or the icon is cropped
	 * into a squashed sliver.
	 */
	static void growCappedAncestors(Component c) {
		for (Container p = c.getParent(); p instanceof JComponent && !(p instanceof JViewport); p = p.getParent()) {
			var max = p.getMaximumSize();
			int want = p.getPreferredSize().height;
			if (max.width == Integer.MAX_VALUE && max.height < want) ((JComponent) p).setMaximumSize(new Dimension(Integer.MAX_VALUE, want));
		}
	}

	/**
	 * Mask avatars and clan marks to a smooth circle; an animated GifIcon keeps playing through it.
	 * The masked picture is kept and redone only when the GIF moves to another frame (or another
	 * label paints it), so a repaint is one drawImage rather than a fresh buffer and mask each time.
	 */
	static Icon roundIcon(Icon image, int w, int h, int rad) {
		return new Icon() {
			BufferedImage masked;
			int maskedFrame = -1;
			Component maskedFor;

			@Override public int getIconWidth() { return w; }
			@Override public int getIconHeight() { return h; }

			@Override
			public void paintIcon(Component c, Graphics g, int x, int y) {
				int frame = image instanceof GifIcon ? ((GifIcon) image).shownFrame() : 0;
				if (masked == null || frame != maskedFrame || c != maskedFor) {
					if (masked == null) masked = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
					// Clipping a GIF directly leaves a visibly jagged Swing edge. Paint the current frame into
					// a tiny ARGB buffer, then apply an antialiased alpha mask; ImageIcon still advances normally.
					// A DstIn fill only touches pixels inside the shape, so it can't cut the corners away: the
					// frame goes into a buffer and is painted through the shape instead.
					var raw = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
					var rg = raw.createGraphics();
					try {
						image.paintIcon(c, rg, 0, 0); // a GifIcon registers c and repaints it per frame itself
					} finally {
						rg.dispose();
					}
					var copy = masked.createGraphics();
					try {
						copy.setComposite(AlphaComposite.Clear);
						copy.fillRect(0, 0, w, h);
						copy.setComposite(AlphaComposite.SrcOver);
						copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
						copy.setPaint(new TexturePaint(raw, new Rectangle(0, 0, w, h)));
						copy.fill(rad > 0 ? new java.awt.geom.RoundRectangle2D.Float(0, 0, w, h, rad * 2f, rad * 2f) : new java.awt.geom.Ellipse2D.Float(0, 0, w, h));
					} finally {
						copy.dispose();
					}
					maskedFrame = frame;
					maskedFor = c;
				}
				g.drawImage(masked, x, y, null);
			}
		};
	}

	/** Puts {@code spec}'s picture on {@code l}; false when there is none to draw. */
	boolean draw(JLabel l, JsonObject spec) {
		int size = num(spec, "w", 12);
		if ("swatch".equals(str(spec, "glyph"))) {
			l.setIcon(swatch(color(str(spec, "color"), MUTED), size));
			return true;
		}
		var tenure = tenureStep(str(spec, "glyph"));
		if (tenure > 0) {
			// The Supporter tenure badge: the chat's pixel sprite, shaded in the name's colour.
			// The site picks the size: a whole multiple of the 11px art keeps it crisp.
			l.setIcon(new ImageIcon(AnvilPlugin.tenureSprite(tenure, color(str(spec, "color"), Color.WHITE).getRGB() & 0xffffff, -1, Math.max(AnvilPlugin.TENURE_PX, Math.min(39, size)))));
			return true;
		}
		if (spec.has("glyph")) {
			var shape = glyph(str(spec, "glyph"));
			if (shape == null) return false;
			l.setIcon(new GlyphIcon(shape, size, color(str(spec, "color"), MUTED)));
			return true;
		}
		if (spec.has("item") && items != null) {
			int qty = num(spec, "qty", 0);
			items.getImage(num(spec, "item", 0), Math.max(1, qty), qty > 1).addTo(l);
			return true;
		}
		if (spec.has("sprite") && sprites != null) {
			sprites.addSpriteTo(l, num(spec, "sprite", 0), 0);
			return true;
		}
		var skill = spec.has("skill") ? skill(str(spec, "skill")) : null;
		if (skill != null && skills != null) {
			l.setIcon(new ImageIcon(skills.getSkillImage(skill, true)));
			return true;
		}
		if (spec.has("boss")) return bossIcon(l, str(spec, "boss"));
		return false;
	}

	JComponent bar(JsonObject n) {
		int pct = Math.max(0, Math.min(100, num(n, "pct", 0)));
		var bg = "card".equals(str(n, "bg")) ? DARKER_GRAY_COLOR : DARK_GRAY_COLOR;
		var fg = color(str(n, "color"), pct >= 100 ? PROGRESS_COMPLETE_COLOR : BRAND_ORANGE);
		int h = num(n, "h", 3);
		if (n.has("label")) {
			var bar = new ProgressBar();
			bar.setMaximumValue(100);
			bar.setValue(pct);
			bar.setCenterLabel(Ui.plainText(str(n, "label")));
			bar.setLeftLabel("");
			bar.setRightLabel("");
			bar.setForeground(fg);
			bar.setBackground(bg);
			bar.setPreferredSize(new Dimension(0, h));
			bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
			return bar;
		}
		int[] fill = {pct};
		JPanel bar = new JPanel() {
			@Override
			protected void paintComponent(Graphics g) {
				g.setColor(bg);
				g.fillRect(0, 0, getWidth(), getHeight());
				g.setColor(fg);
				g.fillRect(0, 0, getWidth() * fill[0] / 100, getHeight());
			}
		};
		live(n, (v, goal) -> {
			fill[0] = percent(v, goal);
			bar.repaint();
		});
		bar.setPreferredSize(new Dimension(0, h));
		return capH(bar);
	}

	/** A bar in segments, one colour each (a race's steps: done, here, still to come). */
	static JComponent segs(JsonObject n) {
		List<Color> cs = new ArrayList<>();
		if (n.has("c") && n.get("c").isJsonArray()) for (JsonElement e : n.getAsJsonArray("c")) cs.add(color(e.getAsString(), MUTED));
		int h = num(n, "h", 6);
		JPanel bar = new JPanel() {
			@Override
			protected void paintComponent(Graphics g) {
				var g2 = smooth(g);
				int k = cs.size();
				var w = (getWidth() - 3f * (k - 1)) / Math.max(1, k);
				for (int i = 0; i < k; i++) {
					g2.setColor(cs.get(i));
					g2.fillRoundRect(Math.round(i * (w + 3)), 0, Math.round(w), h, 4, 4);
				}
				g2.dispose();
			}
		};
		bar.setOpaque(false);
		bar.setPreferredSize(new Dimension(0, h));
		return capH(bar);
	}

	/**
	 * One stop on a vertical track: a dot ({@code done} ticked green, {@code now} gold with a glow,
	 * {@code end} a gold ring, else a hollow ring), a {@code line} down to the next stop in that colour
	 * (none on the last), and the stop's content beside it.
	 */
	JComponent step(JsonObject n) {
		var dot = str(n, "dot");
		var line = color(str(n, "line"), null);
		JPanel gutter = new JPanel() {
			@Override
			protected void paintComponent(Graphics g) {
				var g2 = smooth(g);
				int x = 3, y = 3;
				if (line != null) {
					g2.setColor(line);
					g2.fillRect(x + 5, y + 12, 2, getHeight() - y - 12);
				}
				g2.setStroke(new BasicStroke(2f));
				var gold = BRAND_ORANGE;
				if ("done".equals(dot)) {
					g2.setColor(DONE_DOT);
					g2.fillOval(x, y, 12, 12);
					g2.setColor(DARKER_GRAY_COLOR);
					g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g2.drawPolyline(new int[]{x + 3, x + 5, x + 9}, new int[]{y + 6, y + 8, y + 4}, 3);
				} else if ("now".equals(dot)) {
					g2.setColor(new Color(gold.getRed(), gold.getGreen(), gold.getBlue(), 64));
					g2.fillOval(x - 3, y - 3, 18, 18);
					g2.setColor(gold);
					g2.fillOval(x, y, 12, 12);
				} else if ("end".equals(dot)) {
					g2.setColor(RAISED);
					g2.fillOval(x, y, 12, 12);
					g2.setColor(gold);
					g2.drawOval(x + 1, y + 1, 10, 10);
				} else {
					g2.setColor(new Color(0x666666));
					if ("lock".equals(dot)) { // not reached yet: a small padlock
						g2.setStroke(new BasicStroke(1.4f));
						g2.drawArc(x + 3, y, 6, 7, 0, 180);
						g2.fillRoundRect(x + 2, y + 5, 8, 7, 2, 2);
					} else g2.drawOval(x + 2, y + 2, 8, 8);
				}
				g2.dispose();
			}
		};
		gutter.setOpaque(false);
		gutter.setPreferredSize(new Dimension(18, 18));
		var body = new JPanel(new BorderLayout());
		body.setOpaque(false);
		body.setBorder(BorderFactory.createEmptyBorder(0, 0, line != null ? 8 : 0, 0));
		if (n.has("c") && n.get("c").isJsonObject()) body.add(node(n.getAsJsonObject("c")), BorderLayout.CENTER);
		var p = new Round(new BorderLayout(6, 0), 4, null, null, null);
		p.add(gutter, BorderLayout.WEST);
		p.add(body, BorderLayout.CENTER);
		return capH(left(p));
	}

	/**
	 * The section switcher: one body at a time, built when first picked, so a section that fetches
	 * (CAs) fetches only once someone opens it. Not a CardLayout: the sprites arrive after it would
	 * have measured, and the last row got cut off.
	 */
	JComponent tabs(JsonObject n) {
		var key = str(n, "key");
		var list = n.has("tabs") ? n.getAsJsonArray("tabs") : new JsonArray();
		if (list.size() == 0) return new JPanel();
		// A tab with {@code on} and no body is a link (Feed | Chat): picking it runs the action, and the
		// one marked {@code sel} is lit.
		Map<String, JsonObject> bodies = new LinkedHashMap<>();
		Map<String, JsonObject> links = new HashMap<>();
		var wanted = TABS.getOrDefault(key, str(n, "open"));
		for (JsonElement e : list) {
			var t = e.getAsJsonObject();
			var label = str(t, "label");
			bodies.put(label, t.has("c") ? t.getAsJsonObject("c") : null);
			if (t.has("on") && !t.has("c")) links.put(label, t.getAsJsonObject("on"));
			if (bool(t, "sel")) wanted = label;
		}
		var first = bodies.containsKey(wanted) ? wanted : bodies.keySet().iterator().next();
		var wrap = column();
		var body = Ui.row(0);
		Map<String, JComponent> built = new HashMap<>();
		Consumer<String> open = name -> {
			if (bodies.get(name) != null) replace(body, built.computeIfAbsent(name, k -> node(bodies.get(k))));
		};
		wrap.add(segments(new ArrayList<>(bodies.keySet()), first, name -> {
			if (links.containsKey(name)) {
				act(links.get(name));
				return;
			}
			TABS.put(key, name);
			open.accept(name);
		}));
		open.accept(first);
		if (links.size() < bodies.size()) {
			wrap.add(gap(4));
			wrap.add(body);
		}
		return wrap;
	}

	/** A segmented switch: a dark rounded track, the picked segment raised with an orange underline. */
	static JComponent segments(List<String> labels, String first, Consumer<String> picked) {
		var strip = new Round(new GridLayout(1, labels.size(), 2, 0), 4, DARKER_GRAY_COLOR, null, null);
		strip.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		left(strip);
		Map<String, Round> segs = new LinkedHashMap<>();
		Consumer<String> paint = name -> segs.forEach((k, seg) -> {
			var on = k.equals(name);
			seg.setOpaque(on);
			var l = (JLabel) seg.getComponent(0);
			l.setForeground(on ? Color.WHITE : MUTED);
			l.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 2, 0, on ? BRAND_ORANGE : new Color(0, 0, 0, 0)),
				BorderFactory.createEmptyBorder(3, 2, 2, 2)));
			seg.repaint();
		});
		for (String name : labels) {
			var seg = new Round(new BorderLayout(), 3, RAISED, null, null);
			JLabel l = new ClipLabel(plainText(name), SwingConstants.CENTER);
			l.setFont(SMALL);
			seg.add(l, BorderLayout.CENTER);
			onClick(seg, () -> {
				paint.accept(name);
				picked.accept(name);
			});
			segs.put(name, seg);
			strip.add(seg);
		}
		paint.accept(first);
		return capH(strip);
	}

	JComponent fold(JsonObject n) {
		var wrap = column();
		wrap.setOpaque(false);
		var head = Ui.row(5);
		head.add(node(n.getAsJsonObject("head")), BorderLayout.CENTER);
		JLabel chevron = new ClipLabel();
		head.add(chevron, BorderLayout.EAST);
		var body = node(n.getAsJsonObject("c"));
		var chev = bool(n, "chev");
		Runnable paint = () -> chevron.setIcon(chev
			? new GlyphIcon(body.isVisible() ? GlyphIcon.Shape.CHEVRON_LEFT : GlyphIcon.Shape.CHEVRON_RIGHT, 8, MUTED) : null);
		body.setVisible(bool(n, "open"));
		paint.run();
		clickable(capH(head), () -> {
			body.setVisible(!body.isVisible());
			paint.run();
			wrap.revalidate();
			wrap.repaint();
		});
		wrap.add(head);
		wrap.add(body);
		return wrap;
	}

	/**
	 * A search box over the rows of its children (a grid's cells, a column's rows). Each row is found
	 * by its {@code k}, else its own text; a {@code q} row shows only while something is typed.
	 */
	JComponent filter(JsonObject n) {
		var wrap = column();
		wrap.setOpaque(false);
		var none = small(str(n, "none"), MUTED);
		none.setVisible(false);
		var more = small(str(n, "more"), MUTED);
		more.setVisible(false);
		int max = num(n, "max", Integer.MAX_VALUE);
		List<Runnable> refills = new ArrayList<>();
		String[] query = {""};
		int[] shown = {0};

		var lists = column();
		lists.setOpaque(false);
		for (JsonElement e : n.has("c") ? n.getAsJsonArray("c") : new JsonArray()) {
			var list = e.getAsJsonObject();
			var box = node(list);
			List<Component> rows = new ArrayList<>(Arrays.asList(box.getComponents()));
			var specs = list.has("c") ? list.getAsJsonArray("c") : new JsonArray();
			if (rows.size() != specs.size()) {
				lists.add(box); // a list with gaps or extras between rows isn't searched
				continue;
			}
			refills.add(() -> {
				box.removeAll();
				for (int i = 0; i < rows.size(); i++) {
					var spec = specs.get(i).getAsJsonObject();
					var typed = !query[0].isEmpty();
					if ((!bool(spec, "q") || typed) && matches(query[0], spec.has("k") ? str(spec, "k") : words(spec)) && shown[0] < max) {
						box.add(rows.get(i));
						shown[0]++;
					}
				}
				box.revalidate();
				box.repaint();
			});
			lists.add(box);
		}
		Runnable refill = () -> {
			shown[0] = 0;
			refills.forEach(Runnable::run);
			none.setVisible(shown[0] == 0 && !refills.isEmpty());
			more.setVisible(shown[0] >= max);
		};
		refill.run();
		if (bool(n, "box")) {
			var search = new SearchField(str(n, "hint"), "");
			styleSearch(search);
			search.setFont(SMALL);
			search.setBackground(DARK_GRAY_COLOR);
			search.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			onEdit(search, () -> {
				query[0] = search.getText().trim();
				refill.run();
				wrap.revalidate();
				wrap.repaint();
			});
			wrap.add(capH(left(search)));
			wrap.add(gap(6));
		}
		wrap.add(none);
		wrap.add(lists);
		wrap.add(more);
		return wrap;
	}

	/**
	 * A search box that asks again as the member pauses typing (or presses Enter), its action carrying
	 * every input's value. The results belong in a slot, so the box itself — and its caret — stays put.
	 */
	JComponent search(JsonObject n, String name, String value) {
		var field = new SearchField(str(n, "label"), value);
		styleSearch(field);
		field.setFont(SMALL);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(0x47_47_47)), BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		inputs.put(name, () -> field.getText().trim());
		var on = n.has("on") && n.get("on").isJsonObject() ? n.getAsJsonObject("on") : null;
		if (on != null) {
			var pause = new Timer(350, e -> fire(on));
			pause.setRepeats(false);
			onEdit(field, pause::restart);
			field.addActionListener(e -> {
				pause.stop();
				fire(on);
			});
		}
		return capH(field);
	}

	/**
	 * Redraw every {@code live} count from what this client now knows: its own progress the moment it
	 * happens, a teammate's from the live push. A count only ever moves up from the site's {@code cur}.
	 */
	void tickLive() {
		lives.forEach(Runnable::run);
	}

	void live(JsonObject n, BiConsumer<Long, Long> show) {
		if (!n.has("live") || !n.get("live").isJsonObject()) return;
		var live = n.getAsJsonObject("live");
		int tile = num(live, "tile", 0);
		var cur = live.has("cur") ? live.get("cur").getAsLong() : 0;
		var goal = live.has("goal") ? live.get("goal").getAsLong() : 0;
		long[] shown = {cur};
		lives.add(() -> {
			// Never past the goal: a local count can run ahead of the site (a jump in KC, a lab
			// session's held-back pushes), and "810 / 10" says nothing a full bar doesn't.
			var v = Math.max(cur, host.count(tile));
			if (goal > 0) v = Math.min(v, goal);
			if (v != shown[0]) {
				shown[0] = v;
				show.accept(v, goal);
			}
		});
	}

	/** A live count as the site words it (lib/pluginUi/nodes {@code Live}): of, raw, pct or near. */
	static String liveText(String fmt, long v, long goal) {
		var pct = percent(v, goal) + "%";
		var raw = v + " / " + goal;
		switch (fmt) {
			case "pct":
				return pct;
			case "raw":
				return raw;
			case "near":
				return goal >= 100_000 ? pct : raw;
			default:
				return Ui.count(v) + " / " + Ui.count(goal);
		}
	}

	/** Fetch a load ahead of its click; the host keeps the answer, so the click draws it at once. */
	void warm(JsonObject on) {
		if (on == null || !"load".equals(str(on, "a"))) return;
		var key = str(on, "v") + on.get("args");
		var now = System.currentTimeMillis();
		var last = warmed.get(key);
		if (last == null || now - last >= WARM_EVERY_MS) {
			warmed.put(key, now);
			host.load(str(on, "v"), strings(on.get("args")), v -> { });
		}
	}

	JComponent slot(JsonObject n) {
		var holder = Ui.row(0);
		var id = str(n, "id");
		var panes = n.has("panes") && n.get("panes").isJsonObject() ? n.getAsJsonObject("panes") : null;
		// nav: the slot is a page of its own; `open` names the pane it shows first (no `c` needed).
		var first = bool(n, "nav") ? str(n, "open") : null;
		slots.put(id, new Slot(holder, panes, first));
		var want = openPanes.containsKey(id) ? openPanes.get(id) : first;
		var open = panes == null || want == null ? null : panes.get(want);
		if (open == null && first != null && panes != null) open = panes.get(first); // a pane that was a loaded page: back to the first
		holder.add(node(open != null && open.isJsonObject() ? open.getAsJsonObject() : n.getAsJsonObject("c")), BorderLayout.CENTER);
		if (n.has("load") && n.get("load").isJsonObject()) {
			var load = n.getAsJsonObject("load");
			drawn.remove(id); // a new slot shows its placeholder: whatever answer comes must replace it
			fetch(id, str(load, "v"), strings(load.get("args")));
		}
		return holder;
	}

	JComponent toggle(JsonObject n) {
		var holder = Ui.row(0);
		var key = str(n, "key");
		Runnable paint = () -> replace(holder, node(n.getAsJsonObject(FLIPS.getOrDefault(key, false) ? "lit" : "off")));
		toggles.computeIfAbsent(key, k -> new ArrayList<>()).add(paint);
		paint.run();
		return holder;
	}

	JComponent input(JsonObject n) {
		var name = str(n, "name");
		var value = str(n, "value");
		switch (str(n, "kind")) {
			case "select":
				List<String[]> options = new ArrayList<>();
				for (JsonElement e : n.has("options") ? n.getAsJsonArray("options") : new JsonArray()) {
					options.add(new String[]{str(e.getAsJsonObject(), "v"), plainText(str(e.getAsJsonObject(), "label"))});
				}
				JComboBox<String> combo = new JComboBox<>(options.stream().map(o -> o[1]).toArray(String[]::new));
				AnvilSidebarPanel.styleCombo(combo);
				for (int i = 0; i < options.size(); i++) {
					if (options.get(i)[0].equals(value)) combo.setSelectedIndex(i);
				}
				inputs.put(name, () -> combo.getSelectedIndex() < 0 ? "" : options.get(combo.getSelectedIndex())[0]);
				if (n.has("on") && n.get("on").isJsonObject()) {
					var on = n.getAsJsonObject("on");
					combo.addActionListener(e -> fire(on));
				}
				// The widest option must not set the panel's width: the combo takes the row it's given.
				combo.setPrototypeDisplayValue("");
				combo.setPreferredSize(new Dimension(40, combo.getPreferredSize().height));
				combo.setMinimumSize(new Dimension(0, combo.getPreferredSize().height));
				return capH(combo);
			case "search":
				return search(n, name, value);
			case "number":
				int min = num(n, "min", 0);
				int max = num(n, "max", Integer.MAX_VALUE);
				int start = Math.max(min, Math.min(max, parseInt(value, min)));
				var spinner = new JSpinner(new SpinnerNumberModel(start, min, max, Math.max(1, num(n, "step", 1))));
				spinner.setFont(SMALL);
				JTextField field = ((JSpinner.DefaultEditor) spinner.getEditor()).getTextField();
				field.setBackground(DARKER_GRAY_COLOR);
				field.setForeground(Color.WHITE);
				field.setCaretColor(Color.WHITE);
				inputs.put(name, () -> String.valueOf(spinner.getValue()));
				var row = Ui.row(6);
				row.add(small(str(n, "label"), MUTED), BorderLayout.WEST);
				row.add(spinner, BorderLayout.CENTER);
				return capH(row);
			case "check":
				var check = new JCheckBox(plainText(str(n, "label")), "1".equals(value));
				check.setFont(SMALL);
				check.setOpaque(false);
				inputs.put(name, () -> check.isSelected() ? "1" : "");
				return check;
			default:
				return new JPanel();
		}
	}

	// ---- Pieces ------------------------------------------------------------------------------------

	/** "Next mission in 12:34", moving every second; {@code due} once it's reached, {@code none} with no clock. */
	JComponent countdown(JsonObject n) {
		JLabel l = label("", font(str(n, "font")), color(str(n, "color"), Color.WHITE));
		var at = utcMillis(str(n, "at"));
		Runnable paint = () -> {
			if (at < 0) {
				l.setText(plainText(str(n, "none")));
				return;
			}
			var secs = Math.max(0, (at - System.currentTimeMillis()) / 1000);
			// Past a day, "4d 4h" — "100:15:48" reads as a clock, not as four days.
			var clock = secs >= 86400
				? String.format(Locale.ROOT, "%dd %dh", secs / 86400, secs % 86400 / 3600)
				: secs >= 3600
				? String.format(Locale.ROOT, "%d:%02d:%02d", secs / 3600, secs % 3600 / 60, secs % 60)
				: String.format(Locale.ROOT, "%d:%02d", secs / 60, secs % 60);
			l.setText(plainText(secs == 0 ? str(n, "due") : str(n, "prefix") + clock));
		};
		paint.run();
		if (at >= 0) tickers.add(paint);
		return l;
	}

	/** A right-click menu on {@code c} and everything in it (Swing doesn't bubble a click up from a label). */
	void menu(JComponent c, JsonArray items) {
		MouseAdapter popup = new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				show(e);
			}

			@Override
			public void mouseReleased(MouseEvent e) {
				show(e);
			}

			void show(MouseEvent e) {
				if (!e.isPopupTrigger()) return;
				var menu = new JPopupMenu();
				for (JsonElement el : items) {
					var item = el.getAsJsonObject();
					var mi = new JMenuItem(plainText(str(item, "label")));
					if (item.has("on") && item.get("on").isJsonObject()) {
						var on = item.getAsJsonObject("on");
						mi.addActionListener(ev -> act(on));
					} else mi.setEnabled(false);
					menu.add(mi);
				}
				menu.show(e.getComponent(), e.getX(), e.getY());
			}
		};
		AnvilSidebarPanel.addMouseListenerToTree(c, popup);
	}

	/**
	 * Lights up under the mouse and runs {@code action} on a left click ({@link Ui#onClick}), noting the
	 * press so a background refresh waits for it.
	 */
	void clickable(JComponent c, Runnable action) {
		var opaque = c instanceof Round ? ((Round) c).filled() : c.isOpaque();
		var base = c.getBackground();
		var hover = c instanceof Round && ((Round) c).hover != null ? ((Round) c).hover : DARK_GRAY_HOVER_COLOR;
		AnvilSidebarPanel.addMouseListenerToTree(c, new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				if (SwingUtilities.isLeftMouseButton(e) && Ui.ownClick(c, e)) pressing = true;
			}

			@Override
			public void mouseReleased(MouseEvent e) {
				pressing = false;
				pressedAt = System.currentTimeMillis();
			}

			@Override
			public void mouseEntered(MouseEvent e) {
				c.setOpaque(true);
				c.setBackground(hover);
				c.repaint();
			}

			@Override
			public void mouseExited(MouseEvent e) {
				if (c.getMousePosition(true) == null) // into a child is still inside
				{
					c.setOpaque(opaque);
					c.setBackground(base);
					c.repaint();
				}
			}
		});
		Ui.onClick(c, () -> {
			lastClicked = c;
			action.run();
		});
	}

	static String tip(JsonObject n) {
		var tip = str(n, "tip");
		return tip.isEmpty() ? null : wrapHtml(esc(tip).replace("\n", "<br>"), 180);
	}

	static Font font(String f) {
		return "bold".equals(f) ? BOLD : "regular".equals(f) ? REGULAR : SMALL;
	}

	static Color color(String c, Color fallback) {
		switch (c) {
			case "white":
				return Color.WHITE;
			case "text":
				return TEXT_COLOR;
			case "muted":
				return MUTED;
			case "brand":
				return BRAND_ORANGE;
			case "done":
				return PROGRESS_COMPLETE_COLOR;
			case "error":
				return PROGRESS_ERROR_COLOR;
			case "claim":
				return new Color(0x7D_C4_F0);
			case "progress":
				return PROGRESS_INPROGRESS_COLOR;
			default:
				return teamColor(c, fallback);
		}
	}

	/** A team's colour as a square. */
	static Icon swatch(Color c, int size) {
		return new Icon() {
			@Override
			public void paintIcon(Component comp, Graphics g, int x, int y) {
				g.setColor(c);
				g.fillRect(x, y, size, size);
			}

			@Override
			public int getIconWidth() {
				return size;
			}

			@Override
			public int getIconHeight() {
				return size;
			}
		};
	}

	/** "tenure-1".."tenure-6" (a Supporter's tenure badge), else 0. */
	static int tenureStep(String g) {
		return g != null && g.length() == 8 && g.startsWith("tenure-") && g.charAt(7) >= '1' && g.charAt(7) <= '6' ? g.charAt(7) - '0' : 0;
	}

	static GlyphIcon.Shape glyph(String g) {
		switch (g) {
			case "check":
				return GlyphIcon.Shape.CHECK;
			case "chevron-right":
				return GlyphIcon.Shape.CHEVRON_RIGHT;
			case "chevron-left":
				return GlyphIcon.Shape.CHEVRON_LEFT;
			case "external":
				return GlyphIcon.Shape.EXTERNAL;
			case "close":
				return GlyphIcon.Shape.CLOSE;
			case "star":
				return GlyphIcon.Shape.STAR;
			case "up":
				return GlyphIcon.Shape.UP;
			case "down":
				return GlyphIcon.Shape.DOWN;
			default:
				return null;
		}
	}

	static Skill skill(String key) {
		for (Skill s : Skill.values()) {
			if (s.name().equalsIgnoreCase(key)) return s;
		}
		return null;
	}

	/** Every text in {@code n}, for a row a filter searches without a {@code k}. */
	static String words(JsonObject n) {
		var sb = new StringBuilder(str(n, "s")).append(' ').append(str(n, "alt"));
		for (Map.Entry<String, JsonElement> e : n.entrySet()) {
			if (e.getValue().isJsonObject()) {
				sb.append(' ').append(words(e.getValue().getAsJsonObject()));
			} else if (e.getValue().isJsonArray()) {
				for (JsonElement x : e.getValue().getAsJsonArray()) {
					if (x.isJsonObject()) sb.append(' ').append(words(x.getAsJsonObject()));
				}
			}
		}
		return sb.toString();
	}

	/** Every word of the query somewhere in the name, case and punctuation aside ("kril" finds K'ril). */
	static boolean matches(String query, String name) {
		var n = fold(SearchAliases.augment(name));
		for (String word : query.split("\\s+")) {
			if (!n.contains(fold(word))) return false;
		}
		return true;
	}

	static String fold(String s) {
		return s == null ? "" : s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	static String str(JsonObject o, String key) {
		var e = o == null ? null : o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : "";
	}

	static int num(JsonObject o, String key, int fallback) {
		var e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() ? e.getAsInt() : fallback;
	}

	static boolean bool(JsonObject o, String key) {
		var e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	static int parseInt(String s, int fallback) {
		try {
			return Integer.parseInt(s);
		} catch (NumberFormatException e) {
			return fallback;
		}
	}

	static Map<String, String> strings(JsonElement e) {
		Map<String, String> out = new LinkedHashMap<>();
		if (e != null && e.isJsonObject()) {
			for (Map.Entry<String, JsonElement> x : e.getAsJsonObject().entrySet()) {
				if (x.getValue().isJsonPrimitive()) out.put(x.getKey(), x.getValue().getAsString());
			}
		}
		return out;
	}

	// ---- The game's picture for a boss --------------------------------------------------------------

	/**
	 * RuneLite's hiscore entry for a boss or activity the site names. The site's key
	 * ("alchemicalHydra") and RuneLite's enum (ALCHEMICAL_HYDRA) fold to the same letters; the label
	 * catches the rest, and a prefix catches renames like "barrows" → BARROWS_CHESTS.
	 */
	static HiscoreSkill hiscoreSkill(String key) {
		// The site says "cluesBeginner", RuneLite says CLUE_SCROLL_BEGINNER.
		var k = fold(key).replaceFirst("^clues", "cluescroll");
		if (k.isEmpty()) return null;
		HiscoreSkill best = null;
		int bestLen = 0;
		for (HiscoreSkill s : HiscoreSkill.values()) {
			var e = fold(s.name());
			if (e.equals(k) || fold(s.getName()).equals(k) || e.equals("the" + k)) return s;
			// RuneLite says more than we do (barrows ↔ BARROWS_CHESTS) or less (…ExpertMode ↔ …_EXPERT);
			// longest match wins, so the expert raid doesn't settle for the plain one.
			var fits = e.startsWith(k) || (e.length() >= 6 && k.startsWith(e));
			if (fits && e.length() > bestLen) {
				best = s;
				bestLen = e.length();
			}
		}
		if (best != null) return best;
		// A personal best's name: a boss whose name it contains ("Demonic Brutus" → Brutus).
		for (HiscoreSkill s : HiscoreSkill.values()) {
			var n = fold(s.getName());
			if (n.length() >= 4 && k.contains(n) && (best == null || n.length() > fold(best.getName()).length())) best = s;
		}
		return best;
	}

	/** A boss's sprite, else a skill it names (agility courses, "99 Attack"); false when neither. */
	boolean bossIcon(JLabel l, String name) {
		var boss = hiscoreSkill(name);
		if (boss != null && boss.getSpriteId() > 0 && sprites != null) {
			sprites.addSpriteTo(l, boss.getSpriteId(), 0);
			return true;
		}
		if (skills != null) {
			for (Skill s : Skill.values()) {
				if (name.toLowerCase(Locale.ROOT).contains(s.getName().toLowerCase(Locale.ROOT))) {
					l.setIcon(new ImageIcon(skills.getSkillImage(s, true)));
					return true;
				}
			}
		}
		return false;
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import java.util.*;

/**
 * Where an account sits in a boss's vestige rotation.
 *
 * <p>The DT2 bosses don't hand out their vestige at random: rolls of the unique table go
 * non-vestige, non-vestige, VESTIGE. So counting uniques since the last vestige tells a player
 * something they can act on — "that's roll 2, the next unique is the vestige" — which is worth far
 * more than another "you got a Virtus mask" line. The roll tables themselves (which items count,
 * which one is the vestige, how long the cycle is) come from the server, so a game change is an
 * edit there rather than a plugin release.
 *
 * <p>Honesty about what we can know: the cycle is account state on Jagex's side, and this plugin
 * only sees drops it was running for. A count is therefore ESTIMATED until a vestige is actually
 * observed — after that the cycle is anchored and the count is EXACT. The estimate is still worth
 * showing (it's right whenever the player has been running the plugin), it just says so.
 *
 * <p>RuneLite-free so it can be unit-tested; {@link AnvilPlugin} owns persistence.
 */
final class VestigeRolls {
	/** One boss's cycle state. */
	@RequiredArgsConstructor
	static final class State {
		/** Rolls seen since the last vestige — 0 means "a vestige is 3 rolls away". */
		final int rolls;
		/** True once a vestige has been observed, which anchors the cycle. */
		final boolean exact;
	}

	/** What a drop did to the cycle, and what to say about it. */
	@RequiredArgsConstructor
	static final class Result {
		final State state;
		/** True when this drop WAS the vestige. */
		final boolean vestige;
		/** True when the next unique from this boss is guaranteed to be the vestige. */
		final boolean vestigeNext;
		/** One line for chat and the drop post, or null when there's nothing worth saying. */
		final String line;
	}

	final Map<String, State> byBoss = new HashMap<>();

	static String key(String boss) {
		return boss == null ? "" : boss.trim().toLowerCase(Locale.ROOT);
	}

	State get(String boss) {
		return byBoss.getOrDefault(key(boss), new State(0, false));
	}

	void put(String boss, State state) {
		byBoss.put(key(boss), state);
	}

	/**
	 * Fold one unique-table drop into the boss's cycle. Returns null when the item isn't part of
	 * this boss's roll table (nothing to count) or the table is unusable.
	 */
	Result record(PluginConfigResponse.RollTable table, int itemId) {
		if (table == null || table.rollItemIds == null || !table.rollItemIds.contains(itemId)) return null;
		int cycle = Math.max(2, table.rollsPerVestige);
		var was = get(table.boss);
		var r = advance(was, itemId == table.vestigeItemId, cycle, table.vestigeName);
		put(table.boss, r.state);
		return r;
	}

	/**
	 * The rule, in one place: a vestige resets the cycle and anchors it; anything else advances it.
	 * A non-vestige arriving where the vestige was due means our count was off (drops taken while
	 * the plugin wasn't watching) — start the cycle over from this drop and stop claiming exact.
	 */
	static Result advance(State was, boolean isVestige, int rollsPerVestige, String vestigeName) {
		var vestige = vestigeName == null || vestigeName.isEmpty() ? "vestige" : vestigeName;
		if (isVestige) {
			return new Result(new State(0, true), true, false,
				vestige + "! The cycle resets — the next one is " + rollsPerVestige + " rolls away.");
		}

		int next = was.rolls + 1;
		if (next >= rollsPerVestige) {
			// We thought the vestige was due and it wasn't: the count was wrong, not the game.
			return new Result(new State(1, false), false, false,
				"Roll 1 of " + rollsPerVestige + " (estimated — the count was off, re-anchoring)");
		}

		var vestigeNext = next == rollsPerVestige - 1;
		var line = "Roll " + next + " of " + rollsPerVestige
			+ (vestigeNext ? " — the next unique is the " + vestige + "!" : "")
			+ (was.exact ? "" : " (estimated)");
		return new Result(new State(next, was.exact), false, vestigeNext, line);
	}

	/** Serialised as "boss=rolls:exact;…" for the RuneLite config, so the cycle survives a restart. */
	String serialise() {
		var sb = new StringBuilder();
		for (Map.Entry<String, State> e : byBoss.entrySet()) {
			if (sb.length() > 0) sb.append(';');
			sb.append(e.getKey()).append('=').append(e.getValue().rolls).append(':').append(e.getValue().exact ? 1 : 0);
		}
		return sb.toString();
	}

	static VestigeRolls parse(String raw) {
		var out = new VestigeRolls();
		if (raw == null || raw.trim().isEmpty()) return out;
		for (String part : raw.split(";")) {
			var kv = part.split("=", 2);
			if (kv.length != 2) continue;
			var v = kv[1].split(":", 2);
			try {
				int rolls = Integer.parseInt(v[0].trim());
				var exact = v.length > 1 && "1".equals(v[1].trim());
				out.byBoss.put(key(kv[0]), new State(Math.max(0, rolls), exact));
			} catch (NumberFormatException ignored) {
				// A corrupted entry just loses that boss's count — it re-estimates from the next drop.
			}
		}
		return out;
	}
}

package com.anvil;

import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.WorldType;

/**
 * What the client knows about the world the player is on, in the form the site reads it.
 *
 * <p>The plugin only REPORTS the world: its type flags and the activity line from the world list
 * ("Grid Master", "Deadman Annihilation", "Leagues VI"). Which game mode that is, where its posts
 * go and whether it counts for anything is the site's call (lib/worldModes), so a new mode Jagex
 * ships is recognised on release day without a plugin update — the activity text names it even
 * before RuneLite has a flag for it.</p>
 */
final class WorldInfo {
	WorldInfo() {
	}

	/**
	 * Worlds that run their own save — a separate character, its own drops and kill counts — so
	 * nothing earned there is the player's main-game progression. The site has the authoritative
	 * list; this one only gates what the plugin itself suppresses before sending (level posts).
	 */
	static final Set<WorldType> SEPARATE_SAVE = Collections.unmodifiableSet(EnumSet.of(
		WorldType.SEASONAL, WorldType.DEADMAN, WorldType.HARDCORE_MAIN, WorldType.TOURNAMENT_WORLD,
		WorldType.BETA_WORLD, WorldType.FRESH_START_WORLD));

	/** Minigame worlds with a preset loadout or no save: their levels never post. */
	static final Set<WorldType> PRESET = Collections.unmodifiableSet(EnumSet.of(
		WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.LAST_MAN_STANDING, WorldType.NOSAVE_MODE));

		/** Longest activity line sent. World-list activities are short; this only bounds a surprise. */
	static final int MAX_ACTIVITY = 64;

	/** The world's flags as a stable, comma-separated list of names ("DEADMAN,MEMBERS"); null for none. */
	static String types(Collection<WorldType> types) {
		if (types == null || types.isEmpty()) return null;
		return types.stream().map(Enum::name).sorted().collect(Collectors.joining(","));
	}

	/**
	 * The world-list activity, cleaned to something that can ride in an HTTP header: printable ASCII
	 * only (OkHttp rejects anything else outright), whitespace collapsed, bounded. Null when blank or
	 * a placeholder ("-").
	 */
	static String activity(String raw) {
		if (raw == null) return null;
		var b = new StringBuilder(Math.min(raw.length(), MAX_ACTIVITY));
		var space = false;
		for (int i = 0; i < raw.length() && b.length() < MAX_ACTIVITY; i++) {
			char c = raw.charAt(i);
			if (c == ' ' || c == '\t' || c == ' ') {
				space = b.length() > 0;
				continue;
			}
			if (c < 0x21 || c > 0x7e) continue;
			if (space) {
				b.append(' ');
				space = false;
			}
			b.append(c);
		}
		var s = b.toString().trim();
		return s.isEmpty() || s.equals("-") ? null : s;
	}

	/** Is this world a separate save (Leagues, Deadman, hardcore, …)? */
	static boolean separateSave(Collection<WorldType> types) {
		return types != null && !Collections.disjoint(types, SEPARATE_SAVE);
	}

	/** May a level-up post here? The main game, or a separate save the site sent level rules for. */
	static boolean levelsPost(Collection<WorldType> types, boolean modeRules) {
		return (types == null || Collections.disjoint(types, PRESET)) && (!separateSave(types) || modeRules);
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
