		assertTrue(bodies.get(1).contains("\"act\":\"goal-remove\""));
		assertTrue(bodies.get(1).contains("\"id\":\"4\""));

		code = 500;
		assertNull(c.fetchUi("you", Collections.emptyMap(), null));
	}

	@Test
	public void siteLinksStayOnTheSitesHost()
	{
		BingoApiClient c = client();
