			+ "\"caVarps\":{\"3116\":7},\"caPoints\":40}", bodies.get(0));
	}

	@Test
	public void tokenOptionalCallsCarryThePluginVersion() throws IOException
	{
		BingoApiClient c = client();
		c.hello("Main Guy");
		for (Request r : seen)
		{
			assertEquals(BingoApiClient.PLUGIN_VERSION, r.header("X-Anvil-Plugin-Version"));
			assertEquals("Bearer tok", r.header("Authorization"));
		}
	}

	@Test
	public void everyRefusalIsTypedWithItsStatus()
	{
		BingoApiClient c = client();
		code = 503;
		try
		{
			c.submitEventCounters(1, 2, 3, 4, 5, 6);
			fail();
		}
		catch (IOException e)
		{
			assertTrue(e instanceof BingoApiClient.HttpStatusException);
			assertEquals(503, ((BingoApiClient.HttpStatusException) e).code);
			assertEquals("Counter push failed: HTTP 503 — {}", e.getMessage());
		}
		code = 401;
		try
		{
			c.uploadImage(new byte[]{1}, "a.png");
			fail();
		}
		catch (IOException e)
		{
			assertEquals(401, ((BingoApiClient.HttpStatusException) e).code);
			assertEquals("Image upload failed: HTTP 401", e.getMessage());
		}
	}
}

package com.anvil;

import java.lang.reflect.Proxy;
import org.junit.Test;

/**
 * The service is a singleton that outlives a plugin stop/start. Its executor used to stay terminated after
 * shutdown(), so the next banner threw RejectedExecutionException out of the loot handler — before the drop
 * was queued — and the tile showed "complete" in game while nothing reached the site.
 */
public class BannerSoundServiceTest
{
	private static AnvilConfig soundOn()
	{
		return (AnvilConfig) Proxy.newProxyInstance(AnvilConfig.class.getClassLoader(), new Class<?>[]{AnvilConfig.class},
			(proxy, method, args) -> method.getName().equals("bannerSound") ? Boolean.TRUE : null);
	}

	@Test
	public void playAfterShutdownDoesNotThrow()
	{
		BannerSoundService sound = new BannerSoundService(soundOn(), null);
		sound.play(BannerSoundService.Kind.BANNER);
		sound.shutdown();
		sound.play(BannerSoundService.Kind.BANNER);
		sound.play(BannerSoundService.Kind.MISSION);
		sound.shutdown();
	}

	/**
	 * Startup lists every clip folder before any sound has played. The re-read went to the audio executor
	 * directly, which only exists after the first play — the NullPointerException escaped setRoot() and
	 * skipped the outbox, push stash and disk cache set-up that follows it, every session.
	 */
	@Test
	public void listingBeforeAnySoundDoesNotThrow()
	{
		BannerSoundService sound = new BannerSoundService(soundOn(), null);
		for (BannerSoundService.Kind kind : BannerSoundService.Kind.values())
		{
			sound.listClips(kind);
		}
		sound.shutdown();
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ChatCreditsTest
{
	private static final int SCROLL = 21034;
	private static final int DUST = 22386;

	private static List<ItemStack> one(int id)
	{
		return Collections.singletonList(new ItemStack(id, 1));
	}

	@Test
	public void raidUniqueCreditedAtRaidEndIsNotCreditedAgainAtTheChest()
	{
		ChatCredits c = new ChatCredits();
		c.note(one(SCROLL), 0);
		List<ItemStack> chest = c.unclaimed(Arrays.asList(new ItemStack(SCROLL, 1), new ItemStack(DUST, 1)), 4 * 60_000);
		assertEquals(1, chest.size());
		assertEquals(DUST, chest.get(0).getId());
		// The claim is spent: the next raid's scroll counts.
		assertEquals(1, c.unclaimed(one(SCROLL), 5 * 60_000).size());
	}

