public class ChatFlairTest
{
	/** A look, with the name it's for carried in a side table (the wire keeps names apart from looks). */
	private static final java.util.Map<ChatFlair.Entry, String> NAMES = new java.util.IdentityHashMap<>();

	private static ChatFlair.Entry entry(String n, String c, Boolean star, String... grad)
	{
		ChatFlair.Entry e = new ChatFlair.Entry();
		NAMES.put(e, n);
		e.c = c;
		e.s = star;
		e.g = grad.length == 0 ? null : Arrays.asList(grad);
		return e;
	}

	private static ChatFlair with(ChatFlair.Entry... entries)
	{
		ChatFlair f = new ChatFlair();
		f.adopt(wire(1, null, entries));
		return f;
	}

	static ChatFlair.Wire wire(int v, Integer from, ChatFlair.Entry... entries)
	{
		ChatFlair.Wire w = new ChatFlair.Wire();
		w.v = v;
		w.from = from;
		w.styles = new ArrayList<>(Arrays.asList(entries));
		w.names = new String[entries.length];
		w.ix = new int[entries.length];
		for (int i = 0; i < entries.length; i++)
		{
			w.names[i] = NAMES.get(entries[i]);
			w.ix[i] = i;
		}
		return w;
	}

	private static int kind(String raw)
	{
		return ChatFlair.chatKind(raw, "The AFK Spot", "Iron Pals", "Fc Name", "Me Myself");
	}

	@Test
	public void tenureIconReplacesThePatronStarForEveryTier()
	{
		ChatFlair.Entry sup = entry("ab", "#ffd35c", null);
		sup.t = 3;
		ChatFlair.Entry pat = entry("cd", "#ff7ab8", true, "#ff0000", "#0000ff");
		pat.t = 4;
		ChatFlair f = with(sup, pat, entry("ef", "#ffd35c", true));
		f.tenureIcon = (e, opaque, shift) -> "<img=" + (opaque ? 50 : 40) + e.t + ">";
		assertEquals("<img=403><col=ffd35c>Ab</col>", f.decorate("Ab", "<img=99>"));
		assertTrue(f.decorate("Cd", "<img=99>").startsWith("<img=404><col=ff0000>"));
		assertTrue(f.decorateReadable("Cd", "<img=99>", 0, true).startsWith("<img=504>"));
		// No t: today's Patron star; no icon asked for: none.
		assertTrue(f.decorate("Ef", "<img=99>").startsWith("<img=99>"));
		assertEquals("<col=ffd35c>Ab</col>", f.decorate("Ab", null));
		// A Legend repaints like a moving name (its hex glints); a plain Supporter doesn't.
		assertTrue(f.movingName("cd"));
		assertFalse(f.movingName("ab"));
	}

