	private static final String CHANS = "\"chans\":["
		+ "{\"label\":\"My team\",\"on\":true,\"feed\":\"chat:9:team:4\",\"act\":{\"a\":\"load\",\"v\":\"feed\"}},"
		+ "{\"label\":\"All teams\",\"on\":false,\"feed\":\"chat:9:all\",\"n\":2,\"blue\":true,\"act\":{\"a\":\"load\",\"v\":\"feed\"}},"
		+ "{\"label\":\"Announcements\",\"on\":false,\"feed\":\"chat:9:announce\",\"act\":{\"a\":\"load\",\"v\":\"feed\"}}]";

	@Test
	public void anotherChannelsLinesCountOnItsSegmentNotTheOpenOne()
	{
		Host host = new Host();
		UiView v = drawn(host, "{\"t\":\"feed\",\"id\":\"chat:9:team:4\",\"rows\":[],\"send\":{\"act\":\"chat-send\"}," + CHANS + "}");
		FeedList f = find(v);
		assertEquals(2, f.unread("chat:9:all"));
		v.feedPush(json("{\"t\":\"rows\",\"feeds\":[\"chat:9:all\"],\"rows\":[" + row("c1") + "," + row("c2") + "]}"));
		v.feedPush(json("{\"t\":\"rows\",\"feeds\":[\"chat:9:announce\"],\"rows\":[" + row("c3") + "]}"));
		v.feedPush(json("{\"t\":\"rows\",\"feeds\":[\"chat:9:team:4\"],\"rows\":[" + row("c4") + "]}"));
		assertEquals(4, f.unread("chat:9:all"));
		assertEquals(1, f.unread("chat:9:announce"));
		assertEquals("the open channel takes its lines, it doesn't count them", 0, f.unread("chat:9:team:4"));
		f.flush();
		assertEquals(1, f.rowCount());
	}

	@Test
	public void aLockStandsInPlaceOfTheBoxAndAPauseLeavesAnnouncementsAlone()
	{
		Host host = new Host();
		UiView v = drawn(host, "{\"t\":\"feed\",\"id\":\"chat:9:announce\",\"rows\":[],\"send\":{\"act\":\"chat-send\"},"
			+ "\"locked\":\"Only the host and mods post here\",\"lockSub\":\"Reply in My team or All teams.\"}");
		FeedList f = find(v);
		assertTrue("read-only for a player", f.locked());
		v.feedPush(json("{\"t\":\"rowslock\",\"feeds\":[\"chat:9:all\",\"chat:9:team\"],\"locked\":null}"));
		assertTrue("a resume names only the talking channels", f.locked());
		v.feedPush(json("{\"t\":\"rowslock\",\"feeds\":[\"chat:9\"],\"locked\":\"You\u2019re timed out \u00b7 9m left\",\"warn\":1}"));
		assertTrue(f.locked());

		UiView all = drawn(host, "{\"t\":\"feed\",\"id\":\"chat:9:all\",\"rows\":[],\"send\":{\"act\":\"chat-send\"}}");
		FeedList g = find(all);
		assertFalse(g.locked());
		all.feedPush(json("{\"t\":\"rowslock\",\"feeds\":[\"chat:9\"],\"locked\":\"You\u2019re timed out \u00b7 9m left\",\"warn\":1}"));
		assertTrue("a timeout closes every channel", g.locked());
		all.feedPush(json("{\"t\":\"rowslock\",\"feeds\":[\"chat:9:all\",\"chat:9:team\"],\"locked\":null}"));
		assertFalse(g.locked());
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** The delta rules behind counters read off a varbit/varp (site lib/gameCounters). */
public class GameValueCountersTest
{
	private final Map<String, Integer> vars = new HashMap<>();
	private final GameValueCounters.Reader reader = (varp, id) -> vars.getOrDefault((varp ? "p" : "b") + id, 0);
	private GameValueCounters counters;

	private static GameValueCounters.Source varbit(int id)
	{
		return new GameValueCounters.Source("varbit", id);
	}

	private static GameValueCounters.Source varp(int id)
	{
		return new GameValueCounters.Source("varp", id);
	}

	private final GameValueCounters.Entry tithe = new GameValueCounters.Entry("Tithe Farm points", true, 0, varbit(4893));
	private final GameValueCounters.Entry foundry = new GameValueCounters.Entry("Giants' Foundry reputation", true, 500, varp(3436));

	@Before
	public void setUp()
	{
		counters = new GameValueCounters();
		counters.configure(Arrays.asList(tithe, foundry));
	}

	private List<GameValueCounters.Credit> tick()
	{
		counters.onLoggedIn();
		return counters.tick(reader, e -> true);
	}

	private void settle()
	{
		for (int i = 0; i < GameValueCounters.SETTLE_TICKS; i++)
		{
			assertTrue("nothing counts while settling", tick().isEmpty());
		}
	}

	private static int amountFor(List<GameValueCounters.Credit> credits, String name)
	{
		for (GameValueCounters.Credit c : credits)
		{
			if (c.entry.name.equals(name))
			{
				return c.amount;
			}
		}
		return 0;
	}

	@Test
	public void loginBurstIsBaselineNotCredit()
	{
		tick(); // placeholder 0 at login...
		vars.put("b4893", 740); // ...then the real balance arrives while settling
		vars.put("p3436", 12000);
		for (int i = 1; i < GameValueCounters.SETTLE_TICKS; i++)
		{
			assertTrue(tick().isEmpty());
		}
		assertTrue("first settled read seeds", tick().isEmpty());
		vars.put("b4893", 790);
		List<GameValueCounters.Credit> c = tick();
		assertEquals(1, c.size());
		assertEquals(50, amountFor(c, "Tithe Farm points"));
	}

	@Test
	public void spendingNeverSubtractsAndRebaselines()
	{
		vars.put("p3436", 300);
		settle();
		tick();
		vars.put("p3436", 0); // bought something
		assertTrue(tick().isEmpty());
		vars.put("p3436", 120);
		assertEquals(120, amountFor(tick(), "Giants' Foundry reputation"));
	}

	@Test
	public void decreaseDirectionCountsSpendingOnly()
	{
		GameValueCounters.Entry claimed = new GameValueCounters.Entry("Wintertodt rewards claimed", false, 0, varbit(11435));
		claimed.direction = "decrease";
		GameValueCounters.Entry earned = new GameValueCounters.Entry("Wintertodt rewards earned", false, 0, varbit(11435));
		counters.configure(Arrays.asList(claimed, earned));
		vars.put("b11435", 10);
		settle();
		tick();
		vars.put("b11435", 14);
		List<GameValueCounters.Credit> c = tick();
		assertEquals(4, amountFor(c, "Wintertodt rewards earned"));
		assertEquals(0, amountFor(c, "Wintertodt rewards claimed"));
		vars.put("b11435", 9);
		c = tick();
		assertEquals(5, amountFor(c, "Wintertodt rewards claimed"));
		assertEquals(0, amountFor(c, "Wintertodt rewards earned"));
	}

	@Test
	public void absurdJumpIsReBaselinedNotCredited()
	{
		settle();
		tick();
		vars.put("p3436", 501); // over this entry's 500 cap
		assertTrue(tick().isEmpty());
		vars.put("p3436", 511);
		assertEquals(10, amountFor(tick(), "Giants' Foundry reputation"));
		vars.put("b4893", GameValueCounters.DEFAULT_MAX_DELTA + 1); // default cap
		assertTrue(tick().isEmpty());
	}

	@Test
	public void logoutForgetsBaselinesAndResettles()
	{
		vars.put("b4893", 100);
		settle();
		tick();
		counters.onSessionEnd();
		vars.put("b4893", 900); // another account
		settle();
		assertTrue("re-seeded, not credited", tick().isEmpty());
	}

	@Test
	public void loadingPausesButKeepsBaseline()
	{
		vars.put("b4893", 100);
		settle();
		tick();
		counters.onLoading();
		vars.put("b4893", 130); // changed across the loading zone
		settle();
		assertEquals(30, amountFor(tick(), "Tithe Farm points"));
	}

	@Test
	public void unwantedEntriesAreForgottenAndReseeded()
	{
		settle();
		counters.tick(reader, e -> true);
		vars.put("b4893", 40);
		assertTrue(counters.tick(reader, e -> false).isEmpty());
		assertTrue("a tile added later starts from now", counters.tick(reader, e -> true).isEmpty());
		vars.put("b4893", 45);
		assertEquals(5, amountFor(counters.tick(reader, e -> true), "Tithe Farm points"));
	}

	@Test
	public void severalSourcesSum()
	{
		GameValueCounters.Entry delves = new GameValueCounters.Entry("Doom of Mokhaiotl delves", false, 0,
			varp(4808), varp(4809), varp(4816));
		counters.configure(Arrays.asList(delves));
		settle();
		tick();
		vars.put("p4808", 1);
		vars.put("p4816", 2);
		assertEquals(3, amountFor(tick(), "Doom of Mokhaiotl delves"));
	}

	@Test
	public void slayerSplitCreditsOneTaskOnce()
	{
		GameValueCounters.Entry any = new GameValueCounters.Entry("Slayer tasks: any master", false, 0,
			varp(5720), varbit(5617), varbit(4069));
		any.changes = true;
		GameValueCounters.Entry mortimer = new GameValueCounters.Entry("Slayer tasks: Mortimer", false, 0, varp(5720));
		GameValueCounters.Entry krystilia = new GameValueCounters.Entry("Slayer tasks: Krystilia", false, 0, varbit(5617));
		GameValueCounters.Entry other = new GameValueCounters.Entry("Slayer tasks: other masters", false, 0, varbit(4069));
		other.unless = Arrays.asList(varp(5720), varbit(5617));
		counters.configure(Arrays.asList(any, mortimer, krystilia, other));
		vars.put("b4069", 40);
		settle();
		tick();

		// A Mortimer task that ALSO bumps the main streak: any +1, Mortimer +1, other-masters nothing.
		vars.put("p5720", 1);
		vars.put("b4069", 41);
		List<GameValueCounters.Credit> c = tick();
		assertEquals(1, amountFor(c, "Slayer tasks: any master"));
		assertEquals(1, amountFor(c, "Slayer tasks: Mortimer"));
		assertEquals(0, amountFor(c, "Slayer tasks: other masters"));

		// A Duradel task: main streak only.
		vars.put("b4069", 42);
		c = tick();
		assertEquals(1, amountFor(c, "Slayer tasks: any master"));
		assertEquals(1, amountFor(c, "Slayer tasks: other masters"));
		assertEquals(0, amountFor(c, "Slayer tasks: Mortimer"));

		// Turael resets the streak: nothing. The next task after it counts again.
		vars.put("b4069", 0);
		assertTrue(tick().isEmpty());
		vars.put("b4069", 1);
		assertEquals(1, amountFor(tick(), "Slayer tasks: other masters"));

		// Krystilia, wilderness streak only.
		vars.put("b5617", 1);
		c = tick();
		assertEquals(1, amountFor(c, "Slayer tasks: Krystilia"));
		assertEquals(1, amountFor(c, "Slayer tasks: any master"));
		assertEquals(0, amountFor(c, "Slayer tasks: other masters"));
	}

	@Test
	public void badEntriesAreDropped()
	{
		counters.configure(Arrays.asList(null,
			new GameValueCounters.Entry("", true, 0, varp(1)),
			new GameValueCounters.Entry("X", true, 0, new GameValueCounters.Source("widget", 1)),
			new GameValueCounters.Entry("Y", true, 0, varp(0)),
			new GameValueCounters.Entry("Z", true, 0),
			tithe));
		assertEquals(1, counters.entries().size());
	}

	@Test
	public void lateBalanceArrivalNeverCredits()
	{
		GameValueCounters.Entry balance = new GameValueCounters.Entry("Tithe Farm points", true, 40, varbit(4893));
		balance.balance = true;
		counters.configure(Arrays.asList(balance));
		settle();
		tick(); // seeds 0: the var hasn't arrived
		vars.put("b4893", 33); // arrives late, under the per-action cap
		assertTrue("0 -> balance is arrival, not earning", tick().isEmpty());
		vars.put("b4893", 68);
		assertEquals(35, amountFor(tick(), "Tithe Farm points"));
		vars.put("b4893", 0); // spent everything
		assertTrue(tick().isEmpty());
		vars.put("b4893", 30); // the one action a 0-balance player loses
		assertTrue(tick().isEmpty());
		vars.put("b4893", 41);
		assertEquals(11, amountFor(tick(), "Tithe Farm points"));
	}

	@Test
	public void lateArrivalOverTheActionCeilingReBaselines()
	{
		GameValueCounters.Entry pool = new GameValueCounters.Entry("Wintertodt rewards earned", false, 30, varbit(11435));
		counters.configure(Arrays.asList(pool));
		settle();
		tick();
		vars.put("b11435", 412); // a banked cart arriving late
		assertTrue(tick().isEmpty());
		vars.put("b11435", 418);
		assertEquals(6, amountFor(tick(), "Wintertodt rewards earned"));
	}
}

package com.anvil;

import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.swing.SwingConstants;
import org.junit.Test;

public class GradientLabelTest
{
	/** The colours painted in the label's right-most quarter, where the star sits after the name. */
	private static boolean starIsYellow(boolean tint)
	{
		GradientLabel l = new GradientLabel(new Color[]{Color.RED, Color.BLUE}, false);
		l.setText("Abc");
		l.setForeground(Color.RED);
		l.setIcon(new GlyphIcon(GlyphIcon.Shape.STAR, 10, new Color(0xff, 0xd3, 0x5c)));
		l.setHorizontalTextPosition(SwingConstants.LEADING);
		l.setIconTextGap(4);
		l.setTintIcon(tint);
		Dimension d = l.getPreferredSize();
		l.setSize(d);
		BufferedImage img = new BufferedImage(d.width, d.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		l.paint(g);
		g.dispose();
		boolean yellow = false;
		for (int x = d.width - 10; x < d.width; x++)
		{
			for (int y = 0; y < d.height; y++)
			{
				Color c = new Color(img.getRGB(x, y), true);
				if (c.getAlpha() > 200 && c.getRed() > 200 && c.getGreen() > 150 && c.getBlue() < 140)
				{
					yellow = true;
				}
			}
		}
		return yellow;
	}

	@Test
	public void theStarTakesTheGradientOnlyWhenAsked()
	{
		assertTrue("an ordinary icon keeps its colours", starIsYellow(false));
		assertTrue("the supporter star is painted by the gradient", !starIsYellow(true));
	}
}

package com.anvil;

import com.google.gson.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.*;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.swing.*;
import org.junit.Test;

import static org.junit.Assert.*;

/** A hero card with a real banner and badge picture keeps its rounded corners (build/hero-corners-1x.png, -2x.png). */
public class HeroCornersTest {
	private static final Color PIC = new Color(255, 0, 255);

	private static final class Host implements UiView.Host {
		@Override public void load(String v, Map<String, String> a, Consumer<JsonObject> d) { }
		@Override public void post(String a, Map<String, String> g, Map<String, String> f, Consumer<JsonObject> d) { }
		@Override public void site(String p) { }
		@Override public void lookup(String r) { }
		@Override public void clan(String s) { }
		@Override public void pin(int e, int t, boolean on) { }
		@Override public void switchClan(String s) { }
		@Override public JComponent nativePart(String n) { return null; }
		@Override public void image(String path, int w, int h, boolean motion, Consumer<Icon> done) {
			BufferedImage im = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = im.createGraphics();
			g.setColor(PIC);
			g.fillRect(0, 0, w, h);
			g.dispose();
			done.accept(new ImageIcon(im));
		}
	}

	private static void layOut(Component c) {
		if (c instanceof Container) {
			((Container) c).doLayout();
			for (Component k : ((Container) c).getComponents()) layOut(k);
		}
	}

	private static BufferedImage render(int scale, int width) throws Exception {
		JsonObject root = new JsonParser().parse("{\"ui\":{\"t\":\"col\",\"c\":[{\"t\":\"hero\",\"src\":\"b\",\"c\":["
			+ "{\"t\":\"col\",\"card\":true,\"inset\":2,\"rad\":10,\"c\":[{\"t\":\"img\",\"src\":\"l\",\"w\":32,\"h\":32,\"rad\":8}]}]}]}}").getAsJsonObject();
		BufferedImage[] out = new BufferedImage[1];
		SwingUtilities.invokeAndWait(() -> {
			UiView view = new UiView(new Host(), null, null, null);
			view.render(root);
			view.setSize(width, view.getPreferredSize().height);
			layOut(view);
			out[0] = new BufferedImage(width * scale, view.getHeight() * scale, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = out[0].createGraphics();
			g.scale(scale, scale);
			view.paint(g);
			g.dispose();
		});
		return out[0];
	}

	@Test
	public void realImagesKeepRoundedCorners() throws Exception {
		for (int scale = 1; scale <= 2; scale++) {
			BufferedImage im = render(scale, 225);
			ImageIO.write(im, "png", new File("build/hero-corners-" + scale + "x.png"));
			// The banner's outermost corner pixel must not be the picture, and the strip's middle must be.
			assertNotEquals("banner corner square at " + scale + "x", PIC.getRGB(), im.getRGB(0, 0) | 0xff000000);
			// The badge picture's own corner (8px radius) is cut: the ring shows there.
			int bx = 12 * scale, by = 89 * scale; // bottom-left of the 32px picture (body at x10, y56: banner 74 less the 18 pull-up; ring 2px)
			assertNotEquals("badge corner square at " + scale + "x", PIC.getRGB(), im.getRGB(bx, by) | 0xff000000);
			assertEquals("banner body", PIC.getRGB(), im.getRGB(im.getWidth() / 2, 10 * scale) | 0xff000000);
		}
	}

	/** On a panel wider than the picture the banner still reaches both edges (cover, not centred). */
	@Test
	public void bannerCoversAWidePanel() throws Exception {
		BufferedImage im = render(1, 400);
		ImageIO.write(im, "png", new File("build/hero-corners-wide.png"));
		assertEquals("left edge", PIC.getRGB(), im.getRGB(2, 28) | 0xff000000);
		assertEquals("right edge", PIC.getRGB(), im.getRGB(397, 28) | 0xff000000);
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The first request must carry both halves of identity or roster-first linking falls back to review. */
public class IdentityStampTest
{
	@Test
	public void waitsForBothRsnAndAccountHash()
	{
		assertFalse(AnvilPlugin.identityReady(null, 42L));
		assertFalse(AnvilPlugin.identityReady("", 42L));
		assertFalse(AnvilPlugin.identityReady("Hells Taco", -1L));
		// The client's placeholder before the real name arrives.
		assertFalse(AnvilPlugin.identityReady("#Player1281", 42L));
		assertTrue(AnvilPlugin.identityReady("Hells Taco", 42L));
	}

	@Test
	public void spotsAnInGameRenameButNotAMissingName()
	{
		assertTrue(AnvilPlugin.renamedMidSession("1BM", "LEARNING TOB"));
		assertFalse(AnvilPlugin.renamedMidSession("Hells Taco", "hells_taco"));
