import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Chest loot that lands in the looting bag: only what the bag GAINED counts, and only against a known bag. */
public class LootingBagGainsTest
{
	@Test
	public void countsOnlyIncreases()
	{
		Map<Integer, Integer> before = new HashMap<>();
		before.put(1, 5);
		before.put(2, 1);
		Map<Integer, Integer> after = new HashMap<>();
		after.put(1, 8);
		after.put(3, 2);
		List<ItemStack> gained = AnvilPlugin.lootingBagGains(before, after);
		assertEquals(2, gained.size());
		for (ItemStack s : gained)
		{
			assertEquals(s.getId() == 1 ? 3 : 2, s.getQuantity());
		}
	}

	@Test
	public void anUnknownBagCreditsNothing()
	{
		Map<Integer, Integer> after = new HashMap<>();
		after.put(1, 100);
		assertTrue(AnvilPlugin.lootingBagGains(null, after).isEmpty());
	}

	@Test
	public void matchesBothChestLines()
	{
		assertTrue(TestPatterns.get("chest.larran").matcher("You have opened Larran's big chest 12 times.").matches());
		assertTrue(TestPatterns.get("chest.larran").matcher("You have opened Larran's small chest 1 time.").matches());
	}

	@Test
	public void emptyingStorageIsAMoveNotAGather()
	{
		assertTrue(AnvilPlugin.isStorageMove("Empty"));
		assertTrue(AnvilPlugin.isStorageMove("Withdraw-All"));
		assertTrue(AnvilPlugin.isStorageMove("Remove"));
		org.junit.Assert.assertFalse(AnvilPlugin.isStorageMove("Fill"));
		org.junit.Assert.assertFalse(AnvilPlugin.isStorageMove("Net"));
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;

public class ModeLinesTest
{
	@Test
	public void keepsAnnouncementsOnceAndBatchesThem()
	{
		ModeLines lines = new ModeLines();
		assertTrue(lines.offer("<col=ef1020>You have unlocked a new Relic: Endless Harvest.</col>", 0));
		assertFalse(lines.offer("<col=ef1020>You have unlocked a new Relic: Endless Harvest.</col>", 10));
		assertTrue(lines.offer("Congratulations, you've completed an easy task: Open the Leagues Menu.", 20));
		assertFalse(lines.offer("You catch a shrimp.", 30));
		assertNull(lines.drain(ModeLines.FLUSH_MS - 1));
		assertEquals(Arrays.asList("<col=ef1020>You have unlocked a new Relic: Endless Harvest.</col>",
			"Congratulations, you've completed an easy task: Open the Leagues Menu."), lines.drain(ModeLines.FLUSH_MS));
		assertNull(lines.drain(ModeLines.FLUSH_MS * 2));
	}

	@Test
	public void aBatchIsBounded()
	{
		ModeLines lines = new ModeLines();
		for (int i = 0; i < ModeLines.MAX_BATCH + 5; i++)
		{
			lines.offer("<col=ff0000>line " + i, 0);
		}
		assertEquals(ModeLines.MAX_BATCH, lines.drain(ModeLines.FLUSH_MS).size());
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import org.junit.Test;

public class MotionIconTest
{
	/** An animated GIF of {@code frames} solid frames, each {@code delayCs} centiseconds. */
	static byte[] gif(int w, int h, int frames, int delayCs) throws Exception
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("gif").next();
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (ImageOutputStream ios = ImageIO.createImageOutputStream(out))
		{
			writer.setOutput(ios);
			writer.prepareWriteSequence(null);
			for (int i = 0; i < frames; i++)
			{
				BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
				img.setRGB(0, 0, 0x00ff00 * (i + 1));
				IIOMetadata meta = writer.getDefaultImageMetadata(ImageTypeSpecifier.createFromRenderedImage(img), null);
				IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree("javax_imageio_gif_image_1.0");
				IIOMetadataNode gce = new IIOMetadataNode("GraphicControlExtension");
				gce.setAttribute("disposalMethod", "none");
				gce.setAttribute("userInputFlag", "FALSE");
				gce.setAttribute("transparentColorFlag", "FALSE");
				gce.setAttribute("delayTime", Integer.toString(delayCs));
				gce.setAttribute("transparentColorIndex", "0");
				root.appendChild(gce);
				meta.setFromTree("javax_imageio_gif_image_1.0", root);
				writer.writeToSequence(new IIOImage(img, null, meta), null);
			}
			writer.endWriteSequence();
		}
		finally
		{
			writer.dispose();
		}
		return out.toByteArray();
	}

	@Test
	public void anAnimatedGifDecodesEveryFrameAndLoopsForever() throws Exception
	{
		Icon icon = BingoApiClient.animatedIcon(gif(48, 48, 3, 10), 48, 48);
		assertTrue(icon instanceof GifIcon);
		GifIcon g = (GifIcon) icon;
		assertEquals(3, g.frameCount());
		assertEquals(48, g.getIconWidth());
		// 100 ms a frame: past the end it wraps to the first frame again, whatever the file's loop count.
		assertEquals(0, g.frameAt(50));
		assertEquals(1, g.frameAt(150));
		assertEquals(2, g.frameAt(250));
		g.advance(250);
		assertEquals(2, g.shownFrame());
		g.advance(100);
		assertEquals("looped", 0, g.shownFrame());
	}

	@Test
	public void eachLabelGetsItsOwnClockOverSharedFrames() throws Exception
	{
		GifIcon first = (GifIcon) BingoApiClient.animatedIcon(gif(48, 48, 2, 10), 48, 48);
		GifIcon second = first.copy();
		assertNotSame(first, second);
		first.advance(150);
		assertEquals(1, first.shownFrame());
		assertEquals("paused/other labels keep their own frame", 0, second.shownFrame());
	}

	@Test
	public void aOneFrameGifIsAPlainStill() throws Exception
	{
		assertTrue(BingoApiClient.animatedIcon(gif(48, 48, 1, 0), 48, 48) instanceof ImageIcon);
	}

	@Test
	public void unsafeOrForeignFilesAreRefused() throws Exception
	{
		assertNull("too big for the slot", BingoApiClient.animatedIcon(gif(96, 96, 2, 10), 48, 48));
		byte[] huge = gif(48, 48, 2, 10);
		// Logical screen 4096x4096 behind 48x48 frames.
		huge[6] = 0; huge[7] = 0x10; huge[8] = 0; huge[9] = 0x10;
		assertNull(BingoApiClient.animatedIcon(huge, 48, 48));
		ByteArrayOutputStream jpeg = new ByteArrayOutputStream();
		ImageIO.write(new BufferedImage(48, 48, BufferedImage.TYPE_INT_RGB), "jpg", jpeg);
		assertNull("a still answer is decoded as a still by the caller", BingoApiClient.animatedIcon(jpeg.toByteArray(), 48, 48));
		assertNotNull(BingoApiClient.decodeSmall(jpeg.toByteArray(), 48, 48));
	}
}

package com.anvil;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Several live boards at once, for one character: one rule table carries every board's rules (tile ids
 * are unique across boards), one game event sends one fact the site fans out, completion memory is per
 * board, and pins from different boards sit side by side.
 */
public class MultiBoardTest
{
	private static RuleEngine.DropRule drop(int id, String label)
	{
		RuleEngine.DropRule r = new RuleEngine.DropRule();
		r.t = id;
		r.label = label;
		r.of = 1;
		r.simple = true;
		return r;
	}

	private static PluginConfigResponse.HomeBoard board(int eventId)
	{
		PluginConfigResponse.HomeBoard b = new PluginConfigResponse.HomeBoard();
		b.eventId = eventId;
		return b;
	}

	@Test
	public void oneDropOnTwoBoardsMovesBothAndSendsOneFact()
	{
		RuleEngine.Table t = new RuleEngine.Table();
		t.drops.put("4151", Arrays.asList(drop(11, "Whip"), drop(22, "Whip · Board B")));
		RuleEngine e = new RuleEngine();
		e.set(t);
		RuleEngine.Out out = e.loot("Abyssal demon", "npc", Collections.singletonList(new int[]{4151, 1}), null, null, 0);
		assertEquals("one fact; the site credits every board it matches", 1, out.facts.size());
		assertEquals("loot", out.facts.get(0).get("k").getAsString());
		assertEquals(Long.valueOf(1), out.raised.get(11));
		assertEquals(Long.valueOf(1), out.raised.get(22));
		assertEquals(2, out.say.size());
		assertTrue(out.say.get(1).contains("Board B"));
		// The site's answer corrects each board's tile on its own.
		e.adopt(new JsonParser().parse("{\"credits\":[{\"t\":22,\"have\":0,\"of\":1,\"ok\":true}]}").getAsJsonObject());
		RuleEngine.Out again = e.loot("Abyssal demon", "npc", Collections.singletonList(new int[]{4151, 1}), null, null, 10_000);
		assertEquals(1, again.facts.size());
		assertEquals(Collections.singleton(22), again.raised.keySet());
	}

	@Test
	public void completionMemoryIsPerBoard()
	{
		Set<Integer> seeded = new HashSet<>();
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.boards = Collections.singletonList(board(1));
		assertEquals("first look: board 1 absorbed silently", Collections.singleton(1), AnvilPlugin.freshBoards(seeded, cfg));
		cfg.boards = Arrays.asList(board(1), board(2));
		assertEquals("joining board 2 seeds only board 2: board 1 keeps announcing", Collections.singleton(2), AnvilPlugin.freshBoards(seeded, cfg));
		assertTrue(AnvilPlugin.freshBoards(seeded, cfg).isEmpty());
		cfg.boards = Collections.singletonList(board(2));
		assertTrue(AnvilPlugin.freshBoards(seeded, cfg).isEmpty());
		cfg.boards = Arrays.asList(board(1), board(2));
		assertEquals("a board that dropped out and came back seeds again", Collections.singleton(1), AnvilPlugin.freshBoards(seeded, cfg));

		// Which board a completion is on: its tag, else the addressed board.
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.id = 1;
		PluginConfigResponse.CompletedTile mine = new PluginConfigResponse.CompletedTile();
		PluginConfigResponse.CompletedTile other = new PluginConfigResponse.CompletedTile();
		other.board = board(2);
		assertEquals(1, AnvilPlugin.boardOf(cfg, mine));
		assertEquals(2, AnvilPlugin.boardOf(cfg, other));
		assertTrue(cfg.live(2));
		assertFalse(cfg.live(3));
	}

	@Test
	public void pinsFromTwoBoardsSitSideBySide()
	{
		TileTracker.Widget a = new TileTracker.Widget(0, 11, (id, site) -> site);
		a.event = 1;
		TileTracker.Widget b = new TileTracker.Widget(1, 22, (id, site) -> site);
		b.event = 2;
		String saved = TileTracker.format(Arrays.asList(a, b));
		assertEquals("1:11;2:22", saved);
		Map<Integer, Integer> back = new LinkedHashMap<>();
		back.put(11, 1);
		back.put(22, 2);
		assertEquals(back, TileTracker.parse(saved));
		// One board's pins as they used to be saved still restore.
		Map<Integer, Integer> old = new LinkedHashMap<>();
		old.put(3, 5);
		old.put(4, 5);
		assertEquals(old, TileTracker.parse("5:3,4"));
	}

	@Test
	public void aPushKeepsAnotherBoardsRows()
	{
		JsonObject held = new JsonParser().parse("{\"completedTiles\":[{\"tileId\":1},{\"tileId\":9,\"board\":{\"eventId\":2}}]}").getAsJsonObject();
		JsonObject team = new JsonParser().parse("{\"completedTiles\":[{\"tileId\":1},{\"tileId\":3}]}").getAsJsonObject();
		JsonObject out = PushMerge.merge(held, team, null);
		assertEquals(3, out.getAsJsonArray("completedTiles").size());
		assertEquals(9, out.getAsJsonArray("completedTiles").get(2).getAsJsonObject().get("tileId").getAsInt());
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The facts a notification carries are the whole contract with the site's lib/pluginEmbeds.ts, so
 * their exact JSON is pinned here; the site's tests pin what it builds from them.
 */
public class NotifyFactsTest
{
	@Test
	public void dropFactsLeaveOutWhatIsUnknown()
	{
		NotifyFacts f = new NotifyFacts("drop", "Zezima").put("source", "Vorkath").put("sourceKind", "npc")
			.put("kc", 54).item(22111, "Dragonbone necklace", 1, 12_345_678L).put("dropRate", 1.0 / 1000)
			.flag("guaranteed", false).flag("troll", false).flag("spoon", true).put("note", (String) null);
		assertEquals("{\"rsn\":\"Zezima\",\"source\":\"Vorkath\",\"sourceKind\":\"npc\",\"kc\":54,"
			+ "\"items\":[{\"id\":22111,\"name\":\"Dragonbone necklace\",\"qty\":1,\"value\":12345678}],"
			+ "\"dropRate\":0.001,\"spoon\":true}", f.facts.toString());
	}

	@Test
	public void aHaulCarriesEveryItemAndNoRsnWhenThereIsNone()
	{
		NotifyFacts f = new NotifyFacts("drop", null).put("source", (String) null).put("kc", (Integer) null)
			.item(1, "Item A", 1, 1_000_000L).item(2, "Item B", 4, 2_000_000L);
		assertEquals("{\"items\":[{\"id\":1,\"name\":\"Item A\",\"qty\":1,\"value\":1000000},"
			+ "{\"id\":2,\"name\":\"Item B\",\"qty\":4,\"value\":2000000}]}", f.facts.toString());
	}

	@Test
	public void achievementFacts()
	{
		assertEquals("{\"rsn\":\"Zezima\",\"task\":\"Into the Den of Giants\",\"tier\":\"Hard\",\"totalPoints\":216,"
				+ "\"nextThreshold\":726}",
			new NotifyFacts("caTask", "Zezima").put("task", "Into the Den of Giants")
				.put("tier", CombatAchievementTier.HARD.getDisplayName()).put("totalPoints", 216)
				.put("nextThreshold", 726).facts.toString());
		assertEquals("{\"rsn\":\"Zezima\",\"quest\":\"Dragon Slayer II\",\"difficulty\":\"Grandmaster\"}",
			new NotifyFacts("quest", "Zezima").put("quest", "Dragon Slayer II").put("difficulty", "Grandmaster")
				.facts.toString());
		assertEquals("{\"rsn\":\"Zezima\",\"total\":1800,\"milestone\":1800,\"current\":1803,\"max\":2277}",
			new NotifyFacts("totalLevel", "Zezima").put("total", 1800).flag("maxed", false).put("milestone", 1800)
				.put("current", 1803).put("max", 2277).facts.toString());
		// Maxed: no milestone, no distance.
		assertEquals("{\"rsn\":\"Zezima\",\"total\":2277,\"maxed\":true}",
			new NotifyFacts("totalLevel", "Zezima").put("total", 2277).flag("maxed", true)
				.put("milestone", (Integer) null).facts.toString());
	}

	@Test
	public void theRequestSendsKindAndFactsNotAnEmbed() throws Exception
	{
		assertEquals("{\"channel\":\"levels\",\"kind\":\"level\",\"facts\":{\"rsn\":\"Zezima\",\"skill\":\"Slayer\","
				+ "\"level\":90,\"at99\":12,\"skills\":23}}",
			send(new NotifyFacts("level", "Zezima").put("skill", "Slayer").put("level", 90).put("at99", 12)
				.put("skills", 23), null));
		// An older site's kind, without the level.
		assertEquals("{\"channel\":\"levels\",\"kind\":\"level99\",\"facts\":{\"rsn\":\"Zezima\",\"skill\":\"Slayer\","
				+ "\"at99\":12,\"skills\":23}}",
			send(new NotifyFacts("level99", "Zezima").put("skill", "Slayer").put("level", (Integer) null).put("at99", 12)
				.put("skills", 23), null));

		// With a screenshot it's multipart: the same JSON as payload_json, plus the named file.
		String body = send(new NotifyFacts("caTier", null).put("tier", "Elite"), new byte[]{1, 2, 3});
		assertTrue(body.contains("{\"channel\":\"levels\",\"kind\":\"caTier\",\"facts\":{\"tier\":\"Elite\"}}"));
		assertTrue(body.contains("filename=\"anvil-shot.png\""));
		assertFalse(body.contains("\"embed\""));
	}

	@Test
	public void globReadsTheSitesWatches()
	{
		assertEquals(50, NotifyFacts.glob("You've completed # tasks*",
			"You've completed 50 tasks and received 15 points, giving you a total of 1,234; return to a Slayer master."));
		assertEquals(1234, NotifyFacts.glob("Your * count is: #*", "Your Zulrah kill count is: 1,234."));
		assertEquals(100, NotifyFacts.glob("You have completed # hard Treasure Trail*", "You have completed 100 HARD Treasure Trails."));
		assertEquals(0, NotifyFacts.glob("*duration: *(new personal best)*", "Fight duration: 1:23.40 (new personal best)"));
		assertEquals(-1, NotifyFacts.glob("*duration: *(new personal best)*", "Fight duration: 1:23.40. Personal best: 1:20.00"));
		assertEquals(-1, NotifyFacts.glob("You have completed # elite Treasure Trail*", "You have completed 100 hard Treasure Trails."));
		assertEquals(-1, NotifyFacts.glob("Your * count is: #*", "Your Zulrah kill count is: lots."));
		// A hostile pattern costs at most pattern x line steps: this returns, it doesn't hang.
		StringBuilder line = new StringBuilder();
		for (int i = 0; i < 400; i++) line.append('a');
		assertEquals(-1, NotifyFacts.glob("*a*a*a*a*a*a*a*a*a*a*a*a*a*b", line.toString()));
	}

	@Test
	public void aKindSetToNoScreenshotPostsWithoutOne() throws Exception
	{
		String body = send(new NotifyFacts("level", "Zezima").put("skill", "Slayer").put("level", 90), new byte[]{1, 2, 3}, "level"::equals);
		assertFalse(body.contains("filename="));
		assertTrue(body.contains("\"kind\":\"level\""));
		// Another kind keeps its screenshot.
		assertTrue(send(new NotifyFacts("caTier", null).put("tier", "Elite"), new byte[]{1, 2, 3}, "level"::equals).contains("filename=\"anvil-shot.png\""));
	}

	@Test
	public void aTileProofKeepsItsScreenshotWhateverTheAnnouncementSetting() throws Exception
	{
		// Proofs are evidence: they never pass the announcement's screenshot switch.
		AtomicReference<String> body = new AtomicReference<>();
		BingoApiClient c = client(body, new CountDownLatch(1));
		c.noShot = k -> true;
		c.postProof("k1", new byte[]{(byte) 0x89, 'P', 'N', 'G'}, new com.google.gson.JsonObject());
		assertTrue(body.get().contains("filename=\"proof.png\""));
	}

	private static String send(NotifyFacts f, byte[] png) throws InterruptedException
	{
		return send(f, png, k -> false);
	}

	private static String send(NotifyFacts f, byte[] png, java.util.function.Predicate<String> noShot) throws InterruptedException
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<String> body = new AtomicReference<>();
		BingoApiClient c = client(body, done);
		c.noShot = noShot;
		c.postNotification("levels", null, f, png, "anvil-shot.png");
		assertTrue(done.await(5, TimeUnit.SECONDS));
		return body.get();
	}

	private static BingoApiClient client(AtomicReference<String> body, CountDownLatch done)
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			Request r = chain.request();
			Buffer b = new Buffer();
			r.body().writeTo(b);
			body.set(b.readUtf8());
			done.countDown();
			return new Response.Builder().request(r).protocol(Protocol.HTTP_1_1).code(200).message("x")
				.body(ResponseBody.create(MediaType.parse("application/json"), "{\"ok\":true}")).build();
		}).build();
		BingoApiClient c = new BingoApiClient(new Gson(), http);
		c.configure("tok");
		return c;
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import javax.swing.SwingUtilities;
import org.junit.After;
import org.junit.Test;

public class OffThreadTest
{
	@After
	public void unbind()
	{
		OffThread.bindClientThread(null);
	}

	@Test
	public void aBackgroundThreadMayBlock()
	{
		assertNull(OffThread.where());
	}

	@Test
	public void theEdtMayNot() throws Exception
	{
		String[] seen = new String[1];
		SwingUtilities.invokeAndWait(() -> seen[0] = OffThread.where());
		assertNotNull(seen[0]);
	}

	@Test
	public void theClientThreadMayNot()
	{
		OffThread.bindClientThread(() -> true);
		assertEquals("client thread (game)", OffThread.where());
		OffThread.bindClientThread(() ->
		{
			throw new IllegalStateException("client gone");
		});
		assertNull(OffThread.where());
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class OptimisticProgressTest
{
	@Test
	public void aLocalKillShowsBeforeTheSiteHasIt()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.raise(7, 41, 0);
		assertEquals(41, p.apply(7, 40, 1_000));
	}

	@Test
	public void aConfigRefreshThatLandsBeforeThePushDoesNotWindItBack()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.add(7, 40, 2, 0);
		// The poll still says 40: the push hasn't landed.
		assertEquals(42, p.apply(7, 40, 5_000));
		assertEquals(42, p.apply(7, 40, 10_000));
	}

	@Test
	public void gainsStackOnTheFloorNotOnTheStaleSiteCount()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.add(7, 100, 1, 0);
		p.add(7, 100, 1, 1_000);
		assertEquals(102, p.apply(7, 100, 2_000));
	}

	@Test
	public void theSiteCatchingUpRetiresTheFloor()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.raise(7, 42, 0);
		assertEquals(45, p.apply(7, 45, 1_000)); // a teammate's kills landed too
		assertEquals(30, p.apply(7, 30, 2_000)); // gone: the site's number rules again
	}

	@Test
	public void aFloorTheSiteNeverReachesExpires()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.raise(7, 42, 0);
		assertEquals(40, p.apply(7, 40, OptimisticProgress.TTL_MS + 1));
	}

	@Test
	public void aFailedPushClearsItsFloor()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.raise(7, 42, 0);
		p.clear(7);
		assertEquals(40, p.apply(7, 40, 1_000));
	}

	@Test
	public void readingTheFloorNeverConsumesIt()
	{
		// The panel holds a count that already includes the floor. Handing that to apply() as the
		// site's would read as "caught up", drop the floor, and wind the tile back on the next poll.
		OptimisticProgress p = new OptimisticProgress();
		p.add(7, 100, 5, 0);
		assertEquals(105, p.floor(7, 1_000));
		assertEquals(105, p.floor(7, 2_000));
		assertEquals(105, p.apply(7, 100, 3_000));       // the site still says 100
		assertEquals(0, p.floor(7, OptimisticProgress.TTL_MS + 1));
		assertEquals(0, p.floor(8, 0));
	}

	@Test
	public void aTeammatesPushedCountIsWhatOurNextGainBuildsOn()
	{
		OptimisticProgress o = new OptimisticProgress();
		o.add(7, 1_000, 10, 0); // ours: 1,010 while the config still says 1,000
		assertEquals(1_500, o.apply(7, 1_500, 1)); // a teammate's push puts the tile at 1,500
		o.add(7, 1_000, 10, 2); // our next gain, the config's count still the old one
		assertEquals("moves on from what's shown, not from the old count", 1_510, o.apply(7, 1_500, 3));
	}

	@Test
	public void virtualAltGoalIdsHoldAFloorToo()
	{
		// An either/or goal's entry carries a negative virtual tileId; its local count must still show.
		OptimisticProgress p = new OptimisticProgress();
		p.add(-96, 37, 1, 0);
		assertEquals(38, p.apply(-96, 37, 1_000));
		assertEquals(38, p.floor(-96, 1_000));
		p.raise(0, 5, 0); // 0 is still "no tile"
		assertEquals(0, p.floor(0, 1_000));
	}

	@Test
	public void aLowerSiteCountWinsAndDropsTheFloor()
	{
		OptimisticProgress p = new OptimisticProgress();
		p.seen(7, 5);
		p.add(7, 5, 3, 0);
		org.junit.Assert.assertEquals(8, p.apply(7, 5, 1));
		// A staff member deleted submissions: the site now says 2.
		org.junit.Assert.assertEquals(2, p.apply(7, 2, 2));
		// The next gain builds on 2, not on the old high mark.
		p.add(7, 2, 1, 3);
		org.junit.Assert.assertEquals(3, p.apply(7, 2, 4));
		// Cleared all the way to zero counts too.
		org.junit.Assert.assertEquals(0, p.apply(7, 0, 5));
	}

	@Test
	public void aDroppedCountAsksForARedrawOnceAndARiseDoesNot()
	{
		OptimisticProgress p = new OptimisticProgress();
		int[] redraws = {0};
		p.onDrop(() -> redraws[0]++);
		p.seen(4, 3);
		p.seen(4, 5);
		org.junit.Assert.assertEquals("rises are quiet", 0, redraws[0]);
		p.seen(4, 1);
		org.junit.Assert.assertEquals(1, redraws[0]);
		p.seen(4, 1);
		org.junit.Assert.assertEquals("the same low number again is quiet", 1, redraws[0]);
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What keeps a 1–10 minute site outage from losing notifications, counts and moments, and from
 * turning every queued thing into a request every few seconds: the retry classification, the backoff
 * schedule, the outbox's bounds, and the stash merge.
 */
public class OutageResilienceTest
{
	private ScheduledExecutorService scheduler;
	private ExecutorService pool;

	@Before
	public void setUp()
	{
		scheduler = Executors.newSingleThreadScheduledExecutor();
		pool = Executors.newSingleThreadExecutor();
	}

	@After
	public void tearDown()
	{
		scheduler.shutdownNow();
		pool.shutdownNow();
	}

	// ── RetryPolicy ───────────────────────────────────────────────────────────────────────────

	@Test
	public void permanentIsA4xxOtherThanAuthTimeoutAndRateLimit()
	{
		assertTrue(RetryPolicy.isPermanent(400));
		assertTrue(RetryPolicy.isPermanent(403));
		assertTrue(RetryPolicy.isPermanent(404));
		assertTrue(RetryPolicy.isPermanent(422));
		assertFalse("401 before X-RSN is stamped clears on its own", RetryPolicy.isPermanent(401));
		assertFalse(RetryPolicy.isPermanent(408));
		assertFalse(RetryPolicy.isPermanent(429));
		assertFalse(RetryPolicy.isPermanent(500));
		assertFalse(RetryPolicy.isPermanent(503));
		assertFalse(RetryPolicy.isPermanent(200));
	}

	@Test
	public void backoffDoublesToTheCap()
	{
		// jitter 0.5 = no spread
		assertEquals(0, RetryPolicy.backoffMs(0, 15_000, 300_000, 0.5));
		assertEquals(15_000, RetryPolicy.backoffMs(1, 15_000, 300_000, 0.5));
		assertEquals(30_000, RetryPolicy.backoffMs(2, 15_000, 300_000, 0.5));
		assertEquals(60_000, RetryPolicy.backoffMs(3, 15_000, 300_000, 0.5));
		assertEquals(240_000, RetryPolicy.backoffMs(5, 15_000, 300_000, 0.5));
		assertEquals(300_000, RetryPolicy.backoffMs(6, 15_000, 300_000, 0.5));
		assertEquals(300_000, RetryPolicy.backoffMs(500, 15_000, 300_000, 0.5));
	}

	@Test
	public void jitterSpreadsTwentyPercentAndNeverPassesTheCap()
	{
		assertEquals(12_000, RetryPolicy.backoffMs(1, 15_000, 300_000, 0));
		assertEquals(18_000, RetryPolicy.backoffMs(1, 15_000, 300_000, 1));
		assertEquals(300_000, RetryPolicy.backoffMs(9, 15_000, 300_000, 1));
		assertEquals(240_000, RetryPolicy.backoffMs(9, 15_000, 300_000, 0));
	}

	@Test
	public void syncBackoffTakesItsOwnSchedule()
	{
		SyncBackoff b = new SyncBackoff(30_000, 300_000, () -> 0.5);
		assertTrue(b.ready(0));
		b.onFailure(0);
		assertFalse(b.ready(29_999));
		assertTrue(b.ready(30_000));
		for (int i = 0; i < 10; i++)
		{
			b.onFailure(0);
		}
		assertTrue("capped at five minutes", b.ready(300_000));
		b.reset();
		assertTrue(b.ready(0));
	}

	// ── CoalescedPush ─────────────────────────────────────────────────────────────────────────

	@Test
	public void coalescedRetryStartsAtTheSettleDelayAndCapsAtFiveMinutes()
	{
		assertEquals(15_000, CoalescedPush.retryDelayMs(1, 15_000, 0.5));
		assertEquals(30_000, CoalescedPush.retryDelayMs(2, 15_000, 0.5));
		assertEquals(CoalescedPush.RETRY_CAP_MS, CoalescedPush.retryDelayMs(20, 15_000, 0.5));
	}

	@Test
	public void aPermanentRefusalDropsTheBatchInsteadOfRetryingForever()
	{
		AtomicInteger sends = new AtomicInteger();
		CoalescedPush push = new CoalescedPush("KC", 60_000, false, () -> scheduler, () -> true, b ->
		{
			sends.incrementAndGet();
			throw new BingoApiClient.PermanentSubmissionException("KC push failed: HTTP 403", 403);
		}, () -> { });
		push.queue("Vorkath", 10);
		push.flush();
		assertEquals(1, sends.get());
		assertTrue("dropped, not requeued", push.snapshot().isEmpty());
	}

	@Test
	public void aTransientFailureKeepsTheLargerValue()
	{
		CoalescedPush push = new CoalescedPush("XP", 60_000, false, () -> scheduler, () -> true, b ->
		{
			throw new IOException("Skill XP push failed: HTTP 401 — X-RSN");
		}, () -> { });
		push.queue("mining", 100);
		push.flush();
		assertEquals(Integer.valueOf(100), push.snapshot().get("mining"));
		push.reset();
	}

	@Test
	public void restoreMergesMaxPerKey()
	{
		CoalescedPush push = new CoalescedPush("KC", 60_000, false, () -> scheduler, () -> true, b -> { }, () -> { });
		push.queue("Zulrah", 50);
		Map<String, Integer> saved = new HashMap<>();
		saved.put("Zulrah", 40);
		saved.put("Vorkath", 7);
		push.restore(saved);
		assertEquals(Integer.valueOf(50), push.snapshot().get("Zulrah"));
		assertEquals(Integer.valueOf(7), push.snapshot().get("Vorkath"));
		push.reset();
	}

	// ── NotifyOutbox ──────────────────────────────────────────────────────────────────────────

	private static NotifyOutbox.Item item(long createdAt, int pngBytes)
	{
		NotifyOutbox.Item it = NotifyOutbox.newItem(createdAt);
		it.url = "https://anvilosrs.com/api/plugin/notify";
		it.channel = "drops";
		it.payload = "{}";
		it.pngBytes = pngBytes;
		return it;
	}

	@Test
	public void overflowDropsExpiredThenOldest()
	{
		long now = NotifyOutbox.MAX_AGE_MS * 3;
		NotifyOutbox.Item expired = item(now - NotifyOutbox.MAX_AGE_MS - 1, 0);
		NotifyOutbox.Item a = item(now - 3, 0);
		NotifyOutbox.Item b = item(now - 2, 0);
		NotifyOutbox.Item c = item(now - 1, 0);
		List<NotifyOutbox.Item> evict = NotifyOutbox.overflow(Arrays.asList(expired, a, b, c), now, 2, NotifyOutbox.MAX_AGE_MS, Long.MAX_VALUE);
		assertEquals(Arrays.asList(expired, a), evict);
	}

	@Test
	public void overflowKeepsScreenshotsUnderTheByteCap()
	{
		long now = 1_000_000;
		NotifyOutbox.Item a = item(now - 3, 600);
		NotifyOutbox.Item b = item(now - 2, 600);
		NotifyOutbox.Item c = item(now - 1, 600);
		List<NotifyOutbox.Item> evict = NotifyOutbox.overflow(Arrays.asList(a, b, c), now, 100, NotifyOutbox.MAX_AGE_MS, 1_300);
		assertEquals(Collections.singletonList(a), evict);
		assertTrue(NotifyOutbox.overflow(Arrays.asList(a, b), now, 100, NotifyOutbox.MAX_AGE_MS, 1_300).isEmpty());
	}

	@Test
	public void aNewEntryWaitsAboutFifteenSecondsBeforeItsFirstRetry()
	{
		NotifyOutbox.Item it = NotifyOutbox.newItem(0);
		assertTrue(it.nextAttemptAt >= 12_000 && it.nextAttemptAt <= 18_000);
	}

	@Test
	public void theOutboxCapsItsCountInMemory()
	{
		NotifyOutbox outbox = new NotifyOutbox(new Gson(), () -> scheduler, () -> pool);
		for (int i = 0; i < NotifyOutbox.MAX_ITEMS + 5; i++)
		{
			outbox.enqueue(item(System.currentTimeMillis(), 0), null);
		}
		assertEquals(NotifyOutbox.MAX_ITEMS, outbox.size());
		outbox.clear();
		assertEquals(0, outbox.size());
	}

	@Test
	public void aPassStopsAtTheFirstFailureAndDropsPermanentRefusals()
	{
		NotifyOutbox outbox = new NotifyOutbox(new Gson(), () -> scheduler, () -> pool);
		List<String> tried = new ArrayList<>();
		outbox.setSender((it, png) ->
		{
			tried.add(it.channel);
			switch (it.channel)
			{
				case "sent":
					return NotifyOutbox.Result.SENT;
				case "refused":
					return NotifyOutbox.Result.PERMANENT;
				default:
					return NotifyOutbox.Result.RETRY;
			}
		});
		for (String ch : Arrays.asList("sent", "refused", "down", "after"))
		{
			NotifyOutbox.Item it = item(System.currentTimeMillis(), 0);
			it.channel = ch;
			it.nextAttemptAt = 0;
			outbox.enqueue(it, null);
		}
		outbox.pump();
		assertEquals("one failure ends the pass", Arrays.asList("sent", "refused", "down"), tried);
		assertEquals("the failed one and the untried one wait", 2, outbox.size());
		outbox.stop();
	}

	// ── Moments + PushStash ───────────────────────────────────────────────────────────────────

	@Test
	public void restoredMomentsSkipOldOnesAndYieldToNewerSightings()
	{
		AnvilMoments moments = new AnvilMoments();
		long now = 10L * PushStash.MAX_AGE_MS;
		AnvilMoments.Moment queued = new AnvilMoments.Moment("pet", null, "Vorki", 1, null, "Vorkath", "npc", 50, now, "k1");
		moments.record(queued);
		AnvilMoments.Moment stale = new AnvilMoments.Moment("drop", 1, "x", 1, null, null, null, null, now - PushStash.MAX_AGE_MS - 1, "old");
		AnvilMoments.Moment sameKey = new AnvilMoments.Moment("pet", null, null, 1, null, null, null, null, now - 5, "k1");
		AnvilMoments.Moment fresh = new AnvilMoments.Moment("death", null, null, 1, null, "Zulrah", "npc", null, now - 5, "k2");
		moments.restore(Arrays.asList(stale, sameKey, fresh), now, PushStash.MAX_AGE_MS);
		List<AnvilMoments.Moment> all = moments.snapshot();
		assertEquals(2, all.size());
		assertEquals("Vorki", all.stream().filter(m -> m.key.equals("k1")).findFirst().get().itemName);
	}

	@Test
	public void stashKeysByHashThenNameAndNeverByNothing()
	{
		assertNull(PushStash.keyFor(null, null));
		assertNull(PushStash.keyFor("  ", ""));
		assertEquals(PushStash.keyFor("Zezima", null), PushStash.keyFor("zezima ", null));
		assertFalse(PushStash.keyFor("Zezima", "123").equals(PushStash.keyFor("Zezima", null)));
		assertEquals(16, PushStash.keyFor(null, "123").length());
	}

	@Test
	public void stashMergeKeepsTheLargerCountAndEveryMoment()
	{
		PushStash.Data a = new PushStash.Data();
		a.savedAt = 1;
		a.kc.put("Zulrah", 10);
		a.moments.add(PushStash.SavedMoment.of(new AnvilMoments.Moment("pet", null, null, 1, null, null, null, null, 1, "k1")));
		PushStash.Data b = new PushStash.Data();
		b.savedAt = 2;
		b.kc.put("Zulrah", 12);
		b.xp.put("mining", 5);
		b.moments.add(PushStash.SavedMoment.of(new AnvilMoments.Moment("death", null, null, 1, null, null, null, null, 2, "k2")));
		PushStash.Data m = PushStash.merge(a, b);
		assertEquals(2, m.savedAt);
		assertEquals(Integer.valueOf(12), m.kc.get("Zulrah"));
		assertEquals(Integer.valueOf(5), m.xp.get("mining"));
		assertEquals(2, m.moments.size());
		assertEquals("k2", m.moments.get(1).toMoment().key);
	}

	@org.junit.Test
	public void stashMergeWithNothingNewKeepsTheOlder()
	{
		PushStash.Data older = new PushStash.Data();
		older.savedAt = 5;
		org.junit.Assert.assertSame(older, PushStash.merge(older, null));
		org.junit.Assert.assertNull(PushStash.merge(null, null));
	}
}

package com.anvil;

import com.google.gson.*;
import java.awt.*;
import java.awt.event.InputEvent;
import java.awt.event.MouseEvent;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.*;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Every clickable thing on every panel page, clicked the way AWT delivers a click: a press and a release
 * on the deepest component under the pointer that takes mouse events (a label with a tooltip does).
 * Each must do something — call the host, or change the page (a segment lit, a fold opened, a pane
 * swapped in). Then everything new that click showed (a pane's Back, a drill-down) is clicked too.
 */
public class PanelClickTest {
	private static final int WIDTH = 225;
	private static final String[] FIXTURES = {"race-start", "race-mid", "race-detail", "clan-list", "clan-bingo", "clan-home",
		"clan-event", "clan-event-registered", "clan-event-going", "clan-weekly", "feed", "you", "lookup-player", "lookup-clog", "lookup-clan", "lookup-player-img", "you-img", "lookup-clan-img", "lookup-clan-plain", "feed-clan", "lookup-clan-long"};

	private static final class Host implements UiView.Host {
		int calls;
		String view;
		Map<String, String> args;
		JsonObject answer;

		@Override public void load(String view, Map<String, String> args, Consumer<JsonObject> done) {
			calls++;
			this.view = view;
			this.args = args;
			if (answer != null) done.accept(answer);
		}
		@Override public void post(String act, Map<String, String> args, Map<String, String> fields, Consumer<JsonObject> done) { calls++; }
		@Override public void site(String path) { calls++; }
		@Override public void lookup(String rsn) { calls++; }
		@Override public void clan(String slug) { calls++; }
		@Override public void pin(int event, int tile, boolean on) { calls++; }
		@Override public void switchClan(String slug) { calls++; }
		@Override public void openTab(String name, Map<String, String> args) { calls++; }
		@Override public JComponent nativePart(String name) { return null; }
	}

	private static JsonObject fixture(String name) {
		try (Reader r = new InputStreamReader(PanelClickTest.class.getResourceAsStream("race/" + name + ".json"), StandardCharsets.UTF_8)) {
			return new JsonParser().parse(r).getAsJsonObject();
		} catch (IOException e) {
			throw new UncheckedIOException(e);
		}
	}

	private static void layOut(Component c) {
		if (c instanceof Container) {
			((Container) c).doLayout();
			for (Component k : ((Container) c).getComponents()) layOut(k);
		}
	}

	/** The page sized to what it wants at panel width, laid out. */
	private static void size(JComponent root) {
		invalidate(root);
		root.setSize(WIDTH, 4000);
		layOut(root);
		root.setSize(WIDTH, root.getPreferredSize().height);
		layOut(root);
	}

	private static void invalidate(Component c) {
		c.invalidate();
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) invalidate(k);
	}

	/** What AWT would hand a click at {@code p}: the deepest component there that takes mouse events. */
	private static Component target(JComponent root, Point p) {
		Component c = SwingUtilities.getDeepestComponentAt(root, p.x, p.y);
		while (c != null && c.getMouseListeners().length == 0 && c.getMouseMotionListeners().length == 0 && c.getMouseWheelListeners().length == 0)
			c = c.getParent();
		return c;
	}

	private static boolean shown(Component c, JComponent root) {
		for (Component at = c; at != null && at != root; at = at.getParent()) if (!at.isVisible() || at.getWidth() <= 0 || at.getHeight() <= 0) return false;
		return true;
	}

	/** Everything with a click of its own (a hand cursor set on it), in tree order. */
	private static List<Component> clickables(Component c, JComponent root, List<Component> out) {
		if (c.isCursorSet() && c.getCursor().getType() == Cursor.HAND_CURSOR && shown(c, root)
			&& !(c instanceof JList) && !(c instanceof Round && ((Round) c).filled() && c.getParent() instanceof Round))
			out.add(c); // a lit segment of a switch is already picked: clicking it again rightly does nothing
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) clickables(k, root, out);
		return out;
	}

	private static String describe(Component c) {
		List<String> texts = new ArrayList<>();
		texts(c, texts);
		return c.getClass().getSimpleName() + texts;
	}

	private static void texts(Component c, List<String> out) {
		if (c instanceof JLabel && ((JLabel) c).getText() != null && !((JLabel) c).getText().isEmpty() && out.size() < 3)
			out.add(((JLabel) c).getText().replaceAll("<[^>]*>", "").trim());
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) texts(k, out);
	}

	/** What a click can change: which components are there and shown, and how labels and rounds paint. */
	private static String state(Component c) {
		StringBuilder b = new StringBuilder();
		b.append(System.identityHashCode(c)).append(c.isVisible() ? 'v' : 'h');
		if (c instanceof JLabel) b.append(((JLabel) c).getForeground().getRGB());
		if (c instanceof Round) b.append(((Round) c).filled()).append(((Round) c).edge);
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) b.append('(').append(state(k)).append(')');
		return b.toString();
	}

	/** A real left click at {@code c}'s centre; whether anything happened. */
	private static boolean click(JComponent root, Host host, Component c) {
		Point p = SwingUtilities.convertPoint(c, c.getWidth() / 2, c.getHeight() / 2, root);
		Component t = target(root, p);
		if (t == null) return false;
		lastTarget = describe(t) + "@" + p;
		Point at = SwingUtilities.convertPoint(root, p, t);
		String before = state(root);
		int calls = host.calls;
		t.dispatchEvent(new MouseEvent(t, MouseEvent.MOUSE_PRESSED, 0, InputEvent.BUTTON1_DOWN_MASK, at.x, at.y, 1, false, MouseEvent.BUTTON1));
		t.dispatchEvent(new MouseEvent(t, MouseEvent.MOUSE_RELEASED, 0, 0, at.x, at.y, 1, false, MouseEvent.BUTTON1));
		t.dispatchEvent(new MouseEvent(t, MouseEvent.MOUSE_CLICKED, 0, 0, at.x, at.y, 1, false, MouseEvent.BUTTON1));
		return host.calls != calls || !state(root).equals(before);
	}

	static String lastTarget;

	private static final class Page {
		final Host host = new Host();
		final UiView view = new UiView(host, null, null, null);

		Page(String fixture) {
			UiView.TABS.clear();
			UiView.FLIPS.clear();
			view.render(fixture(fixture));
			size(view);
		}

		List<Component> clickables() {
			return PanelClickTest.clickables(view, view, new ArrayList<>());
		}
	}

	private static List<String> clickAll(String fixture) {
		List<String> broken = new ArrayList<>();
		int n = new Page(fixture).clickables().size();
		assertTrue(fixture + " has something to click", n > 0 || fixture.startsWith("clan-event"));
		for (int i = 0; i < n; i++) {
			Page page = new Page(fixture);
			Component c = page.clickables().get(i);
			String what = fixture + ": " + describe(c);
			Set<Component> before = Collections.newSetFromMap(new IdentityHashMap<>());
			before.addAll(page.clickables());
			if (!click(page.view, page.host, c)) {
				broken.add(what + " got " + lastTarget);
				continue;
			}
			size(page.view);
			// What that click showed (a pane's Back, a section's rows), each clicked once on a fresh copy.
			List<Component> after = page.clickables();
			for (int j = 0; j < after.size(); j++) {
				if (before.contains(after.get(j))) continue;
				Page again = new Page(fixture);
				click(again.view, again.host, again.clickables().get(i));
				size(again.view);
				List<Component> shown = again.clickables();
				if (j >= shown.size()) continue;
				if (!click(again.view, again.host, shown.get(j))) broken.add(what + " > " + describe(shown.get(j)) + " got " + lastTarget);
			}
		}
		return broken;
	}

	@Test
	public void everyClickOnEveryPageDoesSomething() throws Exception {
		List<String> broken = new ArrayList<>();
		SwingUtilities.invokeAndWait(() -> {
			for (String f : FIXTURES) broken.addAll(clickAll(f));
		});
		assertEquals("clicks that did nothing:\n" + String.join("\n", broken), 0, broken.size());
	}

	/** Lookup's Players | Clans (drawn by the panel over the view): each segment picks. */
	@Test
	public void everySegmentOfASwitchPicks() throws Exception {
		List<String> picked = new ArrayList<>();
		SwingUtilities.invokeAndWait(() -> {
			JComponent strip = UiView.segments(Arrays.asList("Players", "Clans"), "Players", picked::add);
			size(strip);
			for (Component seg : strip.getComponents()) click(strip, new Host(), seg);
		});
		assertEquals(Arrays.asList("Players", "Clans"), picked);
	}

	private static JLabel label(Component c, String text) {
		if (c instanceof JLabel && text.equals(((JLabel) c).getText())) return (JLabel) c;
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) {
			JLabel l = label(k, text);
			if (l != null && l.isVisible()) return l;
		}
		return null;
	}

	/** Log → a category → one of its pages (a site answer into the slot) → Back lands on the category. */
	@Test
	public void backFromALogPageLandsOnItsCategory() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			Page page = new Page("lookup-clog");
			click(page.view, page.host, label(page.view, "Log"));
			size(page.view);
			click(page.view, page.host, label(page.view, "7/12 · 58%"));
			size(page.view);
			page.host.answer = new JsonParser().parse("{\"ui\":{\"t\":\"col\",\"c\":[{\"t\":\"text\",\"s\":\"Zulrah\",\"font\":\"bold\","
				+ "\"icon\":{\"t\":\"icon\",\"glyph\":\"chevron-left\",\"w\":10,\"h\":10},\"tip\":\"Back\",\"on\":{\"a\":\"pane\",\"into\":\"prof\",\"pane\":\"cat:Bosses\"}}]}}").getAsJsonObject();
			click(page.view, page.host, label(page.view, "812 kc"));
			size(page.view);
			assertNull("the page replaced the category", label(page.view, "812 kc"));
			assertTrue("Back clicked", click(page.view, page.host, label(page.view, "Zulrah")));
			size(page.view);
			assertNotNull("back on the category", label(page.view, "812 kc"));
			int calls = page.host.calls;
			page.view.refresh();
			size(page.view);
			assertEquals("a refresh after Back asks for nothing the reader left", calls, page.host.calls);
			assertNotNull("still on the list after a refresh", label(page.view, "812 kc"));
		});
	}

	private static Component find(Component c, String text) {
		String t = c instanceof JLabel ? ((JLabel) c).getText() : c instanceof AbstractButton ? ((AbstractButton) c).getText() : null;
		if (t != null && text.equals(t.replaceAll("<[^>]*>", "").trim()) && c.isVisible()) return c;
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) {
			Component f = find(k, text);
			if (f != null) return f;
		}
		return null;
	}

	private static Component tip(Component c, String text) {
		if (c instanceof JComponent && ((JComponent) c).getToolTipText() != null && ((JComponent) c).getToolTipText().contains(text) && shown(c, (JComponent) c)) return c;
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) {
			Component f = tip(k, text);
			if (f != null) return f;
		}
		return null;
	}

	private static final String PAGE = "{\"ui\":{\"t\":\"col\",\"c\":[{\"t\":\"text\",\"s\":\"BossPage\",\"font\":\"bold\","
		+ "\"icon\":{\"t\":\"icon\",\"glyph\":\"chevron-left\",\"w\":10,\"h\":10},\"tip\":\"Back\",\"on\":{\"a\":\"pane\",\"into\":\"prof\",\"pane\":\"main\"}}]}}";

	/** A boss on the Bosses tab opens its log page as a page of its own; Back returns to Bosses. */
	@Test
	public void aBossClickOpensItsLogPageAndBackReturnsToBosses() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			boolean opened = false;
			for (int i = 0; i < 60 && !opened; i++) {
				Page page = new Page("lookup-player");
				page.host.answer = new JsonParser().parse(PAGE).getAsJsonObject();
				click(page.view, page.host, find(page.view, "Bosses"));
				size(page.view);
				List<Component> cs = page.clickables();
				if (i >= cs.size()) break;
				click(page.view, page.host, cs.get(i));
				size(page.view);
				if (!"clog-page".equals(page.host.view)) continue;
				opened = true;
				assertEquals("main", page.host.args.get("back"));
				assertNotNull("the page replaced the card", find(page.view, "BossPage"));
				assertNull("Bosses tab gone while the page is open", find(page.view, "Bosses"));
				assertTrue(click(page.view, page.host, find(page.view, "BossPage")));
				size(page.view);
				assertNotNull("Back lands on the profile", find(page.view, "Bosses"));
			}
			assertTrue("some boss cell opens its page", opened);
		});
	}

	/** Typing an item or page name in the Log tab lists its page; clicking it opens that page directly. */
	@Test
	public void theLogSearchListsPagesAndOpensOne() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			Page page = new Page("lookup-clog");
			click(page.view, page.host, find(page.view, "Log"));
			size(page.view);
			assertNull("pages are listed only while searching", find(page.view, "Vorkath"));
			List<javax.swing.text.JTextComponent> boxes = new ArrayList<>();
			boxes(page.view, boxes);
			javax.swing.text.JTextComponent box = boxes.get(boxes.size() - 1);
			box.setText("head");
			size(page.view);
			Component row = find(page.view, "Vorkath");
			assertNotNull("an item's name finds its page", row);
			assertTrue(click(page.view, page.host, row));
			assertEquals("clog-page", page.host.view);
			assertEquals("Vorkath", page.host.args.get("page"));
			assertEquals("main", page.host.args.get("back"));
		});
	}

	private static void boxes(Component c, List<javax.swing.text.JTextComponent> out) {
		if (c instanceof javax.swing.text.JTextComponent && c.isShowing() == c.isShowing()) out.add((javax.swing.text.JTextComponent) c);
		if (c instanceof Container) for (Component k : ((Container) c).getComponents()) boxes(k, out);
	}

	/** A goal's visible x asks inline first; No puts it back. */
	@Test
	public void aGoalsRemoveButtonAsksInline() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			Page page = new Page("you");
			Component x = tip(page.view, "Remove goal");
			assertNotNull("each goal has a visible remove x", x);
			assertTrue(click(page.view, page.host, x));
			size(page.view);
			Component no = find(page.view, "No");
			assertNotNull("asked inline", no);
			assertNotNull(find(page.view, "Yes, remove"));
			assertTrue(click(page.view, page.host, no));
			size(page.view);
			assertNull("back to the goal", find(page.view, "No"));
		});
	}

	/** A filter click that is a site round trip shows "Loading…" in its slot at once, then the answer. */
	@Test
	public void aSlotLoadShowsLoadingAtOnce() throws Exception {
		SwingUtilities.invokeAndWait(() -> {
			Page page = new Page("lookup-clog");
			JsonObject view = new JsonParser().parse("{\"ui\":{\"t\":\"slot\",\"id\":\"cas\",\"c\":{\"t\":\"text\",\"s\":\"Old list\"}}}").getAsJsonObject();
			page.view.render(view);
			size(page.view);
			assertNotNull(find(page.view, "Old list"));
			Host held = new Host();
			UiView v = new UiView(held, null, null, null);
			v.render(view);
			size(v);
			v.act(new JsonParser().parse("{\"a\":\"load\",\"v\":\"cas\",\"into\":\"cas\"}").getAsJsonObject());
			size(v);
			assertNotNull("loading shows at once", find(v, "Loading..."));
			assertNull(find(v, "Old list"));
		});
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Pins the personal-best parsing to REAL in-game completion messages.
 *
 * <p>The case that matters most is the explicit form: "Duration: 172:18. Personal best: 134:52"
 * contains two times, and reading the first one would file a bad run as somebody's record.
 */
public class PersonalBestParserTest
{
	@Test
	public void newPersonalBestTakesTheRunsOwnDuration()
	{
		// Inferno, and the generic boss fight timer.
		assertEquals(Integer.valueOf(17803), PersonalBestParser.parseCentis("Duration: 2:58.03 (new personal best)"));
		assertEquals(Integer.valueOf(9600), PersonalBestParser.parseCentis("Fight duration: 1:36 (new personal best)"));
		// Barracuda Trials print "Time:" instead of "Duration:".
		assertEquals(Integer.valueOf(36420), PersonalBestParser.parseCentis("Time: 6:04.20 (new personal best)."));
	}

	@Test
	public void explicitPersonalBestIgnoresThisRunsSlowerTime()
	{
		// The whole point: 172:18 is this run, 134:52 is the record.
		assertEquals(Integer.valueOf(809200), PersonalBestParser.parseCentis("Duration: 172:18. Personal best: 134:52"));
		assertEquals(Integer.valueOf(47900), PersonalBestParser.parseCentis("Challenge duration: 10:24. Personal best: 7:59."));
	}

	@Test
	public void hoursMinutesSecondsAreReadAsThreeParts()
	{
		// 1:02:03 is an hour and change, not one minute two seconds.
		assertEquals(Integer.valueOf(372300), PersonalBestParser.parseCentis("Duration: 1:02:03 (new personal best)"));
	}

	@Test
	public void fractionsPadToHundredths()
	{
		// ".3" is three tenths — 30 centiseconds, not 3.
		assertEquals(Integer.valueOf(6030), PersonalBestParser.parseCentis("Duration: 1:00.3 (new personal best)"));
		assertEquals(Integer.valueOf(6003), PersonalBestParser.parseCentis("Duration: 1:00.03 (new personal best)"));
	}

	@Test
	public void linesWithoutAPersonalBestAreIgnored()
	{
		// An ordinary clear is not a record, and must not overwrite one.
		assertNull(PersonalBestParser.parseCentis("Duration: 2:58.03"));
		assertNull(PersonalBestParser.parseCentis("Congratulations - your raid is complete! Duration: 15:39"));
		assertNull(PersonalBestParser.parseCentis("Your Zulrah kill count is: 1,204."));
		assertNull(PersonalBestParser.parseCentis(null));
		// The words with no time attached: nothing to record.
		assertNull(PersonalBestParser.parseCentis("You have a new personal best!"));
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PB capture: correlating a time with the activity that earned it, and never letting a slower run
 * overwrite a record.
 *
 * <p>Both message orderings are tested because the game uses both — the Inferno prints its duration
 * before the kill count, most bosses print it after.
 */
public class PersonalBestsTest
{
	@Test
	public void killCountThenDuration()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 1_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void durationThenKillCount()
	{
		PersonalBests pbs = new PersonalBests();
		// The Inferno's ordering: the time lands with nothing to attach it to yet.
		assertFalse(pbs.onChatLine("Duration: 2:58.03 (new personal best)", 1_000));
		assertTrue(pbs.nextBatch().isEmpty());
		pbs.onActivitySeen("TzKal-Zuk", 1_200);
		assertEquals(Integer.valueOf(17803), pbs.nextBatch().get("tzkal-zuk"));
	}

	@Test
	public void aStaleActivityIsNotCredited()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		// Ten minutes later, an unrelated PB line must not be filed under Zulrah.
		assertFalse(pbs.onChatLine("Duration: 1:00 (new personal best)", 600_000));
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void anOrphanTimeExpiresRatherThanAttachingToTheNextBoss()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onChatLine("Duration: 1:00 (new personal best)", 0);
		// A different boss, long after: the loose time must not land on it.
		pbs.onActivitySeen("Vorkath", 600_000);
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void onlyFasterTimesReplaceARecord()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Vorkath", 0);
		assertTrue(pbs.onChatLine("Fight duration: 1:30 (new personal best)", 10));
		pbs.onActivitySeen("Vorkath", 1_000);
		// A slower run reported as an explicit PB line still can't raise the record.
		assertFalse(pbs.onChatLine("Fight duration: 2:00. Personal best: 1:30.", 1_010));
		assertEquals(Integer.valueOf(9000), pbs.nextBatch().get("vorkath"));
		// A faster one does.
		pbs.onActivitySeen("Vorkath", 2_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:12 (new personal best)", 2_010));
		assertEquals(Integer.valueOf(7200), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void seedingAdoptsOnlyImprovements()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);

		Map<String, Integer> imported = new HashMap<>();
		imported.put("Zulrah", 12000);  // slower than what we have — ignored
		imported.put("Vorkath", 8000);  // new — adopted
		assertEquals(1, pbs.seed(imported, 100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void flushWaitsForQuiet()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_000);
		assertFalse(pbs.isDue(1_000 + PersonalBests.QUIET_MS - 1));
		assertTrue(pbs.isDue(1_000 + PersonalBests.QUIET_MS));
	}

	@Test
	public void stateSurvivesARestartAndIsNotResent()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Chambers of Xeric: Challenge Mode", 0);
		pbs.onChatLine("Duration: 40:00 (new personal best)", 10);
		pbs.onSent(pbs.nextBatch());
		String state = pbs.serializeState();

		PersonalBests restarted = new PersonalBests();
		restarted.restoreState(state);
		assertEquals(0, restarted.pendingCount());
		// A slower run after the restart is still not a record.
		restarted.onActivitySeen("Chambers of Xeric: Challenge Mode", 100);
		assertFalse(restarted.onChatLine("Duration: 45:00 (new personal best)", 110));
	}

	@Test
	public void anImprovementMidFlightStaysPending()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);
		Map<String, Integer> inFlight = pbs.nextBatch();
		// A better time lands while the request is on the wire.
		pbs.onActivitySeen("Zulrah", 20);
		pbs.onChatLine("Fight duration: 1:20 (new personal best)", 30);
		pbs.onSent(inFlight);
		assertEquals(1, pbs.pendingCount());
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void ordinaryChatCostsNothingAndRecordsNothing()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		assertFalse(pbs.onChatLine("Your Zulrah kill count is: 1,204.", 10));
		assertFalse(pbs.onChatLine("Oh dear, you are dead!", 20));
		assertNull(pbs.nextBatch().get("zulrah"));
	}
}

