package com.anvil;

import com.google.gson.*;
import org.junit.Test;

import static org.junit.Assert.*;

public class PushMergeTest
{
	private static JsonObject json(String s)
	{
		return new Gson().fromJson(s.replace('\'', '"'), JsonObject.class);
	}

	private static final JsonObject HELD = json("{"
		+ "'codeword':'ABC123','player':{'id':7},"
		+ "'event':{'id':5,'name':'Old name','standings':{'rank':3}},"
		+ "'trackedKills':[{'tileId':1,'currentAmount':9}],"
		+ "'panel':{'tiles':[],'activeNow':[],'scheduled':[{'id':2}]}}");

	private static final JsonObject TEAM = json("{"
		+ "'event':{'id':5,'name':'New name'},"
		+ "'trackedKills':[{'tileId':1,'currentAmount':0},{'tileId':2,'currentAmount':6}],"
		+ "'tiles':[{'t':1,'have':0,'of':5},{'t':2,'have':6,'of':10}],"
		+ "'panel':{'tiles':[{'tileId':1,'current':0,'goal':5,'complete':false},{'tileId':2,'current':6,'goal':10,'complete':false}],"
		+ "'activeNow':[{'tileId':2,'workers':['Mate','redman'],'self':false,'gains':{'redman':40,'Mate':10}}]}}");

	@Test
	public void teamFieldsReplaceOursAndCallerOnlyFieldsSurvive()
	{
		JsonObject out = PushMerge.merge(HELD, TEAM, null);
		assertEquals("ABC123", out.get("codeword").getAsString());
		assertEquals("New name", out.getAsJsonObject("event").get("name").getAsString());
		assertEquals("a ladder rank is ours, not the team's", 3, out.getAsJsonObject("event").getAsJsonObject("standings").get("rank").getAsInt());
		assertEquals(2, out.getAsJsonArray("trackedKills").size());
		assertEquals("the schedule is ours", 1, out.getAsJsonObject("panel").getAsJsonArray("scheduled").size());
		assertEquals("Old name", HELD.getAsJsonObject("event").get("name").getAsString());
	}

	@Test
	public void ourOwnNumbersGoOnPerMemberTiles()
	{
		JsonObject mine = json("{'c':{'1':5}}");
		JsonObject out = PushMerge.merge(HELD, TEAM, mine);
		assertEquals(5, out.getAsJsonArray("trackedKills").get(0).getAsJsonObject().get("currentAmount").getAsInt());
		assertEquals("a team tile keeps the team's count", 6, out.getAsJsonArray("trackedKills").get(1).getAsJsonObject().get("currentAmount").getAsInt());
		assertEquals("the count list takes ours too", 5, out.getAsJsonArray("tiles").get(0).getAsJsonObject().get("have").getAsInt());
		assertEquals(6, out.getAsJsonArray("tiles").get(1).getAsJsonObject().get("have").getAsInt());
	}
}

package com.anvil;

import com.google.gson.*;
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;
import okio.ByteString;
import org.junit.*;

import static org.junit.Assert.*;

public class PushSocketTest
{
	/** A socket that only remembers whether it was closed. */
	private static final class FakeSocket implements WebSocket
	{
		boolean closed;

		@Override public Request request() { return null; }
		@Override public long queueSize() { return 0; }
		@Override public boolean send(String text) { return true; }
		@Override public boolean send(ByteString bytes) { return true; }
		@Override public boolean close(int code, String reason) { closed = true; return true; }
		@Override public void cancel() { closed = true; }
	}

	/** Hands out a ticket (or none) and records every socket it opened. */
	private static final class FakeApi extends BingoApiClient
	{
		final List<FakeSocket> opened = new CopyOnWriteArrayList<>();
		volatile boolean ticketsAvailable = true;
		volatile int ticketsAsked;

		FakeApi()
		{
			super(new Gson(), new OkHttpClient());
		}

		@Override
		PushTicket fetchPushTicket(boolean feed, boolean rows)
		{
			ticketsAsked++;
			if (!ticketsAvailable)
			{
				return null;
			}
			PushTicket t = new PushTicket();
			t.url = "wss://anvilosrs.com/api/plugin/push/ws";
			t.ticket = "t" + ticketsAsked;
			return t;
		}

		/** The ticket fetch runs inline, so a test sees its socket as soon as the executor settles. */
		@Override
		public ExecutorService interactiveExecutor()
		{
			return new AbstractExecutorService()
			{
				@Override public void execute(Runnable r) { r.run(); }
				@Override public void shutdown() { }
				@Override public List<Runnable> shutdownNow() { return Collections.emptyList(); }
				@Override public boolean isShutdown() { return false; }
				@Override public boolean isTerminated() { return false; }
				@Override public boolean awaitTermination(long t, TimeUnit u) { return true; }
			};
		}

		@Override
		WebSocket openPush(PushTicket ticket, WebSocketListener listener)
		{
			FakeSocket s = new FakeSocket();
			opened.add(s);
			return s;
		}
	}

	private ScheduledExecutorService executor;
	private FakeApi api;
	private PushSocket push;
	private final List<JsonObject> heard = new CopyOnWriteArrayList<>();

	@Before
	public void setUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor();
		api = new FakeApi();
		push = new PushSocket(api, executor, new Gson(), heard::add);
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private void settle() throws Exception
	{
		executor.submit(() -> { }).get(2, TimeUnit.SECONDS);
	}

	@Test
	public void connectsForAScopeAndGoesLiveOnHello() throws Exception
	{
		push.scope("5:2");
		settle();
		assertEquals(1, api.opened.size());
		assertFalse(push.live());

		push.onMessage(api.opened.get(0), "{\"t\":\"hello\"}");
		assertTrue(push.live());
		// Passed on too: on (re)connecting the plugin checks its Supporter list version (ChatFlairSync).
		assertEquals(1, heard.size());
		assertEquals("hello", heard.get(0).get("t").getAsString());
		push.onMessage(api.opened.get(0), "{\"t\":\"tile\",\"eventId\":5,\"tileId\":9}");
		push.onMessage(api.opened.get(0), "not json");
		assertEquals(2, heard.size());
		assertEquals(9, heard.get(1).get("tileId").getAsInt());
	}

	@Test
	public void sameScopeIsANoOpAndANewOneReTickets() throws Exception
	{
		push.scope("5:2");
		push.scope("5:2");
		settle();
		assertEquals(1, api.opened.size());

		push.scope("6:3");
		settle();
		assertTrue("the old board's socket is closed", api.opened.get(0).closed);
		assertEquals(2, api.opened.size());
	}

	@Test
	public void anExpiredTicketReconnectsAtOnce() throws Exception
	{
		push.scope("5:2");
		settle();
		FakeSocket first = api.opened.get(0);
		push.onMessage(first, "{\"t\":\"hello\"}");

		push.onClosing(first, 4001, "ticket expired");
		assertFalse(push.live());
		settle();
		assertEquals(2, api.opened.size());
		assertEquals(2, api.ticketsAsked);
	}

	@Test
	public void stoppingClosesAndNeverReconnects() throws Exception
	{
		push.scope("5:2");
		settle();
		push.onMessage(api.opened.get(0), "{\"t\":\"hello\"}");

		push.scope(null);
		assertTrue(api.opened.get(0).closed);
		assertFalse(push.live());
		push.onFailure(api.opened.get(0), new java.io.IOException("gone"), null);
		settle();
		assertEquals(1, api.opened.size());
	}

	@Test
	public void noTicketBacksOffInsteadOfSpinning() throws Exception
	{
		api.ticketsAvailable = false;
		push.scope("5:2");
		settle();
		settle();
		assertEquals("one ask, then a wait of seconds", 1, api.ticketsAsked);
		assertTrue(api.opened.isEmpty());
	}

	@Test
	public void aReplacedSocketIsIgnored() throws Exception
	{
		push.scope("5:2");
		settle();
		FakeSocket old = api.opened.get(0);
		push.scope("6:3");
		settle();

		push.onMessage(old, "{\"t\":\"hello\"}");
		assertFalse(push.live());
		assertTrue(heard.isEmpty());
		push.onFailure(old, new java.io.IOException("late"), null);
		settle();
		assertEquals("a late failure of the old socket doesn't reconnect", 2, api.opened.size());
	}
}

