package com.anvil;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** The clan dropdown: one row per clan with a slug, "All clans" first, each saying what's running there. */
public class SidebarEventsTest
{
	private static PluginConfigResponse.ClanRef clanRef(String slug, String name, String kind, String live)
	{
		return clanRef(slug, name, kind, live, live == null ? 0 : Math.abs(live.hashCode()));
	}

	private static PluginConfigResponse.ClanRef clanRef(String slug, String name, String kind, String live, int eventId)
	{
		return clanRef(slug, name, kind, live, eventId, "bingo");
	}

	private static PluginConfigResponse.ClanRef clanRef(String slug, String name, String kind, String live,
		int eventId, String liveKind)
	{
		PluginConfigResponse.ClanRef c = new PluginConfigResponse.ClanRef();
		c.slug = slug;
		c.name = name;
		c.kind = kind;
		if (live != null)
		{
			c.live = new PluginConfigResponse.ClanBoard();
			c.live.kind = liveKind;
			c.live.eventId = eventId;
			c.live.eventName = live;
			if (!"weekly".equals(liveKind))
			{
				c.live.tilesComplete = 3;
				c.live.tilesTotal = 9;
			}
		}
		return c;
	}

	@Test
	public void noClansMeansNoDropdownAtAll()
	{
		assertTrue(AnvilSidebarPanel.ClanChoice.of(null).isEmpty());
		assertTrue(AnvilSidebarPanel.ClanChoice.of(java.util.Collections.emptyList()).isEmpty());
	}
	@Test
	public void allClansLeadsTheList()
	{
		List<AnvilSidebarPanel.ClanChoice> choices = AnvilSidebarPanel.ClanChoice.of(Arrays.asList(
			clanRef("theafkspot", "The AFK Spot", "member", "Summer Bingo"),
			clanRef("vanguard", "Iron Vanguard", "guest", null)));

		assertEquals(3, choices.size());
		assertEquals("", choices.get(0).slug);
		assertEquals("All clans", choices.get(0).label);
		assertEquals("theafkspot", choices.get(1).slug);
		assertEquals("vanguard", choices.get(2).slug);
	}
	@Test
	public void eachRowSaysWhatIsRunningThere()
	{
		List<AnvilSidebarPanel.ClanChoice> choices = AnvilSidebarPanel.ClanChoice.of(Arrays.asList(
			clanRef("a", "Alpha", "member", "Summer Bingo"),
			clanRef("b", "Bravo", "guest", null),
			clanRef("c", "Charlie", "member", null)));

		// The board is the reason to pick one clan over another, so it is the second line.
		assertEquals("Summer Bingo  3/9", choices.get(1).detail);
		assertEquals("Guest \u00b7 nothing live", choices.get(2).detail);
		assertEquals("Nothing live", choices.get(3).detail);
	}
	@Test
	public void aClanWithNoNameFallsBackToItsSlugRatherThanRenderingBlank()
	{
		List<AnvilSidebarPanel.ClanChoice> choices =
			AnvilSidebarPanel.ClanChoice.of(Arrays.asList(clanRef("theafkspot", null, "member", null)));
		assertEquals("theafkspot", choices.get(1).label);
	}
	@Test
	public void aRowWithNoSlugIsNotOfferedBecauseItCannotBeAddressed()
	{
		// A slug is what a pick BECOMES — the /c/<slug> the client starts addressing. A row without one
		// would look selectable and then quietly do nothing.
		List<AnvilSidebarPanel.ClanChoice> choices = AnvilSidebarPanel.ClanChoice.of(Arrays.asList(
			clanRef(null, "Nameless", "member", null),
			clanRef("", "Empty", "member", null),
			clanRef("real", "Real", "member", null)));

		assertEquals(2, choices.size());
		assertEquals("real", choices.get(1).slug);
	}

	@Test
	public void someoneInClansAndSpacesSeesWhichRowIsASpace()
	{
		PluginConfigResponse.ClanRef space = clanRef("ahmed", "Ahmed", "guest", "Viewer Bingo");
		space.space = true;
		PluginConfigResponse.ClanRef quiet = clanRef("deno", "Deno", "guest", null);
		quiet.space = true;
		List<AnvilSidebarPanel.ClanChoice> choices = AnvilSidebarPanel.ClanChoice.of(Arrays.asList(
			clanRef("theafkspot", "The AFK Spot", "member", null), space, quiet));

		assertEquals("All clans & spaces", choices.get(0).label);
		assertEquals("Nothing live", choices.get(1).detail);
		assertEquals("Space \u00b7 Viewer Bingo  3/9", choices.get(2).detail);
		assertEquals("Space \u00b7 nothing live", choices.get(3).detail);
	}

	@Test
	public void onlySpacesSaysAllSpaces()
	{
		PluginConfigResponse.ClanRef a = clanRef("a", "A", "guest", null);
		a.space = true;
		PluginConfigResponse.ClanRef b = clanRef("b", "B", "guest", null);
		b.space = true;
		assertEquals("All spaces", AnvilSidebarPanel.ClanChoice.of(Arrays.asList(a, b)).get(0).label);
	}
}

package com.anvil;

import javax.swing.plaf.basic.BasicHTML;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * §2/§6 — the Swing plain-text guard for federated strings. A {@link javax.swing.JLabel} renders as HTML when
 * its text begins with {@code <html}, so an untrusted clan/tile/activity name could inject markup;
 * {@link AnvilSidebarPanel#plainText(String)} (which every federated field routes through) must neutralize it.
 * The authoritative check is {@link BasicHTML#isHTMLString(String)} — exactly what the label UI uses; if it
 * returns {@code false} for our output, Swing renders verbatim (no markup, no injection).
 */
public class SidebarTextSafetyTest
{
	@Test
	public void htmlInjectedNameRendersAsLiteralText()
	{
		String injected = "<html><b>pwned</b><img src=x></html>";
		assertTrue("precondition: the raw string WOULD be treated as HTML by a JLabel",
			BasicHTML.isHTMLString(injected));

		String safe = Ui.plainText(injected);
		assertFalse("sanitized federated string must NOT be treated as HTML", BasicHTML.isHTMLString(safe));
		assertFalse("no live '<html' prefix survives", safe.toLowerCase().startsWith("<html"));
		assertTrue("the intended text is still visible (as literal, escaped markup)", safe.contains("pwned"));
	}

	@Test
	public void neutralizesLeadingWhitespaceAndMixedCase()
	{
		// A JLabel trims leading whitespace before its HTML sniff, and the tag match is case-insensitive.
		for (String injected : new String[] { "   <HTML>x</HTML>", "\t<Html><i>y</i>", "<html>" })
		{
			String safe = Ui.plainText(injected);
			assertFalse("‘" + injected + "’ must not render as HTML", BasicHTML.isHTMLString(safe));
		}
	}

	@Test
	public void ordinaryStringsPassThroughUnchanged()
	{
		assertEquals("Clan A", Ui.plainText("Clan A"));
		assertEquals("Any barrows item", Ui.plainText("Any barrows item"));
		assertEquals("You + Kayle", Ui.plainText("You + Kayle"));
		// A stray '<' that isn't the HTML trigger is left alone (JLabel wouldn't treat it as HTML either).
		assertEquals("<3 clan", Ui.plainText("<3 clan"));
		assertFalse(BasicHTML.isHTMLString(Ui.plainText("<3 clan")));
	}

	@Test
	public void nullBecomesEmpty()
	{
		assertEquals("", Ui.plainText(null));
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * When the plugin is allowed to reach the network, and when it offers to sign in.
 *
 * The site is fixed (BingoApiClient.CANONICAL_SITE). What this pins is the explicit sign-in gate: an
 * install nobody signs into contacts nothing. The client only takes the address once it holds a
 * token, every poll bails on an empty address, and sign-in itself (run before a token exists) goes to
 * the constant directly on an explicit click.
 */
public class SignInGateTest
{
	private BingoApiClient client()
	{
		return new BingoApiClient(new Gson(), new OkHttpClient());
	}

	@Test
	public void aFreshInstallKnowsNoSite()
	{
		// Nothing configured: no address, so nothing to call.
		assertEquals("", client().getApiUrl());
	}

	@Test
	public void signInIsOfferedBeforeASiteIsKnown()
	{
		// It used to require a URL, which hid the button that would have configured them behind the
		// configuration it was meant to perform.
		BingoApiClient c = client();
		assertTrue("a fresh install is offered the way in", c.needsSignIn());
	}

	@Test
	public void signInStopsBeingOfferedOnceThereIsAToken()
	{
		BingoApiClient c = client();
		c.configure("tok");
		assertFalse(c.needsSignIn());
		assertEquals("signed in: talking to the one site", BingoApiClient.CANONICAL_SITE, c.getApiUrl());
	}

	@Test
	public void signingOutTakesTheAddressAway()
	{
		BingoApiClient c = client();
		c.configure("tok");
		c.configure("");
		assertTrue(c.needsSignIn());
		assertEquals("no token, no address — nothing polls", "", c.getApiUrl());
		c.configure("   ");
		assertEquals("blank is no token", "", c.getApiUrl());
	}

	@Test
	public void signInGoesToTheFixedSiteBeforeThereIsAToken()
	{
		assertEquals("https://anvilosrs.com/api/plugin/auth/start", BingoApiClient.authUrl("/api/plugin/auth/start"));
	}

	@Test
	public void theCanonicalSiteIsAnAbsoluteHttpsAddress()
	{
		// Every request URL is built by appending a path to it, so a trailing slash would double up.
		assertEquals("https://anvilosrs.com", BingoApiClient.CANONICAL_SITE);
		assertTrue(BingoApiClient.CANONICAL_SITE.startsWith("https://"));
		assertFalse(BingoApiClient.CANONICAL_SITE.endsWith("/"));
	}
}

package com.anvil;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.atomic.AtomicInteger;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * STARTING SHOT (site lib/startProof) — the plugin half. Covers what the sidebar is allowed to ask
 * for ({@link AnvilSidebarDataSource#startProof()}) and the one retry rule that keeps a real drop
 * from being thrown away while a screenshot is outstanding.
 */
public class StartProofTest
{
	private static PluginConfigResponse liveConfig()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.id = 7;
		cfg.event.name = "Summer Bingo";
		cfg.event.startDate = Instant.now().minus(1, ChronoUnit.HOURS).toString();
		cfg.event.endDate = Instant.now().plus(1, ChronoUnit.DAYS).toString();
		cfg.team = new PluginConfigResponse.TeamInfo();
		cfg.team.name = "Team Molten";
		return cfg;
	}

	private static PluginConfigResponse.StartProof owed()
	{
		PluginConfigResponse.StartProof sp = new PluginConfigResponse.StartProof();
		sp.required = true;
		sp.drawn = true;
		sp.location = "Edgeville bank";
		sp.keyword = "ANVIL-GRAPE-47";
		sp.needsUpload = true;
		return sp;
	}

	private static AnvilSidebarDataSource sourceFor(PluginConfigResponse cfg)
	{
		return new AnvilSidebarDataSource(() -> cfg, new BingoApiClient(new Gson(), new OkHttpClient()));
	}

	@Test
	public void owedShotIsOfferedWhileTheEventIsLive()
	{
		PluginConfigResponse cfg = liveConfig();
		cfg.startProof = owed();

		PluginConfigResponse.StartProof offered = sourceFor(cfg).startProof();
		assertNotNull(offered);
		assertEquals("Edgeville bank", offered.location);
		assertEquals("ANVIL-GRAPE-47", offered.keyword);
	}

	@Test
	public void nothingIsAskedForWhenNothingIsOwed()
	{
		// No starting-shot block at all — an event without the rule, or a site that predates it.
		assertNull(sourceFor(liveConfig()).startProof());

		// Required but not yet drawn: the event hasn't started, so there is no location and no keyword.
		PluginConfigResponse notDrawn = liveConfig();
		notDrawn.startProof = owed();
		notDrawn.startProof.drawn = false;
		assertNull(sourceFor(notDrawn).startProof());

		// Already filed — the server says the obligation is settled.
		PluginConfigResponse filed = liveConfig();
		filed.startProof = owed();
		filed.startProof.needsUpload = false;
		assertNull(sourceFor(filed).startProof());
	}

	@Test
	public void endedEventNeverAsksForAShot()
	{
		PluginConfigResponse over = liveConfig();
		over.startProof = owed();
		over.event.endDate = Instant.now().minus(1, ChronoUnit.MINUTES).toString();
		assertNull(sourceFor(over).startProof());

		PluginConfigResponse forceEnded = liveConfig();
		forceEnded.startProof = owed();
		forceEnded.event.forceEndedAt = Instant.now().toString();
		assertNull(sourceFor(forceEnded).startProof());
	}

	@Test
	public void captureRunsTheBoundActionAndIsSafeWithoutOne()
	{
		AnvilSidebarDataSource ds = sourceFor(liveConfig());
		ds.captureStartProof(); // unbound (tests, or before the plugin wires itself up) — must not throw

		AtomicInteger fired = new AtomicInteger();
		ds.setStartProofCapture(fired::incrementAndGet);
		ds.captureStartProof();
		assertEquals(1, fired.get());
	}

	private static PluginConfigResponse.StartProof checked()
	{
		PluginConfigResponse.StartProof sp = owed();
		sp.spot = new PluginConfigResponse.StartProof.Spot();
		sp.spot.x = 3094;
		sp.spot.y = 3491;
		sp.spot.radius = 25;
		sp.maxSessionMinutes = 15;
		return sp;
	}

	private static final long NOW = 1_800_000_000_000L;

	@Test
	public void aShotFromTheSpotOnAFreshSessionIsLetThrough()
	{
		// Six squares out, five minutes into the session: nothing to complain about.
		assertNull(StartProofRules.blockReason(checked(), NOW - 5 * 60_000L, NOW, 3100, 3489));
	}

	@Test
	public void standingSomewhereElseIsRefusedBeforeTheFrameIsGrabbed()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, 2400, 3489);
		assertNotNull(reason);
		// The distance is the useful half of the message — "go to Edgeville bank" alone reads like a
		// bug when you believe you ARE at Edgeville bank.
		assertTrue(reason, reason.contains("694"));
		assertTrue(reason, reason.contains("Edgeville bank"));
	}

	@Test
	public void aSessionOlderThanTheWindowIsRefused()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 130 * 60_000L, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.contains("2h 10m"));
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void notKnowingWhenTheSessionStartedCountsAsStale()
	{
		// Plugin enabled mid-session: we can't vouch for the logout that flushed the hiscores, and
		// "probably fine" is exactly the answer this rule exists to stop giving.
		String reason = StartProofRules.blockReason(checked(), StartProofRules.UNKNOWN_LOGIN, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void checksThatCannotRunNeverBlock()
	{
		// An older site: no pin, no window. Exactly the behaviour before any of this existed.
		assertNull(StartProofRules.blockReason(owed(), StartProofRules.UNKNOWN_LOGIN, NOW, 2400, 3489));

		// Pinned spot, but logged out / no position to read — the distance check simply doesn't run.
		PluginConfigResponse.StartProof spotOnly = checked();
		spotOnly.maxSessionMinutes = 0;
		assertNull(StartProofRules.blockReason(spotOnly, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));

		// Session window on, position unknown, session fresh: still fine.
		assertNull(StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, null, null));

		// And nothing owed at all can't block anything.
		assertNull(StartProofRules.blockReason(null, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));
	}

	@Test
	public void distanceIsMeasuredTheWayTheGameMeasuresIt()
	{
		PluginConfigResponse.StartProof sp = checked();
		// The longer axis wins — 30 east and 4 north is 30 squares away, not 34.
		assertEquals(30, StartProofRules.distance(sp, 3124, 3495));
		assertEquals(0, StartProofRules.distance(sp, 3094, 3491));
		// Nothing to measure against.
		assertEquals(-1, StartProofRules.distance(owed(), 3094, 3491));
		assertEquals(-1, StartProofRules.distance(sp, null, null));
	}

	@Test
	public void describeWindowCountsDownAndThenGivesUp()
	{
		PluginConfigResponse.StartProof sp = owed();
		long now = java.time.Instant.parse("2026-08-16T19:00:00Z").toEpochMilli();
		sp.windowEndsAt = "2026-08-17T00:00:00Z";
		assertEquals("5h 00m", StartProofRules.describeWindow(sp, now));

		// Past the end there is nothing to quote — the ask has lapsed, it hasn't been failed.
		sp.windowEndsAt = "2026-08-16T18:30:00Z";
		assertEquals(null, StartProofRules.describeWindow(sp, now));

		// A site too old to send one, and a stamp we can't read, both say nothing rather than lying.
		sp.windowEndsAt = null;
		assertEquals(null, StartProofRules.describeWindow(sp, now));
		sp.windowEndsAt = "not a date";
		assertEquals(null, StartProofRules.describeWindow(sp, now));
	}

	@Test
	public void awaitingAStartingShotIsRetryable()
	{
		// 409 is normally a permanent 4xx — but this one clears the moment the player files their
		// shot, and the pending drop must survive until then.
		java.io.IOException awaiting = BingoApiClient.submissionError(
			"Submission failed", 409, "{\"error\":\"Upload your starting shot first\",\"code\":\"start_proof_required\"}");
		assertTrue(!(awaiting instanceof BingoApiClient.PermanentSubmissionException));

		// Any other 409 stays permanent (tile already complete, etc.) so it can't loop forever.
		java.io.IOException other = BingoApiClient.submissionError(
			"Submission failed", 409, "{\"error\":\"Tile already complete\"}");
		assertTrue(other instanceof BingoApiClient.PermanentSubmissionException);
	}

	@Test
	public void chatGetsTheSitesSentenceNotTheRawResponse()
	{
		java.io.IOException refused = BingoApiClient.submissionError(
			"Start proof failed", 403, "{\"error\":\"Sign-ups are closed\",\"code\":\"closed\"}");
		assertEquals("Sign-ups are closed", BingoApiClient.forPlayer(refused));
		// The diagnostic form stays on getMessage() for the log.
		assertTrue(refused.getMessage().contains("HTTP 403"));

		java.io.IOException noWords = BingoApiClient.submissionError("Start proof failed", 503, "<html>oops</html>");
		assertEquals("the clan's site is having trouble", BingoApiClient.forPlayer(noWords));
		assertEquals("couldn't reach the site", BingoApiClient.forPlayer(new java.io.IOException("timeout")));
	}

	// ── Live checks on the card — the same thresholds the button refuses on ───────────────────────

	private static PluginConfigResponse.StartProof pinned(int maxMinutes)
	{
		PluginConfigResponse.StartProof sp = owed();
		sp.maxSessionMinutes = maxMinutes;
		sp.spot = new PluginConfigResponse.StartProof.Spot();
		sp.spot.x = 3329;
		sp.spot.y = 3233;
		sp.spot.radius = 25;
		return sp;
	}

	@Test
	public void freshSessionIsGreenStaleOrUnknownIsRed()
	{
		long now = 10_000_000L;
		PluginConfigResponse.StartProof sp = pinned(15);
		assertEquals(StartProofRules.Check.State.OK,
			StartProofRules.sessionCheck(sp, now - 3 * 60_000L, now).state);
		assertEquals(StartProofRules.Check.State.BAD,
			StartProofRules.sessionCheck(sp, now - 24 * 60_000L, now).state);
		assertEquals(StartProofRules.Check.State.BAD,
			StartProofRules.sessionCheck(sp, StartProofRules.UNKNOWN_LOGIN, now).state);
		assertNull("not asked for", StartProofRules.sessionCheck(pinned(0), now, now));
	}

	@Test
	public void positionIsGreenInsideTheRadiusOnly()
	{
		PluginConfigResponse.StartProof sp = pinned(15);
		assertEquals(StartProofRules.Check.State.OK, StartProofRules.positionCheck(sp, 3340, 3250).state);
		assertEquals(StartProofRules.Check.State.BAD, StartProofRules.positionCheck(sp, 3290, 3170).state);
		assertEquals(StartProofRules.Check.State.UNKNOWN, StartProofRules.positionCheck(sp, null, null).state);
		assertNull("no pin, nothing to measure", StartProofRules.positionCheck(owed(), 3340, 3250));
	}

	@Test
	public void greenChecksMeanTheButtonWontRefuse()
	{
		long now = 10_000_000L;
		PluginConfigResponse.StartProof sp = pinned(15);
		long login = now - 5 * 60_000L;
		assertEquals(StartProofRules.Check.State.OK, StartProofRules.sessionCheck(sp, login, now).state);
		assertEquals(StartProofRules.Check.State.OK, StartProofRules.positionCheck(sp, 3329, 3233).state);
		assertNull(StartProofRules.blockReason(sp, login, now, 3329, 3233));
	}

	@Test
	public void autoShotOnlyWhenPinnedFreshStillAndThere()
	{
		long now = 10_000_000L;
		long fresh = now - 2 * 60_000L;
		PluginConfigResponse.StartProof sp = pinned(15);
		int still = StartProofRules.AUTO_STILL_TICKS;
		assertTrue(StartProofRules.autoReady(sp, fresh, now, 3329, 3233, still));
		assertTrue("not yet standing still", !StartProofRules.autoReady(sp, fresh, now, 3329, 3233, still - 1));
		assertTrue("too far", !StartProofRules.autoReady(sp, fresh, now, 3200, 3233, still));
		assertTrue("stale session", !StartProofRules.autoReady(sp, now - 30 * 60_000L, now, 3329, 3233, still));
		assertTrue("unknown session", !StartProofRules.autoReady(sp, StartProofRules.UNKNOWN_LOGIN, now, 3329, 3233, still));
		assertTrue("no pin, nobody vouching", !StartProofRules.autoReady(owed(), fresh, now, 3329, 3233, still));
	}
}

package com.anvil;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * When the plugin may push a live boss KC or skill XP.
 *
 * <p>THE BUG THIS PINS. The gate used to demand an ACTIVE bingo, so being drafted into a board that
 * starts in six weeks turned the live weekly off: the server was asking for `kalphite queen` in
 * trackedKcNames, and the plugin refused to send it because of a bingo neither of them was playing
 * yet. Seven Kalphite Queen kills, "+0 kc" on the Boss of the Week, and nothing visibly broken —
 * the competition moved only on the hiscores sweep, which lags by design.</p>
 *
 * <p>What decides now is what the SERVER asked to watch. Sending during an inactive board is safe
 * there: completions are refused before a start and baselines re-anchor at it.</p>
 */
public class StatPushGateTest
{
	private static PluginConfigResponse cfgWithEvent(boolean started)
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.startDate = started ? "2020-01-01T00:00:00.000Z" : "2099-01-01T00:00:00.000Z";
		return cfg;
	}

	@Test
	public void aWeeklyOnlyConfigMaySend()
	{
		assertTrue(AnvilPlugin.statPushAllowed(new PluginConfigResponse()));
	}

	/** The case that was broken: a board exists, has not started, and the weekly still has to move. */
	@Test
	public void aBoardThatHasNotStartedDoesNotSilenceTheWeekly()
	{
		assertTrue(AnvilPlugin.statPushAllowed(cfgWithEvent(false)));
	}

	@Test
	public void aRunningBoardMaySendToo()
	{
		assertTrue(AnvilPlugin.statPushAllowed(cfgWithEvent(true)));
	}

	@Test
	public void nothingSendsBeforeThereIsAConfig()
	{
		assertFalse("no config means nothing is known to be tracked",
			AnvilPlugin.statPushAllowed(null));
	}

	@Test
	public void signedInWithNoClanStillReports()
	{
		assertTrue("no clan is an answer, not a stop: the stats are the person's",
			AnvilPlugin.statPushAllowed(null, true));
		assertFalse(AnvilPlugin.statPushAllowed(null, false));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link SyncBackoff} — what stops a refused push becoming a request every 30 seconds for as long as
 * someone stays logged in.
 */
public class SyncBackoffTest
{
	/** No jitter: the exact doubling, so the waits below are exact. */
	private static SyncBackoff exact()
	{
		return new SyncBackoff(SyncBackoff.FIRST_MS, SyncBackoff.MAX_MS, () -> 0.5);
	}

	@Test
	public void readyUntilSomethingFails()
	{
		SyncBackoff backoff = exact();
		assertTrue(backoff.ready(0));
		assertTrue(backoff.ready(1_000_000));
	}

	@Test
	public void spreadsEachWaitSoAClanDoesNotRetryInStep()
	{
		SyncBackoff early = new SyncBackoff(SyncBackoff.FIRST_MS, SyncBackoff.MAX_MS, () -> 0);
		SyncBackoff late = new SyncBackoff(SyncBackoff.FIRST_MS, SyncBackoff.MAX_MS, () -> 0.999);
		early.onFailure(0);
		late.onFailure(0);
		assertTrue(early.ready(SyncBackoff.FIRST_MS * 8 / 10));
		assertFalse(late.ready(SyncBackoff.FIRST_MS));
	}

	@Test
	public void waitsLongerEachTimeUpToTheCeiling()
	{
		SyncBackoff backoff = exact();
		long now = 10_000;

		backoff.onFailure(now);
		assertFalse(backoff.ready(now + SyncBackoff.FIRST_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));

		backoff.onFailure(now);
		assertFalse("second failure waits twice as long", backoff.ready(now + SyncBackoff.FIRST_MS));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS * 2));

		// However bad it gets, it settles at the ceiling rather than growing forever.
		for (int i = 0; i < 20; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now + SyncBackoff.MAX_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.MAX_MS));
	}

	@Test
	public void oneSuccessClearsTheWholeStreak()
	{
		SyncBackoff backoff = exact();
		long now = 10_000;
		for (int i = 0; i < 5; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now));

		backoff.onSuccess();
		assertTrue(backoff.ready(now));
		// And the next failure starts from the bottom again, not from where the streak left off.
		backoff.onFailure(now);
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));
	}

	@Test
	public void reportsHowLongTheSilenceLasts()
	{
		SyncBackoff backoff = exact();
		backoff.onFailure(0);
		assertEquals(SyncBackoff.FIRST_MS / 1000, backoff.secondsUntilReady(0));
		assertEquals(0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS));
		assertEquals("never negative", 0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS * 10));
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import org.junit.Test;

public class TenureGlyphTest
{
	@Test
	public void panelGlyphNamesMapToTheSixSteps()
	{
		assertEquals(1, UiView.tenureStep("tenure-1"));
		assertEquals(6, UiView.tenureStep("tenure-6"));
		assertEquals(0, UiView.tenureStep("tenure-7"));
		assertEquals(0, UiView.tenureStep("star"));
		assertEquals(0, UiView.tenureStep(null));
	}

	@Test
	public void chatSpritesAreSolidShadedAndAllDifferent()
	{
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (int t = 1; t <= AnvilPlugin.TENURE_STEPS; t++)
		{
			BufferedImage img = AnvilPlugin.tenureSprite(t, 0x4da3ff, -1);
			assertEquals(15, img.getWidth());
			assertEquals(13, img.getHeight());
			java.util.Set<Integer> tones = new java.util.HashSet<>();
			StringBuilder px = new StringBuilder();
			for (int y = 0; y < img.getHeight(); y++) for (int x = 0; x < 15; x++)
			{
				int p = img.getRGB(x, y), a = p >>> 24;
				// The game keeps solid pixels only: every pixel is all or nothing.
				assertTrue(a == 0 || a == 255);
				if (x >= 13) assertEquals("the gap before the name", 0, a);
				if (a > 0) tones.add(p);
				px.append(Integer.toHexString(p)).append(',');
			}
			assertTrue("shaded: outline, body and highlights", tones.size() >= 3);
			assertTrue(seen.add(px.toString()));
		}
		// The Legend's glint moves a highlight across it.
		boolean differs = false;
		for (int y = 0; y < 13; y++) for (int x = 0; x < 15; x++)
			differs |= AnvilPlugin.tenureSprite(6, 0x4da3ff, 1).getRGB(x, y) != AnvilPlugin.tenureSprite(6, 0x4da3ff, -1).getRGB(x, y);
		assertTrue(differs);
		assertNotEquals(AnvilPlugin.tenureSprite(6, 0x4da3ff, -1).getRGB(6, 4), AnvilPlugin.tenureSprite(6, 0xe05ad0, -1).getRGB(6, 4));
	}

	@Test
	public void neverAModsGoldOrSilver()
	{
		for (int ink : new int[]{0xffd35c, 0xffff00, 0xffffff, 0xc0c0c0, 0xa0a0a0})
		{
			int c = AnvilPlugin.tenureInk(ink);
			float[] h = java.awt.Color.RGBtoHSB(c >> 16 & 255, c >> 8 & 255, c & 255, null);
			assertTrue(Integer.toHexString(ink), h[1] > 0.3f && !(h[0] > 0.115f && h[0] < 0.19f));
		}
		// Dark greys and black are no mod's colour: they stay dark (a blue-to-black gradient once flashed bright).
		assertTrue((AnvilPlugin.tenureInk(0x101010) & 0xff) < 0x30);
		// Smooth: neighbouring colours (a moving gradient's frames) stay neighbours.
		for (int v = 0; v < 254; v++)
		{
			int a = AnvilPlugin.tenureInk(v * 0x010101), b = AnvilPlugin.tenureInk((v + 1) * 0x010101);
			assertTrue(Math.abs((a >> 16 & 255) - (b >> 16 & 255)) + Math.abs((a >> 8 & 255) - (b >> 8 & 255)) + Math.abs((a & 255) - (b & 255)) < 24);
		}
		assertEquals(0xe05ad0, AnvilPlugin.tenureInk(0xe05ad0));
	}
}

