package com.anvil;

import static org.junit.Assert.*;

import com.anvil.PluginConfigResponse.CompletedTile;
import com.anvil.PluginConfigResponse.TrackedCombo;
import com.google.gson.Gson;
import java.util.*;
import org.junit.Test;

public class TileNotesTest
{
	private static final Gson GSON = new Gson();

	@Test
	public void multiRunTimedTileReadsAsRuns()
	{
		assertEquals("3/5 runs", TileNotes.runs(3, 5));
		assertEquals("0/5 runs", TileNotes.runs(0, 5));
		assertEquals("5/5 runs", TileNotes.runs(7, 5)); // never past the goal
	}

	@Test
	public void plainTimedTileHasNoRunsLine()
	{
		assertNull(TileNotes.runs(0, 1));
		assertNull(TileNotes.runs(1, 1));
		assertNull(TileNotes.runs(0, 0));
	}

	@Test
	public void olderConfigsHaveNoCapsOrParts()
	{
		assertTrue(TileNotes.partCombos(null).isEmpty());
	}

	@Test
	public void capAndPartEntriesParseFromTheSiteContract()
	{
		CompletedTile done = GSON.fromJson("{\"tileId\":31,\"label\":\"GOTR - 100 searches\",\"points\":0,\"partOf\":30}", CompletedTile.class);
		assertEquals(30, (int) done.partOf);
		assertEquals("GOTR — 2 new clog slots", TileNotes.partLabel("GOTR", "2 new clog slots"));
	}

	@Test
	public void comboFoldsItsPartsIntoLines()
	{
		PluginConfigResponse cfg = GSON.fromJson("{\"trackedCombos\":[{\"tileId\":30,\"label\":\"GOTR rare or searches\","
			+ "\"rule\":\"any\",\"needed\":1,\"done\":0,\"parts\":[{\"tileId\":31,\"label\":\"GOTR rare reward\"},"
			+ "{\"tileId\":32,\"label\":\"100 searches\"}],\"completed\":false}]}", PluginConfigResponse.class);
		Map<Integer, Integer> parts = TileNotes.partCombos(cfg.trackedCombos);
		assertEquals(Integer.valueOf(30), parts.get(31));
		assertEquals(Integer.valueOf(30), parts.get(32));
		assertNull(parts.get(30));

		TrackedCombo combo = cfg.trackedCombos.get(0);
		Map<Integer, long[]> counts = new HashMap<>();
		counts.put(31, new long[]{0, 1});
		counts.put(32, new long[]{37, 100});
		assertEquals(Arrays.asList("0 of 1 done", "GOTR rare reward", "100 searches  37/100"), TileNotes.comboLines(combo, counts));

		combo.rule = "all";
		combo.needed = 2;
		combo.done = 1;
		combo.parts.get(0).completed = true;
		assertEquals(Arrays.asList("1 of 2 done", "GOTR rare reward  done", "100 searches  37/100"), TileNotes.comboLines(combo, counts));
		assertEquals("GOTR rare or searches \u2014 100 searches", TileNotes.partLabel(combo.label, "100 searches"));
		assertEquals("100 searches", TileNotes.partLabel(null, "100 searches"));
		combo.rule = "mix";
		combo.percent = 75;
		assertEquals("75%", TileNotes.comboLines(combo, counts).get(0));
		assertEquals(3, TileNotes.comboLines(combo, counts).size());
		PluginConfigResponse mix = GSON.fromJson("{\"trackedCombos\":[{\"tileId\":40,\"rule\":\"mix\",\"percent\":140,"
			+ "\"parts\":[{\"tileId\":41,\"label\":\"A\",\"weight\":0.5}]}]}", PluginConfigResponse.class);
		assertEquals("100%", TileNotes.comboLines(mix.trackedCombos.get(0), null).get(0));
	}

	@Test
	public void plurals()
	{
		assertEquals("searches", TileNotes.plural("search"));
		assertEquals("kills", TileNotes.plural("kill"));
		assertEquals("bodies", TileNotes.plural("body"));
		assertEquals("days", TileNotes.plural("day"));
		assertEquals("boxes", TileNotes.plural("box"));
	}
}

package com.anvil;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** A pinned tile takes itself down once the viewer's team finishes it, unless it was pinned already done. */
public class TileTrackerDoneTest
{
	private static TileTracker.Progress progress(boolean mineDone)
	{
		TileTracker.Team mine = new TileTracker.Team();
		mine.mine = true;
		mine.complete = mineDone;
		TileTracker.Team other = new TileTracker.Team();
		other.complete = true;
		TileTracker.Progress p = new TileTracker.Progress();
		p.phase = "active";
		p.teams = Arrays.asList(mine, other);
		return p;
	}

	@Test
	public void freshPinComesDownAfterTheLinger()
	{
		TileTracker.Widget w = new TileTracker.Widget(0, 0, (id, site) -> site);
		w.keepWhenDone = null; // a fresh pin
		assertFalse(TileTracker.finishedAndShown(w, progress(false), 0));
		assertFalse(TileTracker.finishedAndShown(w, progress(true), 1_000)); // "Done" goes up
		assertFalse(TileTracker.finishedAndShown(w, progress(true), 5_000));
		assertTrue(TileTracker.finishedAndShown(w, progress(true), 11_000));
	}

	@Test
	public void tilePinnedAlreadyDoneStaysUp()
	{
		TileTracker.Widget w = new TileTracker.Widget(0, 0, (id, site) -> site);
		w.keepWhenDone = null;
		assertFalse(TileTracker.finishedAndShown(w, progress(true), 0));
		assertFalse(TileTracker.finishedAndShown(w, progress(true), 60_000));
	}

	@Test
	public void restoredPinFinishedWhileOfflineComesDown()
	{
		TileTracker.Widget w = new TileTracker.Widget(0, 0, (id, site) -> site); // restored from config: keepWhenDone false
		assertFalse(TileTracker.finishedAndShown(w, progress(true), 100_000));
		assertTrue(TileTracker.finishedAndShown(w, progress(true), 130_000));
	}

	@Test
	public void anotherTeamFinishingDoesNotUnpin()
	{
		TileTracker.Widget w = new TileTracker.Widget(0, 0, (id, site) -> site);
		assertFalse(TileTracker.finishedAndShown(w, progress(false), 0));
		assertFalse(TileTracker.finishedAndShown(w, progress(false), 60_000));
	}

	@Test
	public void finishingAPinAsksAgainAfterTheLingerThenComesDown()
	{
		TileTracker.Widget w = new TileTracker.Widget(0, 0, (id, site) -> site); // pinned with Track on screen
		assertEquals(TileTracker.KEEP, TileTracker.afterFetch(w, progress(false), 0));
		// Completed: "Done" goes up once, and that is when the plugin schedules the next look.
		assertEquals(TileTracker.DONE_SHOWN, TileTracker.afterFetch(w, progress(true), 1_000));
		assertEquals(TileTracker.KEEP, TileTracker.afterFetch(w, progress(true), 2_000));
		assertEquals(TileTracker.UNPIN, TileTracker.afterFetch(w, progress(true), 1_000 + TileTracker.DONE_LINGER_MS + 1_000));
	}
}

package com.anvil;

import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.*;

/** Pins always end in a real state: restored (old or new format), loaded, or let go — never "loading" for good. */
public class TileTrackerPinTest {
	private static TileTracker.Widget pin() {
		return new TileTracker.Widget(0, 7, (id, site) -> site);
	}

	@Test
	public void oldFormatPinsRestoreWithABoardToFind() {
		Map<Integer, Integer> m = TileTracker.parse("5:1,2;9:3");
		assertEquals(Integer.valueOf(5), m.get(1));
		assertEquals(Integer.valueOf(9), m.get(3));
		// Saved before pins kept a board, or damaged: still restored (board 0 = find it), junk skipped.
		Map<Integer, Integer> old = TileTracker.parse("4,8");
		assertEquals(Integer.valueOf(0), old.get(4));
		assertEquals(Integer.valueOf(0), old.get(8));
		Map<Integer, Integer> mixed = TileTracker.parse("5:1,x,2;3");
		assertEquals(Integer.valueOf(5), mixed.get(2));
		assertEquals(Integer.valueOf(0), mixed.get(3));
	}

	@Test
	public void loadedPinStaysAndAnotherBoardsPinLoads() {
		TileTracker.Widget w = pin();
		w.event = 12; // a pin from a second board loads like the first's
		TileTracker.Progress p = new TileTracker.Progress();
		assertFalse(TileTracker.letGo(w, p));
		assertFalse(TileTracker.letGo(w, null)); // a blip after it loaded never drops it
		w.progress = p;
		for (int i = 0; i < 20; i++) assertFalse(TileTracker.letGo(w, null));
	}

	@Test
	public void unresolvablePinIsDroppedNotStuck() {
		TileTracker.Widget gone = pin();
		assertTrue(TileTracker.letGo(gone, TileTracker.Progress.GONE)); // a deleted tile: down at once

		TileTracker.Widget never = pin();
		for (int i = 1; i < TileTracker.MAX_FAILS; i++) assertFalse(TileTracker.letGo(never, null));
		assertTrue(TileTracker.letGo(never, null));
	}

	@Test
	public void lockedTileComesDownAtOnce() {
		assertTrue(TileTracker.letGo(pin(), TileTracker.Progress.LOCKED));
	}
}

