	private static JTextField findField(Component c)
	{
		if (c instanceof JTextField)
		{
			return (JTextField) c;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				JTextField f = findField(child);
				if (f != null)
				{
					return f;
				}
			}
		}
		return null;
	}

